import cn from "classnames";

import { memo, ReactNode, useCallback, useEffect, useRef, useState } from "react";
import { useLiveAPIContext } from "../../contexts/LiveAPIContext";
import { UseMediaStreamResult } from "../../hooks/use-media-stream-mux";
import { useScreenCapture } from "../../hooks/use-screen-capture";
import { useWebcam } from "../../hooks/use-webcam";
import { AudioRecorder } from "../../lib/audio-recorder";
import AudioPulse from "../audio-pulse/AudioPulse";
import "./control-tray.scss";
import ThinkingModeToggle from "../thinking-mode-toggle/ThinkingModeToggle";
import MicrophoneStatus from "../microphone-status/MicrophoneStatus";
// import InteractiveWhiteboard from "../interactive-whiteboard/InteractiveWhiteboard";
import { CalendarGeminiService } from "../../services/CalendarGeminiService";
import { userPreferencesService } from "../../services/UserPreferencesService";

export type ControlTrayProps = {
  currentVideoElement?: HTMLVideoElement | null;
  children?: ReactNode;
  supportsVideo: boolean;
  onVideoStreamChange?: (stream: MediaStream | null) => void;
  enableEditingSettings?: boolean;
  isScreenSharing?: boolean;
  isYouTubeActive?: boolean;
  onStopScreenSharing?: () => void;
  onToggleYouTube?: () => void;
};

type MediaStreamButtonProps = {
  isStreaming: boolean;
  onIcon: string;
  offIcon: string;
  start: () => Promise<any>;
  stop: () => any;
};

/**
 * button used for triggering webcam or screen-capture
 */
const MediaStreamButton = memo(
  ({ isStreaming, onIcon, offIcon, start, stop }: MediaStreamButtonProps) =>
    isStreaming ? (
      <button className="action-button" onClick={stop}>
        <span className="material-symbols-outlined">{onIcon}</span>
      </button>
    ) : (
      <button className="action-button" onClick={start}>
        <span className="material-symbols-outlined">{offIcon}</span>
      </button>
    )
);

function ControlTray({
  currentVideoElement,
  children,
  onVideoStreamChange = () => {},
  supportsVideo,
  enableEditingSettings,
  isScreenSharing = false,
  isYouTubeActive = false,
  onStopScreenSharing = () => {},
  onToggleYouTube = () => {},
}: ControlTrayProps) {
  const videoStreams = [useWebcam(), useScreenCapture()];
  const [activeVideoStream, setActiveVideoStream] =
    useState<MediaStream | null>(null);
  const [webcam, screenCapture] = videoStreams;
  const [inVolume, setInVolume] = useState(0);
  const [audioRecorder] = useState(() => new AudioRecorder());
  const [muted, setMuted] = useState(false);
  const [microphoneError, setMicrophoneError] = useState<string | null>(null);
  const [microphoneStatus, setMicrophoneStatus] = useState<'idle' | 'requesting' | 'granted' | 'denied'>('idle');
  const [connectionError, setConnectionError] = useState<string | null>(null);
  const [isConnecting, setIsConnecting] = useState(false);
  const [quotaExceeded, setQuotaExceeded] = useState(false);
  const [isLoadingCalendarData, setIsLoadingCalendarData] = useState(false);
  const [calendarDataMessage, setCalendarDataMessage] = useState<string>("");
  // const [showWhiteboard, setShowWhiteboard] = useState(false);
  const renderCanvasRef = useRef<HTMLCanvasElement>(null);
  const connectButtonRef = useRef<HTMLButtonElement>(null);

  const { client, connected, connect, disconnect, volume } =
    useLiveAPIContext();

  // Escuchar eventos de cuota excedida
  useEffect(() => {
    const handleQuotaExceeded = (event: CustomEvent) => {
      console.error("🚫 CUOTA EXCEDIDA detectada en ControlTray:", event.detail);
      setQuotaExceeded(true);
      setConnectionError(event.detail.message);
      setIsConnecting(false);
      
      // Mostrar alerta crítica al usuario
      if (window.alert) {
        window.alert(`🚫 CUOTA EXCEDIDA - VOXIA\n\n${event.detail.message}\n\n❌ NO se realizarán más intentos de conexión automática.\n\n🔧 Para solucionar:\n1. Verifica tu plan de Google AI Studio\n2. Revisa los detalles de facturación\n3. Considera actualizar tu plan si es necesario`);
      }
    };

    window.addEventListener('quota-exceeded', handleQuotaExceeded as EventListener);
    
    return () => {
      window.removeEventListener('quota-exceeded', handleQuotaExceeded as EventListener);
    };
  }, []);

  // Función segura para conectar con manejo de errores
  const safeConnect = useCallback(async () => {
    if (isConnecting || connected || quotaExceeded) {
      // Si la cuota está excedida, no permitir más intentos
      if (quotaExceeded) {
        window.alert("🚫 CUOTA EXCEDIDA\n\nNo se pueden realizar más conexiones porque se ha excedido la cuota de la API de Gemini.\n\nPor favor verifica tu plan y facturación en Google AI Studio.");
        return;
      }
      return;
    }
    
    setIsConnecting(true);
    setConnectionError(null);
    setIsLoadingCalendarData(true);
    
    // Mensaje condicional basado en preferencias del usuario
    const shouldLoadCalendarData = userPreferencesService.shouldAutoLoadCalendarData();
    const initialMessage = shouldLoadCalendarData 
      ? "Cargando y leyendo tus datos locales..."
      : "Iniciando Gemini Live...";
    setCalendarDataMessage(initialMessage);
    
    try {
      // Inicializar datos del calendario en paralelo con la conexión (solo si está habilitado)
      const calendarService = CalendarGeminiService.getInstance();
      const calendarDataPromise = calendarService.initializeCalendarData();
      
      // Conectar a Gemini Live
      const connectPromise = connect();
      
      // Esperar ambas operaciones
      await Promise.all([connectPromise, calendarDataPromise]);
      
      console.log("✅ VOXIA conectado exitosamente");
      setQuotaExceeded(false); // Reset si la conexión fue exitosa
      
      // Mensaje final condicional
      const finalMessage = shouldLoadCalendarData 
        ? "✅ Datos del calendario listos"
        : "✅ Gemini Live conectado";
      setCalendarDataMessage(finalMessage);
      
      // Limpiar mensaje después de 2 segundos
      setTimeout(() => {
        setCalendarDataMessage("");
      }, 2000);
      
    } catch (error) {
      console.error("❌ Error al conectar VOXIA:", error);
      const errorMessage = error instanceof Error ? error.message : "Error desconocido de conexión";
      setConnectionError(errorMessage);
      
      // Verificar si es error de cuota
      if (errorMessage.includes("exceeded your current quota") || errorMessage.includes("CUOTA EXCEDIDA")) {
        setQuotaExceeded(true);
      }
      
      setCalendarDataMessage("❌ Error al cargar datos");
      
      // Mostrar alerta al usuario
      if (window.alert) {
        window.alert(`🚫 Error de Conexión VOXIA\n\n${errorMessage}\n\nPor favor, verifica:\n1. Tu conexión a internet\n2. Que la API key esté configurada\n3. Que el servicio esté disponible`);
      }
    } finally {
      setIsConnecting(false);
      setIsLoadingCalendarData(false);
      
      // Limpiar mensaje de error después de 3 segundos
      if (calendarDataMessage.includes("❌")) {
        setTimeout(() => {
          setCalendarDataMessage("");
        }, 3000);
      }
    }
  }, [connect, isConnecting, connected, quotaExceeded, calendarDataMessage]);

  // Función segura para desconectar
  const safeDisconnect = useCallback(async () => {
    try {
      await disconnect();
      setConnectionError(null);
      console.log("🔌 VOXIA desconectado");
    } catch (error) {
      console.error("❌ Error al desconectar:", error);
    }
  }, [disconnect]);

  useEffect(() => {
    if (!connected && connectButtonRef.current) {
      connectButtonRef.current.focus();
    }
  }, [connected]);
  useEffect(() => {
    document.documentElement.style.setProperty(
      "--volume",
      `${Math.max(5, Math.min(inVolume * 200, 8))}px`
    );
  }, [inVolume]);

  useEffect(() => {
    const onData = (base64: string) => {
      client.sendRealtimeInput([
        {
          mimeType: "audio/pcm;rate=16000",
          data: base64,
        },
      ]);
    };
    
    if (connected && !muted && audioRecorder) {
      setMicrophoneStatus('requesting');
      setMicrophoneError(null);
      
      audioRecorder.on("data", onData).on("volume", setInVolume);
      
      audioRecorder.start()
        .then(() => {
          console.log("🎤 Micrófono iniciado exitosamente");
          setMicrophoneStatus('granted');
          setMicrophoneError(null);
        })
        .catch((error: Error) => {
          console.error("❌ Error del micrófono:", error.message);
          setMicrophoneStatus('denied');
          setMicrophoneError(error.message);
          
          // Mostrar notificación al usuario
          if (window.alert) {
            window.alert(`🎤 VOXIA - Error de Micrófono\n\n${error.message}`);
          }
        });
    } else {
      audioRecorder.stop();
      setMicrophoneStatus('idle');
    }
    
    return () => {
      audioRecorder.off("data", onData).off("volume", setInVolume);
    };
  }, [connected, client, muted, audioRecorder]);

  useEffect(() => {
    if (currentVideoElement) {
      currentVideoElement.srcObject = activeVideoStream;
    }

    let timeoutId = -1;

    function sendVideoFrame() {
      const video = currentVideoElement;
      const canvas = renderCanvasRef.current;

      if (!video || !canvas) {
        return;
      }

      const ctx = canvas.getContext("2d")!;
      canvas.width = video.videoWidth * 0.25;
      canvas.height = video.videoHeight * 0.25;
      if (canvas.width + canvas.height > 0) {
        ctx.drawImage(currentVideoElement, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL("image/jpeg", 1.0);
        const data = base64.slice(base64.indexOf(",") + 1, Infinity);
        client.sendRealtimeInput([{ mimeType: "image/jpeg", data }]);
      }
      if (connected) {
        timeoutId = window.setTimeout(sendVideoFrame, 1000 / 0.5);
      }
    }
    if (connected && activeVideoStream !== null) {
      requestAnimationFrame(sendVideoFrame);
    }
    return () => {
      clearTimeout(timeoutId);
    };
  }, [connected, activeVideoStream, client, currentVideoElement]);

  //handler for swapping from one video-stream to the next
  const changeStreams = (next?: UseMediaStreamResult) => async () => {
    if (next) {
      const mediaStream = await next.start();
      setActiveVideoStream(mediaStream);
      onVideoStreamChange(mediaStream);
    } else {
      setActiveVideoStream(null);
      onVideoStreamChange(null);
    }

    videoStreams.filter((msr) => msr !== next).forEach((msr) => msr.stop());
  };

  return (
    <section className="control-tray">
      <canvas style={{ display: "none" }} ref={renderCanvasRef} />
      
      {/* Pizarrón Interactivo - Solo en pantallas grandes */}
      {/* <InteractiveWhiteboard
        isVisible={showWhiteboard}
        onToggle={() => setShowWhiteboard(!showWhiteboard)}
      /> */}
      
      <nav className={cn("actions-nav", { disabled: !connected })}>
        <button
          className={cn("action-button mic-button", {
            recording: connected && !muted && microphoneStatus === 'granted',
            requesting: microphoneStatus === 'requesting',
            error: microphoneStatus === 'denied'
          })}
          onClick={() => setMuted(!muted)}
          title={
            microphoneError 
              ? `❌ Error: ${microphoneError}` 
              : microphoneStatus === 'requesting'
              ? "🎤 Solicitando acceso al micrófono..."
              : microphoneStatus === 'denied'
              ? "❌ Acceso al micrófono denegado"
              : muted 
              ? "🎤 Activar micrófono" 
              : "🎤 Silenciar micrófono"
          }
        >
          {microphoneStatus === 'requesting' ? (
            <span className="material-symbols-outlined">hourglass_empty</span>
          ) : microphoneStatus === 'denied' ? (
            <span className="material-symbols-outlined filled">mic_off</span>
          ) : !muted ? (
            <span className="material-symbols-outlined filled">mic</span>
          ) : (
            <span className="material-symbols-outlined filled">mic_off</span>
          )}
        </button>

        <div className="action-button no-action outlined">
          <AudioPulse volume={volume} active={connected} hover={false} />
        </div>

        {supportsVideo && (
          <>
            <MediaStreamButton
              isStreaming={screenCapture.isStreaming}
              start={changeStreams(screenCapture)}
              stop={changeStreams()}
              onIcon="cancel_presentation"
              offIcon="present_to_all"
            />
            <MediaStreamButton
              isStreaming={webcam.isStreaming}
              start={changeStreams(webcam)}
              stop={changeStreams()}
              onIcon="videocam_off"
              offIcon="videocam"
            />
          </>
        )}
        
        {/* Toggle de Thinking Mode */}
        <ThinkingModeToggle />
        
        {/* Botón para mostrar/ocultar pizarrón - Solo en pantallas grandes */}
        {/* <button
          className="action-button whiteboard-toggle"
          onClick={() => setShowWhiteboard(!showWhiteboard)}
          title={showWhiteboard ? "Ocultar pizarrón" : "Mostrar pizarrón"}
        >
          <span className="material-symbols-outlined">
            {showWhiteboard ? 'draw_off' : 'draw'}
          </span>
        </button> */}
        
        {children}
        
        {/* Controles especiales para screen sharing + YouTube */}
        {isScreenSharing && isYouTubeActive && (
          <div className="screen-share-controls">
            <button
              className="stop-sharing-btn"
              onClick={() => {
                changeStreams()();
                onStopScreenSharing();
              }}
              title="Detener compartir pantalla"
            >
              Detener
            </button>
            <button
              className="minimize-youtube-btn"
              onClick={onToggleYouTube}
              title={isYouTubeActive ? "Ocultar YouTube" : "Mostrar YouTube"}
            >
              {isYouTubeActive ? "📺" : "🎵"}
            </button>
          </div>
        )}
      </nav>

      <div className={cn("connection-container", { connected })}>
        <div className="connection-button-container">
          <button
            ref={connectButtonRef}
            className={cn("action-button connect-toggle", { 
              connected, 
              connecting: isConnecting,
              error: connectionError,
              "quota-exceeded": quotaExceeded
            })}
            onClick={connected ? safeDisconnect : safeConnect}
            disabled={isConnecting || quotaExceeded || isLoadingCalendarData}
            title={
              quotaExceeded
                ? "🚫 CUOTA EXCEDIDA: Verifica tu plan de Google AI Studio"
                : connectionError 
                ? `❌ Error: ${connectionError}` 
                : isConnecting || isLoadingCalendarData
                ? (calendarDataMessage || "🔄 Conectando a VOXIA...")
                : connected 
                ? "⏸️ Pausar VOXIA" 
                : "▶️ Iniciar VOXIA"
            }
          >
            <span className="material-symbols-outlined filled">
              {quotaExceeded ? "block" : isConnecting ? "hourglass_empty" : connected ? "pause" : connectionError ? "error" : "play_arrow"}
            </span>
          </button>
        </div>
        <span className="text-indicator">Streaming</span>
        
        {/* Mensaje de carga de datos del calendario */}
        {(isLoadingCalendarData || calendarDataMessage) && (
          <div className="calendar-loading-message">
            <div className="loading-content">
              {isLoadingCalendarData && (
                <div className="loading-spinner">
                  <span className="material-symbols-outlined rotating">hourglass_empty</span>
                </div>
              )}
              <span className="loading-text">
                {calendarDataMessage || (userPreferencesService.shouldAutoLoadCalendarData() 
                  ? "Cargando y leyendo tus datos locales..." 
                  : "Iniciando Gemini Live...")}
              </span>
            </div>
          </div>
        )}
        
        {/* Mostrar error de conexión si existe */}
        {connectionError && (
          <div className={cn("connection-error", { "quota-exceeded": quotaExceeded })}>
            <span className="error-message">
              {quotaExceeded ? "🚫" : "❌"} {connectionError}
            </span>
            {!quotaExceeded && (
              <button 
                className="retry-button"
                onClick={() => {
                  setConnectionError(null);
                  safeConnect();
                }}
                title="Reintentar conexión"
              >
                🔄 Reintentar
              </button>
            )}
            {quotaExceeded && (
              <div style={{ display: 'flex', gap: '4px', flexDirection: 'column', alignItems: 'center' }}>
                <button 
                  className="info-button"
                  onClick={() => {
                    window.open("https://makersuite.google.com/", "_blank");
                  }}
                  title="Abrir Google AI Studio"
                >
                  🔧 Configurar API
                </button>
                <button 
                  className="retry-button"
                  onClick={() => {
                    setQuotaExceeded(false);
                    setConnectionError(null);
                    // Dar un momento para que el usuario haya actualizado su configuración
                    setTimeout(() => {
                      safeConnect();
                    }, 1000);
                  }}
                  title="Intentar de nuevo (después de configurar API)"
                  style={{ fontSize: '10px', padding: '2px 6px' }}
                >
                  🔄 Intentar de nuevo
                </button>
              </div>
            )}
          </div>
        )}
      </div>
      
      {/* Componente de estado del micrófono */}
      <MicrophoneStatus
        status={microphoneStatus}
        error={microphoneError}
        onRetry={() => {
          setMicrophoneError(null);
          setMicrophoneStatus('idle');
          // Forzar reconexión
          if (connected && !muted) {
            audioRecorder.stop();
            setTimeout(() => {
              setMicrophoneStatus('requesting');
              audioRecorder.start()
                .then(() => {
                  setMicrophoneStatus('granted');
                  setMicrophoneError(null);
                })
                .catch((error: Error) => {
                  setMicrophoneStatus('denied');
                  setMicrophoneError(error.message);
                });
            }, 100);
          }
        }}
        onDismiss={() => {
          setMicrophoneError(null);
          setMicrophoneStatus('idle');
        }}
      />
    </section>
  );
}

export default memo(ControlTray);
