import { supabase } from './supabase'
import { DateTimeUtils } from '../utils/dateTimeUtils'

// Interfaces completas basadas en Google Calendar API v3
interface CalendarEvent {
  id: string
  kind?: string
  etag?: string
  status?: 'confirmed' | 'tentative' | 'cancelled'
  htmlLink?: string
  created?: string
  updated?: string
  summary: string
  description?: string
  location?: string
  colorId?: string
  creator?: {
    id?: string
    email?: string
    displayName?: string
    self?: boolean
  }
  organizer?: {
    id?: string
    email?: string
    displayName?: string
    self?: boolean
  }
  start: {
    date?: string
    dateTime?: string
    timeZone?: string
  }
  end: {
    date?: string
    dateTime?: string
    timeZone?: string
  }
  endTimeUnspecified?: boolean
  recurrence?: string[]
  recurringEventId?: string
  originalStartTime?: {
    date?: string
    dateTime?: string
    timeZone?: string
  }
  transparency?: 'opaque' | 'transparent'
  visibility?: 'default' | 'public' | 'private' | 'confidential'
  iCalUID?: string
  sequence?: number
  attendees?: Array<{
    id?: string
    email: string
    displayName?: string
    organizer?: boolean
    self?: boolean
    resource?: boolean
    optional?: boolean
    responseStatus?: 'needsAction' | 'declined' | 'tentative' | 'accepted'
    comment?: string
    additionalGuests?: number
  }>
  attendeesOmitted?: boolean
  hangoutLink?: string
  conferenceData?: {
    createRequest?: {
      requestId?: string
      conferenceSolutionKey?: {
        type: string
      }
      status?: {
        statusCode?: string
      }
    }
    entryPoints?: Array<{
      entryPointType?: 'video' | 'phone' | 'sip' | 'more'
      uri?: string
      label?: string
      pin?: string
      accessCode?: string
      meetingCode?: string
      passcode?: string
      password?: string
    }>
    conferenceSolution?: {
      key?: {
        type: string
      }
      name?: string
      iconUri?: string
    }
    conferenceId?: string
    signature?: string
    notes?: string
  }
  reminders?: {
    useDefault?: boolean
    overrides?: Array<{
      method: 'email' | 'popup'
      minutes: number
    }>
  }
  attachments?: Array<{
    fileUrl: string
    title?: string
    mimeType?: string
    iconLink?: string
    fileId?: string
  }>
  eventType?: 'default' | 'birthday' | 'focusTime' | 'fromGmail' | 'outOfOffice' | 'workingLocation'
  anyoneCanAddSelf?: boolean
  guestsCanInviteOthers?: boolean
  guestsCanModify?: boolean
  guestsCanSeeOtherGuests?: boolean
  privateCopy?: boolean
  locked?: boolean
  source?: {
    url?: string
    title?: string
  }
}

interface CalendarList {
  id: string
  kind?: string
  etag?: string
  summary: string
  description?: string
  location?: string
  timeZone?: string
  summaryOverride?: string
  colorId?: string
  backgroundColor?: string
  foregroundColor?: string
  hidden?: boolean
  selected?: boolean
  accessRole: 'freeBusyReader' | 'reader' | 'writer' | 'owner'
  defaultReminders?: Array<{
    method: 'email' | 'popup'
    minutes: number
  }>
  notificationSettings?: {
    notifications?: Array<{
      type: string
      method: string
    }>
  }
  primary?: boolean
  deleted?: boolean
  conferenceProperties?: {
    allowedConferenceSolutionTypes?: string[]
  }
}

interface CreateEventRequest {
  summary: string
  description?: string
  location?: string
  start: {
    dateTime?: string
    date?: string
    timeZone?: string
  }
  end: {
    dateTime?: string
    date?: string
    timeZone?: string
  }
  colorId?: string
  transparency?: 'opaque' | 'transparent'
  visibility?: 'default' | 'public' | 'private' | 'confidential'
  attendees?: Array<{
    email: string
    displayName?: string
    optional?: boolean
  }>
  recurrence?: string[]
  reminders?: {
    useDefault?: boolean
    overrides?: Array<{
      method: 'email' | 'popup'
      minutes: number
    }>
  }
  conferenceData?: {
    createRequest?: {
      requestId: string
      conferenceSolutionKey: {
        type: 'hangoutsMeet' | 'addOn'
      }
    }
  }
  attachments?: Array<{
    fileUrl: string
    title?: string
    mimeType?: string
  }>
  anyoneCanAddSelf?: boolean
  guestsCanInviteOthers?: boolean
  guestsCanModify?: boolean
  guestsCanSeeOtherGuests?: boolean
  source?: {
    url?: string
    title?: string
  }
}

interface UpdateEventRequest extends Partial<CreateEventRequest> {
  id?: string
}

interface EventsListParams {
  calendarId?: string
  timeMin?: string
  timeMax?: string
  maxResults?: number
  orderBy?: 'startTime' | 'updated'
  singleEvents?: boolean
  showDeleted?: boolean
  q?: string // parámetro de búsqueda
  colorId?: string
  pageToken?: string
  showHiddenInvitations?: boolean
  syncToken?: string
  updatedMin?: string
  alwaysIncludeEmail?: boolean
  maxAttendees?: number
  iCalUID?: string
}

interface FreeBusyRequest {
  timeMin: string
  timeMax: string
  timeZone?: string
  groupExpansionMax?: number
  calendarExpansionMax?: number
  items: Array<{
    id: string
  }>
}

interface FreeBusyResponse {
  timeMin: string
  timeMax: string
  calendars: {
    [calendarId: string]: {
      busy?: Array<{
        start: string
        end: string
      }>
      errors?: Array<{
        domain: string
        reason: string
      }>
    }
  }
}

interface CalendarColors {
  calendar: {
    [colorId: string]: {
      background: string
      foreground: string
    }
  }
  event: {
    [colorId: string]: {
      background: string
      foreground: string
    }
  }
  reminders?: {
    useDefault?: boolean
    overrides?: Array<{
      method: 'email' | 'popup'
      minutes: number
    }>
  }
}

class GoogleCalendarService {
  
  private async getGoogleToken(): Promise<string | null> {
    try {
      const { data: { session } } = await supabase.auth.getSession()
      
      if (!session?.provider_token) {
        console.warn('🗓️ GoogleCalendar: No hay token de Google disponible. Usuario debe autenticarse.')
        return null
      }
      
      console.log('🗓️ GoogleCalendar: Token de Google disponible:', session.provider_token.substring(0, 20) + '...')
      return session.provider_token
    } catch (error) {
      console.error('🗓️ GoogleCalendar: Error obteniendo token de Google:', error)
      return null
    }
  }

  private async makeCalendarRequest(endpoint: string, method: 'GET' | 'POST' | 'PUT' | 'DELETE' = 'GET', params: Record<string, string> = {}, body?: any): Promise<any> {
    const token = await this.getGoogleToken()
    
    if (!token) {
      throw new Error('Token de Google no disponible. El usuario debe autenticarse primero.')
    }

    const url = new URL(`https://www.googleapis.com/calendar/v3/${endpoint}`)
    
    // Solo agregar parámetros para GET requests
    if (method === 'GET') {
      Object.entries(params).forEach(([key, value]) => {
        url.searchParams.append(key, value)
      })
    }

    const requestOptions: RequestInit = {
      method,
      headers: {
        'Authorization': `Bearer ${token}`,
        'Accept': 'application/json',
        'Content-Type': 'application/json',
      },
    }

    // Agregar body para POST/PUT requests
    if (body && (method === 'POST' || method === 'PUT')) {
      requestOptions.body = JSON.stringify(body)
    }

    const response = await fetch(url.toString(), requestOptions)

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}))
      
      console.error('🗓️ GoogleCalendar API Error:', {
        status: response.status,
        statusText: response.statusText,
        errorData,
        endpoint,
        url: url.toString()
      })
      
      // Manejar específicamente errores de scopes
      if (response.status === 403 && errorData.error?.message?.includes('insufficient authentication scopes')) {
        throw new Error('Sin permisos de Google Calendar. Necesitas reautenticarte con scopes de Calendar.')
      }
      
      if (response.status === 403 && errorData.error?.message?.includes('access_denied')) {
        throw new Error('Acceso denegado a Google Calendar API. Verifica configuración OAuth.')
      }

      if (response.status === 401) {
        throw new Error('Token de autenticación inválido. Necesitas iniciar sesión de nuevo.')
      }
      
      throw new Error(`Google Calendar API Error: ${response.status} - ${errorData.error?.message || response.statusText}`)
    }

    return response.json()
  }

  // Obtener lista de calendarios del usuario
  async getCalendarList(): Promise<CalendarList[]> {
    const response = await this.makeCalendarRequest('users/me/calendarList')
    return response.items || []
  }

  // Obtener eventos de un calendario específico
  async getEvents(params: EventsListParams = {}): Promise<CalendarEvent[]> {
    const calendarId = params.calendarId || 'primary'
    const queryParams: Record<string, string> = {
      singleEvents: 'true',
      orderBy: 'startTime',
      maxResults: '10'
    }

    // Agregar parámetros adicionales y convertir a string
    Object.entries(params).forEach(([key, value]) => {
      if (key !== 'calendarId' && value !== undefined) {
        if (typeof value === 'boolean') {
          queryParams[key] = value.toString()
        } else if (typeof value === 'number') {
          queryParams[key] = value.toString()
        } else {
          queryParams[key] = value
        }
      }
    })

    const response = await this.makeCalendarRequest(`calendars/${encodeURIComponent(calendarId)}/events`, 'GET', queryParams)
    return response.items || []
  }

  // Obtener eventos próximos (hoy y siguientes 7 días)
  async getUpcomingEvents(maxResults: number = 10): Promise<CalendarEvent[]> {
    const now = new Date()
    const oneWeekLater = new Date()
    oneWeekLater.setDate(now.getDate() + 7)

    return this.getEvents({
      timeMin: now.toISOString(),
      timeMax: oneWeekLater.toISOString(),
      maxResults,
      singleEvents: true,
      orderBy: 'startTime'
    })
  }

  // Obtener eventos de hoy
  async getTodayEvents(): Promise<CalendarEvent[]> {
    console.log('🗓️ GoogleCalendarService.getTodayEvents: INICIO')
    
    // Usar las utilidades de fecha para obtener el rango correcto
    const { startOfDay, endOfDay } = DateTimeUtils.getTodayRange();

    try {
      const result = await this.getEvents({
        timeMin: startOfDay.toISOString(),
        timeMax: endOfDay.toISOString(),
        singleEvents: true,
        orderBy: 'startTime'
      })
      
      console.log('🗓️ GoogleCalendarService.getTodayEvents: ÉXITO - Eventos encontrados:', result.length)
      console.log('🗓️ GoogleCalendarService.getTodayEvents: IDs encontrados:', result.map(e => ({
        id: e.id, 
        summary: e.summary, 
        start: e.start,
        fechaLocal: e.start?.dateTime ? new Date(e.start.dateTime).toLocaleString() : e.start?.date
      })))
      return result
    } catch (error) {
      console.error('🗓️ GoogleCalendarService.getTodayEvents: ERROR:', error)
      throw error
    }
  }

  // Crear un nuevo evento
  async createEvent(eventData: CreateEventRequest, calendarId: string = 'primary'): Promise<CalendarEvent> {
    const timeZone = DateTimeUtils.getUserTimeZone();
    console.log('🗓️ GoogleCalendarService.createEvent: INICIO', {
      calendarId,
      summary: eventData.summary,
      startTime: eventData.start?.dateTime || eventData.start?.date,
      endTime: eventData.end?.dateTime || eventData.end?.date,
      timeZone,
      fechaActual: DateTimeUtils.formatForDisplay(DateTimeUtils.getCurrentDate())
    });
    
    const result = await this.makeCalendarRequest(`calendars/${encodeURIComponent(calendarId)}/events`, 'POST', {}, eventData);
    
    console.log('🗓️ GoogleCalendarService.createEvent: EVENTO CREADO', {
      id: result.id,
      summary: result.summary,
      created: result.created,
      startTime: result.start?.dateTime || result.start?.date,
      endTime: result.end?.dateTime || result.end?.date,
      fechaLocalCreacion: result.start?.dateTime ? new Date(result.start.dateTime).toLocaleString() : 'Evento de día completo'
    });
    
    return result;
  }

  // Actualizar un evento existente
  async updateEvent(eventId: string, eventData: Partial<CreateEventRequest>, calendarId: string = 'primary'): Promise<CalendarEvent> {
    return this.makeCalendarRequest(`calendars/${encodeURIComponent(calendarId)}/events/${eventId}`, 'PUT', {}, eventData)
  }

  // Eliminar un evento
  async deleteEvent(eventId: string, calendarId: string = 'primary'): Promise<void> {
    await this.makeCalendarRequest(`calendars/${encodeURIComponent(calendarId)}/events/${eventId}`, 'DELETE')
  }

  // Buscar eventos por texto
  async searchEvents(query: string, maxResults: number = 10): Promise<CalendarEvent[]> {
    return this.getEvents({
      q: query,
      maxResults,
      singleEvents: true,
      orderBy: 'startTime'
    })
  }

  // Verificar si el usuario tiene acceso a Google Calendar
  async checkCalendarAccess(): Promise<boolean> {
    try {
      console.log('🗓️ GoogleCalendar: Verificando acceso a Calendar API...')
      
      // Obtener token directamente
      const token = await this.getGoogleToken()
      if (!token) {
        console.log('🗓️ GoogleCalendar: No hay token disponible')
        return false
      }
      
      console.log('🗓️ GoogleCalendar: Token disponible, haciendo llamada directa a Calendar API...')
      
      // Hacer llamada directa simple a Calendar API
      const response = await fetch('https://www.googleapis.com/calendar/v3/users/me/calendarList?maxResults=1', {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Accept': 'application/json'
        }
      })
      
      console.log('🗓️ GoogleCalendar: Respuesta de Calendar API:', {
        status: response.status,
        statusText: response.statusText,
        ok: response.ok
      })
      
      if (response.ok) {
        const data = await response.json()
        console.log('🗓️ GoogleCalendar: Acceso exitoso, calendarios encontrados:', data.items?.length || 0)
        return true
      } else {
        // Obtener detalles del error
        const errorData = await response.json().catch(() => ({}))
        console.warn('🗓️ GoogleCalendar: Error en Calendar API:', {
          status: response.status,
          statusText: response.statusText,
          error: errorData.error?.message || 'Error desconocido',
          errorCode: errorData.error?.code,
          errorDetails: errorData.error
        })
        return false
      }
    } catch (error) {
      console.warn('🗓️ GoogleCalendar: Excepción verificando acceso a Calendar API:', error)
      return false
    }
  }

  // Obtener información sobre el acceso a Calendar
  async getCalendarAccessInfo(): Promise<{ hasAccess: boolean; message: string }> {
    try {
      const hasAccess = await this.checkCalendarAccess()
      if (hasAccess) {
        return {
          hasAccess: true,
          message: 'Acceso a Google Calendar API disponible'
        }
      } else {
        return {
          hasAccess: false,
          message: 'Sin acceso a Google Calendar API. Usuario debe autenticarse con permisos de Calendar.'
        }
      }
    } catch (error) {
      return {
        hasAccess: false,
        message: `Error verificando acceso a Calendar: ${error}`
      }
    }
  }

  // Crear evento rápido (formato simplificado)
  async createQuickEvent(summary: string, date?: Date, duration: number = 60): Promise<CalendarEvent> {
    const startDate = date || new Date()
    const endDate = new Date(startDate.getTime() + duration * 60000) // duration en minutos

    const eventData: CreateEventRequest = {
      summary,
      start: {
        dateTime: startDate.toISOString(),
        timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
      },
      end: {
        dateTime: endDate.toISOString(),
        timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
      },
      reminders: {
        useDefault: true
      }
    }

    return this.createEvent(eventData)
  }

  // Obtener eventos en un rango de fechas específico
  async getEventsInRange(startDate: Date, endDate: Date, calendarId: string = 'primary'): Promise<CalendarEvent[]> {
    return this.getEvents({
      calendarId,
      timeMin: startDate.toISOString(),
      timeMax: endDate.toISOString(),
      singleEvents: true,
      orderBy: 'startTime'
    })
  }

  // ========== MÉTODOS AVANZADOS ==========

  // Gestión de calendarios múltiples
  async createCalendar(calendar: { summary: string; description?: string; timeZone?: string }): Promise<CalendarList> {
    return this.makeCalendarRequest('calendars', 'POST', {}, calendar)
  }

  async updateCalendar(calendarId: string, calendar: Partial<{ summary: string; description?: string; timeZone?: string }>): Promise<CalendarList> {
    return this.makeCalendarRequest(`calendars/${calendarId}`, 'PUT', {}, calendar)
  }

  async deleteCalendar(calendarId: string): Promise<void> {
    await this.makeCalendarRequest(`calendars/${calendarId}`, 'DELETE')
  }

  async clearCalendar(calendarId: string): Promise<void> {
    await this.makeCalendarRequest(`calendars/${calendarId}/clear`, 'POST')
  }

  // Gestión de eventos con funciones avanzadas
  async getEventDetails(eventId: string, calendarId: string = 'primary'): Promise<CalendarEvent> {
    return this.makeCalendarRequest(`calendars/${calendarId}/events/${eventId}`)
  }

  async moveEvent(eventId: string, sourceCalendarId: string, destinationCalendarId: string): Promise<CalendarEvent> {
    return this.makeCalendarRequest(`calendars/${sourceCalendarId}/events/${eventId}/move`, 'POST', {
      destination: destinationCalendarId
    })
  }

  async duplicateEvent(eventId: string, calendarId: string = 'primary'): Promise<CalendarEvent> {
    const originalEvent = await this.getEventDetails(eventId, calendarId)
    
    // Filtrar solo las propiedades compatibles con CreateEventRequest
    const eventData: CreateEventRequest = {
      summary: `Copy of ${originalEvent.summary}`,
      description: originalEvent.description,
      location: originalEvent.location,
      start: originalEvent.start,
      end: originalEvent.end,
      colorId: originalEvent.colorId,
      transparency: originalEvent.transparency,
      visibility: originalEvent.visibility,
      attendees: originalEvent.attendees?.map(att => ({
        email: att.email,
        displayName: att.displayName,
        optional: att.optional
      })),
      recurrence: originalEvent.recurrence,
      reminders: originalEvent.reminders,
      anyoneCanAddSelf: originalEvent.anyoneCanAddSelf,
      guestsCanInviteOthers: originalEvent.guestsCanInviteOthers,
      guestsCanModify: originalEvent.guestsCanModify,
      guestsCanSeeOtherGuests: originalEvent.guestsCanSeeOtherGuests,
      source: originalEvent.source
    }
    
    return this.createEvent(eventData, calendarId)
  }

  // Eventos recurrentes
  async getEventInstances(eventId: string, calendarId: string = 'primary', maxResults: number = 250): Promise<CalendarEvent[]> {
    const response = await this.makeCalendarRequest(`calendars/${calendarId}/events/${eventId}/instances`, 'GET', {
      maxResults: maxResults.toString()
    })
    return response.items || []
  }

  async createRecurringEvent(eventData: CreateEventRequest & { recurrence: string[] }, calendarId: string = 'primary'): Promise<CalendarEvent> {
    return this.createEvent(eventData, calendarId)
  }

  // Invitados y respuestas
  async addAttendees(eventId: string, attendees: Array<{ email: string; optional?: boolean }>, calendarId: string = 'primary'): Promise<CalendarEvent> {
    const event = await this.getEventDetails(eventId, calendarId)
    const currentAttendees = event.attendees || []
    const newAttendees = attendees.map(att => ({
      email: att.email,
      optional: att.optional || false,
      responseStatus: 'needsAction' as const
    }))
    
    return this.updateEvent(eventId, {
      attendees: [...currentAttendees, ...newAttendees]
    }, calendarId)
  }

  async removeAttendee(eventId: string, attendeeEmail: string, calendarId: string = 'primary'): Promise<CalendarEvent> {
    const event = await this.getEventDetails(eventId, calendarId)
    const filteredAttendees = (event.attendees || []).filter(att => att.email !== attendeeEmail)
    
    return this.updateEvent(eventId, {
      attendees: filteredAttendees
    }, calendarId)
  }

  async updateAttendeeResponse(eventId: string, attendeeEmail: string, responseStatus: 'accepted' | 'declined' | 'tentative', calendarId: string = 'primary'): Promise<CalendarEvent> {
    const event = await this.getEventDetails(eventId, calendarId)
    const updatedAttendees = (event.attendees || []).map(att => 
      att.email === attendeeEmail ? { ...att, responseStatus } : att
    )
    
    return this.updateEvent(eventId, {
      attendees: updatedAttendees
    }, calendarId)
  }

  // Google Meet integration
  async addGoogleMeetToEvent(eventId: string, calendarId: string = 'primary'): Promise<CalendarEvent> {
    const conferenceData = {
      createRequest: {
        requestId: `meet-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        conferenceSolutionKey: {
          type: 'hangoutsMeet' as const
        }
      }
    }
    
    return this.updateEvent(eventId, { conferenceData }, calendarId)
  }

  // Free/Busy información
  async getFreeBusy(request: FreeBusyRequest): Promise<FreeBusyResponse> {
    return this.makeCalendarRequest('freeBusy', 'POST', {}, request)
  }

  async isTimeFree(startTime: string, endTime: string, calendarIds: string[] = ['primary']): Promise<boolean> {
    const request: FreeBusyRequest = {
      timeMin: startTime,
      timeMax: endTime,
      items: calendarIds.map(id => ({ id }))
    }
    
    const response = await this.getFreeBusy(request)
    
    // Verificar si hay conflictos en algún calendario
    for (const calendarId of calendarIds) {
      const calendar = response.calendars[calendarId]
      if (calendar?.busy && calendar.busy.length > 0) {
        return false // Hay conflictos
      }
    }
    
    return true // No hay conflictos
  }

  // Colores
  async getColors(): Promise<CalendarColors> {
    return this.makeCalendarRequest('colors')
  }

  async setEventColor(eventId: string, colorId: string, calendarId: string = 'primary'): Promise<CalendarEvent> {
    return this.updateEvent(eventId, { colorId }, calendarId)
  }

  async setCalendarColor(calendarId: string, colorId: string): Promise<CalendarList> {
    return this.makeCalendarRequest(`users/me/calendarList/${calendarId}`, 'PUT', {}, { colorId })
  }

  // Búsquedas avanzadas
  async searchEventsByDate(query: string, startDate: Date, endDate: Date, calendarId: string = 'primary'): Promise<CalendarEvent[]> {
    return this.getEvents({
      calendarId,
      q: query,
      timeMin: startDate.toISOString(),
      timeMax: endDate.toISOString(),
      singleEvents: true,
      orderBy: 'startTime'
    })
  }

  async searchEventsByAttendee(attendeeEmail: string, calendarId: string = 'primary'): Promise<CalendarEvent[]> {
    const events = await this.getEvents({ calendarId })
    return events.filter(event => 
      event.attendees?.some(attendee => attendee.email === attendeeEmail)
    )
  }

  async getEventsByStatus(status: 'confirmed' | 'tentative' | 'cancelled', calendarId: string = 'primary'): Promise<CalendarEvent[]> {
    const events = await this.getEvents({ calendarId })
    return events.filter(event => event.status === status)
  }

  // Recordatorios
  async setEventReminders(eventId: string, reminders: { method: 'email' | 'popup'; minutes: number }[], calendarId: string = 'primary'): Promise<CalendarEvent> {
    return this.updateEvent(eventId, {
      reminders: {
        useDefault: false,
        overrides: reminders
      }
    }, calendarId)
  }

  async setDefaultReminders(eventId: string, calendarId: string = 'primary'): Promise<CalendarEvent> {
    return this.updateEvent(eventId, {
      reminders: { useDefault: true }
    }, calendarId)
  }

  // Archivos adjuntos
  async addAttachment(eventId: string, attachment: { fileUrl: string; title?: string; mimeType?: string }, calendarId: string = 'primary'): Promise<CalendarEvent> {
    const event = await this.getEventDetails(eventId, calendarId)
    const currentAttachments = event.attachments || []
    
    return this.updateEvent(eventId, {
      attachments: [...currentAttachments, attachment]
    }, calendarId)
  }

  // Configuraciones de privacidad
  async setEventPrivacy(eventId: string, visibility: 'default' | 'public' | 'private' | 'confidential', calendarId: string = 'primary'): Promise<CalendarEvent> {
    return this.updateEvent(eventId, { visibility }, calendarId)
  }

  async setEventTransparency(eventId: string, transparent: boolean, calendarId: string = 'primary'): Promise<CalendarEvent> {
    return this.updateEvent(eventId, {
      transparency: transparent ? 'transparent' : 'opaque'
    }, calendarId)
  }

  // Utilidades de fecha
  createAllDayEvent(summary: string, date: Date, description?: string, calendarId: string = 'primary'): Promise<CalendarEvent> {
    const dateString = date.toISOString().split('T')[0]
    const nextDay = new Date(date)
    nextDay.setDate(nextDay.getDate() + 1)
    const endDateString = nextDay.toISOString().split('T')[0]
    
    return this.createEvent({
      summary,
      description,
      start: { date: dateString },
      end: { date: endDateString }
    }, calendarId)
  }

  createTimedEvent(summary: string, startDateTime: Date, endDateTime: Date, description?: string, location?: string, calendarId: string = 'primary'): Promise<CalendarEvent> {
    return this.createEvent({
      summary,
      description,
      location,
      start: { 
        dateTime: startDateTime.toISOString(),
        timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
      },
      end: { 
        dateTime: endDateTime.toISOString(),
        timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
      }
    }, calendarId)
  }

  // Estadísticas y análisis
  async getEventStats(calendarId: string = 'primary', days: number = 30): Promise<{
    totalEvents: number
    confirmedEvents: number
    tentativeEvents: number
    cancelledEvents: number
    eventsWithAttendees: number
    averageEventDuration: number // en minutos
    busyTime: number // en minutos
  }> {
    const endDate = new Date()
    const startDate = new Date()
    startDate.setDate(startDate.getDate() - days)
    
    const events = await this.getEventsInRange(startDate, endDate, calendarId)
    
    let totalDuration = 0
    let busyTime = 0
    
    const stats = {
      totalEvents: events.length,
      confirmedEvents: events.filter(e => e.status === 'confirmed').length,
      tentativeEvents: events.filter(e => e.status === 'tentative').length,
      cancelledEvents: events.filter(e => e.status === 'cancelled').length,
      eventsWithAttendees: events.filter(e => e.attendees && e.attendees.length > 0).length,
      averageEventDuration: 0,
      busyTime: 0
    }
    
    events.forEach(event => {
      if (event.start.dateTime && event.end.dateTime) {
        const duration = new Date(event.end.dateTime).getTime() - new Date(event.start.dateTime).getTime()
        const durationMinutes = duration / (1000 * 60)
        totalDuration += durationMinutes
        
        if (event.transparency !== 'transparent') {
          busyTime += durationMinutes
        }
      }
    })
    
    stats.averageEventDuration = events.length > 0 ? totalDuration / events.length : 0
    stats.busyTime = busyTime
    
    return stats
  }
}

