/**
 * Hook personalizado para gestionar el modo Screen Sharing + YouTube
 * Optimizado para dispositivos móviles
 */

import { useEffect, useState, useCallback } from 'react';

interface UseScreenSharingYouTubeOptions {
  isScreenSharing: boolean;
  isYouTubeActive: boolean;
  isMobile: boolean;
  onYouTubeMiniToggle?: () => void;
  onScreenShareStop?: () => void;
}

interface UseScreenSharingYouTubeReturn {
  isMiniMode: boolean;
  showSpecialControls: boolean;
  panelPosition: { top: number; right: number };
  handleDoubleTab: () => void;
  handleDragStart: (e: React.TouchEvent | React.MouseEvent) => void;
  isTemporarilyExpanded: boolean;
}

export const useScreenSharingYouTube = ({
  isScreenSharing,
  isYouTubeActive,
  isMobile,
  onYouTubeMiniToggle,
  onScreenShareStop,
}: UseScreenSharingYouTubeOptions): UseScreenSharingYouTubeReturn => {
  
  const [isTemporarilyExpanded, setIsTemporarilyExpanded] = useState(false);
  const [panelPosition, setPanelPosition] = useState({ top: 70, right: 10 });
  const [lastTapTime, setLastTapTime] = useState(0);
    // Determinar si debe estar en modo mini
  const isMiniMode = isScreenSharing && isYouTubeActive && isMobile;
  
  // Mostrar controles especiales cuando ambos están activos
  const showSpecialControls = isMiniMode;
  
  // Efecto para preservar YouTube cuando se inicia screen sharing
  useEffect(() => {
    if (isScreenSharing && isYouTubeActive) {
      console.log('🎵📱 Modo Screen Sharing + YouTube activado - manteniendo YouTube activo');
      
      // Manejar errores de red de YouTube durante screen sharing
      const handleYouTubeError = (event: Event) => {
        console.warn('🎵 ⚠️ Error de red de YouTube durante screen sharing (ignorando):', event);
        // Prevenir que estos errores se propaguen y causen problemas
        event.preventDefault();
        event.stopPropagation();
      };
      
      // Agregar listeners para errores de red
      window.addEventListener('error', handleYouTubeError, true);
      window.addEventListener('unhandledrejection', handleYouTubeError, true);
      
      // Cleanup
      return () => {
        window.removeEventListener('error', handleYouTubeError, true);
        window.removeEventListener('unhandledrejection', handleYouTubeError, true);
      };
    }
  }, [isScreenSharing, isYouTubeActive]);
  
  // Manejar doble tap para expandir temporalmente
  const handleDoubleTab = useCallback(() => {
    const now = Date.now();
    const timeSinceLastTap = now - lastTapTime;
    
    if (timeSinceLastTap < 300 && timeSinceLastTap > 0) {
      // Doble tap detectado
      setIsTemporarilyExpanded(prev => !prev);
      
      // Auto-colapsar después de 3 segundos
      if (!isTemporarilyExpanded) {
        setTimeout(() => {
          setIsTemporarilyExpanded(false);
        }, 3000);
      }
    }
    
    setLastTapTime(now);
  }, [lastTapTime, isTemporarilyExpanded]);
  
  // Manejar inicio de arrastre (drag)
  const handleDragStart = useCallback((e: React.TouchEvent | React.MouseEvent) => {
    e.preventDefault();
    
    const startX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const startY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    const startPosition = { ...panelPosition };
    
    const handleMove = (moveEvent: TouchEvent | MouseEvent) => {
      const currentX = 'touches' in moveEvent ? moveEvent.touches[0].clientX : moveEvent.clientX;
      const currentY = 'touches' in moveEvent ? moveEvent.touches[0].clientY : moveEvent.clientY;
      
      const deltaX = currentX - startX;
      const deltaY = currentY - startY;
      
      // Calcular nueva posición
      const newTop = Math.max(10, Math.min(window.innerHeight - 100, startPosition.top + deltaY));
      const newRight = Math.max(10, Math.min(window.innerWidth - 150, startPosition.right - deltaX));
      
      setPanelPosition({ top: newTop, right: newRight });
    };
    
    const handleEnd = () => {
      document.removeEventListener('touchmove', handleMove);
      document.removeEventListener('mousemove', handleMove);
      document.removeEventListener('touchend', handleEnd);
      document.removeEventListener('mouseup', handleEnd);
      
      // Snap a los bordes si está cerca
      setPanelPosition(prev => {
        const snapDistance = 30;
        let newPosition = { ...prev };
        
        if (prev.right < snapDistance) {
          newPosition.right = 10;
        } else if (prev.right > window.innerWidth - 150 - snapDistance) {
          newPosition.right = window.innerWidth - 150;
        }
        
        if (prev.top < snapDistance) {
          newPosition.top = 10;
        } else if (prev.top > window.innerHeight - 100 - snapDistance) {
          newPosition.top = window.innerHeight - 100;
        }
        
        return newPosition;
      });
    };
    
    document.addEventListener('touchmove', handleMove, { passive: false });
    document.addEventListener('mousemove', handleMove);
    document.addEventListener('touchend', handleEnd);
    document.addEventListener('mouseup', handleEnd);
  }, [panelPosition]);
  
  // Ajustar posición en cambios de orientación
  useEffect(() => {
    const handleOrientationChange = () => {
      setTimeout(() => {
        setPanelPosition(prev => ({
          top: Math.min(prev.top, window.innerHeight - 100),
          right: Math.min(prev.right, window.innerWidth - 150)
        }));
      }, 100);
    };
    
    window.addEventListener('orientationchange', handleOrientationChange);
    window.addEventListener('resize', handleOrientationChange);
    
    return () => {
      window.removeEventListener('orientationchange', handleOrientationChange);
      window.removeEventListener('resize', handleOrientationChange);
    };
  }, []);
  
  // Reset estado al salir del modo mini
  useEffect(() => {
    if (!isMiniMode) {
      setIsTemporarilyExpanded(false);
      setPanelPosition({ top: 70, right: 10 });
    }
  }, [isMiniMode]);
  
  // Gestionar teclas de acceso rápido
  useEffect(() => {
    if (!isMiniMode) return;
    
    const handleKeyPress = (e: KeyboardEvent) => {
      // Escape para salir del modo screen sharing
      if (e.key === 'Escape') {
        onScreenShareStop?.();
      }
      
      // Espacio para toggle de YouTube
      if (e.key === ' ' && e.ctrlKey) {
        e.preventDefault();
        onYouTubeMiniToggle?.();
      }
    };
    
    document.addEventListener('keydown', handleKeyPress);
    return () => document.removeEventListener('keydown', handleKeyPress);
  }, [isMiniMode, onScreenShareStop, onYouTubeMiniToggle]);
  
  return {
    isMiniMode,
    showSpecialControls,
    panelPosition,
    handleDoubleTab,
    handleDragStart,
    isTemporarilyExpanded,
  };
};

export default useScreenSharingYouTube;
