import React, { useState, useEffect, useRef, useCallback, memo } from 'react';
import { logger } from '../../utils/logger';
import vegaEmbed from "vega-embed";
import { useLiveAPIContext } from "../../contexts/LiveAPIContext";
import {
  FunctionDeclaration,
  LiveServerToolCall,
  Modality,
  Type,
} from "@google/genai";
import { translations } from "../../i18n/translations";
import { CalendarGeminiService } from "../../services/CalendarGeminiService";

const declaration: FunctionDeclaration = {
  name: "render_altair",
  description: "Display an altair chart in JSON format.",
  parameters: {
    type: Type.OBJECT,
    properties: {
      json_graph: {
        type: Type.STRING,
        description:
          "JSON STRING representation of the chart to render. Must be a string, not a json object",
      },
    },
    required: ["json_graph"],
  },
};

const youtubeDeclaration: FunctionDeclaration = {
  name: "play_youtube_music",
  description: "Search and play music from YouTube when user requests a song.",
  parameters: {
    type: Type.OBJECT,
    properties: {
      query: {
        type: Type.STRING,
        description: "The search query for the song or music (include artist and title when possible)",
      },
      song_title: {
        type: Type.STRING,
        description: "The song title if identifiable",
      },
      artist: {
        type: Type.STRING,
        description: "The artist name if identifiable",
      },
    },
    required: ["query"],
  },
};

const youtubeVolumeDeclaration: FunctionDeclaration = {
  name: "youtube_volume_control",
  description: "Control YouTube player volume through voice commands like 'volume up', 'volume down', 'mute YouTube'.",
  parameters: {
    type: Type.OBJECT,
    properties: {
      action: {
        type: Type.STRING,
        description: "The action to perform: 'up' (increase), 'down' (decrease), 'mute' (mute), 'unmute' (unmute), 'set' (set specific level)",
      },
      level: {
        type: Type.NUMBER,
        description: "Specific volume level (0-100) when action is 'set'",
      },
    },
    required: ["action"],
  },
};

const studyDeclaration: FunctionDeclaration = {
  name: "generate_study_questions",
  description: "Generate interactive study questions based on content provided by user. Can create quizzes, oral exams, flashcards and summaries.",
  parameters: {
    type: Type.OBJECT,
    properties: {
      content: {
        type: Type.STRING,
        description: "The study content from which to generate questions (text extracted from PDF or study material)",
      },
      study_type: {
        type: Type.STRING,
        description: "Type of study: 'quiz' (quiz), 'oral-exam' (oral exam), 'flashcards' (flashcards), 'summary' (interactive summary)",
      },
      difficulty: {
        type: Type.STRING,
        description: "Difficulty level: 'easy', 'medium', 'hard'",
      },
      num_questions: {
        type: Type.NUMBER,
        description: "Number of questions to generate (5-30)",
      },
      focus_areas: {
        type: Type.STRING,
        description: "Specific areas of content to focus on (optional)",
      },
    },
    required: ["content", "study_type", "difficulty", "num_questions"],
  },
};

const studyAnswerDeclaration: FunctionDeclaration = {
  name: "evaluate_study_answer",
  description: "Evaluate student answers and provide detailed educational feedback.",
  parameters: {
    type: Type.OBJECT,
    properties: {
      question: {
        type: Type.STRING,
        description: "The question being evaluated",
      },
      student_answer: {
        type: Type.STRING,
        description: "The answer provided by the student",
      },
      correct_answer: {
        type: Type.STRING,
        description: "The correct or expected answer",
      },
      evaluation_type: {
        type: Type.STRING,
        description: "Type of evaluation: 'semantic', 'exact', 'partial'",
      },
    },
    required: ["question", "student_answer", "correct_answer"],
  },
};

interface AltairProps {
  onMusicRequest?: (query: string) => void;
  onVolumeControl?: (action: string, level?: number) => void;
  onStudyRequest?: (content: string, studyType: string, options?: any) => void;
  onStudyEvaluation?: (question: string, answer: string, correctAnswer: string) => void;
}

function AltairComponent({ onMusicRequest, onVolumeControl, onStudyRequest, onStudyEvaluation }: AltairProps) {
  const [jsonString, setJSONString] = useState<string>("");
  const { client, setConfig, setModel, config } = useLiveAPIContext();
  const t = translations.es;

  useEffect(() => {
    // Obtener configuración de voz actual o usar Zephyr por defecto
    const currentVoiceName = config.speechConfig?.voiceConfig?.prebuiltVoiceConfig?.voiceName || "Zephyr";
    
    // Obtener herramientas del calendario
    const calendarService = CalendarGeminiService.getInstance();
    const calendarTools = calendarService.getCalendarTools();
    
    // Convertir herramientas del calendario al formato FunctionDeclaration
    const calendarDeclarations: FunctionDeclaration[] = calendarTools.map(tool => ({
      name: tool.name,
      description: tool.description,
      parameters: {
        type: Type.OBJECT,
        properties: tool.parameters.properties,
        required: tool.parameters.required
      }
    }));
    
    // Configuración mínima sin instrucciones que interfieran
    setModel("models/gemini-2.5-flash-native-audio-preview-09-2025");
    setConfig({
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { 
          prebuiltVoiceConfig: {
            voiceName: currentVoiceName
          } 
        }
        // NO configurar languageCode - Gemini 2.5 Flash detecta automáticamente
      },
      tools: [
        { googleSearch: {} },
        { functionDeclarations: [
          declaration, 
          youtubeDeclaration, 
          youtubeVolumeDeclaration, 
          studyDeclaration, 
          studyAnswerDeclaration,
          ...calendarDeclarations
        ] },
      ],
    });
    
    logger.log(`✅ VOXIA - Configuración cargada con voz: ${currentVoiceName} (detección automática de idioma)`);
    logger.log(`📅 VOXIA - Herramientas del calendario agregadas: ${calendarDeclarations.map(d => d.name).join(', ')}`);
  }, [setModel, setConfig]);

  useEffect(() => {
    const onToolCall = (toolCall: LiveServerToolCall) => {
      if (!toolCall.functionCalls) {
        return;
      }
      
      // Handle Altair charts
      const altairFC = toolCall.functionCalls.find(
        (fc) => fc.name === declaration.name
      );
      if (altairFC) {
        const str = (altairFC.args as any).json_graph;
        setJSONString(str);
        console.log('📊 Rendering Altair chart');
      }
      
      // Handle YouTube music requests
      const youtubeFC = toolCall.functionCalls.find(
        (fc) => fc.name === youtubeDeclaration.name
      );
      if (youtubeFC && onMusicRequest) {
        const query = (youtubeFC.args as any).query;
        const songTitle = (youtubeFC.args as any).song_title;
        const artist = (youtubeFC.args as any).artist;
        
        console.log('🎵 Music request:', { query, songTitle, artist });
        
        // Build optimized query
        let searchQuery = query;
        if (artist && songTitle) {
          searchQuery = `${artist} ${songTitle}`;
        }
        
        onMusicRequest(searchQuery);
      }
      
      // Handle YouTube volume control
      const volumeFC = toolCall.functionCalls.find(
        (fc) => fc.name === youtubeVolumeDeclaration.name
      );
      if (volumeFC && onVolumeControl) {
        const action = (volumeFC.args as any).action;
        const level = (volumeFC.args as any).level;
        
        console.log('🔊 YouTube volume control:', { action, level });
        
        onVolumeControl(action, level);
      }
      
      // Handle study question generation
      const studyFC = toolCall.functionCalls.find(
        (fc) => fc.name === studyDeclaration.name
      );
      if (studyFC && onStudyRequest) {
        const content = (studyFC.args as any).content;
        const studyType = (studyFC.args as any).study_type;
        const difficulty = (studyFC.args as any).difficulty;
        const numQuestions = (studyFC.args as any).num_questions;
        const focusAreas = (studyFC.args as any).focus_areas;
        
        console.log('📚 Generating study:', { content, studyType, difficulty, numQuestions });
        
        onStudyRequest(content, studyType, {
          difficulty,
          numQuestions,
          focusAreas
        });
      }
      
      // Handle study answer evaluation
      const studyAnswerFC = toolCall.functionCalls.find(
        (fc) => fc.name === studyAnswerDeclaration.name
      );
      if (studyAnswerFC && onStudyEvaluation) {
        const question = (studyAnswerFC.args as any).question;
        const studentAnswer = (studyAnswerFC.args as any).student_answer;
        const correctAnswer = (studyAnswerFC.args as any).correct_answer;
        const evaluationType = (studyAnswerFC.args as any).evaluation_type;
        
        console.log('📝 Evaluating answer:', { question, studentAnswer, correctAnswer });
        
        onStudyEvaluation(question, studentAnswer, correctAnswer);
      }
      
      // Handle calendar tools
      const calendarService = CalendarGeminiService.getInstance();
      const calendarFC = toolCall.functionCalls.find(
        (fc) => fc.name && ['leer_calendario', 'crear_tarea', 'crear_evento'].includes(fc.name)
      );
      if (calendarFC && calendarFC.name) {
        console.log('📅 Calendar tool called:', calendarFC.name, calendarFC.args);
        
        // Execute calendar tool asynchronously and send response
        calendarService.executeCalendarTool(calendarFC.name, calendarFC.args)
          .then(result => {
            console.log('📅 Calendar tool result:', result);
            client.sendToolResponse({
              functionResponses: [{
                response: { 
                  output: { 
                    success: true,
                    message: result
                  } 
                },
                id: calendarFC.id,
                name: calendarFC.name,
              }]
            });
          })
          .catch(error => {
            console.error('📅 Calendar tool error:', error);
            client.sendToolResponse({
              functionResponses: [{
                response: { 
                  output: { 
                    success: false,
                    message: `Error: ${error.message}`
                  } 
                },
                id: calendarFC.id,
                name: calendarFC.name,
              }]
            });
          });
        
        // Return early to avoid the general response below
        return;
      }
      
      // Send confirmation response for all tools
      if (toolCall.functionCalls.length) {
        setTimeout(
          () =>
            client.sendToolResponse({
              functionResponses: toolCall.functionCalls?.map((fc) => ({
                response: { 
                  output: { 
                    success: true,
                    message: fc.name === youtubeDeclaration.name ? 
                      'Searching and playing music...' : 
                      'Processing request...'
                  } 
                },
                id: fc.id,
                name: fc.name,
              })),
            }),
          200
        );
      }
    };
    client.on("toolcall", onToolCall);
    return () => {
      client.off("toolcall", onToolCall);
    };
  }, [client, onMusicRequest, onVolumeControl, onStudyRequest, onStudyEvaluation]);

  // Manejar eventos de voz del panel de estudio
  useEffect(() => {
    const handleStudyVoiceInteraction = (event: Event) => {
      const customEvent = event as CustomEvent;
      const { message } = customEvent.detail;
      console.log('🎤 Mensaje de voz del panel de estudio recibido:', message);
      
      // Enviar el mensaje directamente a VOXIA
      if (client && message) {
        // Enviar como mensaje de usuario para que VOXIA responda
        client.send([{ text: message }]);
      }
    };

    // Escuchar eventos de voz del panel de estudio
    window.addEventListener('studyVoiceInteraction', handleStudyVoiceInteraction);
    
    return () => {
      window.removeEventListener('studyVoiceInteraction', handleStudyVoiceInteraction);
    };
  }, [client]);

  const embedRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (embedRef.current && jsonString) {
      console.log("Renderizando gráfico:", jsonString);
      try {
        vegaEmbed(embedRef.current, JSON.parse(jsonString));
      } catch (error) {
        console.error("Error al renderizar gráfico:", error);
      }
    }
  }, [embedRef, jsonString]);

  return (
    <div className="vega-embed" ref={embedRef} title="Gráfico generado por IA" />
  );
}

export const Altair = memo(AltairComponent);
