/**
 * Servicio para manejar la configuración personalizada de API keys del usuario
 * Permite que los usuarios usen sus propias API keys de Gemini
 */

export interface ApiConfiguration {
  useCustomGeminiKey: boolean;
  customGeminiKey: string;
  lastValidated?: Date;
  isValid?: boolean;
}

class ApiConfigService {
  private static instance: ApiConfigService;
  private readonly STORAGE_KEY = 'voxia_api_config';
  private readonly DEFAULT_GEMINI_KEY = process.env.REACT_APP_GEMINI_API_KEY || '';
  private lastValidationTime = 0;
  private readonly VALIDATION_COOLDOWN = 3000; // 3 segundos entre validaciones
  
  private constructor() {}

  static getInstance(): ApiConfigService {
    if (!ApiConfigService.instance) {
      ApiConfigService.instance = new ApiConfigService();
    }
    return ApiConfigService.instance;
  }

  /**
   * Obtiene la configuración actual de API del usuario
   */
  getApiConfig(): ApiConfiguration {
    try {
      const stored = localStorage.getItem(this.STORAGE_KEY);
      if (stored) {
        const config = JSON.parse(stored);
        // Convertir fecha string de vuelta a Date si existe
        if (config.lastValidated) {
          config.lastValidated = new Date(config.lastValidated);
        }
        return config;
      }
    } catch (error) {
      console.error('Error al leer configuración de API:', error);
    }
    
    return {
      useCustomGeminiKey: false,
      customGeminiKey: '',
      isValid: false
    };
  }

  /**
   * Guarda la configuración de API del usuario
   */
  saveApiConfig(config: ApiConfiguration): void {
    try {
      localStorage.setItem(this.STORAGE_KEY, JSON.stringify(config));
      
      // Disparar evento para notificar cambios en la misma pestaña
      window.dispatchEvent(new CustomEvent('voxia-api-config-changed'));
    } catch (error) {
      console.error('Error al guardar configuración de API:', error);
    }
  }

  /**
   * Obtiene la API key efectiva que se debe usar (personalizada o del sistema)
   */
  getEffectiveGeminiKey(): string {
    const config = this.getApiConfig();
    
    if (config.useCustomGeminiKey && config.customGeminiKey && config.isValid) {
      return config.customGeminiKey;
    }
    
    return this.DEFAULT_GEMINI_KEY;
  }

  /**
   * Valida una API key de Gemini usando el endpoint de modelos (más eficiente)
   */
  async validateGeminiKey(apiKey: string): Promise<boolean> {
    if (!apiKey || !apiKey.startsWith('AIzaSy')) {
      return false;
    }

    // Verificar si ya se validó recientemente para evitar rate limiting
    const lastValidation = localStorage.getItem(`voxia_api_validation_${apiKey.substring(0, 20)}`);
    if (lastValidation) {
      const validationTime = parseInt(lastValidation);
      const timeSinceValidation = Date.now() - validationTime;
      // Si se validó en los últimos 5 minutos, considerarla válida
      if (timeSinceValidation < 5 * 60 * 1000) {
        console.log('✅ API key validada recientemente, usando cache');
        return true;
      }
    }

    try {
      // Usar endpoint de listar modelos en lugar de generar contenido (más eficiente y menos limitado)
      const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models?key=${apiKey}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        }
      });

      if (response.ok) {
        // Guardar timestamp de validación exitosa
        localStorage.setItem(`voxia_api_validation_${apiKey.substring(0, 20)}`, Date.now().toString());
        console.log('✅ API key validada exitosamente');
        return true;
      } else if (response.status === 429) {
        // Rate limit - consideramos que la key es válida pero está limitada
        console.warn('⚠️ API key válida pero con rate limiting activo');
        localStorage.setItem(`voxia_api_validation_${apiKey.substring(0, 20)}`, Date.now().toString());
        return true;
      } else {
        console.error('❌ API key inválida:', response.status, response.statusText);
        return false;
      }
    } catch (error) {
      console.error('❌ Error al validar API key:', error);
      // En caso de error de red, asumir que la key podría ser válida
      return true;
    }
  }

  /**
   * Actualiza la API key personalizada y la valida
   */
  async updateCustomGeminiKey(apiKey: string, useCustom: boolean = true): Promise<boolean> {
    const config = this.getApiConfig();
    
    if (!useCustom) {
      config.useCustomGeminiKey = false;
      config.customGeminiKey = '';
      config.isValid = false;
      config.lastValidated = new Date();
      this.saveApiConfig(config);
      return true;
    }

    if (!apiKey.trim()) {
      return false;
    }

    // Verificar rate limiting
    const now = Date.now();
    if (now - this.lastValidationTime < this.VALIDATION_COOLDOWN) {
      console.warn('⏳ Rate limiting: Espera antes de validar otra API key');
      return false;
    }

    this.lastValidationTime = now;
    const isValid = await this.validateGeminiKey(apiKey);
    
    config.customGeminiKey = apiKey;
    config.useCustomGeminiKey = isValid;
    config.isValid = isValid;
    config.lastValidated = new Date();
    
    this.saveApiConfig(config);
    return isValid;
  }

  /**
   * Elimina la configuración personalizada y vuelve a la del sistema
   */
  resetToDefault(): void {
    try {
      localStorage.removeItem(this.STORAGE_KEY);
      
      // Disparar evento para notificar cambios
      window.dispatchEvent(new CustomEvent('voxia-api-config-changed'));
    } catch (error) {
      console.error('Error al resetear configuración:', error);
    }
  }

  /**
   * Verifica si hay una API key del sistema disponible
   */
  hasSystemApiKey(): boolean {
    return !!this.DEFAULT_GEMINI_KEY;
  }

  /**
   * Obtiene el estado actual de configuración para mostrar en UI
   */
  getConfigStatus(): {
    hasSystemKey: boolean;
    hasCustomKey: boolean;
    usingCustomKey: boolean;
    isCustomValid: boolean;
    lastValidated?: Date;
  } {
    const config = this.getApiConfig();
    
    return {
      hasSystemKey: this.hasSystemApiKey(),
      hasCustomKey: !!config.customGeminiKey,
      usingCustomKey: config.useCustomGeminiKey && (config.isValid || false),
      isCustomValid: config.isValid || false,
      lastValidated: config.lastValidated
    };
  }
}

export default ApiConfigService.getInstance();