import React, { useState, useEffect, useRef } from 'react';
import { RiCloseLine, RiSearchLine, RiPlayLine, RiPauseLine, RiDragMove2Line } from 'react-icons/ri';
import { YouTubeService } from '../../services/YouTubeService';
import { useAutoplayInstant } from '../../hooks/useAutoplayInstant';
import { useDraggablePanel } from '../../hooks/useDraggablePanel';
import { AutoplayNotification } from '../autoplay-notification/AutoplayNotification';
import { logger } from '../../utils/logger';
import './youtube-panel.scss';

interface YouTubePanelProps {
  isVisible: boolean;
  onClose: () => void;
  searchQuery?: string;
  isMinimized?: boolean;
  onMinimize?: () => void;
  position?: 'left' | 'right';
  isRepositioned?: boolean; // For static repositioning needs, e.g., due to fixed sidebars
  isScreenSharingMode?: boolean;
  miniModePosition?: { top: number; right: number };
  onDoubleTab?: () => void;
  onDragStart?: (e: React.TouchEvent | React.MouseEvent) => void;
  isTemporarilyExpanded?: boolean;
  onVolumeChange?: (volume: number) => void;
}

export const YouTubePanel: React.FC<YouTubePanelProps> = ({
  isVisible,
  onClose,
  searchQuery = '',
  isMinimized = false,
  onMinimize,
  position = 'right',
  isRepositioned = false,
  isScreenSharingMode = false,
  miniModePosition = { top: 70, right: 10 },
  onDoubleTab = () => {},
  onDragStart = () => {},
  isTemporarilyExpanded = false,
  onVolumeChange = () => {}
}) => {
  const [currentVideoUrl, setCurrentVideoUrl] = useState<string>('');
  const [searchInput, setSearchInput] = useState<string>(searchQuery);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const [isMobile, setIsMobile] = useState<boolean>(false);
  const [volume, setVolume] = useState<number>(50);
  const [isMuted, setIsMuted] = useState<boolean>(false);
  const [previousVolume, setPreviousVolume] = useState<number>(50);
  
  // ============ ESTADOS PARA AUTOPLAY ============
  const [currentVideoData, setCurrentVideoData] = useState<any>(null);
  const [nextVideoTitle, setNextVideoTitle] = useState<string>('');
  const [showNextVideoAlert, setShowNextVideoAlert] = useState<boolean>(false);
  const [videoStartTime, setVideoStartTime] = useState<number>(0);
  const [autoplayTimer, setAutoplayTimer] = useState<NodeJS.Timeout | null>(null);
  
  // ============ NUEVOS ESTADOS PARA DETECCIÓN REAL ============
  const [videoHistory, setVideoHistory] = useState<string[]>([]); // Historial de IDs reproducidos
  const [videoDuration, setVideoDuration] = useState<number>(0); // Duración del video actual
  const [currentTime, setCurrentTime] = useState<number>(0); // Tiempo actual de reproducción
  const [isVideoEnded, setIsVideoEnded] = useState<boolean>(false); // Si el video terminó
  const [progressCheckTimer, setProgressCheckTimer] = useState<NodeJS.Timeout | null>(null);
  
  const iframeRef = useRef<HTMLIFrameElement>(null);

  // Hook de autoplay INSTANTÁNEO integrado
  const { 
    autoplayService,
    startRandomMusic,
    setCurrentVideo: setAutoplayCurrentVideo,
    getState: getAutoplayState,
    subscribe: subscribeToAutoplay
  } = useAutoplayInstant();
  const searchInputRef = useRef<HTMLInputElement>(null);

  // === INICIAR MÚSICA ALEATORIA SOLO CUANDO EL USUARIO LO SOLICITE ===
  // Se elimina el inicio automático para optimizar recursos
  // La música aleatoria solo se iniciará cuando:
  // 1. El usuario haga clic en el botón de música aleatoria
  // 2. El usuario busque específicamente música
  // 3. Se termine un video y esté habilitado el autoplay

  // Hook para drag & drop (exactamente igual que StudyPanel)
  const initialPosition = position === 'left' ? { x: 25, y: 80 } : { x: window.innerWidth - 355, y: 80 };
  const { panelStyle, dragHandleProps, isDragging } = useDraggablePanel(
    initialPosition,
    !isMobile && !isScreenSharingMode // Solo habilitado en desktop y no en screen sharing
  );

  // Detectar móvil (igual que StudyPanel)
  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth <= 768);
    };
    
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  // Función para enviar comando de volumen al iframe de YouTube
  const sendVolumeCommand = (newVolume: number) => {
    if (iframeRef.current && currentVideoUrl) {
      const command = {
        event: 'command',
        func: 'setVolume',
        args: [newVolume]
      };
      iframeRef.current.contentWindow?.postMessage(JSON.stringify(command), '*');
      onVolumeChange(newVolume);
    }
  };

  // Función para silenciar/activar sonido
  const toggleMute = () => {
    if (iframeRef.current && currentVideoUrl) {
      if (isMuted) {
        // Activar sonido
        setVolume(previousVolume);
        sendVolumeCommand(previousVolume);
        setIsMuted(false);
      } else {
        // Silenciar
        setPreviousVolume(volume);
        setVolume(0);
        sendVolumeCommand(0);
        setIsMuted(true);
      }
    }
  };

  // Función para cambiar volumen
  const handleVolumeChange = (newVolume: number) => {
    setVolume(newVolume);
    sendVolumeCommand(newVolume);
    if (newVolume > 0 && isMuted) {
      setIsMuted(false);
    }
  };

  // Función para controlar volumen via comandos de voz (será llamada desde el componente padre)
  const handleVoiceVolumeControl = (action: string, level?: number) => {
    switch (action) {
      case 'up':
        const newVolumeUp = Math.min(volume + 10, 100);
        handleVolumeChange(newVolumeUp);
        break;
      case 'down':
        const newVolumeDown = Math.max(volume - 10, 0);
        handleVolumeChange(newVolumeDown);
        break;
      case 'mute':
        toggleMute();
        break;
      case 'unmute':
        if (isMuted) {
          toggleMute();
        }
        break;
      case 'set':
        if (level !== undefined) {
          const clampedLevel = Math.max(0, Math.min(100, level));
          handleVolumeChange(clampedLevel);
        }
        break;
    }
  };

  // Exponer la función al componente padre
  useEffect(() => {
    if (typeof onVolumeChange === 'function') {
      // Guardamos la referencia de la función de control de volumen
      (window as any).youtubeVolumeControl = handleVoiceVolumeControl;
    }
  }, [volume, isMuted, previousVolume]);

  // Actualizar input cuando cambia searchQuery
  useEffect(() => {
    if (searchQuery) {
      setSearchInput(searchQuery);
      handleSearch(searchQuery);
    }
  }, [searchQuery]);

  // DEBUG: Monitorear cambios en currentVideoUrl
  useEffect(() => {
    logger.log('🎯 currentVideoUrl cambió:', currentVideoUrl);
    if (currentVideoUrl) {
      logger.log('✅ Video URL establecida, iframe debería renderizarse');
    } else {
      logger.log('⚠️ currentVideoUrl está vacía, iframe no se renderizará');
    }
  }, [currentVideoUrl]);

  // DEBUG: Monitorear estado de loading
  useEffect(() => {
    logger.log('⏳ isLoading cambió:', isLoading);
  }, [isLoading]);

  // Focus en search input cuando se abre el panel
  useEffect(() => {
    if (isVisible && !isMinimized && searchInputRef.current) {
      setTimeout(() => {
        searchInputRef.current?.focus();
      }, 100);
    }
  }, [isVisible, isMinimized]);

  // Cleanup de timers cuando se cierra el componente
  useEffect(() => {
    return () => {
      if (autoplayTimer) {
        clearTimeout(autoplayTimer);
      }
      if (progressCheckTimer) {
        clearInterval(progressCheckTimer);
      }
      setShowNextVideoAlert(false);
    };
  }, [autoplayTimer, progressCheckTimer]);

  // ========== LISTENER PARA AUTOPLAY SERVICE AUTOMÁTICO ==========
  useEffect(() => {
    const handleAutoplayChange = (event: CustomEvent) => {
      const { video } = event.detail;
      
      // VERIFICAR que video no sea null
      if (!video || !video.id) {
        logger.warn('🎵 ⚠️ Video data inválida recibida:', video);
        return;
      }
      
      logger.log('🎵 ⚡ AUTOPLAY AUTOMÁTICO detectado en Panel:', video.title || video.id);
      
      // Extraer ID del video y construir URL
      const embedUrl = `https://www.youtube.com/embed/${video.id}?autoplay=1&enablejsapi=1&origin=${encodeURIComponent(window.location.origin)}&playsinline=1&rel=0&showinfo=0&modestbranding=1&fs=1&cc_load_policy=0&iv_load_policy=3&widget_referrer=${encodeURIComponent(window.location.href)}`;
      
      // Cambiar video INMEDIATAMENTE
      setCurrentVideoUrl(embedUrl);
      setIsPlaying(true);
      
      // Limpiar timers previos
      if (autoplayTimer) {
        clearTimeout(autoplayTimer);
        setAutoplayTimer(null);
      }
      if (progressCheckTimer) {
        clearInterval(progressCheckTimer);
        setProgressCheckTimer(null);
      }
      
      logger.log('🎵 ⚡ Transición automática COMPLETADA a:', video.title);
    };

    window.addEventListener('autoplay-video-change', handleAutoplayChange as EventListener);
    
    return () => {
      window.removeEventListener('autoplay-video-change', handleAutoplayChange as EventListener);
    };
  }, [autoplayTimer, progressCheckTimer]);

  // ========== LISTENER PARA DETECTAR FINAL REAL DEL VIDEO ==========
  useEffect(() => {
    const handleYouTubeMessage = async (event: MessageEvent) => {
      if (event.origin !== 'https://www.youtube.com') return;
      
      try {
        const data = JSON.parse(event.data);
        
        // Detectar cuando el video termina
        if (data.event === 'video-ended' || data.info === 0) {
          logger.log('🎵 📺 VIDEO TERMINÓ VIA MESSAGE - AutoplayService lo manejará automáticamente');
          // No ejecutar autoplay manual, el AutoplayService lo maneja automáticamente
        }
      } catch (error) {
        // Mensaje no es JSON válido, ignorar
      }
    };

    // Listener para evento personalizado de YouTube
    const handleCustomVideoEnd = async (event: CustomEvent) => {
      logger.log('🎵 � VIDEO TERMINÓ VIA CUSTOM EVENT - Iniciando autoplay...');
      await executeAutoplay();
    };

    // Función para ejecutar autoplay cuando termine el video
    const executeAutoplay = async () => {
      if (!currentVideoData) return;
      
      try {
        logger.log('🎵 🔄 EJECUTANDO AUTOPLAY REAL AL FINAL DEL VIDEO...');
        
        // Limpiar timer de progreso si existe
        if (progressCheckTimer) {
          clearInterval(progressCheckTimer);
          setProgressCheckTimer(null);
        }
        
        // Buscar siguiente video evitando repetidos
        const searchTerms = [
          currentVideoData.title.split(' ')[0] + ' música',
          currentVideoData.channelTitle + ' canciones', 
          'música popular ' + Math.random().toString(36).substring(7), // Random para variedad
          'top hits español',
          'música latina nueva',
          'reggaeton 2024',
          'pop español'
        ];
        
        let nextVideo = null;
        
        for (const term of searchTerms) {
          const results = await YouTubeService.searchForPlaylist(term, 20);
          nextVideo = results.find((v: any) => 
            v.id !== currentVideoData.id && !videoHistory.includes(v.id)
          );
          if (nextVideo) break;
        }
        
        if (nextVideo) {
          logger.log('🎵 ⚡ REPRODUCIENDO SIGUIENTE AL TERMINAR:', nextVideo.title);
          // Llamar recursivamente para continuar infinitamente
          await handleSearch(nextVideo.title);
        } else {
          logger.log('🎵 ⚠️ No se encontró video siguiente, limpiando historial...');
          setVideoHistory([]); // Limpiar historial si no encuentra nada
          // Intentar con búsqueda genérica
          await handleSearch('música popular');
        }
      } catch (error) {
        console.error('🎵 ❌ Error en autoplay real:', error);
      }
    };

    // ========== TEMPORALMENTE DESHABILITADO PARA RESTAURAR REPRODUCCIÓN BÁSICA ==========
    // window.addEventListener('message', handleYouTubeMessage);
    
    return () => {
      // window.removeEventListener('message', handleYouTubeMessage);
    };
  }, [currentVideoData, videoHistory, progressCheckTimer]);

  // ========== CALLBACK GLOBAL PARA EVENTOS DE YOUTUBE - TEMPORALMENTE DESHABILITADO ==========
  useEffect(() => {
    // ========== TEMPORALMENTE COMENTADO PARA RESTAURAR REPRODUCCIÓN BÁSICA ==========
    // // Definir callback global para YouTube
    // (window as any).onYouTubePlayerStateChange = (event: any) => {
    //   logger.log('🎵 📺 Estado del video cambió:', event);
    //   
    //   // Estado 0 = video terminó
    //   if (event === 0 || (event.data && event.data === 0)) {
    //     logger.log('🎵 ✅ VIDEO TERMINÓ - Activando autoplay');
    //     setIsVideoEnded(true);
    //     
    //     // Disparar evento personalizado para el listener
    //     window.dispatchEvent(new CustomEvent('youtube-video-ended', {
    //       detail: { videoData: currentVideoData }
    //     }));
    //   }
    // };
    
    return () => {
      // delete (window as any).onYouTubePlayerStateChange;
    };
  }, [currentVideoData]);

  // ========== FUNCIÓN PARA MEJORAR URL CON PARÁMETROS DE EVENTOS ==========
  const enhanceVideoUrlForEvents = (url: string): string => {
    try {
      const urlObj = new URL(url);
      
      // Asegurar parámetros necesarios para detección de eventos
      urlObj.searchParams.set('enablejsapi', '1');
      urlObj.searchParams.set('origin', window.location.origin);
      urlObj.searchParams.set('version', '3');
      urlObj.searchParams.set('playerapiid', 'player_' + Date.now());
      
      // Agregar callback para eventos
      urlObj.searchParams.set('onStateChange', 'onYouTubePlayerStateChange');
      
      logger.log('🎵 🔧 URL mejorada para eventos:', urlObj.toString());
      return urlObj.toString();
    } catch (error) {
      logger.warn('🎵 ⚠️ Error mejorando URL, usando original:', error);
      return url;
    }
  };

  const handleSearch = async (query: string) => {
    if (!query.trim()) return;
    
    logger.log('🔍 Iniciando búsqueda de YouTube:', query);
    setIsLoading(true);
    try {
      logger.log('📡 Llamando a YouTubeService.searchAndPlayForPanel...');
      const result = await YouTubeService.searchAndPlayForPanel(query);
      logger.log('✅ Resultado obtenido:', result);
      
      // Crear objeto de video para el autoplay service
      const videoData = {
        id: result.url.match(/embed\/([^?]+)/)?.[1] || '',
        title: result.title,
        channelTitle: result.channelTitle,
        description: '',
        thumbnail: '',
        duration: '',
        publishedAt: '',
        url: result.url
      };
      
      // INTEGRAR con el AutoplayService para autoplay automático
      setAutoplayCurrentVideo(videoData);
      
      setCurrentVideoUrl(result.url);
      setIsPlaying(true);
      
      logger.log('📺 currentVideoUrl establecida:', result.url);
      logger.log('🎵 ⚡ Video integrado con AutoplayService para reproducción continua');
      
    } catch (error) {
      console.error('❌ Error al buscar video:', error);
    } finally {
      setIsLoading(false);
      logger.log('🔄 isLoading establecido a false');
    }
  };

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    handleSearch(searchInput);
  };

  const handlePlayPause = () => {
    if (iframeRef.current) {
      const iframe = iframeRef.current;
      if (isPlaying) {
        // Pausar - enviamos mensaje al iframe
        iframe.contentWindow?.postMessage('{"event":"command","func":"pauseVideo","args":""}', '*');
      } else {
        // Reproducir - enviamos mensaje al iframe
        iframe.contentWindow?.postMessage('{"event":"command","func":"playVideo","args":""}', '*');
      }
      setIsPlaying(!isPlaying);
    }
  };
  if (!isVisible) return null;

  // Handle double tap for expansion
  const handleDoubleClick = () => {
    if (isScreenSharingMode) {
      onDoubleTab();
    }
  };

  // Handle touch start for drag (mobile)
  const handleTouchStart = (e: React.TouchEvent) => {
    if (isScreenSharingMode) {
      onDragStart(e);
    }
  };

  // Handle mouse down for drag (desktop)
  const handleMouseDown = (e: React.MouseEvent) => {
    if (isScreenSharingMode) {
      onDragStart(e);
    }
  };

  // Inline styles for mini-mode positioning
  const miniModeStyles = isScreenSharingMode ? {
    position: 'fixed' as const,
    top: `${miniModePosition.top}px`,
    right: `${miniModePosition.right}px`,
    zIndex: 1000,
  } : {};

  return (
    <div
      className={`youtube-panel ${position} ${isMinimized ? 'minimized' : ''} ${isMobile ? 'mobile' : ''} ${isScreenSharingMode ? 'mini-mode' : ''} ${isTemporarilyExpanded ? 'temporarily-expanded' : ''} ${isRepositioned ? 'repositioned' : ''} ${isDragging ? 'dragging' : ''} ${!isMobile && !isScreenSharingMode ? 'draggable' : ''}`}
      style={isScreenSharingMode ? miniModeStyles : panelStyle}
      onDoubleClick={handleDoubleClick}
      onTouchStart={handleTouchStart}
      onMouseDown={handleMouseDown}
    >
      {/* Header del panel */}
      <div 
        className="youtube-panel-header"
      >
        <div className="panel-title">
          <span className="youtube-icon">🎵</span>
          <h3>YouTube Player</h3>
          {!isMobile && !isScreenSharingMode && (
            <button 
              {...dragHandleProps}
              className="drag-handle"
              title="Mover panel"
              type="button"
            >
              <RiDragMove2Line />
            </button>
          )}
        </div>
        <div className="panel-controls">
          {onMinimize && (
            <button 
              className="minimize-btn"
              onClick={onMinimize}
              title={isMinimized ? 'Expandir' : 'Minimizar'}
            >
              {isMinimized ? '⬆️' : '⬇️'}
            </button>
          )}
          <button 
            className="close-btn"
            onClick={onClose}
            title="Cerrar"
          >
            <RiCloseLine />
          </button>
        </div>
      </div>      {/* Contenido del panel (oculto cuando está minimizado) */}
      {!isMinimized && (
        <div className="youtube-panel-content">
          {/* Barra de búsqueda - oculta en mini-mode a menos que esté temporalmente expandido */}
          {(!isScreenSharingMode || isTemporarilyExpanded) && (
            <form className="search-form" onSubmit={handleSearchSubmit}>
              <div className="search-input-container">
                <input
                  ref={searchInputRef}
                  type="text"
                  className="search-input"
                  placeholder="Buscar música en YouTube..."
                  value={searchInput}
                  onChange={(e) => setSearchInput(e.target.value)}
                  disabled={isLoading}
                />
                <button 
                  type="submit" 
                  className="search-btn"
                  disabled={isLoading || !searchInput.trim()}
                >
                  {isLoading ? (
                    <div className="loading-spinner">⏳</div>
                  ) : (
                    <RiSearchLine />
                  )}
                </button>
              </div>
            </form>
          )}

          {/* Botón de música aleatoria */}
          {(!isScreenSharingMode || isTemporarilyExpanded) && (
            <div className="random-music-section">
              <button 
                className="random-music-btn"
                onClick={async () => {
                  logger.log('🎵 🎲 Iniciando música aleatoria por botón...');
                  try {
                    if (startRandomMusic) {
                      await startRandomMusic();
                    }
                  } catch (error) {
                    console.error('🎵 ❌ Error con música aleatoria:', error);
                  }
                }}
                disabled={isLoading}
                title="Reproducir música completamente aleatoria"
              >
                🎲 Música Aleatoria
              </button>
            </div>
          )}          {/* Controles de reproducción - siempre visibles pero compactos en mini-mode */}
          {currentVideoUrl && (
            <div className={`playback-controls ${isScreenSharingMode && !isTemporarilyExpanded ? 'mini' : ''}`}>
              <div className="media-controls">
                <button 
                  className="play-pause-btn"
                  onClick={handlePlayPause}
                  title={isPlaying ? 'Pausar' : 'Reproducir'}
                >
                  {isPlaying ? <RiPauseLine /> : <RiPlayLine />}
                </button>
                
                {/* Controles de volumen */}
                <div className="volume-controls">
                  <button 
                    className="mute-btn"
                    onClick={toggleMute}
                    title={isMuted ? 'Activar sonido' : 'Silenciar'}
                  >
                    {isMuted ? '🔇' : volume > 50 ? '🔊' : volume > 0 ? '🔉' : '🔈'}
                  </button>
                  {(!isScreenSharingMode || isTemporarilyExpanded) && (
                    <input
                      type="range"
                      min="0"
                      max="100"
                      value={isMuted ? 0 : volume}
                      onChange={(e) => handleVolumeChange(parseInt(e.target.value))}
                      className="volume-slider"
                      title={`Volumen: ${volume}%`}
                    />
                  )}
                  {(!isScreenSharingMode || isTemporarilyExpanded) && (
                    <span className="volume-label">{volume}%</span>
                  )}
                </div>
              </div>
              
              {(!isScreenSharingMode || isTemporarilyExpanded) && (
                <span className="current-track">
                  🎵 Reproduciendo desde YouTube
                </span>
              )}
            </div>
          )}          {/* Reproductor de video */}
          <div className={`video-container ${isScreenSharingMode ? 'mini-video' : ''}`}>
            {currentVideoUrl ? (
              <iframe
                ref={iframeRef}
                src={currentVideoUrl}
                title="YouTube Player"
                frameBorder="0"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                allowFullScreen
                className="youtube-iframe"
              />
            ) : (
              <div className="placeholder">
                <div className="placeholder-content">
                  <span className="placeholder-icon">🎵</span>
                  {(!isScreenSharingMode || isTemporarilyExpanded) && (
                    <>
                      <p>Busca música para comenzar</p>
                      <small>💡 También puedes pedirle al asistente: "Reproduce [canción]"</small>
                    </>
                  )}
                  {isScreenSharingMode && !isTemporarilyExpanded && (
                    <p>Toca dos veces para expandir</p>
                  )}
                </div>
              </div>
            )}
          </div>

          {/* Indicador visual para mini-mode */}
          {isScreenSharingMode && !isTemporarilyExpanded && (
            <div className="mini-mode-indicator">
              <span>📱</span>
            </div>
          )}

        </div>
      )}

      {/* ============ CUADRO DE SIGUIENTE CANCIÓN ============ */}
      {showNextVideoAlert && nextVideoTitle && (
        <div className="next-video-alert">
          <div className="next-video-content">
            <div className="next-video-icon">🎵</div>
            <div className="next-video-text">
              <div className="next-video-title">A continuación:</div>
              <div className="next-video-name">{nextVideoTitle}</div>
            </div>
            <div className="next-video-animation">▶️</div>
          </div>
        </div>
      )}

      {/* Notificación de autoplay */}
      <AutoplayNotification 
        isVisible={getAutoplayState()?.showNotification || false}
        message={getAutoplayState()?.notificationMessage || ''}
      />
    </div>
  );
};

export default YouTubePanel;
