import React, { createContext, useContext, useEffect, useState } from 'react'
import { Session, User } from '@supabase/supabase-js'
import { supabase } from '../services/supabase'
import { youtubeOAuth } from '../services/youtubeOAuth'
import { googleCalendar } from '../services/googleCalendar'

interface AuthContextType {
  user: User | null
  session: Session | null
  loading: boolean
  hasYouTubeAccess: boolean
  hasCalendarAccess: boolean
  checkingYouTubeAccess: boolean
  checkingCalendarAccess: boolean
  signInWithGoogle: () => Promise<void>
  signInWithYouTube: () => Promise<void>
  signOut: () => Promise<void>
  refreshYouTubeAccess: () => Promise<void>
  refreshCalendarAccess: () => Promise<void>
}

const AuthContext = createContext<AuthContextType | undefined>(undefined)

export function useAuth() {
  const context = useContext(AuthContext)
  if (context === undefined) {
    throw new Error('useAuth debe ser usado dentro de un AuthProvider')
  }
  return context
}

interface AuthProviderProps {
  children: React.ReactNode
}

export function AuthProvider({ children }: AuthProviderProps) {
  const [user, setUser] = useState<User | null>(null)
  const [session, setSession] = useState<Session | null>(null)
  const [loading, setLoading] = useState(true)
  const [hasYouTubeAccess, setHasYouTubeAccess] = useState(false)
  const [hasCalendarAccess, setHasCalendarAccess] = useState(false)
  const [checkingYouTubeAccess, setCheckingYouTubeAccess] = useState(false)
  const [checkingCalendarAccess, setCheckingCalendarAccess] = useState(false)

  const checkYouTubeAccess = async () => {
    if (!session?.provider_token) {
      setHasYouTubeAccess(false)
      return
    }

    setCheckingYouTubeAccess(true)
    try {
      const hasAccess = await youtubeOAuth.checkYouTubeAccess()
      setHasYouTubeAccess(hasAccess)
    } catch (error) {
      console.error('Error verificando acceso a YouTube:', error)
      setHasYouTubeAccess(false)
    } finally {
      setCheckingYouTubeAccess(false)
    }
  }

  const checkCalendarAccess = async () => {
    if (!session?.provider_token) {
      console.log('🗓️ AuthContext: No hay provider_token, hasCalendarAccess = false')
      setHasCalendarAccess(false)
      return
    }

    console.log('🗓️ AuthContext: Verificando acceso a Calendar...')
    setCheckingCalendarAccess(true)
    try {
      const hasAccess = await googleCalendar.checkCalendarAccess()
      console.log('🗓️ AuthContext: Resultado checkCalendarAccess:', hasAccess)
      setHasCalendarAccess(hasAccess)
    } catch (error) {
      console.error('🗓️ AuthContext: Error verificando acceso a Google Calendar:', error)
      setHasCalendarAccess(false)
    } finally {
      setCheckingCalendarAccess(false)
    }
  }

  useEffect(() => {
    // Obtener sesión inicial
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session)
      setUser(session?.user ?? null)
      setLoading(false)
      
      // Verificar acceso a YouTube y Calendar si hay sesión
      if (session?.provider_token) {
        checkYouTubeAccess()
        checkCalendarAccess()
      }
    })

    // Escuchar cambios en la autenticación
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session)
      setUser(session?.user ?? null)
      setLoading(false)
      
      // Verificar acceso a YouTube y Calendar cuando cambie la sesión
      if (session?.provider_token) {
        checkYouTubeAccess()
        checkCalendarAccess()
      } else {
        setHasYouTubeAccess(false)
        setHasCalendarAccess(false)
      }
    })

    return () => subscription.unsubscribe()
  }, [])

  const signInWithGoogle = async () => {
    // Usar scopes combinados de YouTube + Calendar + Profile
    const combinedScopes = process.env.REACT_APP_COMBINED_OAUTH_SCOPES || 
      'openid email profile https://www.googleapis.com/auth/youtube.readonly https://www.googleapis.com/auth/calendar https://www.googleapis.com/auth/calendar.events'
    
    // Obtener URL limpia sin hash para redirección
    const cleanUrl = window.location.origin + window.location.pathname
    
    const { error } = await supabase.auth.signInWithOAuth({
      provider: 'google',
      options: {
        redirectTo: cleanUrl,
        scopes: combinedScopes,
        queryParams: {
          access_type: 'offline',
          prompt: 'consent',
        },
      }
    })
    if (error) {
      console.error('Error al iniciar sesión con Google:', error.message)
      throw error
    }
  }

  const signInWithYouTube = async () => {
    // Usar scopes combinados para incluir también Calendar
    const combinedScopes = process.env.REACT_APP_COMBINED_OAUTH_SCOPES || 
      'openid email profile https://www.googleapis.com/auth/youtube.readonly https://www.googleapis.com/auth/calendar https://www.googleapis.com/auth/calendar.events'
    
    // Obtener URL limpia sin hash para redirección
    const cleanUrl = window.location.origin + window.location.pathname
    
    const { error } = await supabase.auth.signInWithOAuth({
      provider: 'google',
      options: {
        redirectTo: cleanUrl,
        scopes: combinedScopes,
        queryParams: {
          access_type: 'offline',
          prompt: 'consent',
        },
      }
    })
    if (error) {
      console.error('Error al iniciar sesión con YouTube:', error.message)
      throw error
    }
  }

  const signOut = async () => {
    const { error } = await supabase.auth.signOut()
    if (error) {
      console.error('Error al cerrar sesión:', error.message)
      throw error
    }
    // Limpiar estado de YouTube y Calendar al cerrar sesión
    setHasYouTubeAccess(false)
    setHasCalendarAccess(false)
  }

  const refreshYouTubeAccess = async () => {
    await checkYouTubeAccess()
  }

  const refreshCalendarAccess = async () => {
    await checkCalendarAccess()
  }

  const value: AuthContextType = {
    user,
    session,
    loading,
    hasYouTubeAccess,
    hasCalendarAccess,
    checkingYouTubeAccess,
    checkingCalendarAccess,
    signInWithGoogle,
    signInWithYouTube,
    signOut,
    refreshYouTubeAccess,
    refreshCalendarAccess,
  }

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}