/**
 * Servicio de Playlist Personalizada Infinita (sin repeticiones consecutivas)
 * - Carga lista personalizada desde /playlist.json (o fallback /playlist-example.json)
 * - Mezcla (shuffle) los elementos en memoria
 * - Garantiza que no se repita un video hasta que todos hayan sido reproducidos
 * - Reproduce en bucle infinito regenerando un nuevo orden aleatorio al completar un ciclo
 * - Se integra con AutoplayService añadiendo el siguiente video a la cola cuando se requiera
 * - No elimina ni modifica código existente: sólo añade capacidades
 */

import { autoplayService } from './AutoplayService';
import { YouTubeVideo } from './YouTubeService';

interface RawPlaylistItem {
  id: string; // YouTube video ID
  title?: string;
  channelTitle?: string;
  // Campos opcionales extendibles
}

interface PlaylistConfig {
  sourceUrl?: string; // URL remota opcional para cargar playlist
  localPath?: string; // Ruta local en public
  autoStart?: boolean; // Si debe iniciar inmediatamente
  preloadNext?: boolean; // Si se añade automáticamente next a la cola
}

export class CustomPlaylistService {
  private static instance: CustomPlaylistService | null = null;
  private playlist: RawPlaylistItem[] = [];
  private currentCycle: string[] = []; // IDs en el orden actual barajado
  private position = 0;
  private initialized = false;
  private config: PlaylistConfig;
  private loading = false;

  private constructor(config?: PlaylistConfig) {
    this.config = {
      sourceUrl: undefined,
      localPath: '/playlist.json',
      autoStart: true,
      preloadNext: true,
      ...(config || {})
    };

    // Suscribirse a cambios de Autoplay para saber qué video se está reproduciendo
    autoplayService.subscribe(state => {
      if (state.currentVideo) {
        // Si el video actual coincide con uno gestionado por nosotros, preparar el siguiente
        if (this.config.preloadNext) {
          this.ensureQueued();
        }
      }
    });
  }

  public static getInstance(config?: PlaylistConfig) {
    if (!this.instance) {
      this.instance = new CustomPlaylistService(config);
    }
    return this.instance;
  }

  /**
   * Inicializar (idempotente)
   */
  public async init() {
    if (this.initialized || this.loading) return;
    this.loading = true;
    try {
      await this.loadPlaylist();
      this.shuffleNewCycle();
      this.initialized = true;

      if (this.config.autoStart) {
        // Establecer primer video si no hay uno actual
        const state = autoplayService.getState();
        if (!state.currentVideo) {
          const first = this.buildYouTubeVideo(this.currentCycle[0]);
          autoplayService.setCurrentVideo(first);
          this.position = 1; // siguiente posición
        } else {
          // Garantizar que el siguiente esté en cola
          this.ensureQueued();
        }
      }
    } catch (e) {
      console.error('🎵 ❌ Error inicializando CustomPlaylistService:', e);
    } finally {
      this.loading = false;
    }
  }

  /**
   * Cargar playlist desde localPath o fallback example
   */
  private async loadPlaylist() {
    const sources: string[] = [];
    if (this.config.localPath) sources.push(this.config.localPath);
    sources.push('/playlist-example.json'); // fallback

    for (const url of sources) {
      try {
        const res = await fetch(url, { cache: 'no-store' });
        if (res.ok) {
          const data = await res.json();
          if (Array.isArray(data) && data.length > 0) {
            this.playlist = data.filter(item => item.id);
            console.log('🎵 ✅ Playlist cargada:', url, 'Items:', this.playlist.length);
            return;
          }
        }
      } catch (err) {
        console.warn('🎵 ⚠️ No se pudo cargar playlist desde', url, err);
      }
    }

    if (this.playlist.length === 0) {
      console.warn('🎵 ⚠️ Playlist vacía, no se podrá iniciar reproducción personalizada');
    }
  }

  /**
   * Crear nuevo ciclo aleatorio sin repetir hasta finalizar ciclo
   */
  private shuffleNewCycle() {
    const ids = this.playlist.map(p => p.id);
    this.currentCycle = this.shuffle(ids);
    this.position = 0;
    console.log('🎵 🔁 Nuevo ciclo barajado generado (longitud:', this.currentCycle.length, ')');
  }

  private shuffle<T>(arr: T[]): T[] {
    const copy = [...arr];
    for (let i = copy.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [copy[i], copy[j]] = [copy[j], copy[i]];
    }
    return copy;
  }

  /**
   * Asegurar que hay un siguiente video en la cola del autoplay service
   */
  private ensureQueued() {
    const state = autoplayService.getState();
    if (state.nextVideo || state.queue.length > 0) return; // ya hay algo

    const next = this.getNextVideo();
    if (next) {
      autoplayService.addToQueue(next);
      console.log('🎵 ➡️ Siguiente video añadido desde CustomPlaylistService:', next.title);
    }
  }

  /**
   * Obtener siguiente video (y avanzar posición)
   */
  private getNextVideo(): YouTubeVideo | null {
    if (this.currentCycle.length === 0) return null;

    if (this.position >= this.currentCycle.length) {
      // Empezar nuevo ciclo infinito
      this.shuffleNewCycle();
    }
    const id = this.currentCycle[this.position];
    this.position += 1;
    return this.buildYouTubeVideo(id);
  }

  private buildYouTubeVideo(id: string): YouTubeVideo {
    const meta = this.playlist.find(p => p.id === id);
    const thumbBase = `https://i.ytimg.com/vi/${id}`;
    // Construir objeto cumpliendo con interface YouTubeVideo usada en el proyecto
    const video: YouTubeVideo = {
      id,
      title: meta?.title || `Video ${id}`,
      channelTitle: meta?.channelTitle || 'Personalizado',
      description: '',
      publishedAt: new Date().toISOString(),
      thumbnail: `${thumbBase}/hqdefault.jpg`,
      duration: 'N/A',
      url: `https://www.youtube.com/watch?v=${id}`
    } as YouTubeVideo;
    return video;
  }
}

