/**
 * Sistema de logging centralizado para VOXIA
 * En producción, todos los logs están deshabilitados por seguridad
 */

class Logger {
  private isDevelopment: boolean;

  constructor() {
    this.isDevelopment = process.env.NODE_ENV === 'development';
    
    if (!this.isDevelopment) {
      // Mensaje único de advertencia en producción
      console.warn('🔒 VOXIA - Console deshabilitada por seguridad. Solo para desarrolladores y usuarios maliciosos.');
    }
  }

  log(...args: any[]) {
    if (this.isDevelopment) {
      console.log(...args);
    }
  }

  warn(...args: any[]) {
    if (this.isDevelopment) {
      console.warn(...args);
    }
  }

  error(...args: any[]) {
    if (this.isDevelopment) {
      console.error(...args);
    }
  }

  info(...args: any[]) {
    if (this.isDevelopment) {
      console.info(...args);
    }
  }

  debug(...args: any[]) {
    if (this.isDevelopment) {
      console.debug(...args);
    }
  }
}

// Instancia global del logger
export const logger = new Logger();

// Exportar métodos directamente para fácil uso
export const { log, warn, error, info, debug } = logger;