/**
 * Componente de verificación de variables de entorno
 * Para debug y validación de configuración
 */

import React, { useState, useEffect } from 'react';
import YouTubeService from '../../services/YouTubeService';

export const EnvChecker: React.FC = () => {
  const [isVisible, setIsVisible] = useState(true);
  const [youtubeServiceStatus, setYoutubeServiceStatus] = useState<string>('Verificando...');
  
  const geminiKey = process.env.REACT_APP_GEMINI_API_KEY;
  const youtubeKey = process.env.REACT_APP_YOUTUBE_API_KEY;

  useEffect(() => {
    // Verificar que el servicio de YouTube se pueda instanciar
    try {
      const service = new YouTubeService();
      setYoutubeServiceStatus('✅ Servicio inicializado correctamente');
    } catch (error) {
      setYoutubeServiceStatus(`❌ Error: ${error}`);
    }
    
    // Agregar listener para ocultar/mostrar con Ctrl+Shift+E
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.ctrlKey && event.shiftKey && event.key.toLowerCase() === 'e') {
        event.preventDefault();
        setIsVisible(prev => !prev);
      }
    };
    
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, []);

  if (!isVisible) return null;

  return (
    <div style={{
      position: 'fixed',
      top: '10px',
      right: '10px',
      background: 'rgba(0,0,0,0.9)',
      color: 'white',
      padding: '15px',
      borderRadius: '8px',
      fontSize: '12px',
      zIndex: 9999,
      border: '1px solid #333',
      maxWidth: '350px',
      fontFamily: 'monospace'
    }}>
      <h4 style={{ margin: '0 0 10px 0', color: '#4CAF50' }}>
        🔧 Diagnóstico del Sistema
      </h4>
      
      <div style={{ marginBottom: '8px' }}>
        <span style={{ color: geminiKey ? '#4CAF50' : '#f44336' }}>●</span>
        {' '}GEMINI_API_KEY: {geminiKey ? '✅ Configurada' : '❌ No configurada'}
        {geminiKey && <div style={{ fontSize: '10px', color: '#ccc', marginLeft: '15px' }}>
          {geminiKey.substring(0, 15)}...
        </div>}
      </div>
      
      <div style={{ marginBottom: '8px' }}>
        <span style={{ color: youtubeKey ? '#4CAF50' : '#f44336' }}>●</span>
        {' '}YOUTUBE_API_KEY: {youtubeKey ? '✅ Configurada' : '❌ No configurada'}
        {youtubeKey && <div style={{ fontSize: '10px', color: '#ccc', marginLeft: '15px' }}>
          {youtubeKey.substring(0, 15)}...
        </div>}
      </div>
      
      <div style={{ marginBottom: '8px' }}>
        <span style={{ color: youtubeServiceStatus.includes('✅') ? '#4CAF50' : '#f44336' }}>●</span>
        {' '}YouTube Service: {youtubeServiceStatus}
      </div>
      
      <hr style={{ border: '1px solid #333', margin: '10px 0' }} />
      
      <div style={{ fontSize: '10px', color: '#aaa' }}>
        <div>🌐 URL: {window.location.href}</div>
        <div>🕐 {new Date().toLocaleTimeString()}</div>
        <div>⌨️ Ctrl+Shift+E para ocultar</div>
      </div>
      
      {(!geminiKey || !youtubeKey) && (
        <div style={{ 
          marginTop: '10px', 
          padding: '8px', 
          background: 'rgba(255,193,7,0.2)', 
          border: '1px solid #FFC107',
          borderRadius: '4px',
          fontSize: '11px'
        }}>
          ⚠️ Faltan configuraciones. Verifica el archivo .env
        </div>
      )}
    </div>
  );
};

export default EnvChecker;
