import React, { useState, useEffect } from 'react'
import { CalendarEvent } from '../../services/googleCalendar'
import './CalendarComponents.scss'

interface InteractiveCalendarProps {
  events: CalendarEvent[]
  loading: boolean
  onDateClick: (date: Date) => void
  onEventClick: (event: CalendarEvent) => void
  onEventsChange: () => void
}

type ViewMode = 'month' | 'week' | 'day'

export function InteractiveCalendar({ 
  events, 
  loading, 
  onDateClick, 
  onEventClick,
  onEventsChange 
}: InteractiveCalendarProps) {
  const [currentDate, setCurrentDate] = useState(new Date())
  const [viewMode, setViewMode] = useState<ViewMode>('month')

  const monthNames = [
    'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
    'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'
  ]

  const dayNames = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb']

  // Obtener eventos para una fecha específica
  const getEventsForDate = (date: Date): CalendarEvent[] => {
    return events.filter(event => {
      const eventDate = new Date(event.start.dateTime || event.start.date || '')
      return eventDate.toDateString() === date.toDateString()
    })
  }

  // Generar días del mes actual
  const generateMonthDays = () => {
    const year = currentDate.getFullYear()
    const month = currentDate.getMonth()
    
    const firstDay = new Date(year, month, 1)
    const lastDay = new Date(year, month + 1, 0)
    const startDate = new Date(firstDay)
    startDate.setDate(startDate.getDate() - firstDay.getDay())
    
    const days = []
    const currentDateObj = new Date(startDate)
    
    // Generar 42 días (6 semanas x 7 días)
    for (let i = 0; i < 42; i++) {
      const isCurrentMonth = currentDateObj.getMonth() === month
      const isToday = currentDateObj.toDateString() === new Date().toDateString()
      const dayEvents = getEventsForDate(currentDateObj)
      
      days.push({
        date: new Date(currentDateObj),
        day: currentDateObj.getDate(),
        isCurrentMonth,
        isToday,
        events: dayEvents,
        hasEvents: dayEvents.length > 0
      })
      
      currentDateObj.setDate(currentDateObj.getDate() + 1)
    }
    
    return days
  }

  // Generar horas para vista semanal/diaria
  const generateHours = () => {
    const hours = []
    for (let i = 0; i < 24; i++) {
      hours.push({
        hour: i,
        display: i === 0 ? '12 AM' : i < 12 ? `${i} AM` : i === 12 ? '12 PM' : `${i - 12} PM`
      })
    }
    return hours
  }

  // Navegación de fechas
  const navigateMonth = (direction: 'prev' | 'next') => {
    const newDate = new Date(currentDate)
    if (direction === 'prev') {
      newDate.setMonth(newDate.getMonth() - 1)
    } else {
      newDate.setMonth(newDate.getMonth() + 1)
    }
    setCurrentDate(newDate)
  }

  const navigateWeek = (direction: 'prev' | 'next') => {
    const newDate = new Date(currentDate)
    const days = direction === 'prev' ? -7 : 7
    newDate.setDate(newDate.getDate() + days)
    setCurrentDate(newDate)
  }

  const goToToday = () => {
    setCurrentDate(new Date())
  }

  // Formatear tiempo del evento
  const formatEventTime = (event: CalendarEvent) => {
    if (event.start.dateTime) {
      return new Date(event.start.dateTime).toLocaleTimeString('es-ES', {
        hour: '2-digit',
        minute: '2-digit'
      })
    }
    return 'Todo el día'
  }

  // Obtener color del evento
  const getEventColor = (event: CalendarEvent) => {
    // Google Calendar color scheme
    const colors: Record<string, string> = {
      '1': '#a4bdfc', '2': '#7ae7bf', '3': '#dbadff', '4': '#ff887c',
      '5': '#fbd75b', '6': '#ffb878', '7': '#46d6db', '8': '#e1e1e1',
      '9': '#5484ed', '10': '#51b749', '11': '#dc2127'
    }
    return colors[event.colorId || '1'] || '#1976d2'
  }

  // Renderizar vista mensual
  const renderMonthView = () => {
    const days = generateMonthDays()

    return (
      <div className="calendar-month-view">
        {/* Header con días de la semana */}
        <div className="calendar-weekdays">
          {dayNames.map(day => (
            <div key={day} className="calendar-weekday">
              {day}
            </div>
          ))}
        </div>

        {/* Grid de días */}
        <div className="calendar-month-grid">
          {days.map((dayObj, index) => (
            <div
              key={index}
              className={`calendar-day ${
                !dayObj.isCurrentMonth ? 'other-month' : ''
              } ${dayObj.isToday ? 'today' : ''} ${
                dayObj.hasEvents ? 'has-events' : ''
              }`}
              onClick={() => onDateClick(dayObj.date)}
            >
              <div className="day-number">{dayObj.day}</div>
              
              {/* Eventos del día */}
              <div className="day-events">
                {dayObj.events.slice(0, 3).map((event, eventIndex) => (
                  <div
                    key={event.id}
                    className="calendar-event-item"
                    style={{ backgroundColor: getEventColor(event) }}
                    onClick={(e) => {
                      e.stopPropagation()
                      onEventClick(event)
                    }}
                    title={`${event.summary} - ${formatEventTime(event)}`}
                  >
                    <span className="event-time">{formatEventTime(event)}</span>
                    <span className="event-title">{event.summary}</span>
                  </div>
                ))}
                
                {/* Mostrar "+X más" si hay más eventos */}
                {dayObj.events.length > 3 && (
                  <div className="more-events">
                    +{dayObj.events.length - 3} más
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>
    )
  }

  // Renderizar vista semanal
  const renderWeekView = () => {
    const hours = generateHours()
    const startOfWeek = new Date(currentDate)
    startOfWeek.setDate(currentDate.getDate() - currentDate.getDay())
    
    const weekDays: Array<{
      date: Date
      events: CalendarEvent[]
      isToday: boolean
    }> = []
    
    for (let i = 0; i < 7; i++) {
      const day = new Date(startOfWeek)
      day.setDate(startOfWeek.getDate() + i)
      weekDays.push({
        date: day,
        events: getEventsForDate(day),
        isToday: day.toDateString() === new Date().toDateString()
      })
    }

    return (
      <div className="calendar-week-view">
        {/* Header con días de la semana */}
        <div className="week-header">
          <div className="time-column"></div>
          {weekDays.map((day, index) => (
            <div 
              key={index} 
              className={`week-day-header ${day.isToday ? 'today' : ''}`}
              onClick={() => onDateClick(day.date)}
            >
              <div className="day-name">{dayNames[day.date.getDay()]}</div>
              <div className="day-number">{day.date.getDate()}</div>
            </div>
          ))}
        </div>

        {/* Grid de horas */}
        <div className="week-grid">
          {hours.map(hour => (
            <div key={hour.hour} className="week-hour-row">
              <div className="time-label">{hour.display}</div>
              {weekDays.map((day, dayIndex) => (
                <div 
                  key={dayIndex} 
                  className="week-hour-cell"
                  onClick={() => onDateClick(new Date(day.date.setHours(hour.hour)))}
                >
                  {/* Eventos en esta hora */}
                  {day.events
                    .filter((event: CalendarEvent) => {
                      if (!event.start.dateTime) return false
                      const eventHour = new Date(event.start.dateTime).getHours()
                      return eventHour === hour.hour
                    })
                    .map((event: CalendarEvent) => (
                      <div
                        key={event.id}
                        className="week-event"
                        style={{ backgroundColor: getEventColor(event) }}
                        onClick={(e) => {
                          e.stopPropagation()
                          onEventClick(event)
                        }}
                        title={event.summary}
                      >
                        <div className="event-title">{event.summary}</div>
                        <div className="event-time">{formatEventTime(event)}</div>
                      </div>
                    ))
                  }
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>
    )
  }

  return (
    <div className="interactive-calendar">
      {/* Header de navegación */}
      <div className="calendar-header">
        <div className="calendar-navigation">
          <button 
            className="nav-btn"
            onClick={() => viewMode === 'month' ? navigateMonth('prev') : navigateWeek('prev')}
          >
            ‹
          </button>
          
          <div className="current-date">
            <h3>
              {viewMode === 'month' 
                ? `${monthNames[currentDate.getMonth()]} ${currentDate.getFullYear()}`
                : `Semana del ${currentDate.toLocaleDateString('es-ES')}`
              }
            </h3>
          </div>
          
          <button 
            className="nav-btn"
            onClick={() => viewMode === 'month' ? navigateMonth('next') : navigateWeek('next')}
          >
            ›
          </button>
        </div>

        <div className="calendar-controls">
          <button 
            className={`view-btn ${viewMode === 'month' ? 'active' : ''}`}
            onClick={() => setViewMode('month')}
          >
            Mes
          </button>
          <button 
            className={`view-btn ${viewMode === 'week' ? 'active' : ''}`}
            onClick={() => setViewMode('week')}
          >
            Semana
          </button>
          <button className="today-btn" onClick={goToToday}>
            Hoy
          </button>
        </div>
      </div>

      {/* Contenido del calendario */}
      <div className="calendar-content">
        {loading ? (
          <div className="calendar-loading">
            <div className="loading-spinner"></div>
            <p>Cargando calendario...</p>
          </div>
        ) : (
          <>
            {viewMode === 'month' && renderMonthView()}
            {viewMode === 'week' && renderWeekView()}
          </>
        )}
      </div>
    </div>
  )
}