import React, { useCallback, useEffect, useState } from "react";
import { useLiveAPIContext } from "../../contexts/LiveAPIContext";
import './AdvancedVoiceSelector.scss';

// Voces avanzadas compatibles con ambos modelos
const ADVANCED_VOICE_OPTIONS = [
  // Voces optimizadas para español
  { 
    value: "Zephyr", 
    label: "🌟 Zephyr - Español Latino", 
    region: "es-419",
    description: "Voz estándar española latinoamericana, ideal para ambos modos",
    compatibility: "✅ Normal + Thinking"
  },
  { 
    value: "Aoede", 
    label: "🇪🇸 Aoede - Español España", 
    region: "es-ES",
    description: "Voz española peninsular, excelente pronunciación",
    compatibility: "✅ Normal + Thinking"
  },
  { 
    value: "Callirrhoe", 
    label: "🎭 Callirrhoe - España Premium", 
    region: "es-ES",
    description: "Voz premium española con alta calidad",
    compatibility: "✅ Normal + Thinking"
  },
  { 
    value: "Despina", 
    label: "🌎 Despina - Latino Neutro", 
    region: "es-419",
    description: "Voz latina neutra, clara pronunciación",
    compatibility: "✅ Normal + Thinking"
  },
  { 
    value: "Leda", 
    label: "🇲🇽 Leda - Español México", 
    region: "es-MX",
    description: "Voz mexicana natural, ideal para usuarios mexicanos",
    compatibility: "✅ Normal + Thinking"
  },
  { 
    value: "Umbriel", 
    label: "⭐ Umbriel - Latino Premium", 
    region: "es-419",
    description: "Voz latina premium, articulación suave",
    compatibility: "✅ Normal + Thinking"
  },
  // Voces en inglés para funcionalidad completa
  { 
    value: "Puck", 
    label: "🇺🇸 Puck - English US", 
    region: "en-US",
    description: "Voz estándar inglés americano",
    compatibility: "✅ Normal + Thinking"
  },
  { 
    value: "Charon", 
    label: "🇬🇧 Charon - English UK", 
    region: "en-GB",
    description: "Voz estándar inglés británico",
    compatibility: "✅ Normal + Thinking"
  },
  { 
    value: "Kore", 
    label: "🔥 Kore - US Premium", 
    region: "en-US",
    description: "Voz premium inglés americano",
    compatibility: "✅ Normal + Thinking"
  },
  { 
    value: "Fenrir", 
    label: "👑 Fenrir - UK Premium", 
    region: "en-GB",
    description: "Voz premium inglés británico",
    compatibility: "✅ Normal + Thinking"
  }
];

interface AdvancedVoiceSelectorProps {
  onVoiceChange?: (voice: string, region: string) => void;
  showToggleButton?: boolean; // Nueva prop para controlar si mostrar el botón toggle
  defaultVisible?: boolean; // Nueva prop para controlar visibilidad inicial
}

const AdvancedVoiceSelector: React.FC<AdvancedVoiceSelectorProps> = ({ 
  onVoiceChange,
  showToggleButton = true,
  defaultVisible = false
}) => {
  const { config, setConfig } = useLiveAPIContext();
  
  // Estados para voz seleccionada
  const [selectedVoice, setSelectedVoice] = useState<typeof ADVANCED_VOICE_OPTIONS[0] | null>(
    ADVANCED_VOICE_OPTIONS[0] // Default: Zephyr
  );
  const [isTestingVoice, setIsTestingVoice] = useState(false);
  const [isConfigVisible, setIsConfigVisible] = useState(defaultVisible); // Estado para toggle usando defaultVisible

  // Inicializar estado desde configuración actual
  useEffect(() => {
    const currentVoiceName = config.speechConfig?.voiceConfig?.prebuiltVoiceConfig?.voiceName || "Zephyr";
    const voice = ADVANCED_VOICE_OPTIONS.find(v => v.value === currentVoiceName) || ADVANCED_VOICE_OPTIONS[0];
    setSelectedVoice(voice);
  }, [config]);

  // Actualizar configuración cuando cambie la voz o región
  const updateVoiceConfig = useCallback((voice: string, regionCode: string) => {
    const newSpeechConfig: any = {
      ...config.speechConfig,
      voiceConfig: {
        prebuiltVoiceConfig: {
          voiceName: voice
        }
      },
      languageCode: regionCode || 'es-419' // Default Spanish Latin America
    };

    setConfig({
      ...config,
      speechConfig: newSpeechConfig
    });

    console.log(`🎙️ Voz actualizada: ${voice} (${regionCode || 'auto'})`);
    
    // Llamar callback si existe
    if (onVoiceChange) {
      onVoiceChange(voice, regionCode || 'es-419');
    }
  }, [config, setConfig, onVoiceChange]);

  // Manejar cambio de voz
  const handleVoiceChange = (voiceValue: string) => {
    const voice = ADVANCED_VOICE_OPTIONS.find(v => v.value === voiceValue);
    if (voice) {
      setSelectedVoice(voice);
      updateVoiceConfig(voice.value, voice.region);
    }
  };

  // Probar voz seleccionada
  const testSelectedVoice = () => {
    if (!selectedVoice) return;
    
    setIsTestingVoice(true);
    console.log(`🎤 Prueba de voz: ${selectedVoice?.label} (detección automática de idioma)`);
    console.log("ℹ️ VOXIA usa audio nativo de Gemini - no síntesis local");
    
    // Simular prueba
    setTimeout(() => {
      setIsTestingVoice(false);
    }, 2000);
  };

  return (
    <div className="min-h-screen p-4 bg-gray-900 text-white">
      {/* Header si showToggleButton es true */}
      {showToggleButton && (
        <div>
          <header className="flex justify-between items-center pb-4 border-b border-gray-700">
            <h1 className="text-xl font-bold">Panel de Control</h1>
            <span className="material-icons text-gray-400">fullscreen_exit</span>
          </header>
          
          <button 
            className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-4 rounded-lg my-6 flex items-center justify-center transition duration-300 ease-in-out"
            onClick={() => setIsConfigVisible(!isConfigVisible)}
          >
            <span className="material-icons mr-2">face</span>
            {isConfigVisible ? 'Ocultar Configuración de Voz' : 'Mostrar Configuración de Voz'}
          </button>
        </div>
      )}

      {/* Panel principal con scroll para móviles */}
      {isConfigVisible && (
        <div className="voice-config-panel">
          {/* Header con icono */}
          <div className="panel-header">
            <span className="material-icons">mic</span>
            <div>
              <h2>Configuración de Voz</h2>
              <p>Compatible con modos Normal y Thinking - Detección automática de idioma</p>
            </div>
          </div>

          {/* Selector de voz */}
          <div className="voice-selector-section">
            <label htmlFor="voice-select">
              Seleccionar Voz
            </label>
            <div className="voice-select-wrapper">
              <span className="material-icons select-icon">keyboard_voice</span>
              <select 
                className="voice-select"
                id="voice-select"
                value={selectedVoice?.value || ''}
                onChange={(e) => handleVoiceChange(e.target.value)}
              >
                {ADVANCED_VOICE_OPTIONS.map((voice) => (
                  <option key={voice.value} value={voice.value}>
                    {voice.label}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Configuración actual */}
          <div className="current-config-section">
            <h3>
              <span className="material-icons">settings</span>
              Configuración Actual
            </h3>
            <div className="config-items">
              <div className="config-item">
                <span className="config-label">Voz:</span>
                <div className="config-value">
                  <span className="material-icons config-icon text-yellow-400">wb_sunny</span>
                  <span>{selectedVoice?.label || 'Zephyr - Español Latino'}</span>
                </div>
              </div>
              <div className="config-item">
                <span className="config-label">Idioma:</span>
                <div className="config-value">
                  <span className="material-icons config-icon text-blue-400">language</span>
                  <span>Detección automática</span>
                </div>
              </div>
              <div className="config-item">
                <span className="config-label">Compatibilidad:</span>
                <div className="config-value">
                  <span className="material-icons config-icon text-green-400">check_circle</span>
                  <span>Normal</span>
                </div>
              </div>
            </div>
          </div>

          {/* Botón aplicar */}
          <button 
            className="apply-button"
            onClick={() => selectedVoice && updateVoiceConfig(selectedVoice.value, selectedVoice.region)}
          >
            <span className="material-icons">check</span>
            Aplicar Configuración
          </button>

          {/* Consejo final */}
          <div className="voice-tip">
            <span className="material-icons tip-icon">lightbulb</span>
            <p>Para una mejor experiencia, recomendamos las voces Zephyr o Echo con detección automática de idioma.</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdvancedVoiceSelector;
