export const testSpanishVoices = () => {
  console.log('🎤 Testing Spanish voice synthesis...');
  
  if (!window.speechSynthesis) {
    console.error('❌ Web Speech API no está disponible en este navegador');
    return false;
  }

  const synth = window.speechSynthesis;
  const voices = synth.getVoices();
  
  console.log('🔍 Voces disponibles:', voices.length);
  
  const spanishVoices = voices.filter(voice => 
    voice.lang.startsWith('es') || 
    voice.name.toLowerCase().includes('spanish') ||
    voice.name.toLowerCase().includes('español')
  );
  
  console.log('🇪🇸 Voces en español encontradas:', spanishVoices.length);
  
  spanishVoices.forEach((voice, index) => {
    console.log(`${index + 1}. ${voice.name} (${voice.lang}) - ${voice.localService ? 'Local' : 'Remota'}`);
  });
  
  // Test basic Spanish pronunciation
  if (spanishVoices.length > 0) {
    const testText = 'Hola, esta es una prueba de síntesis de voz en español. ¿Puedes escucharme correctamente?';
    const utterance = new SpeechSynthesisUtterance(testText);
    utterance.voice = spanishVoices[0];
    utterance.rate = 0.9;
    utterance.pitch = 1;
    utterance.volume = 0.8;
    
    utterance.onstart = () => console.log('✅ Testing Spanish voice synthesis');
    utterance.onend = () => console.log('✅ Spanish voice test completed');
    utterance.onerror = (error) => console.error('❌ Error en síntesis:', error);
    
    console.log('🎯 Ready to test Spanish voice synthesis');
    console.log('📝 Test text:', testText);
    return true;
  } else {
    console.warn('⚠️ No Spanish voices found for testing');
    return false;
  }
};

export const getSpanishVoiceInfo = () => {
  const synth = window.speechSynthesis;
  const voices = synth.getVoices();
  
  return voices.filter(voice => 
    voice.lang.startsWith('es') || 
    voice.name.toLowerCase().includes('spanish') ||
    voice.name.toLowerCase().includes('español')
  ).map(voice => ({
    name: voice.name,
    lang: voice.lang,
    gender: voice.name.toLowerCase().includes('female') || voice.name.toLowerCase().includes('mujer') ? 'femenina' : 
            voice.name.toLowerCase().includes('male') || voice.name.toLowerCase().includes('hombre') ? 'masculina' : 'desconocido',
    localService: voice.localService,
    default: voice.default
  }));
};
