/**
 * Componente de Estado del Micrófono para VOXIA
 * Muestra el estado del micrófono y errores de manera amigable
 */

import React, { useEffect, useState } from 'react';
import './MicrophoneStatus.scss';

interface MicrophoneStatusProps {
  status: 'idle' | 'requesting' | 'granted' | 'denied';
  error?: string | null;
  onRetry?: () => void;
  onDismiss?: () => void;
}

export const MicrophoneStatus: React.FC<MicrophoneStatusProps> = ({
  status,
  error,
  onRetry,
  onDismiss
}) => {
  const [isVisible, setIsVisible] = useState(false);
  const [autoHideTimer, setAutoHideTimer] = useState<NodeJS.Timeout | null>(null);

  useEffect(() => {
    if (status === 'requesting' || status === 'denied' || error) {
      setIsVisible(true);
      
      // Auto-ocultar después de 10 segundos si es un error
      if (status === 'denied' && autoHideTimer) {
        clearTimeout(autoHideTimer);
      }
      
      if (status === 'denied') {
        const timer = setTimeout(() => {
          setIsVisible(false);
          onDismiss?.();
        }, 10000);
        setAutoHideTimer(timer);
      }
    } else {
      setIsVisible(false);
      if (autoHideTimer) {
        clearTimeout(autoHideTimer);
        setAutoHideTimer(null);
      }
    }

    return () => {
      if (autoHideTimer) {
        clearTimeout(autoHideTimer);
      }
    };
  }, [status, error, onDismiss]);

  if (!isVisible) return null;

  const getStatusInfo = () => {
    switch (status) {
      case 'requesting':
        return {
          icon: '🎤',
          title: 'Solicitando acceso al micrófono',
          message: 'Por favor, permite el acceso al micrófono cuando el navegador lo solicite.',
          type: 'info'
        };
      case 'granted':
        return {
          icon: '✅',
          title: 'Micrófono conectado',
          message: 'VOXIA puede escucharte correctamente.',
          type: 'success'
        };
      case 'denied':
        return {
          icon: '❌',
          title: 'Acceso al micrófono denegado',
          message: error || 'No se pudo acceder al micrófono.',
          type: 'error'
        };
      default:
        return null;
    }
  };

  const statusInfo = getStatusInfo();
  if (!statusInfo) return null;

  const getHelpContent = () => {
    if (status === 'denied') {
      return (
        <div className="help-content">
          <h4>¿Cómo solucionar esto?</h4>
          <ol>
            <li>
              <strong>Permisos del navegador:</strong>
              <ul>
                <li>Haz clic en el ícono de candado 🔒 en la barra de direcciones</li>
                <li>Permite el acceso al micrófono</li>
                <li>Recarga la página</li>
              </ul>
            </li>
            <li>
              <strong>Verifica tu conexión:</strong>
              <ul>
                <li>Asegúrate de estar usando HTTPS (https://)</li>
                <li>Cierra otras aplicaciones que usen el micrófono</li>
              </ul>
            </li>
            <li>
              <strong>Configuración del sistema:</strong>
              <ul>
                <li>Verifica que tu micrófono esté conectado y funcionando</li>
                <li>Comprueba la configuración de privacidad del sistema</li>
              </ul>
            </li>
          </ol>
        </div>
      );
    }
    return null;
  };

  return (
    <div className={`microphone-status ${statusInfo.type}`}>
      <div className="status-header">
        <span className="status-icon">{statusInfo.icon}</span>
        <div className="status-text">
          <h3>{statusInfo.title}</h3>
          <p>{statusInfo.message}</p>
        </div>
        <button 
          className="close-btn"
          onClick={() => {
            setIsVisible(false);
            onDismiss?.();
          }}
          title="Cerrar"
        >
          ✕
        </button>
      </div>

      {getHelpContent()}

      {status === 'denied' && onRetry && (
        <div className="action-buttons">
          <button className="retry-btn" onClick={onRetry}>
            🔄 Intentar de nuevo
          </button>
        </div>
      )}

      {status === 'requesting' && (
        <div className="loading-indicator">
          <div className="loading-dots">
            <span></span>
            <span></span>
            <span></span>
          </div>
        </div>
      )}
    </div>
  );
};

export default MicrophoneStatus;
