import { useState, useEffect } from "react";
import "./App.scss";
import { LiveAPIProvider } from "./contexts/LiveAPIContext";
import { AuthProvider } from "./contexts/AuthContext";
import SidePanel from "./components/side-panel/SidePanel";
import { Altair } from "./components/altair/Altair";
import ControlTray from "./components/control-tray/ControlTray";
import SpanishTestPanel from "./components/spanish-test-panel/SpanishTestPanel";
import YouTubePanel from "./components/youtube-panel/YouTubePanel";
import StudyPanel from "./components/study-panel/StudyPanel";
import { CalendarPanel } from "./components/calendar-panel";
import PonitivoxPanel from "./components/ponitivox-panel/PonitivoxPanel";
import UserProfilePanel from "./components/user-profile-panel/UserProfilePanel";
import EnvChecker from "./components/env-checker/EnvChecker";
import ConnectionDiagnostic from "./components/connection-diagnostic/ConnectionDiagnostic";
import ChatbotVox from "./components/chatbot-vox/ChatbotVox";
import { VideoDisplay } from "./components/video-display/VideoDisplay";
import { LoginButton } from "./components/auth";
import { AuthWrapper } from "./components/AuthWrapper";
// import PonitivoxDropdown from "./components/ponitivox-panel/PonitivoxDropdown";
// import GoogleClassroomPanel from "./components/ponitivox-panel/GoogleClassroomPanel";
// import PresentationGeneratorPanel from "./components/ponitivox-panel/PresentationGeneratorPanel";
import { LiveClientOptions } from "./types";
import { translations } from "./i18n/translations";
import ConversationControlButton from "./components/conversation-control/ConversationControlButton";
import { spanishVoiceService } from "./services/SpanishVoiceService";
import { useYouTubePanel } from "./hooks/use-youtube-panel";
import { useScreenSharingYouTube } from "./hooks/use-screen-sharing-youtube";
import { useChatbotVox } from "./hooks/useChatbotVox";

const API_KEY = process.env.REACT_APP_GEMINI_API_KEY as string;

// Verificar si tenemos API key válida
const hasValidApiKey = typeof API_KEY === "string" && API_KEY.length > 0;

// Configuración de API para VOXIA - usando configuración por defecto del modelo nativo
const apiOptions: LiveClientOptions = {
  apiKey: API_KEY,
};

// Componente de error para API key faltante
function ApiKeyError() {
  return (
    <div style={{ 
      padding: '40px', 
      textAlign: 'center', 
      backgroundColor: '#fff3cd', 
      color: '#856404',
      border: '1px solid #ffeaa7',
      borderRadius: '8px',
      margin: '20px'
    }}>
      <h2>⚠️ Configuración Requerida</h2>
      <p><strong>No se encontró la API key de Gemini.</strong></p>
      <p>Por favor, configura <code>REACT_APP_GEMINI_API_KEY</code> en el archivo <code>.env</code></p>
      <p>Obtén tu API key en: <a href="https://aistudio.google.com/apikey" target="_blank" rel="noopener noreferrer">https://aistudio.google.com/apikey</a></p>
      <p><small>Archivo .env debe estar en la raíz del proyecto</small></p>
    </div>
  );
}

function App() {
  // Stream de video activo o null si está oculto
  const [videoStream, setVideoStream] = useState<MediaStream | null>(null);
  // Referencia al elemento de video del VideoDisplay para ControlTray
  const [currentVideoElement, setCurrentVideoElement] = useState<HTMLVideoElement | null>(null);
  // Estado para mostrar el panel de pruebas (solo para desarrollo)
  const [showTestPanel, setShowTestPanel] = useState(false);
  // Estado para mostrar el panel de diagnóstico
  const [showDiagnostic, setShowDiagnostic] = useState(false);
  // Estado para el panel lateral en móviles
  const [showSidePanel, setShowSidePanel] = useState(false);
  // Estado para el panel de PONITIVOX
  const [showPonitivoxPanel, setShowPonitivoxPanel] = useState(false);
  // Estado para el panel de perfil de usuario
  const [showUserProfilePanel, setShowUserProfilePanel] = useState(false);
  // Estado para el panel de estudio interactivo
  const [showStudyPanel, setShowStudyPanel] = useState(false);
  const studyPanelPosition = "left"; // Hardcoded as per current setup
  // Estado para el panel de Google Calendar
  const [showCalendarPanel, setShowCalendarPanel] = useState(false);
  // Estados para los paneles de PONITIVOX
  // const [showGoogleClassroomPanel, setShowGoogleClassroomPanel] = useState(false);
  // const [showPresentationGeneratorPanel, setShowPresentationGeneratorPanel] = useState(false);
  // Hook personalizado para el panel de YouTube
  const [youtubeState, youtubeActions] = useYouTubePanel({
    defaultPosition: 'right',
    autoMinimizeOnVideoStream: false, // Desactivado para evitar que se cierre YouTube
    autoRepositionOnVideoStream: true
  });
  // Estado para detectar si se está compartiendo pantalla específicamente
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  
  // Detectar si es móvil
  const [isMobile, setIsMobile] = useState(false);
  
  // Hook personalizado para el Chatbot Vox
  const chatbotVox = useChatbotVox();
  
  // Hook personalizado para gestionar screen sharing + YouTube
  const screenSharingYouTube = useScreenSharingYouTube({
    isScreenSharing,
    isYouTubeActive: youtubeState.isVisible,
    isMobile,
    onYouTubeMiniToggle: () => youtubeState.isVisible ? youtubeActions.hide() : youtubeActions.show(),
    onScreenShareStop: () => setVideoStream(null)
  });
  
  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth <= 768);
    };
    
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);
  
  // Obtener textos en español
  const t = translations.es;

  // Agregar shortcut para el panel de pruebas (Ctrl+T)
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.ctrlKey && event.key.toLowerCase() === 't') {
        event.preventDefault();
        setShowTestPanel(prev => !prev);
      }
      
      // Agregar shortcut para diagnóstico (Ctrl+D)
      if (event.ctrlKey && event.key.toLowerCase() === 'd') {
        event.preventDefault();
        setShowDiagnostic(prev => !prev);
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, []);

  // Función para manejar requests de música desde el AI
  const handleMusicRequest = (query: string) => {
    console.log('🎵 Solicitud de música recibida:', query);
    youtubeActions.setQuery(query);
    youtubeActions.show(query);
  };

  // Función para manejar control de volumen de YouTube desde el AI
  const handleVolumeControl = (action: string, level?: number) => {
    console.log('🔊 Control de volumen de YouTube recibido:', { action, level });
    
    // Llamar a la función de control de volumen del panel de YouTube si está disponible
    if (typeof window !== 'undefined' && (window as any).youtubeVolumeControl) {
      (window as any).youtubeVolumeControl(action, level);
    } else {
      console.warn('⚠️ Control de volumen de YouTube no disponible');
    }
  };

  // Función para manejar solicitudes de estudio desde el AI
  const handleStudyRequest = (content: string, studyType: string, options?: any) => {
    console.log('📚 Solicitud de estudio recibida:', { content, studyType, options });
    
    // Mostrar el panel de estudio
    setShowStudyPanel(true);
    
    // Si hay contenido, procesarlo (en una implementación real)
    if (content && typeof window !== 'undefined') {
      // Enviar contenido al panel de estudio
      (window as any).studyContent = { content, studyType, options };
    }
  };

  // Función para manejar interacciones de voz del panel de estudio
  const handleVoiceInteraction = (message: string) => {
    console.log('🎤 Interacción de voz del panel de estudio:', message);
    
    // Enviar el mensaje directamente a VOXIA a través del contexto
    // Esto se integrará con el componente Altair/LiveAPI
    if (typeof window !== 'undefined') {
      // Crear evento personalizado para enviar a VOXIA
      const voiceEvent = new CustomEvent('studyVoiceInteraction', {
        detail: { message }
      });
      window.dispatchEvent(voiceEvent);
    }
  };

  // Función para manejar evaluación de respuestas de estudio
  const handleStudyEvaluation = (question: string, answer: string, correctAnswer: string) => {
    console.log('📝 Evaluación de respuesta de estudio:', { question, answer, correctAnswer });
    
    // Aquí se implementaría la lógica de evaluación
    // Por ahora, simplemente logeamos la información
    const evaluation = {
      question,
      studentAnswer: answer,
      correctAnswer,
      timestamp: new Date().toISOString()
    };
    
    // En una implementación real, esto se enviaría al sistema de evaluación
    if (typeof window !== 'undefined') {
      (window as any).lastEvaluation = evaluation;
    }
  };

  // Función para manejar cambios en el video stream (cámara/pantalla)
  const handleVideoStreamChange = (stream: MediaStream | null) => {
    console.log('🎥 Video stream change:', stream ? 'ACTIVO' : 'INACTIVO');
    
    setVideoStream(stream);
    
    // Detectar si el stream es de screen sharing
    if (stream) {
      const videoTrack = stream.getVideoTracks()[0];
      const isScreen = videoTrack && videoTrack.label.includes('screen');
      setIsScreenSharing(isScreen);
      
      console.log('🔄 Tipo de stream:', isScreen ? 'SCREEN SHARING' : 'CÁMARA');
      
      // Si es screen sharing Y YouTube está activo, NO cerrarlo
      if (isScreen && youtubeState.isVisible) {
        console.log('🎵 YouTube permanece activo durante screen sharing');
        // No hacer nada, mantener YouTube abierto
      }
    } else {
      setIsScreenSharing(false);
      console.log('📱 Todos los streams detenidos');
    }
  };

  // Generar clases CSS dinámicas para el contenedor principal
  const getAppClasses = () => {
    const classes = ['App', 'mobile-first-layout'];
    
    if (isMobile) {
      classes.push('mobile-layout');
    }
    
    if (isScreenSharing) {
      classes.push('screen-sharing-active');
    }
    
    if (youtubeState.isVisible) {
      classes.push('youtube-active');
    }
    
    return classes.join(' ');
  };
  // Si no hay API key válida, mostrar componente de error
  if (!hasValidApiKey) {
    return <ApiKeyError />;
  }

  return (
    <AuthProvider>
      <AuthWrapper>
        <div className={getAppClasses()}>
          <LiveAPIProvider options={apiOptions}>
            {/* Verificador de variables de entorno (oculto por defecto en móvil) */}
            <div className="env-checker-container hidden-mobile">
              <EnvChecker />
            </div>
            
            {/* Panel de pruebas para desarrollo - presiona Ctrl+T para mostrar/ocultar */}
            {showTestPanel && <SpanishTestPanel />}
            
            {/* Panel de diagnóstico de conexión - presiona Ctrl+D para mostrar/ocultar */}
            {showDiagnostic && (
              <div className="diagnostic-overlay">
                <div className="diagnostic-container">
                  <button 
                    className="diagnostic-close" 
                    onClick={() => setShowDiagnostic(false)}
                    aria-label="Cerrar diagnóstico"
                  >
                    ✕
                  </button>
                  <ConnectionDiagnostic />
                </div>
              </div>
            )}
            
            {/* Panel de YouTube integrado como side panel */}
            <YouTubePanel 
              isVisible={youtubeState.isVisible}
              onClose={youtubeActions.hide}
              searchQuery={youtubeState.currentQuery}
              isMinimized={youtubeState.isMinimized}
              onMinimize={() => youtubeState.isMinimized ? youtubeActions.expand() : youtubeActions.minimize()}
              position={youtubeState.position}
              isScreenSharingMode={screenSharingYouTube.isMiniMode}
              miniModePosition={screenSharingYouTube.panelPosition}
              onDoubleTab={screenSharingYouTube.handleDoubleTab}
              onDragStart={screenSharingYouTube.handleDragStart}
              isTemporarilyExpanded={screenSharingYouTube.isTemporarilyExpanded}
              isRepositioned={!isMobile && youtubeState.position === 'left'} // Reposition if YT panel is on the left in desktop/tablet view
            />
            
            {/* Layout mobile-first estilo VOXIA */}
            <div className="mobile-chat-layout">
              {/* Header compacto para móvil */}
              <header className="mobile-header">
                <div className="header-content">
                  <div className="header-brand">
                    <img 
                      src="/voxia-logo.png" 
                      alt="VOXIA" 
                      className="voxia-logo"
                    />
                    <h1 className="app-title">VOXIA</h1>
                  </div>
                  <div className="header-actions">
                    <button 
                      className="youtube-btn"
                      onClick={() => youtubeActions.show()}
                      title="YouTube"
                    >
                      🎵
                    </button>
                    <button 
                      className="chatbot-vox-btn"
                      onClick={chatbotVox.toggleChatbot}
                      title="Chatbot Vox - IA Multimodal"
                    >
                      💬
                    </button>
                    <button 
                      className="study-btn"
                      onClick={() => setShowStudyPanel(true)}
                      title="Panel de Estudio"
                    >
                      📚
                    </button>
                    <button 
                      className="calendar-btn"
                      onClick={() => setShowCalendarPanel(true)}
                      title="Google Calendar"
                    >
                      📅
                    </button>
                    {/* <PonitivoxDropdown 
                      onGoogleClassroom={() => setShowGoogleClassroomPanel(true)}
                      onGeneratePresentation={() => setShowPresentationGeneratorPanel(true)}
                    /> */}
                    <button 
                      className="user-profile-btn"
                      onClick={() => setShowUserProfilePanel(true)}
                      title="Perfil de Usuario"
                    >
                      👤
                    </button>
                    {isMobile && (
                      <button 
                        className="control-panel-btn"
                        onClick={() => setShowSidePanel(true)}
                        title="Panel de Control"
                      >
                        ⚙️
                      </button>
                    )}
                  </div>
                </div>
              </header>
          
          {/* Área de conversación principal */}
          <main className="conversation-area">
            <div className="chat-container">
              {/* Componente principal de chat/conversación */}
              <Altair 
                onMusicRequest={handleMusicRequest} 
                onVolumeControl={handleVolumeControl}
                onStudyRequest={handleStudyRequest}
                onStudyEvaluation={handleStudyEvaluation}
              />
              
              {/* Video stream mejorado - funciona bien en PC y móvil */}
              {videoStream && (
                <div className="video-container mobile-video-wrapper">
                  <VideoDisplay
                    stream={videoStream}
                    type={isScreenSharing ? 'screen' : 'webcam'}
                    isActive={!!videoStream}
                    showControls={true}
                    className="main-video-display"
                    onVideoRef={setCurrentVideoElement}
                  />
                </div>
              )}
            </div>
          </main>

          {/* Overlay especial mejorado para screen sharing */}
          {isScreenSharing && (
            <div className="screen-sharing-display">
              <div className="sharing-indicator">
                🖥️ Compartiendo pantalla
              </div>
              <div className="screen-content">
                <VideoDisplay
                  stream={videoStream}
                  type="screen"
                  isActive={isScreenSharing}
                  showControls={true}
                  className="screen-sharing-video"
                  onVideoRef={setCurrentVideoElement}
                  onToggleFullscreen={() => {
                    // Toggle fullscreen específico para screen sharing
                    const display = document.querySelector('.screen-sharing-display');
                    if (display) {
                      if ((display as any).requestFullscreen) {
                        (display as any).requestFullscreen();
                      }
                    }
                  }}
                />
              </div>
            </div>
          )}
          
          {/* Controles inferiores fijos estilo ChatGPT */}
          <footer className="mobile-controls-footer">
            <ControlTray
              currentVideoElement={currentVideoElement}
              supportsVideo={true}
              onVideoStreamChange={handleVideoStreamChange}
              enableEditingSettings={true}
              isScreenSharing={isScreenSharing}
              isYouTubeActive={youtubeState.isVisible}
              onStopScreenSharing={() => setVideoStream(null)}
              onToggleYouTube={() => youtubeState.isVisible ? youtubeActions.hide() : youtubeActions.show()}
            >
              <ConversationControlButton 
                spanishVoiceService={spanishVoiceService}
              />
            </ControlTray>
          </footer>
          
          {/* Panel lateral como drawer móvil */}
          <SidePanel 
            onOpenYouTube={() => youtubeActions.show()}
            isVisible={showSidePanel}
            onClose={() => setShowSidePanel(false)}
          />
          
          {/* Panel de estudio interactivo */}
          <StudyPanel
            isVisible={showStudyPanel}
            onClose={() => setShowStudyPanel(false)}
            onVoiceInteraction={handleVoiceInteraction}
            position={studyPanelPosition}
            isRepositioned={!isMobile && showStudyPanel} // Reposition if study panel is shown on desktop/tablet
          />
          
          {/* Panel de Google Calendar */}
          <CalendarPanel
            isVisible={showCalendarPanel}
            onClose={() => setShowCalendarPanel(false)}
            position="right"
          />
          
          {/* Panel de PONITIVOX */}
          <PonitivoxPanel
            isVisible={showPonitivoxPanel}
            onClose={() => setShowPonitivoxPanel(false)}
            position="right"
            isRepositioned={!isMobile && (showStudyPanel || showPonitivoxPanel)}
          />
          
          {/* Panel de Perfil de Usuario */}
          <UserProfilePanel
            isVisible={showUserProfilePanel}
            onClose={() => setShowUserProfilePanel(false)}
            position="right"
            isRepositioned={!isMobile && (showStudyPanel || showPonitivoxPanel || showUserProfilePanel)}
          />
          
          {/* Chatbot Vox - IA Multimodal */}
          <ChatbotVox
            isVisible={chatbotVox.isVisible}
            onClose={chatbotVox.hideChatbot}
            position={chatbotVox.position}
            isMinimized={chatbotVox.isMinimized}
            onMinimize={chatbotVox.minimizeChatbot}
          />

          {/* Paneles de PONITIVOX */}
          {/* <GoogleClassroomPanel
            isOpen={showGoogleClassroomPanel}
            onClose={() => setShowGoogleClassroomPanel(false)}
          /> */}
          
          {/* <PresentationGeneratorPanel 
            isOpen={showPresentationGeneratorPanel}
            onClose={() => setShowPresentationGeneratorPanel(false)}
          /> */}
        </div>
      </LiveAPIProvider>
    </div>
  </AuthWrapper>
</AuthProvider>
  );
}

export default App;
