/**
 * Servicio de integración entre Google Calendar y Gemini Live
 * Permite que Gemini Live lea y cree tareas/eventos únicamente
 * 100% seguro - Solo acceso al calendario
 */

import { CalendarEvent, CreateEventRequest } from './googleCalendar';
import { googleCalendar } from './googleCalendar';
import { userPreferencesService } from './UserPreferencesService';
import { DateTimeUtils } from '../utils/dateTimeUtils';

export interface CalendarTool {
  name: string;
  description: string;
  parameters: {
    type: string;
    properties: Record<string, any>;
    required: string[];
  };
}

export interface CalendarContext {
  events: CalendarEvent[];
  today: string;
  hasAccess: boolean;
}

export class CalendarGeminiService {
  private static instance: CalendarGeminiService;
  private calendarService = googleCalendar;
  private isLoadingData = false;

  private constructor() {}

  public static getInstance(): CalendarGeminiService {
    if (!CalendarGeminiService.instance) {
      CalendarGeminiService.instance = new CalendarGeminiService();
    }
    return CalendarGeminiService.instance;
  }

  /**
   * Indica si está cargando datos del calendario
   */
  isLoadingCalendarData(): boolean {
    return this.isLoadingData;
  }

  /**
   * Inicia la carga de datos del calendario y muestra mensaje
   */
  async initializeCalendarData(): Promise<void> {
    // Verificar si el usuario tiene datos personalizados habilitados
    if (!userPreferencesService.shouldAutoLoadCalendarData()) {
      console.log('📅 Carga automática del calendario deshabilitada por el usuario');
      return;
    }

    console.log('📅 Cargando y leyendo tus datos locales...');
    this.isLoadingData = true;
    
    try {
      // Verificar acceso al calendario
      await this.calendarService.checkCalendarAccess();
      
      // Pre-cargar datos básicos del calendario
      await this.getCalendarContext();
      
      console.log('📅 ✅ Datos del calendario cargados exitosamente');
    } catch (error) {
      console.error('📅 ❌ Error al cargar datos del calendario:', error);
    } finally {
      this.isLoadingData = false;
    }
  }

  /**
   * Verifica si el usuario permite uso de datos personalizados
   */
  isPersonalizedDataEnabled(): boolean {
    return userPreferencesService.isPersonalizedDataEnabled();
  }

  /**
   * Obtiene las herramientas del calendario para Gemini Live
   */
  getCalendarTools(): CalendarTool[] {
    // Solo devolver herramientas si el usuario tiene datos personalizados habilitados
    if (!this.isPersonalizedDataEnabled()) {
      return [];
    }

    return [
      {
        name: 'leer_calendario',
        description: 'Lee las tareas y eventos del calendario del usuario. Úsala cuando el usuario pregunte sobre sus tareas, eventos, agenda o calendario.',
        parameters: {
          type: 'object',
          properties: {
            filtro: {
              type: 'string',
              description: 'Filtro opcional: "hoy", "semana", "mes" o "todo"',
              enum: ['hoy', 'semana', 'mes', 'todo']
            }
          },
          required: []
        }
      },
      {
        name: 'crear_tarea',
        description: 'Crea una nueva tarea o recordatorio en el calendario de Google. Úsala SIEMPRE cuando el usuario diga frases como: "agenda una tarea", "recuérdame", "agrega al calendario", "programa una tarea", "añade un recordatorio", "crea una cita personal", "quiero agendar algo".',
        parameters: {
          type: 'object',
          properties: {
            titulo: {
              type: 'string',
              description: 'Título de la tarea. OBLIGATORIO.'
            },
            descripcion: {
              type: 'string',
              description: 'Descripción opcional de la tarea'
            },
            fecha: {
              type: 'string',
              description: 'Fecha en formato YYYY-MM-DD. Si no se especifica, usar fecha actual.'
            },
            hora: {
              type: 'string',
              description: 'Hora en formato HH:MM (24h). Opcional para tareas de todo el día.'
            },
            todo_el_dia: {
              type: 'boolean',
              description: 'Si es true, la tarea es de todo el día (sin hora específica)'
            },
            color: {
              type: 'string',
              description: 'Color de la tarea: azul, verde, purpura, rosa, amarillo, naranja, turquesa, gris, azul_intenso, verde_intenso, rojo',
              enum: ['azul', 'verde', 'purpura', 'rosa', 'amarillo', 'naranja', 'turquesa', 'gris', 'azul_intenso', 'verde_intenso', 'rojo']
            }
          },
          required: ['titulo']
        }
      },
      {
        name: 'crear_evento',
        description: 'Crea un nuevo evento, reunión o cita en el calendario de Google. Úsala SIEMPRE cuando el usuario diga frases como: "agenda una reunión", "programa una cita", "crea un evento", "tengo una reunión", "reserva tiempo para", "bloquea mi calendario", "organiza una junta".',
        parameters: {
          type: 'object',
          properties: {
            titulo: {
              type: 'string',
              description: 'Título del evento. OBLIGATORIO.'
            },
            descripcion: {
              type: 'string',
              description: 'Descripción opcional del evento'
            },
            fecha_inicio: {
              type: 'string',
              description: 'Fecha de inicio en formato YYYY-MM-DD. OBLIGATORIO.'
            },
            hora_inicio: {
              type: 'string',
              description: 'Hora de inicio en formato HH:MM (24h). OBLIGATORIO para eventos con horario específico.'
            },
            fecha_fin: {
              type: 'string',
              description: 'Fecha de fin en formato YYYY-MM-DD. Si no se especifica, usar la misma fecha de inicio.'
            },
            hora_fin: {
              type: 'string',
              description: 'Hora de fin en formato HH:MM (24h). Debe ser posterior a la hora de inicio.'
            },
            todo_el_dia: {
              type: 'boolean',
              description: 'Si es true, el evento es de todo el día'
            },
            ubicacion: {
              type: 'string',
              description: 'Ubicación opcional del evento'
            },
            color: {
              type: 'string',
              description: 'Color del evento: azul, verde, purpura, rosa, amarillo, naranja, turquesa, gris, azul_intenso, verde_intenso, rojo',
              enum: ['azul', 'verde', 'purpura', 'rosa', 'amarillo', 'naranja', 'turquesa', 'gris', 'azul_intenso', 'verde_intenso', 'rojo']
            }
          },
          required: ['titulo', 'fecha_inicio']
        }
      }
    ];
  }

  /**
   * Mapea colores legibles a IDs de Google Calendar
   */
  private mapColorToId(color?: string): string {
    const colorMap: Record<string, string> = {
      'azul': '1',
      'verde': '2', 
      'purpura': '3',
      'rosa': '4',
      'amarillo': '5',
      'naranja': '6',
      'turquesa': '7',
      'gris': '8',
      'azul_intenso': '9',
      'verde_intenso': '10',
      'rojo': '11'
    };
    return colorMap[color || 'azul'] || '1';
  }

  /**
   * Obtiene el contexto actual del calendario para Gemini
   */
  async getCalendarContext(): Promise<CalendarContext> {
    try {
      const hasAccess = await this.calendarService.checkCalendarAccess();
      const currentDate = DateTimeUtils.getCurrentDate();
      const todayFormatted = currentDate.toISOString().split('T')[0];
      
      if (!hasAccess) {
        return {
          events: [],
          today: todayFormatted,
          hasAccess: false
        };
      }

      const events = await this.calendarService.getTodayEvents();
      
      console.log('📅 Contexto del calendario para Gemini:', {
        fechaActual: DateTimeUtils.formatForDisplay(currentDate),
        fechaISO: todayFormatted,
        zonaHoraria: DateTimeUtils.getUserTimeZone(),
        eventosEncontrados: events.length,
        acceso: hasAccess
      });
      
      return {
        events,
        today: todayFormatted,
        hasAccess: true
      };
    } catch (error) {
      console.error('Error obteniendo contexto del calendario:', error);
      const currentDate = DateTimeUtils.getCurrentDate();
      return {
        events: [],
        today: currentDate.toISOString().split('T')[0],
        hasAccess: false
      };
    }
  }

  /**
   * Ejecuta una herramienta del calendario
   */
  async executeCalendarTool(toolName: string, parameters: any): Promise<string> {
    console.log(`📅 🔧 EJECUTANDO HERRAMIENTA: ${toolName}`, parameters);
    
    try {
      switch (toolName) {
        case 'leer_calendario':
          console.log('📅 📖 Leyendo calendario...');
          return await this.readCalendar(parameters.filtro);
        
        case 'crear_tarea':
          console.log('📅 ✨ Creando tarea...', parameters);
          return await this.createTask(parameters);
        
        case 'crear_evento':
          console.log('📅 🎯 Creando evento...', parameters);
          return await this.createEvent(parameters);
        
        default:
          console.error(`❌ Herramienta no reconocida: ${toolName}`);
          return `Error: Herramienta '${toolName}' no reconocida.`;
      }
    } catch (error) {
      console.error(`❌ Error ejecutando herramienta ${toolName}:`, error);
      return `Error: No se pudo ejecutar la acción solicitada. ${error instanceof Error ? error.message : 'Error desconocido'}`;
    }
  }

  /**
   * Lee el calendario según el filtro especificado
   */
  private async readCalendar(filtro: string = 'hoy'): Promise<string> {
    const hasAccess = await this.calendarService.checkCalendarAccess();
    if (!hasAccess) {
      return "No tienes acceso a Google Calendar. Necesitas iniciar sesión y autorizar el acceso.";
    }

    let events: CalendarEvent[] = [];
    let timeRange = '';

    switch (filtro) {
      case 'hoy':
        events = await this.calendarService.getTodayEvents();
        timeRange = 'de hoy';
        break;
      case 'semana':
        const ahora = new Date();
        const finSemana = new Date(ahora);
        finSemana.setDate(ahora.getDate() + 7);
        events = await this.calendarService.getEventsInRange(ahora, finSemana);
        timeRange = 'de esta semana';
        break;
      case 'mes':
        const inicioMes = new Date();
        const finMes = new Date(inicioMes);
        finMes.setMonth(inicioMes.getMonth() + 1);
        events = await this.calendarService.getEventsInRange(inicioMes, finMes);
        timeRange = 'de este mes';
        break;
      case 'todo':
        events = await this.calendarService.getUpcomingEvents(50);
        timeRange = 'de todos los eventos próximos';
        break;
      default:
        events = await this.calendarService.getTodayEvents();
        timeRange = 'de hoy';
    }

    if (events.length === 0) {
      return `No tienes tareas ni eventos ${timeRange}.`;
    }

    let response = `Tienes ${events.length} evento(s) ${timeRange}:\n\n`;
    
    events.forEach((event, index) => {
      const startTime = event.start?.dateTime ? 
        new Date(event.start.dateTime).toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' }) :
        'Todo el día';
      
      const date = event.start?.date || 
        (event.start?.dateTime ? new Date(event.start.dateTime).toLocaleDateString('es-ES') : 'Sin fecha');
      
      response += `${index + 1}. **${event.summary}**\n`;
      response += `   📅 ${date} - ⏰ ${startTime}\n`;
      
      if (event.description) {
        response += `   📝 ${event.description}\n`;
      }
      
      if (event.location) {
        response += `   📍 ${event.location}\n`;
      }
      
      response += '\n';
    });

    return response;
  }

  /**
   * Crea una nueva tarea
   */
  private async createTask(params: any): Promise<string> {
    console.log('📅 ✨ Iniciando creación de tarea:', params);
    
    const hasAccess = await this.calendarService.checkCalendarAccess();
    if (!hasAccess) {
      console.error('❌ Sin acceso a Google Calendar para crear tarea');
      return "No puedo crear la tarea porque no tienes acceso a Google Calendar. Necesitas iniciar sesión y autorizar el acceso.";
    }

    // Validar parámetros requeridos
    if (!params.titulo) {
      console.error('❌ Falta el título de la tarea');
      return "Error: Necesito un título para crear la tarea.";
    }

    // Preparar fechas
    const fecha = params.fecha || new Date().toISOString().split('T')[0];
    const esTodoElDia = params.todo_el_dia || !params.hora;
    
    console.log(`📅 ✨ Preparando tarea: "${params.titulo}" para ${fecha}, todo el día: ${esTodoElDia}`);
    
    let startDateTime: string | undefined;
    let endDateTime: string | undefined;

    if (!esTodoElDia && params.hora) {
      startDateTime = new Date(`${fecha}T${params.hora}`).toISOString();
      endDateTime = new Date(`${fecha}T${params.hora}`).toISOString();
      // Duración por defecto: 1 hora
      const endDate = new Date(endDateTime);
      endDate.setHours(endDate.getHours() + 1);
      endDateTime = endDate.toISOString();
      console.log(`📅 ⏰ Horario: ${params.hora} - ${endDate.toLocaleTimeString()}`);
    }

    const taskData: CreateEventRequest = {
      summary: params.titulo,
      description: params.descripcion,
      colorId: this.mapColorToId(params.color),
      start: esTodoElDia ? { date: fecha } : { dateTime: startDateTime },
      end: esTodoElDia ? { date: fecha } : { dateTime: endDateTime }
    };

    console.log('📅 ✨ Datos finales de la tarea:', taskData);

    try {
      const result = await this.calendarService.createEvent(taskData, 'primary');
      console.log('📅 ✅ Tarea creada exitosamente:', result);
      const timeInfo = esTodoElDia ? 'para todo el día' : `a las ${params.hora}`;
      return `✅ Tarea creada exitosamente: "${params.titulo}" para el ${fecha} ${timeInfo}.`;
    } catch (error) {
      console.error('📅 ❌ Error creando la tarea:', error);
      return `❌ Error creando la tarea: ${error instanceof Error ? error.message : 'Error desconocido'}`;
    }
  }

  /**
   * Crea un nuevo evento
   */
  private async createEvent(params: any): Promise<string> {
    console.log('📅 🎯 Iniciando creación de evento:', params);
    
    const hasAccess = await this.calendarService.checkCalendarAccess();
    if (!hasAccess) {
      console.error('❌ Sin acceso a Google Calendar para crear evento');
      return "No puedo crear el evento porque no tienes acceso a Google Calendar. Necesitas iniciar sesión y autorizar el acceso.";
    }

    // Validar parámetros requeridos
    if (!params.titulo) {
      console.error('❌ Falta el título del evento');
      return "Error: Necesito un título para crear el evento.";
    }

    if (!params.fecha_inicio) {
      console.error('❌ Falta la fecha de inicio del evento');
      return "Error: Necesito una fecha de inicio para crear el evento.";
    }

    // Preparar fechas
    const fechaInicio = params.fecha_inicio;
    const fechaFin = params.fecha_fin || fechaInicio;
    const esTodoElDia = params.todo_el_dia || (!params.hora_inicio && !params.hora_fin);
    
    console.log(`📅 🎯 Preparando evento: "${params.titulo}" del ${fechaInicio} al ${fechaFin}, todo el día: ${esTodoElDia}`);
    
    let startDateTime: string | undefined;
    let endDateTime: string | undefined;

    if (!esTodoElDia) {
      if (!params.hora_inicio) {
        console.error('❌ Falta la hora de inicio para evento con horario específico');
        return "Error: Necesito una hora de inicio para eventos que no son de todo el día.";
      }
      
      startDateTime = new Date(`${fechaInicio}T${params.hora_inicio}`).toISOString();
      console.log(`📅 ⏰ Inicio: ${params.hora_inicio} -> ${startDateTime}`);
      
      if (params.hora_fin) {
        endDateTime = new Date(`${fechaFin}T${params.hora_fin}`).toISOString();
        console.log(`📅 ⏰ Fin: ${params.hora_fin} -> ${endDateTime}`);
      } else {
        // Duración por defecto: 1 hora
        const endDate = new Date(startDateTime);
        endDate.setHours(endDate.getHours() + 1);
        endDateTime = endDate.toISOString();
        console.log(`📅 ⏰ Fin automático (1 hora): ${endDateTime}`);
      }
    }

    const eventData: CreateEventRequest = {
      summary: params.titulo,
      description: params.descripcion,
      location: params.ubicacion,
      colorId: this.mapColorToId(params.color),
      start: esTodoElDia ? { date: fechaInicio } : { dateTime: startDateTime },
      end: esTodoElDia ? { date: fechaFin } : { dateTime: endDateTime }
    };

    console.log('📅 🎯 Datos finales del evento:', eventData);

    try {
      const result = await this.calendarService.createEvent(eventData, 'primary');
      console.log('📅 ✅ Evento creado exitosamente:', result);
      const timeInfo = esTodoElDia ? 
        'para todo el día' : 
        `de ${params.hora_inicio} a ${params.hora_fin || 'una hora después'}`;
      return `✅ Evento creado exitosamente: "${params.titulo}" para el ${fechaInicio} ${timeInfo}.`;
    } catch (error) {
      console.error('📅 ❌ Error creando el evento:', error);
      return `❌ Error creando el evento: ${error instanceof Error ? error.message : 'Error desconocido'}`;
    }
  }
}

// Instancia singleton
export const calendarGeminiService = CalendarGeminiService.getInstance();