import React, { useState, useEffect } from 'react';
import { 
  RiCloseLine,
  RiUserLine,
  RiSettingsLine,
  RiLockLine,
  RiLogoutBoxLine,
  RiGoogleLine,
  RiKeyLine,
  RiCheckLine,
  RiErrorWarningLine,
  RiEyeLine,
  RiEyeOffLine,
  RiCalendarLine,
  RiShieldLine,
  RiRobotLine
} from 'react-icons/ri';
import { useDraggablePanel } from '../../hooks/useDraggablePanel';
import { useAuth } from '../../contexts/AuthContext';
import { LoginButton } from '../auth/LoginButton';
import ApiConfigService from '../../services/ApiConfigService';
import { userPreferencesService, UserPreferences } from '../../services/UserPreferencesService';
import { PreferencesToggle } from '../PreferencesToggle';
import './user-profile-panel.scss';

interface UserProfilePanelProps {
  isVisible: boolean;
  onClose: () => void;
  position?: 'left' | 'right';
  isRepositioned?: boolean;
}

const UserProfilePanel: React.FC<UserProfilePanelProps> = ({
  isVisible,
  onClose,
  position = 'right',
  isRepositioned = false
}) => {
  const [isMobile, setIsMobile] = useState<boolean>(false);
  const { user, signOut, loading, hasYouTubeAccess, checkingYouTubeAccess, refreshYouTubeAccess, signInWithYouTube } = useAuth();
  const [isSigningOut, setIsSigningOut] = useState(false);
  
  // Estados para configuración de API
  const [apiConfig, setApiConfig] = useState(ApiConfigService.getConfigStatus());
  const [customApiKey, setCustomApiKey] = useState('');
  const [useCustomApi, setUseCustomApi] = useState(false);
  const [isValidatingApi, setIsValidatingApi] = useState(false);
  const [showApiKey, setShowApiKey] = useState(false);
  const [apiValidationMessage, setApiValidationMessage] = useState('');

  // Estados para preferencias de usuario
  const [userPreferences, setUserPreferences] = useState<UserPreferences>(userPreferencesService.getPreferences());

  // Hook para hacer el panel arrastrable (solo en desktop)
  const initialPosition = position === 'left' ? { x: 25, y: 80 } : { x: window.innerWidth - 365, y: 80 };
  const { panelStyle, dragHandleProps, isDragging } = useDraggablePanel(
    initialPosition,
    !isMobile // Solo habilitado en desktop
  );

  // Detectar móvil
  React.useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth <= 768);
    };
    
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  // Cargar configuración de API al montar el componente
  useEffect(() => {
    const config = ApiConfigService.getConfigStatus();
    setApiConfig(config);
    if (config.hasCustomKey) {
      const userConfig = ApiConfigService.getApiConfig();
      setCustomApiKey(userConfig.customGeminiKey);
      setUseCustomApi(userConfig.useCustomGeminiKey);
    }
  }, []);

  // Función para cerrar sesión
  const handleSignOut = async () => {
    try {
      setIsSigningOut(true);
      await signOut();
      // El panel se puede mantener abierto para mostrar el estado de no autenticado
    } catch (error) {
      console.error('Error al cerrar sesión:', error);
      alert('Error al cerrar sesión. Por favor, intenta de nuevo.');
    } finally {
      setIsSigningOut(false);
    }
  };

  // Funciones para manejar configuración de API
  const handleToggleCustomApi = async (useCustom: boolean) => {
    setUseCustomApi(useCustom);
    
    if (!useCustom) {
      // Deshabilitar API personalizada
      await ApiConfigService.updateCustomGeminiKey('', false);
      setApiValidationMessage('Usando API del sistema');
      const updatedConfig = ApiConfigService.getConfigStatus();
      setApiConfig(updatedConfig);
    } else if (customApiKey.trim()) {
      // Habilitar si ya hay una key válida
      await handleValidateAndSaveApi();
    }
  };

  const handleValidateAndSaveApi = async () => {
    if (!customApiKey.trim()) {
      setApiValidationMessage('Por favor ingresa una API key válida');
      return;
    }

    setIsValidatingApi(true);
    setApiValidationMessage('Validando API key...');

    try {
      const isValid = await ApiConfigService.updateCustomGeminiKey(customApiKey, true);
      
      if (isValid) {
        setApiValidationMessage('✅ API key válida y guardada');
        setUseCustomApi(true);
      } else {
        setApiValidationMessage('❌ API key inválida o rate limited. Puedes guardarla sin validar.');
        setUseCustomApi(false);
      }
      
      const updatedConfig = ApiConfigService.getConfigStatus();
      setApiConfig(updatedConfig);
    } catch (error) {
      setApiValidationMessage('❌ Error al validar API key. Puedes guardarla sin validar.');
      setUseCustomApi(false);
    } finally {
      setIsValidatingApi(false);
    }
  };

  const handleSaveWithoutValidation = () => {
    if (!customApiKey.trim()) {
      setApiValidationMessage('Por favor ingresa una API key válida');
      return;
    }

    // Guardar directamente sin validación
    const config = ApiConfigService.getApiConfig();
    config.customGeminiKey = customApiKey;
    config.useCustomGeminiKey = true;
    config.isValid = true; // Asumir que es válida
    config.lastValidated = new Date();
    
    ApiConfigService.saveApiConfig(config);
    setUseCustomApi(true);
    setApiValidationMessage('💾 API key guardada sin validación');
    
    const updatedConfig = ApiConfigService.getConfigStatus();
    setApiConfig(updatedConfig);
  };

  const handleResetToDefault = () => {
    ApiConfigService.resetToDefault();
    setCustomApiKey('');
    setUseCustomApi(false);
    setApiValidationMessage('Configuración restablecida');
    const updatedConfig = ApiConfigService.getConfigStatus();
    setApiConfig(updatedConfig);
  };

  // Funciones para manejar las preferencias de usuario
  const handleTogglePersonalizedData = (enabled: boolean) => {
    userPreferencesService.togglePersonalizedData(enabled);
    setUserPreferences(userPreferencesService.getPreferences());
    
    // Mostrar mensaje informativo
    if (enabled) {
      console.log('📊 Respuestas personalizadas activadas - Gemini usará tus datos locales');
    } else {
      console.log('📊 Respuestas personalizadas desactivadas - Solo respuestas generales');
    }
  };

  const handleToggleAutoLoadCalendar = (enabled: boolean) => {
    userPreferencesService.toggleAutoLoadCalendarData(enabled);
    setUserPreferences(userPreferencesService.getPreferences());
    
    if (enabled) {
      console.log('📅 Carga automática del calendario activada');
    } else {
      console.log('📅 Carga automática del calendario desactivada');
    }
  };

  const handleToggleShareDataWithAI = (enabled: boolean) => {
    userPreferencesService.setPreference('shareDataWithAI', enabled);
    setUserPreferences(userPreferencesService.getPreferences());
  };

  const handleToggleConversationHistory = (enabled: boolean) => {
    userPreferencesService.setPreference('saveConversationHistory', enabled);
    setUserPreferences(userPreferencesService.getPreferences());
  };

  if (!isVisible) return null;

  return (
    <div 
      className={`user-profile-panel ${isMobile ? 'mobile' : ''} ${isDragging ? 'dragging' : ''} ${isRepositioned ? 'repositioned' : ''}`}
      style={!isMobile ? panelStyle : undefined}
    >
      {/* Header arrastrable */}
      <div 
        className="user-profile-panel-header"
        {...(!isMobile ? dragHandleProps : {})}
      >
        <div className="panel-title">
          <span className="panel-icon">👤</span>
          <h3>Perfil de Usuario</h3>
        </div>
        <button 
          className="close-button"
          onClick={onClose}
          title="Cerrar panel"
        >
          <RiCloseLine />
        </button>
      </div>

      {/* Contenido del panel */}
      <div className="user-profile-panel-content">
        {loading ? (
          // Estado de carga
          <div className="loading-section">
            <div className="loading-spinner"></div>
            <p>Cargando...</p>
          </div>
        ) : user ? (
          // Usuario autenticado
          <div className="user-profile-main">
            {/* Avatar y info básica del usuario autenticado */}
            <div className="user-avatar-section authenticated">
              <div className="avatar-container">
                {user.user_metadata?.avatar_url ? (
                  <img 
                    src={user.user_metadata.avatar_url} 
                    alt={user.user_metadata?.full_name || user.email || 'Usuario'}
                    className="avatar-image"
                  />
                ) : (
                  <div className="avatar-placeholder">
                    <span className="avatar-initial">
                      {(user.user_metadata?.full_name || user.email || 'U').charAt(0).toUpperCase()}
                    </span>
                  </div>
                )}
              </div>
              <div className="user-info">
                <h4>{user.user_metadata?.full_name || 'Usuario'}</h4>
                <p className="user-email">{user.email}</p>
                <p className="user-status authenticated">✅ Autenticado</p>
              </div>
            </div>

            {/* Información de la cuenta */}
            <div className="account-info-section">
              <h5>Información de la cuenta</h5>
              <div className="info-grid">
                <div className="info-item">
                  <span className="info-label">Proveedor:</span>
                  <span className="info-value">
                    <RiGoogleLine className="provider-icon" />
                    Google
                  </span>
                </div>
                <div className="info-item">
                  <span className="info-label">Último acceso:</span>
                  <span className="info-value">
                    {user.last_sign_in_at ? new Date(user.last_sign_in_at).toLocaleDateString('es-ES', {
                      year: 'numeric',
                      month: 'short',
                      day: 'numeric',
                      hour: '2-digit',
                      minute: '2-digit'
                    }) : 'No disponible'}
                  </span>
                </div>
                <div className="info-item">
                  <span className="info-label">ID de usuario:</span>
                  <span className="info-value user-id">{user.id.substring(0, 8)}...</span>
                </div>
              </div>
            </div>

            {/* Estado de YouTube API */}
            <div className="youtube-api-section">
              <h5>YouTube API</h5>
              <div className="youtube-status">
                {checkingYouTubeAccess ? (
                  <div className="checking-status">
                    <div className="loading-spinner small"></div>
                    <span>Verificando acceso...</span>
                  </div>
                ) : (
                  <div className={`api-status ${hasYouTubeAccess ? 'connected' : 'disconnected'}`}>
                    <span className="status-indicator">
                      {hasYouTubeAccess ? '🟢' : '🔴'}
                    </span>
                    <div className="status-info">
                      <span className="status-text">
                        {hasYouTubeAccess ? 'YouTube Conectado' : 'YouTube Desconectado'}
                      </span>
                      <span className="status-detail">
                        {hasYouTubeAccess 
                          ? 'Acceso completo a YouTube API con cuota individual'
                          : 'Sin acceso a YouTube API. Reinicia sesión para activar.'
                        }
                      </span>
                    </div>
                  </div>
                )}
                {!checkingYouTubeAccess && (
                  <div className="youtube-actions">
                    <button 
                      className="refresh-youtube-btn"
                      onClick={refreshYouTubeAccess}
                      title="Verificar acceso a YouTube"
                    >
                      🔄 Verificar
                    </button>
                    {!hasYouTubeAccess && (
                      <button 
                        className="enable-youtube-btn"
                        onClick={signInWithYouTube}
                        title="Habilitar acceso a YouTube"
                      >
                        📺 Habilitar YouTube
                      </button>
                    )}
                  </div>
                )}
              </div>
            </div>

            {/* Configuraciones de usuario */}
            <div className="user-preferences-section">
              <h5>
                <RiSettingsLine className="section-icon" />
                Preferencias de Usuario
              </h5>
              
              <div className="preferences-container">
                {/* Respuestas Personalizadas */}
                <PreferencesToggle
                  id="personalized-data"
                  label="Respuestas Personalizadas"
                  description="Permite que Gemini use tus datos locales (calendario, etc.) para dar respuestas más personalizadas (activado por defecto)"
                  checked={userPreferences.enablePersonalizedData}
                  onChange={handleTogglePersonalizedData}
                  icon="🤖"
                />

                {/* Carga Automática del Calendario */}
                <PreferencesToggle
                  id="auto-load-calendar"
                  label="Carga Automática del Calendario"
                  description="Cargar automáticamente datos del calendario al iniciar Gemini Live (recomendado y activado por defecto)"
                  checked={userPreferences.autoLoadCalendarData}
                  onChange={handleToggleAutoLoadCalendar}
                  disabled={!userPreferences.enablePersonalizedData}
                  icon="📅"
                  className={!userPreferences.enablePersonalizedData ? 'disabled' : ''}
                />

                {/* Compartir Datos con IA */}
                <PreferencesToggle
                  id="share-data-ai"
                  label="Compartir Datos con IA"
                  description="Permitir que la IA acceda a información adicional para mejorar las respuestas"
                  checked={userPreferences.shareDataWithAI}
                  onChange={handleToggleShareDataWithAI}
                  icon="🔗"
                />

                {/* Historial de Conversaciones */}
                <PreferencesToggle
                  id="conversation-history"
                  label="Guardar Historial de Conversaciones"
                  description="Mantener un historial local de tus conversaciones con Gemini"
                  checked={userPreferences.saveConversationHistory}
                  onChange={handleToggleConversationHistory}
                  icon="💬"
                />
              </div>

              <div className="preferences-info">
                <p className="info-text">
                  � <strong>Google Calendar habilitado por defecto:</strong>
                </p>
                <ul className="privacy-list">
                  <li>🏠 Todos los datos se almacenan localmente</li>
                  <li>🔐 Control total sobre qué información se usa</li>
                  <li>📅 Google Calendar se carga automáticamente para mejor experiencia</li>
                  <li>❌ Puedes desactivar funciones en cualquier momento</li>
                  <li>🗑️ Tus datos nunca se envían a servidores externos</li>
                </ul>
              </div>
            </div>

            {/* Configuración de API Personal */}
            <div className="api-config-section">
              <h5>
                <RiKeyLine className="section-icon" />
                Configuración de API Personal
              </h5>
              
              <div className="api-status-info">
                <div className="current-status">
                  <span className="status-label">Estado actual:</span>
                  <span className={`status-value ${apiConfig.usingCustomKey ? 'custom' : 'system'}`}>
                    {apiConfig.usingCustomKey ? '🔑 API Personal' : '🏢 API del Sistema'}
                  </span>
                </div>
                {apiConfig.lastValidated && (
                  <div className="last-validated">
                    <span className="status-label">Última validación:</span>
                    <span className="status-value">
                      {apiConfig.lastValidated.toLocaleDateString('es-ES')}
                    </span>
                  </div>
                )}
              </div>

              <div className="api-toggle-section">
                <label className="toggle-label">
                  <input
                    type="checkbox"
                    checked={useCustomApi}
                    onChange={(e) => handleToggleCustomApi(e.target.checked)}
                    disabled={isValidatingApi}
                  />
                  <span className="toggle-text">
                    Usar mi propia API key de Gemini
                  </span>
                </label>
                
                {useCustomApi && (
                  <div className="api-input-section">
                    <div className="input-group">
                      <input
                        type={showApiKey ? 'text' : 'password'}
                        value={customApiKey}
                        onChange={(e) => setCustomApiKey(e.target.value)}
                        placeholder="Ingresa tu API key de Gemini..."
                        className="api-key-input"
                        disabled={isValidatingApi}
                      />
                      <button
                        type="button"
                        className="toggle-visibility-btn"
                        onClick={() => setShowApiKey(!showApiKey)}
                        title={showApiKey ? 'Ocultar API key' : 'Mostrar API key'}
                      >
                        {showApiKey ? <RiEyeOffLine /> : <RiEyeLine />}
                      </button>
                    </div>
                    
                    <div className="api-actions">
                      <button
                        className="validate-btn"
                        onClick={handleValidateAndSaveApi}
                        disabled={isValidatingApi || !customApiKey.trim()}
                      >
                        {isValidatingApi ? (
                          <>
                            <div className="loading-spinner tiny"></div>
                            Validando...
                          </>
                        ) : (
                          <>
                            <RiCheckLine />
                            Validar y Guardar
                          </>
                        )}
                      </button>
                      
                      <button
                        className="save-direct-btn"
                        onClick={handleSaveWithoutValidation}
                        disabled={isValidatingApi || !customApiKey.trim()}
                        title="Guardar sin validar (útil si hay rate limiting)"
                      >
                        💾 Guardar Directo
                      </button>
                      
                      <button
                        className="reset-btn"
                        onClick={handleResetToDefault}
                        disabled={isValidatingApi}
                        title="Volver a usar API del sistema"
                      >
                        Restablecer
                      </button>
                    </div>
                    
                    {apiValidationMessage && (
                      <div className={`validation-message ${
                        apiValidationMessage.includes('✅') ? 'success' : 
                        apiValidationMessage.includes('❌') ? 'error' : 'info'
                      }`}>
                        {apiValidationMessage}
                      </div>
                    )}
                  </div>
                )}
              </div>

              <div className="api-info">
                <p className="info-text">
                  💡 <strong>¿Por qué usar tu propia API?</strong>
                </p>
                <ul className="benefits-list">
                  <li>🔒 Mayor privacidad y control</li>
                  <li>⚡ Sin límites compartidos</li>
                  <li>📊 Uso exclusivo de tu cuota</li>
                  <li>🎯 Configuración personalizada</li>
                </ul>
                
                <div className="rate-limit-info">
                  <p className="info-text">
                    ⚠️ <strong>Sobre Rate Limiting:</strong>
                  </p>
                  <ul className="benefits-list">
                    <li>🕐 Si ves errores 429, usa "Guardar Directo"</li>
                    <li>⏱️ La validación tiene cooldown de 3 segundos</li>
                    <li>✅ Las keys se cachean por 5 minutos</li>
                    <li>🔄 Rate limiting se resetea automáticamente</li>
                  </ul>
                </div>
                
                <p className="api-link">
                  🔗 <a href="https://aistudio.google.com/apikey" target="_blank" rel="noopener noreferrer">
                    Obtener API key gratuita de Gemini
                  </a>
                </p>
              </div>
            </div>

            {/* Botón de cerrar sesión */}
            <div className="logout-section">
              <button 
                className="logout-btn"
                onClick={handleSignOut}
                disabled={isSigningOut}
              >
                <RiLogoutBoxLine className="logout-icon" />
                <span>{isSigningOut ? 'Cerrando sesión...' : 'Cerrar sesión'}</span>
              </button>
            </div>

            {/* Características futuras */}
            <div className="features-preview">
              <h5>Disponible con tu cuenta:</h5>
              <ul className="features-list">
                <li>✅ Autenticación segura</li>
                <li>💾 Historial de conversaciones (pronto)</li>
                <li>⚙️ Configuraciones personalizadas (pronto)</li>
                <li>🌐 Sincronización multiplataforma (pronto)</li>
                <li>📊 Estadísticas de uso (pronto)</li>
              </ul>
            </div>
          </div>
        ) : (
          // Usuario no autenticado
          <div className="user-profile-main">
            {/* Avatar y info básica */}
            <div className="user-avatar-section">
              <div className="avatar-placeholder">
                <RiUserLine className="avatar-icon" />
              </div>
              <div className="user-info">
                <h4>Usuario Invitado</h4>
                <p className="user-status">No autenticado</p>
              </div>
            </div>

            {/* Botón de inicio de sesión */}
            <div className="login-section">
              <LoginButton 
                variant="primary" 
                size="medium"
                className="panel-login-btn"
              />
              <p className="login-hint">
                Inicia sesión para acceder a todas las funciones
              </p>
            </div>

            {/* Características futuras */}
            <div className="features-preview">
              <h5>Al iniciar sesión tendrás acceso a:</h5>
              <ul className="features-list">
                <li>🔐 Autenticación segura</li>
                <li>👤 Personalización de perfil</li>
                <li>💾 Historial de conversaciones</li>
                <li>⚙️ Configuraciones personalizadas</li>
                <li>🌐 Sincronización multiplataforma</li>
                <li>📊 Estadísticas de uso</li>
              </ul>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default UserProfilePanel;