import React from 'react'
import { 
  RiTaskLine,
  RiTimeLine,
  RiEditLine,
  RiDeleteBinLine,
  RiCheckLine,
  RiCalendarLine
} from 'react-icons/ri'
import { CalendarEvent } from '../../services/googleCalendar'

interface TaskListProps {
  tasks: CalendarEvent[]
  loading: boolean
  onEditTask: (task: CalendarEvent) => void
  onDeleteTask: (taskId: string) => void
  onCompleteTask: (taskId: string) => void
}

export function TaskList({ tasks, loading, onEditTask, onDeleteTask, onCompleteTask }: TaskListProps) {
  const formatTaskDate = (task: CalendarEvent) => {
    const dateStr = task.start.dateTime || task.start.date
    if (dateStr) {
      return new Date(dateStr).toLocaleDateString('es-ES', {
        weekday: 'short',
        month: 'short',
        day: 'numeric'
      })
    }
    return 'Sin fecha'
  }

  const formatTaskTime = (task: CalendarEvent) => {
    if (task.start.dateTime) {
      return new Date(task.start.dateTime).toLocaleTimeString('es-ES', {
        hour: '2-digit',
        minute: '2-digit'
      })
    }
    return 'Todo el día'
  }

  if (loading) {
    return (
      <div className="task-list-loading">
        <p>⏳ Cargando tareas...</p>
      </div>
    )
  }

  if (tasks.length === 0) {
    return (
      <div className="task-list-empty">
        <RiTaskLine className="empty-icon" />
        <p>No hay tareas pendientes</p>
        <small>Las tareas creadas aparecerán aquí</small>
      </div>
    )
  }

  return (
    <div className="task-list">
      <div className="task-list-header">
        <h4>
          <RiTaskLine /> Mis Tareas ({tasks.length})
        </h4>
      </div>
      
      <div className="task-items">
        {tasks.map((task) => (
          <div key={task.id} className="task-item">
            <div className="task-content">
              <div className="task-main">
                <h5 className="task-title">{task.summary}</h5>
                {task.description && (
                  <p className="task-description">{task.description}</p>
                )}
              </div>
              
              <div className="task-meta">
                <div className="task-datetime">
                  <span className="task-date">
                    <RiCalendarLine /> {formatTaskDate(task)}
                  </span>
                  <span className="task-time">
                    <RiTimeLine /> {formatTaskTime(task)}
                  </span>
                </div>
              </div>
            </div>
            
            <div className="task-actions">
              <button
                className="task-action complete"
                onClick={() => onCompleteTask(task.id!)}
                title="Marcar como completada"
              >
                <RiCheckLine />
              </button>
              <button
                className="task-action edit"
                onClick={() => onEditTask(task)}
                title="Editar tarea"
              >
                <RiEditLine />
              </button>
              <button
                className="task-action delete"
                onClick={() => onDeleteTask(task.id!)}
                title="Eliminar tarea"
              >
                <RiDeleteBinLine />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

export default TaskList