import React, { useState, useCallback, useEffect } from 'react';
import { useLiveAPIContext } from '../../contexts/LiveAPIContext';
import { SpanishVoiceService } from '../../services/SpanishVoiceService';
import { translations } from '../../i18n/translations';
import './ConversationControlButton.scss';

interface ConversationControlButtonProps {
  spanishVoiceService: SpanishVoiceService;
  className?: string;
}

export const ConversationControlButton: React.FC<ConversationControlButtonProps> = ({
  spanishVoiceService,
  className = ''
}) => {
  const { client, connected } = useLiveAPIContext();
  const [isInterrupted, setIsInterrupted] = useState(false);
  const [isAISpeaking, setIsAISpeaking] = useState(false);
  const [isVoiceSpeaking, setIsVoiceSpeaking] = useState(false);
  const t = translations.es;

  // Monitorear el estado de síntesis de voz española
  useEffect(() => {
    const checkVoiceStatus = () => {
      const speaking = spanishVoiceService.isSpeaking();
      setIsVoiceSpeaking(speaking);
    };

    const interval = setInterval(checkVoiceStatus, 100);
    return () => clearInterval(interval);
  }, [spanishVoiceService]);

  // Escuchar eventos del cliente de IA
  useEffect(() => {
    if (!client) return;

    const handleAudioStart = () => {
      setIsAISpeaking(true);
    };

    const handleAudioEnd = () => {
      setIsAISpeaking(false);
    };

    const handleInterrupted = () => {
      setIsInterrupted(true);
      setIsAISpeaking(false);
      setTimeout(() => setIsInterrupted(false), 2000); // Reset después de 2 segundos
    };

    const handleTurnComplete = () => {
      setIsAISpeaking(false);
    };

    // Agregar listeners
    client.on('audio', handleAudioStart);
    client.on('turncomplete', handleTurnComplete);
    client.on('interrupted', handleInterrupted);

    return () => {
      client.off('audio', handleAudioStart);
      client.off('turncomplete', handleTurnComplete);  
      client.off('interrupted', handleInterrupted);
    };
  }, [client]);

  // Función para interrumpir la conversación
  const handleInterrupt = useCallback(() => {
    if (!connected) return;

    try {
      // 1. Detener síntesis de voz española
      if (spanishVoiceService.isSpeaking()) {
        spanishVoiceService.stop();
      }

      // 2. Interrumpir el audio del AI (esto debería activar el evento 'interrupted')
      if (client) {
        // Enviar una interrupción manual si es necesario
        client.sendRealtimeInput([{
          mimeType: "text/plain",
          data: btoa("") // Envío vacío para interrumpir
        }]);
      }

      // 3. Indicar que se ha interrumpido
      setIsInterrupted(true);
      setTimeout(() => setIsInterrupted(false), 2000);

    } catch (error) {
      console.error('Error al interrumpir conversación:', error);
    }
  }, [connected, client, spanishVoiceService]);

  // Determinar el estado actual
  const isSpeaking = isAISpeaking || isVoiceSpeaking;
  const canInterrupt = connected && isSpeaking && !isInterrupted;

  // Determinar el texto del botón
  const getButtonText = () => {
    if (!connected) return t.connection.disconnected;
    if (isInterrupted) return '✓ Interrumpido';
    if (isSpeaking) return t.buttons.interrupt;
    return t.buttons.listening;
  };

  // Determinar el icono del botón
  const getButtonIcon = () => {
    if (!connected) return '🔌';
    if (isInterrupted) return '✋';
    if (isSpeaking) return '⏹️';
    return '👂';
  };

  // Clases CSS dinámicas
  const buttonClasses = [
    'conversation-control-button',
    className,
    !connected && 'disconnected',
    isSpeaking && 'speaking',
    isInterrupted && 'interrupted',
    canInterrupt && 'can-interrupt'
  ].filter(Boolean).join(' ');

  return (
    <div className="conversation-control-container">
      <button
        className={buttonClasses}
        onClick={handleInterrupt}
        disabled={!canInterrupt}
        title={getButtonText()}
        aria-label={getButtonText()}
      >
        <span className="button-icon">{getButtonIcon()}</span>
        <span className="button-text">{getButtonText()}</span>
      </button>
      
      {/* Indicador de estado */}
      <div className="status-indicators">
        {isAISpeaking && (
          <div className="status-indicator ai-speaking">
            <span className="indicator-dot"></span>
            <span className="indicator-text">IA hablando</span>
          </div>
        )}
        {isVoiceSpeaking && (
          <div className="status-indicator voice-speaking">
            <span className="indicator-dot"></span>
            <span className="indicator-text">Voz sintetizada</span>
          </div>
        )}
        {isInterrupted && (
          <div className="status-indicator interrupted">
            <span className="indicator-dot"></span>
            <span className="indicator-text">Conversación interrumpida</span>
          </div>
        )}
      </div>
    </div>
  );
};

export default ConversationControlButton;
