import React, { useEffect, useState } from 'react'
import { 
  RiCloseLine,
  RiCalendarLine,
  RiDragMove2Line,
  RiAddLine,
  RiTaskLine,
  RiCalendarEventLine,
  RiRefreshLine,
  RiSearchLine,
  RiSettings3Line,
  RiSaveLine,
  RiFileTextLine,
  RiTimeLine,
  RiPaletteLine
} from 'react-icons/ri'
import { useGoogleCalendar } from '../../hooks/useGoogleCalendar'
import { useDraggablePanel } from '../../hooks/useDraggablePanel'
import { CalendarEvent, CreateEventRequest } from '../../services/googleCalendar'
import { DateTimeUtils } from '../../utils/dateTimeUtils'
import { TaskList } from './TaskList'
import { CalendarView } from './CalendarView'
import { InteractiveCalendar } from './InteractiveCalendar'
import { AdvancedEventForm } from './AdvancedEventForm'
import { CalendarManager } from './CalendarManager'
import { AdvancedSearch } from './AdvancedSearch'
import './CalendarPanel.scss'

interface CalendarPanelProps {
  isVisible: boolean
  onClose: () => void
  position?: 'left' | 'right'
  isRepositioned?: boolean
  className?: string
}

type ViewType = 'tasks' | 'calendar' | 'interactive' | 'search' | 'manager'

export function CalendarPanel({ 
  isVisible,
  onClose,
  position = 'right',
  isRepositioned = false,
  className = '' 
}: CalendarPanelProps) {
  const [isMobile, setIsMobile] = useState<boolean>(false)
  
  // Hook para hacer el panel arrastrable (solo en desktop)
  const initialPosition = { 
    x: Math.max(20, (window.innerWidth - 600) / 2), 
    y: Math.max(20, (window.innerHeight - 600) / 2) 
  }
  const { panelStyle, dragHandleProps, isDragging } = useDraggablePanel(
    initialPosition,
    !isMobile
  )

  // Detectar móvil
  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth <= 768)
    }
    
    checkMobile()
    window.addEventListener('resize', checkMobile)
    return () => window.removeEventListener('resize', checkMobile)
  }, [])

  const {
    loading,
    error,
    events,
    hasAccess,
    checkingAccess,
    getTodayEvents,
    createEvent,
    updateEvent,
    deleteEvent,
    clearError
  } = useGoogleCalendar()

  // Estados del componente
  const [currentView, setCurrentView] = useState<ViewType>('tasks')
  const [isRefreshing, setIsRefreshing] = useState(false)
  const [showTaskForm, setShowTaskForm] = useState(false)
  const [editingTask, setEditingTask] = useState<CalendarEvent | null>(null)
  const [formLoading, setFormLoading] = useState(false)
  const [formError, setFormError] = useState<string | null>(null) // Nuevo estado para errores de formulario
  
  // Estados adicionales para las nuevas funcionalidades
  const [showAdvancedForm, setShowAdvancedForm] = useState(false)
  const [showEventForm, setShowEventForm] = useState(false) // Nuevo estado para formulario de eventos
  const [editingEvent, setEditingEvent] = useState<CalendarEvent | null>(null) // Nuevo estado para evento en edición
  const [selectedDate, setSelectedDate] = useState<Date>(DateTimeUtils.getCurrentDate())
  const [calendarView, setCalendarView] = useState<'month' | 'week'>('month')
  const [selectedCalendars, setSelectedCalendars] = useState<string[]>(['primary'])

  // Función para obtener valores iniciales de fecha y hora correctos
  const getInitialDateTimeValues = () => {
    const now = DateTimeUtils.getCurrentDate();
    const nextHour = new Date(now);
    nextHour.setHours(nextHour.getHours() + 1);
    
    return {
      date: now.toISOString().split('T')[0], // YYYY-MM-DD
      time: now.toTimeString().slice(0, 5), // HH:MM
      endTime: nextHour.toTimeString().slice(0, 5) // HH:MM + 1 hora
    };
  };

  // Estados para formularios integrados
  const [taskFormData, setTaskFormData] = useState(() => {
    const { date, time } = getInitialDateTimeValues();
    return {
      summary: '',
      description: '',
      date,
      time,
      isAllDay: false,
      colorId: '1' // Azul por defecto
    };
  })

  const [eventFormData, setEventFormData] = useState(() => {
    const { date, time, endTime } = getInitialDateTimeValues();
    return {
      summary: '',
      description: '',
      location: '',
      startDate: date,
      startTime: time,
      endDate: date,
      endTime,
      isAllDay: false,
      colorId: '1' // Azul por defecto
    };
  })

  // Estado para controlar si ya se cargaron los eventos iniciales
  const [initialEventsLoaded, setInitialEventsLoaded] = useState(false)

  // Debug logging (sin trigger de carga)
  useEffect(() => {
    console.log('🗓️ CalendarPanel Debug:', {
      hasAccess,
      checkingAccess,
      isVisible,
      events: events.length,
      error,
      loading,
      currentView,
      initialEventsLoaded
    })
  }, [hasAccess, checkingAccess, isVisible, events.length, error, loading, currentView, initialEventsLoaded])

  // Cargar eventos SOLO UNA VEZ cuando tenemos acceso por primera vez
  useEffect(() => {
    if (hasAccess && !loading && !checkingAccess && isVisible && !initialEventsLoaded) {
      console.log('🗓️ CalendarPanel: Cargando eventos de hoy (primera vez)...')
      const loadEvents = async () => {
        try {
          await getTodayEvents()
          setInitialEventsLoaded(true)
        } catch (err) {
          console.warn('Error cargando eventos:', err)
        }
      }
      loadEvents()
    }
  }, [hasAccess, loading, checkingAccess, isVisible, initialEventsLoaded, getTodayEvents])

  // Reset del flag cuando el panel se cierra
  useEffect(() => {
    if (!isVisible) {
      setInitialEventsLoaded(false)
    }
  }, [isVisible])

  const loadTodayEvents = async () => {
    try {
      await getTodayEvents()
      setInitialEventsLoaded(true) // Marcar como cargados para evitar bucles
    } catch (err) {
      console.warn('Error cargando eventos:', err)
    }
  }

  const handleRefresh = async () => {
    setIsRefreshing(true)
    setInitialEventsLoaded(false) // Reset flag para permitir recarga
    try {
      console.log('🗓️ CalendarPanel: Refrescando y forzando verificación de acceso...')
      await clearError()
      
      // Forzar re-verificación de acceso manualmente
      const { googleCalendar } = await import('../../services/googleCalendar')
      const hasCalendarAccessManual = await googleCalendar.checkCalendarAccess()
      console.log('🗓️ CalendarPanel: Verificación manual de acceso:', hasCalendarAccessManual)
      
      if (hasCalendarAccessManual) {
        await loadTodayEvents()
      }
    } catch (error) {
      console.error('Error refrescando:', error)
    } finally {
      setIsRefreshing(false)
    }
  }

  const handleCreateTask = () => {
    setEditingTask(null)
    setShowTaskForm(true)
  }

  const handleEditTask = (task: CalendarEvent) => {
    setEditingTask(task)
    setShowTaskForm(true)
  }

  const handleDeleteTask = async (taskId: string) => {
    if (window.confirm('¿Estás seguro de que quieres eliminar esta tarea?')) {
      try {
        await deleteEvent(taskId, 'primary')
        await loadTodayEvents()
      } catch (error) {
        console.error('Error eliminando tarea:', error)
      }
    }
  }

  const handleCompleteTask = async (taskId: string) => {
    try {
      // Actualizar tarea como completada
      await updateEvent(taskId, { 
        summary: '[COMPLETADA] ' + events.find(e => e.id === taskId)?.summary 
      }, 'primary')
      await loadTodayEvents()
    } catch (error) {
      console.error('Error completando tarea:', error)
    }
  }

  const handleSaveTask = async (taskData: CreateEventRequest) => {
    setFormLoading(true)
    setFormError(null)
    try {
      console.log('🗓️ CalendarPanel: Guardando tarea...', taskData);
      if (editingTask) {
        await updateEvent(editingTask.id!, taskData, 'primary')
        console.log('🗓️ CalendarPanel: Tarea actualizada exitosamente');
      } else {
        await createEvent(taskData, 'primary')
        console.log('🗓️ CalendarPanel: Tarea creada exitosamente');
      }
      // No necesitamos llamar loadTodayEvents() manualmente porque
      // el hook ya maneja la recarga automáticamente después de crear/actualizar
      setShowTaskForm(false)
      setEditingTask(null)
    } catch (error) {
      console.error('🗓️ CalendarPanel: Error guardando tarea:', error)
      const errorMessage = error instanceof Error ? error.message : 'Error desconocido al guardar la tarea';
      setFormError(errorMessage);
      throw error
    } finally {
      setFormLoading(false)
    }
  }

  const handleSaveEvent = async (eventData: CreateEventRequest) => {
    setFormLoading(true)
    setFormError(null)
    try {
      console.log('🗓️ CalendarPanel: Guardando evento...', eventData);
      if (editingEvent) {
        await updateEvent(editingEvent.id!, eventData, 'primary')
        console.log('🗓️ CalendarPanel: Evento actualizado exitosamente');
      } else {
        await createEvent(eventData, 'primary')
        console.log('🗓️ CalendarPanel: Evento creado exitosamente');
      }
      // No necesitamos llamar loadTodayEvents() manualmente porque
      // el hook ya maneja la recarga automáticamente después de crear/actualizar
      setShowEventForm(false)
      setEditingEvent(null)
    } catch (error) {
      console.error('🗓️ CalendarPanel: Error guardando evento:', error)
      const errorMessage = error instanceof Error ? error.message : 'Error desconocido al guardar el evento';
      setFormError(errorMessage);
      throw error
    } finally {
      setFormLoading(false)
    }
  }

  // Funciones para formularios integrados
  const handleTaskSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    
    if (!taskFormData.summary.trim()) {
      return
    }

    setFormLoading(true)
    setFormError(null)
    try {
      // Crear fechas de manera más robusta usando DateTimeUtils
      let startDateTime: Date | undefined;
      let endDateTime: Date | undefined;
      
      if (!taskFormData.isAllDay) {
        // Usar DateTimeUtils para crear fechas en zona horaria local
        const [year, month, day] = taskFormData.date.split('-').map(Number);
        const [hours, minutes] = taskFormData.time.split(':').map(Number);
        
        startDateTime = DateTimeUtils.createLocalDate(year, month, day, hours, minutes);
        endDateTime = DateTimeUtils.createLocalDate(year, month, day, hours + 1, minutes); // +1 hora por defecto
        
        console.log('🗓️ CalendarPanel: Fechas de tarea creadas con DateTimeUtils:', {
          fechaFormulario: taskFormData.date,
          horaFormulario: taskFormData.time,
          startDateTime: DateTimeUtils.formatForDisplay(startDateTime),
          endDateTime: DateTimeUtils.formatForDisplay(endDateTime),
          startDateTimeISO: startDateTime.toISOString(),
          endDateTimeISO: endDateTime.toISOString(),
          zonaHoraria: DateTimeUtils.getUserTimeZone(),
          fechaActual: DateTimeUtils.formatForDisplay(DateTimeUtils.getCurrentDate())
        });
      }

      const taskData: CreateEventRequest = {
        summary: taskFormData.summary,
        description: taskFormData.description,
        colorId: taskFormData.colorId,
        start: taskFormData.isAllDay 
          ? { date: taskFormData.date }
          : { 
              dateTime: startDateTime?.toISOString(),
              timeZone: DateTimeUtils.getUserTimeZone()
            },
        end: taskFormData.isAllDay 
          ? { date: taskFormData.date }
          : { 
              dateTime: endDateTime?.toISOString(),
              timeZone: DateTimeUtils.getUserTimeZone()
            }
      }

      console.log('🗓️ CalendarPanel: Enviando tarea desde formulario integrado...', taskData);
      
      if (editingTask) {
        await updateEvent(editingTask.id!, taskData, 'primary')
        console.log('🗓️ CalendarPanel: Tarea actualizada desde formulario integrado');
      } else {
        await createEvent(taskData, 'primary')
        console.log('🗓️ CalendarPanel: Tarea creada desde formulario integrado');
      }
      
      // No necesitamos llamar loadTodayEvents() manualmente porque
      // el hook ya maneja la recarga automáticamente después de crear/actualizar
      setShowTaskForm(false)
      setEditingTask(null)
      
      // Reset form
      setTaskFormData({
        summary: '',
        description: '',
        date: new Date().toISOString().split('T')[0],
        time: new Date().toTimeString().slice(0, 5),
        isAllDay: false,
        colorId: '1'
      })
    } catch (error) {
      console.error('🗓️ CalendarPanel: Error guardando tarea desde formulario integrado:', error)
      const errorMessage = error instanceof Error ? error.message : 'Error desconocido al guardar la tarea';
      setFormError(errorMessage);
    } finally {
      setFormLoading(false)
    }
  }

  const handleTaskCancel = () => {
    const { date, time } = getInitialDateTimeValues();
    setShowTaskForm(false)
    setEditingTask(null)
    setTaskFormData({
      summary: '',
      description: '',
      date,
      time,
      isAllDay: false,
      colorId: '1'
    })
  }

  const handleTaskFieldChange = (field: keyof typeof taskFormData, value: string | boolean) => {
    setTaskFormData(prev => ({
      ...prev,
      [field]: value
    }))
  }

  const handleEventSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    
    if (!eventFormData.summary.trim()) {
      return
    }

    setFormLoading(true)
    setFormError(null)
    try {
      // Crear fechas de manera más robusta usando DateTimeUtils
      let startDateTime: Date | undefined;
      let endDateTime: Date | undefined;
      
      if (!eventFormData.isAllDay) {
        // Crear fecha de inicio usando DateTimeUtils
        const [startYear, startMonth, startDay] = eventFormData.startDate.split('-').map(Number);
        const [startHours, startMinutes] = eventFormData.startTime.split(':').map(Number);
        startDateTime = DateTimeUtils.createLocalDate(startYear, startMonth, startDay, startHours, startMinutes);
        
        // Crear fecha de fin usando DateTimeUtils
        const [endYear, endMonth, endDay] = eventFormData.endDate.split('-').map(Number);
        const [endHours, endMinutes] = eventFormData.endTime.split(':').map(Number);
        endDateTime = DateTimeUtils.createLocalDate(endYear, endMonth, endDay, endHours, endMinutes);
        
        console.log('🗓️ CalendarPanel: Fechas de evento creadas con DateTimeUtils:', {
          fechaInicioFormulario: eventFormData.startDate,
          horaInicioFormulario: eventFormData.startTime,
          fechaFinFormulario: eventFormData.endDate,
          horaFinFormulario: eventFormData.endTime,
          startDateTime: DateTimeUtils.formatForDisplay(startDateTime),
          endDateTime: DateTimeUtils.formatForDisplay(endDateTime),
          startDateTimeISO: startDateTime.toISOString(),
          endDateTimeISO: endDateTime.toISOString(),
          zonaHoraria: DateTimeUtils.getUserTimeZone(),
          fechaActual: DateTimeUtils.formatForDisplay(DateTimeUtils.getCurrentDate())
        });
      }

      const eventData: CreateEventRequest = {
        summary: eventFormData.summary,
        description: eventFormData.description,
        location: eventFormData.location,
        colorId: eventFormData.colorId,
        start: eventFormData.isAllDay 
          ? { date: eventFormData.startDate }
          : { 
              dateTime: startDateTime?.toISOString(),
              timeZone: DateTimeUtils.getUserTimeZone()
            },
        end: eventFormData.isAllDay 
          ? { date: eventFormData.endDate }
          : { 
              dateTime: endDateTime?.toISOString(),
              timeZone: DateTimeUtils.getUserTimeZone()
            }
      }

      console.log('🗓️ CalendarPanel: Enviando evento desde formulario integrado...', eventData);

      if (editingEvent) {
        await updateEvent(editingEvent.id!, eventData, 'primary')
        console.log('🗓️ CalendarPanel: Evento actualizado desde formulario integrado');
      } else {
        await createEvent(eventData, 'primary')
        console.log('🗓️ CalendarPanel: Evento creado desde formulario integrado');
      }
      
      // No necesitamos llamar loadTodayEvents() manualmente porque
      // el hook ya maneja la recarga automáticamente después de crear/actualizar
      setShowEventForm(false)
      setEditingEvent(null)
      
      // Reset form
      const { date, time, endTime } = getInitialDateTimeValues();
      setEventFormData({
        summary: '',
        description: '',
        location: '',
        startDate: date,
        startTime: time,
        endDate: date,
        endTime,
        isAllDay: false,
        colorId: '1'
      })
    } catch (error) {
      console.error('🗓️ CalendarPanel: Error guardando evento desde formulario integrado:', error)
      const errorMessage = error instanceof Error ? error.message : 'Error desconocido al guardar el evento';
      setFormError(errorMessage);
    } finally {
      setFormLoading(false)
    }
  }

  const handleEventCancel = () => {
    setShowEventForm(false)
    setEditingEvent(null)
    setEventFormData({
      summary: '',
      description: '',
      location: '',
      startDate: new Date().toISOString().split('T')[0],
      startTime: new Date().toTimeString().slice(0, 5),
      endDate: new Date().toISOString().split('T')[0],
      endTime: new Date(Date.now() + 60 * 60 * 1000).toTimeString().slice(0, 5),
      isAllDay: false,
      colorId: '1'
    })
  }

  const handleEventClick = (event: CalendarEvent) => {
    handleEditTask(event)
  }

  const handleDateChange = (date: Date) => {
    setSelectedDate(date)
    console.log('🗓️ Fecha seleccionada:', date)
  }

  const handleCreateEvent = () => {
    setEditingTask(null)
    setShowAdvancedForm(true)
  }

  const handleEditEvent = (event: CalendarEvent) => {
    setEditingTask(event)
    setShowAdvancedForm(true)
  }

  const handleSaveAdvancedEvent = async (eventData: CreateEventRequest) => {
    setFormLoading(true)
    try {
      if (editingTask) {
        await updateEvent(editingTask.id, eventData, 'primary')
      } else {
        await createEvent(eventData, 'primary')
      }
      await loadTodayEvents()
      setShowAdvancedForm(false)
      setEditingTask(null)
    } catch (error) {
      console.error('Error guardando evento:', error)
    } finally {
      setFormLoading(false)
    }
  }

  const handleCalendarViewChange = (view: 'month' | 'week') => {
    setCalendarView(view)
  }

  const handleCalendarToggle = (calendarId: string, enabled: boolean) => {
    setSelectedCalendars(prev => 
      enabled 
        ? [...prev, calendarId]
        : prev.filter(id => id !== calendarId)
    )
  }

  // Si el panel no es visible, no renderizar nada
  if (!isVisible) return null

  // Clases CSS dinámicas
  const panelClasses = [
    'calendar-panel',
    className,
    isMobile ? 'calendar-panel--mobile' : 'calendar-panel--desktop',
    isDragging ? 'calendar-panel--dragging' : '',
    isRepositioned ? 'calendar-panel--repositioned' : ''
  ].filter(Boolean).join(' ')

  // Estilo combinado para posicionamiento
  const combinedStyles = !isMobile ? 
    { ...panelStyle, top: 'unset', left: 'unset', right: 'unset', bottom: 'unset' } : 
    {}

  // Condición simplificada para evitar bucle de "verificando acceso"
  if (checkingAccess) {
    return (
      <div 
        className={`${panelClasses} calendar-panel--loading`}
        style={combinedStyles}
      >
        <div 
          className="calendar-panel__header"
          {...(!isMobile ? dragHandleProps : {})}
        >
          <div className="header-info">
            <RiCalendarLine className="calendar-icon" />
            <div>
              <h3>📅 Google Calendar</h3>
              <span>Verificando acceso...</span>
            </div>
          </div>
          <div className="header-actions">
            <button onClick={onClose} className="close-btn" title="Cerrar">
              <RiCloseLine />
            </button>
          </div>
        </div>
        <div className="calendar-panel__content">
          <div className="loading-message">
            <p>🔄 Verificando acceso a Google Calendar...</p>
          </div>
        </div>
      </div>
    )
  }

  // Si no tiene acceso, mostrar mensaje de error
  if (!hasAccess) {
    return (
      <div 
        className={`${panelClasses} calendar-panel--no-access`}
        style={combinedStyles}
      >
        <div 
          className="calendar-panel__header"
          {...(!isMobile ? dragHandleProps : {})}
        >
          <div className="header-info">
            <RiCalendarLine className="calendar-icon" />
            <div>
              <h3>📅 Google Calendar</h3>
              <span>Sin acceso</span>
            </div>
          </div>
          <div className="header-actions">
            <button onClick={onClose} className="close-btn" title="Cerrar">
              <RiCloseLine />
            </button>
          </div>
        </div>
        <div className="calendar-panel__content">
          <div className="no-access-message">
            <p>🔒 <strong>Acceso a Google Calendar no disponible</strong></p>
            <p>Para usar el calendario, necesitas:</p>
            <ul>
              <li>✅ Iniciar sesión con Google</li>
              <li>✅ Autorizar acceso a Google Calendar</li>
            </ul>
            <p><small>Usa el botón de "Iniciar Sesión" en la parte superior de la página.</small></p>
            <button 
              className="retry-access-btn"
              onClick={handleRefresh}
              disabled={isRefreshing || checkingAccess}
            >
              {isRefreshing || checkingAccess ? '⏳ Verificando...' : '🔄 Verificar acceso de nuevo'}
            </button>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div 
      className={panelClasses}
      style={combinedStyles}
    >
      <div 
        className="calendar-panel__header"
        {...(!isMobile ? dragHandleProps : {})}
      >
        <div className="header-info">
          <RiCalendarLine className="calendar-icon" />
          <div>
            <h3>
              📅 Google Calendar
              {!isMobile && (
                <span className="drag-indicator" title="Arrastra para mover el panel">⋮⋮</span>
              )}
            </h3>
            <span>Tareas y eventos</span>
          </div>
        </div>
        <div className="header-actions">
          <button
            className="action-btn"
            onClick={handleRefresh}
            disabled={isRefreshing}
            title="Actualizar"
          >
            <RiRefreshLine />
          </button>
          <button onClick={onClose} className="close-btn" title="Cerrar">
            <RiCloseLine />
          </button>
        </div>
      </div>
      
      {/* Navegación entre vistas */}
      <div className="calendar-panel__nav">
        <button
          className={`nav-btn ${currentView === 'tasks' ? 'active' : ''}`}
          onClick={() => setCurrentView('tasks')}
          title="Ver tareas pendientes"
        >
          <RiTaskLine /> Tareas
        </button>
        <button
          className={`nav-btn ${currentView === 'calendar' ? 'active' : ''}`}
          onClick={() => setCurrentView('calendar')}
          title="Vista de calendario básica"
        >
          <RiCalendarEventLine /> Vista
        </button>
        <button
          className={`nav-btn ${currentView === 'interactive' ? 'active' : ''}`}
          onClick={() => setCurrentView('interactive')}
          title="Calendario interactivo completo"
        >
          <RiCalendarLine /> Interactivo
        </button>
        <button
          className={`nav-btn ${currentView === 'search' ? 'active' : ''}`}
          onClick={() => setCurrentView('search')}
          title="Búsqueda avanzada de eventos"
        >
          <RiSearchLine /> Buscar
        </button>
        <button
          className={`nav-btn ${currentView === 'manager' ? 'active' : ''}`}
          onClick={() => setCurrentView('manager')}
          title="Gestionar calendarios"
        >
          <RiSettings3Line /> Gestión
        </button>
      </div>

      <div className="calendar-panel__content">
        {error && (
          <div className="error-message">
            <p>❌ {error}</p>
            <button onClick={clearError} className="error-dismiss">
              Cerrar
            </button>
          </div>
        )}

        {/* Mensaje de error específico del formulario */}
        {formError && (
          <div className="error-message form-error">
            <p>❌ {formError}</p>
            <button onClick={() => setFormError(null)} className="error-dismiss">
              Cerrar
            </button>
          </div>
        )}

        {/* Vista de Tareas */}
        {currentView === 'tasks' && (
          <div className="task-view-container">
            {!showTaskForm ? (
              <>
                <div className="action-buttons-container">
                  <button
                    className="create-task-btn"
                    onClick={() => setShowTaskForm(true)}
                    title="Nueva tarea rápida"
                  >
                    <RiAddLine /> Crear Tarea
                  </button>
                </div>
                <TaskList
                  tasks={events}
                  loading={loading}
                  onEditTask={handleEditTask}
                  onDeleteTask={handleDeleteTask}
                  onCompleteTask={handleCompleteTask}
                />
              </>
            ) : (
              <div className="integrated-task-form">
                <div className="form-header">
                  <h3>
                    <RiTaskLine />
                    {editingTask ? 'Editar Tarea' : 'Nueva Tarea'}
                  </h3>
                  <button 
                    className="close-btn"
                    onClick={() => {
                      setShowTaskForm(false)
                      setEditingTask(null)
                    }}
                    disabled={formLoading}
                  >
                    <RiCloseLine />
                  </button>
                </div>

                <form onSubmit={handleTaskSubmit} className="task-form-content">
                  <div className="form-group">
                    <label>
                      <RiTaskLine /> Título *
                    </label>
                    <input
                      type="text"
                      value={taskFormData.summary}
                      onChange={(e) => setTaskFormData(prev => ({ ...prev, summary: e.target.value }))}
                      placeholder="¿Qué necesitas hacer?"
                      disabled={formLoading}
                      required
                    />
                  </div>

                  <div className="form-group">
                    <label>
                      <RiFileTextLine /> Descripción
                    </label>
                    <textarea
                      value={taskFormData.description}
                      onChange={(e) => setTaskFormData(prev => ({ ...prev, description: e.target.value }))}
                      placeholder="Detalles adicionales (opcional)"
                      rows={2}
                      disabled={formLoading}
                    />
                  </div>

                  <div className="form-group">
                    <label>
                      <RiPaletteLine /> Color de la tarea
                    </label>
                    <div className="color-selector">
                      {[
                        { id: '1', name: 'Azul claro', color: '#a4bdfc' },
                        { id: '2', name: 'Verde claro', color: '#7ae7bf' },
                        { id: '3', name: 'Púrpura', color: '#dbadff' },
                        { id: '4', name: 'Rosa', color: '#ff887c' },
                        { id: '5', name: 'Amarillo', color: '#fbd75b' },
                        { id: '6', name: 'Naranja', color: '#ffb878' },
                        { id: '7', name: 'Turquesa', color: '#46d6db' },
                        { id: '8', name: 'Gris', color: '#e1e1e1' },
                        { id: '9', name: 'Azul intenso', color: '#5484ed' },
                        { id: '10', name: 'Verde intenso', color: '#51b749' },
                        { id: '11', name: 'Rojo', color: '#dc2127' }
                      ].map(colorOption => (
                        <button
                          key={colorOption.id}
                          type="button"
                          className={`color-option ${taskFormData.colorId === colorOption.id ? 'selected' : ''}`}
                          style={{ backgroundColor: colorOption.color }}
                          onClick={() => setTaskFormData(prev => ({ ...prev, colorId: colorOption.id }))}
                          disabled={formLoading}
                          title={colorOption.name}
                        />
                      ))}
                    </div>
                  </div>

                  <div className="form-row">
                    <div className="form-group">
                      <label>
                        <RiCalendarLine /> Fecha *
                      </label>
                      <input
                        type="date"
                        value={taskFormData.date}
                        onChange={(e) => setTaskFormData(prev => ({ ...prev, date: e.target.value }))}
                        disabled={formLoading}
                        required
                      />
                    </div>

                    <div className="form-group">
                      <label>
                        <RiTimeLine /> Hora
                      </label>
                      <div className="time-picker-container">
                        <input
                          type="time"
                          value={taskFormData.time}
                          onChange={(e) => setTaskFormData(prev => ({ ...prev, time: e.target.value }))}
                          disabled={taskFormData.isAllDay || formLoading}
                          className="visual-time-input"
                        />
                        <span className="time-display">
                          {!taskFormData.isAllDay && taskFormData.time ? 
                            new Date(`2000-01-01T${taskFormData.time}`).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) 
                            : '⏰'
                          }
                        </span>
                      </div>
                    </div>
                  </div>

                  <div className="form-group checkbox-group">
                    <label className="checkbox-label">
                      <input
                        type="checkbox"
                        checked={taskFormData.isAllDay}
                        onChange={(e) => setTaskFormData(prev => ({ ...prev, isAllDay: e.target.checked }))}
                        disabled={formLoading}
                      />
                      <span>Todo el día</span>
                    </label>
                  </div>

                  <div className="form-actions">
                    <button
                      type="button"
                      className="cancel-btn"
                      onClick={() => {
                        setShowTaskForm(false)
                        setEditingTask(null)
                      }}
                      disabled={formLoading}
                    >
                      Cancelar
                    </button>
                    <button
                      type="submit"
                      className="save-btn"
                      disabled={formLoading || !taskFormData.summary.trim()}
                    >
                      <RiSaveLine />
                      {formLoading ? 'Guardando...' : (editingTask ? 'Actualizar' : 'Crear Tarea')}
                    </button>
                  </div>
                </form>
              </div>
            )}
          </div>
        )}

        {/* Vista de Calendario */}
        {currentView === 'calendar' && (
          <div className="calendar-view-container">
            {!showEventForm ? (
              <>
                <div className="action-buttons-container">
                  <button
                    className="create-event-btn"
                    onClick={() => setShowEventForm(true)}
                    title="Crear evento completo"
                  >
                    <RiCalendarEventLine /> Crear Evento
                  </button>
                </div>
                <CalendarView
                  events={events}
                  loading={loading}
                  onEventClick={handleEventClick}
                  onDateChange={handleDateChange}
                />
              </>
            ) : (
              <div className="integrated-event-form">
                <div className="form-header">
                  <h3>
                    <RiCalendarEventLine />
                    {editingEvent ? 'Editar Evento' : 'Nuevo Evento'}
                  </h3>
                  <button 
                    className="close-btn"
                    onClick={() => {
                      setShowEventForm(false)
                      setEditingEvent(null)
                    }}
                    disabled={formLoading}
                  >
                    <RiCloseLine />
                  </button>
                </div>

                <form onSubmit={handleEventSubmit} className="event-form-content">
                  <div className="form-group">
                    <label>
                      <RiCalendarEventLine /> Título *
                    </label>
                    <input
                      type="text"
                      value={eventFormData.summary}
                      onChange={(e) => setEventFormData(prev => ({ ...prev, summary: e.target.value }))}
                      placeholder="Título del evento"
                      disabled={formLoading}
                      required
                    />
                  </div>

                  <div className="form-group">
                    <label>
                      <RiFileTextLine /> Descripción
                    </label>
                    <textarea
                      value={eventFormData.description}
                      onChange={(e) => setEventFormData(prev => ({ ...prev, description: e.target.value }))}
                      placeholder="Descripción del evento (opcional)"
                      rows={2}
                      disabled={formLoading}
                    />
                  </div>

                  <div className="form-group">
                    <label>
                      <RiPaletteLine /> Color del evento
                    </label>
                    <div className="color-selector">
                      {[
                        { id: '1', name: 'Azul claro', color: '#a4bdfc' },
                        { id: '2', name: 'Verde claro', color: '#7ae7bf' },
                        { id: '3', name: 'Púrpura', color: '#dbadff' },
                        { id: '4', name: 'Rosa', color: '#ff887c' },
                        { id: '5', name: 'Amarillo', color: '#fbd75b' },
                        { id: '6', name: 'Naranja', color: '#ffb878' },
                        { id: '7', name: 'Turquesa', color: '#46d6db' },
                        { id: '8', name: 'Gris', color: '#e1e1e1' },
                        { id: '9', name: 'Azul intenso', color: '#5484ed' },
                        { id: '10', name: 'Verde intenso', color: '#51b749' },
                        { id: '11', name: 'Rojo', color: '#dc2127' }
                      ].map(colorOption => (
                        <button
                          key={colorOption.id}
                          type="button"
                          className={`color-option ${eventFormData.colorId === colorOption.id ? 'selected' : ''}`}
                          style={{ backgroundColor: colorOption.color }}
                          onClick={() => setEventFormData(prev => ({ ...prev, colorId: colorOption.id }))}
                          disabled={formLoading}
                          title={colorOption.name}
                        />
                      ))}
                    </div>
                  </div>

                  <div className="form-row">
                    <div className="form-group">
                      <label>
                        <RiCalendarLine /> Fecha inicio *
                      </label>
                      <input
                        type="date"
                        value={eventFormData.startDate}
                        onChange={(e) => setEventFormData(prev => ({ ...prev, startDate: e.target.value }))}
                        disabled={formLoading}
                        required
                      />
                    </div>

                    <div className="form-group">
                      <label>
                        <RiTimeLine /> Hora inicio
                      </label>
                      <div className="time-picker-container">
                        <input
                          type="time"
                          value={eventFormData.startTime}
                          onChange={(e) => setEventFormData(prev => ({ ...prev, startTime: e.target.value }))}
                          disabled={eventFormData.isAllDay || formLoading}
                          className="visual-time-input"
                        />
                        <span className="time-display">
                          {!eventFormData.isAllDay && eventFormData.startTime ? 
                            new Date(`2000-01-01T${eventFormData.startTime}`).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) 
                            : '⏰'
                          }
                        </span>
                      </div>
                    </div>
                  </div>

                  <div className="form-row">
                    <div className="form-group">
                      <label>
                        <RiCalendarLine /> Fecha fin *
                      </label>
                      <input
                        type="date"
                        value={eventFormData.endDate}
                        onChange={(e) => setEventFormData(prev => ({ ...prev, endDate: e.target.value }))}
                        disabled={formLoading}
                        required
                      />
                    </div>

                    <div className="form-group">
                      <label>
                        <RiTimeLine /> Hora fin
                      </label>
                      <div className="time-picker-container">
                        <input
                          type="time"
                          value={eventFormData.endTime}
                          onChange={(e) => setEventFormData(prev => ({ ...prev, endTime: e.target.value }))}
                          disabled={eventFormData.isAllDay || formLoading}
                          className="visual-time-input"
                        />
                        <span className="time-display">
                          {!eventFormData.isAllDay && eventFormData.endTime ? 
                            new Date(`2000-01-01T${eventFormData.endTime}`).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) 
                            : '⏰'
                          }
                        </span>
                      </div>
                    </div>
                  </div>

                  <div className="form-group checkbox-group">
                    <label className="checkbox-label">
                      <input
                        type="checkbox"
                        checked={eventFormData.isAllDay}
                        onChange={(e) => setEventFormData(prev => ({ ...prev, isAllDay: e.target.checked }))}
                        disabled={formLoading}
                      />
                      <span>Todo el día</span>
                    </label>
                  </div>

                  <div className="form-actions">
                    <button
                      type="button"
                      className="cancel-btn"
                      onClick={() => {
                        setShowEventForm(false)
                        setEditingEvent(null)
                      }}
                      disabled={formLoading}
                    >
                      Cancelar
                    </button>
                    <button
                      type="submit"
                      className="save-btn"
                      disabled={formLoading || !eventFormData.summary.trim()}
                    >
                      <RiSaveLine />
                      {formLoading ? 'Guardando...' : (editingEvent ? 'Actualizar' : 'Crear Evento')}
                    </button>
                  </div>
                </form>
              </div>
            )}
          </div>
        )}

        {/* Vista Interactiva de Calendario */}
        {currentView === 'interactive' && (
          <div className="interactive-view-container">
            <div className="action-buttons-container">
              <button
                className="create-event-btn"
                onClick={handleCreateEvent}
                title="Crear evento completo"
              >
                <RiCalendarEventLine /> Crear Evento
              </button>
            </div>
            <InteractiveCalendar
              events={events}
              loading={loading}
              onDateClick={handleDateChange}
              onEventClick={handleEditEvent}
              onEventsChange={loadTodayEvents}
            />
          </div>
        )}

        {/* Vista de Búsqueda Avanzada */}
        {currentView === 'search' && (
          <AdvancedSearch
            onSearch={() => {}}
            onClear={() => {}}
            calendars={[]}
            loading={loading}
            results={events}
            onEventClick={handleEditEvent}
          />
        )}

        {/* Vista de Gestión de Calendarios */}
        {currentView === 'manager' && (
          <CalendarManager
            calendars={[]}
            loading={loading}
            onCalendarToggle={handleCalendarToggle}
            onCreateCalendar={() => {}}
            onEditCalendar={() => {}}
            onDeleteCalendar={() => {}}
            onRefresh={handleRefresh}
            visibleCalendars={new Set(selectedCalendars)}
          />
        )}
      </div>
    </div>
  )
}

export default CalendarPanel