import React, { useState } from 'react'
import { 
  RiCalendarLine,
  RiArrowLeftLine,
  RiArrowRightLine,
  RiCalendarTodoLine,
  RiTimeLine,
  RiMapPinLine,
  RiGroupLine,
  RiVideoLine
} from 'react-icons/ri'
import { CalendarEvent } from '../../services/googleCalendar'

interface CalendarViewProps {
  events: CalendarEvent[]
  loading: boolean
  onEventClick: (event: CalendarEvent) => void
  onDateChange: (date: Date) => void
}

export function CalendarView({ events, loading, onEventClick, onDateChange }: CalendarViewProps) {
  const [currentDate, setCurrentDate] = useState(new Date())
  const [viewMode, setViewMode] = useState<'day' | 'week'>('day')

  const formatEventTime = (event: CalendarEvent) => {
    if (event.start.dateTime) {
      return new Date(event.start.dateTime).toLocaleTimeString('es-ES', {
        hour: '2-digit',
        minute: '2-digit'
      })
    }
    return 'Todo el día'
  }

  const isToday = (date: Date) => {
    const today = new Date()
    return date.toDateString() === today.toDateString()
  }

  const isSameDay = (date1: Date, date2: Date) => {
    return date1.toDateString() === date2.toDateString()
  }

  const getTodaysEvents = () => {
    return events.filter(event => {
      const eventDate = new Date(event.start.dateTime || event.start.date || '')
      return isSameDay(eventDate, currentDate)
    })
  }

  const getWeekEvents = () => {
    const weekStart = new Date(currentDate)
    weekStart.setDate(currentDate.getDate() - currentDate.getDay())
    
    const weekEnd = new Date(weekStart)
    weekEnd.setDate(weekStart.getDate() + 6)

    return events.filter(event => {
      const eventDate = new Date(event.start.dateTime || event.start.date || '')
      return eventDate >= weekStart && eventDate <= weekEnd
    })
  }

  const navigateDate = (direction: 'prev' | 'next') => {
    const newDate = new Date(currentDate)
    if (viewMode === 'day') {
      newDate.setDate(currentDate.getDate() + (direction === 'next' ? 1 : -1))
    } else {
      newDate.setDate(currentDate.getDate() + (direction === 'next' ? 7 : -7))
    }
    setCurrentDate(newDate)
    onDateChange(newDate)
  }

  const goToToday = () => {
    const today = new Date()
    setCurrentDate(today)
    onDateChange(today)
  }

  const displayEvents = viewMode === 'day' ? getTodaysEvents() : getWeekEvents()

  return (
    <div className="calendar-view">
      {/* Header de navegación */}
      <div className="calendar-header">
        <div className="calendar-nav">
          <button 
            className="nav-btn"
            onClick={() => navigateDate('prev')}
            title={`${viewMode === 'day' ? 'Día' : 'Semana'} anterior`}
          >
            <RiArrowLeftLine />
          </button>
          
          <div className="current-period">
            <h4>
              {viewMode === 'day' 
                ? currentDate.toLocaleDateString('es-ES', { 
                    weekday: 'long', 
                    year: 'numeric', 
                    month: 'long', 
                    day: 'numeric' 
                  })
                : `Semana del ${currentDate.toLocaleDateString('es-ES', { 
                    month: 'short', 
                    day: 'numeric' 
                  })}`
              }
            </h4>
            {isToday(currentDate) && <span className="today-badge">Hoy</span>}
          </div>
          
          <button 
            className="nav-btn"
            onClick={() => navigateDate('next')}
            title={`${viewMode === 'day' ? 'Día' : 'Semana'} siguiente`}
          >
            <RiArrowRightLine />
          </button>
        </div>

        <div className="calendar-controls">
          <button
            className="control-btn today"
            onClick={goToToday}
            title="Ir a hoy"
          >
            <RiCalendarTodoLine /> Hoy
          </button>
          
          <div className="view-switcher">
            <button
              className={`view-btn ${viewMode === 'day' ? 'active' : ''}`}
              onClick={() => setViewMode('day')}
            >
              Día
            </button>
            <button
              className={`view-btn ${viewMode === 'week' ? 'active' : ''}`}
              onClick={() => setViewMode('week')}
            >
              Semana
            </button>
          </div>
        </div>
      </div>

      {/* Contenido del calendario */}
      <div className="calendar-content">
        {loading ? (
          <div className="calendar-loading">
            <p>⏳ Cargando eventos...</p>
          </div>
        ) : displayEvents.length === 0 ? (
          <div className="calendar-empty">
            <RiCalendarLine className="empty-icon" />
            <p>No hay eventos para {viewMode === 'day' ? 'hoy' : 'esta semana'}</p>
          </div>
        ) : (
          <div className="event-list">
            {displayEvents.map((event) => (
              <div 
                key={event.id} 
                className="calendar-event"
                onClick={() => onEventClick(event)}
              >
                <div className="event-time">
                  <RiTimeLine />
                  <span>{formatEventTime(event)}</span>
                </div>
                
                <div className="event-details">
                  <h5 className="event-title">{event.summary}</h5>
                  
                  {event.description && (
                    <p className="event-description">{event.description}</p>
                  )}
                  
                  <div className="event-extras">
                    {event.location && (
                      <span className="event-location">
                        <RiMapPinLine /> {event.location}
                      </span>
                    )}
                    
                    {event.attendees && event.attendees.length > 0 && (
                      <span className="event-attendees">
                        <RiGroupLine /> {event.attendees.length} invitados
                      </span>
                    )}
                    
                    {event.conferenceData && (
                      <span className="event-meet">
                        <RiVideoLine /> Google Meet
                      </span>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

export default CalendarView