import React, { useState } from 'react'
import './TermsDialog.scss'

interface TermsDialogProps {
  isOpen: boolean
  onAccept: () => void
  onReject: () => void
}

export const TermsDialog: React.FC<TermsDialogProps> = ({ isOpen, onAccept, onReject }) => {
  const [hasScrolled, setHasScrolled] = useState(false)

  if (!isOpen) return null

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const element = e.currentTarget
    const scrolledToBottom = element.scrollHeight - element.scrollTop <= element.clientHeight + 50
    if (scrolledToBottom && !hasScrolled) {
      setHasScrolled(true)
    }
  }

  return (
    <div role="dialog" aria-modal="true" className="terms-dialog-overlay">
      <div className="terms-dialog">
        <div className="terms-header">
          <h1>📋 POLÍTICA DE PRIVACIDAD DE VOXIA</h1>
          <div className="terms-date">
            <strong>Fecha de última actualización:</strong> 17 de septiembre de 2025<br/>
            <strong>Vigente en:</strong> <span className="mexico-flag">Estados Unidos Mexicanos</span>
          </div>
        </div>
        
        <div className="terms-content" onScroll={handleScroll}>
          <div className="legal-compliance">
            <h3>🏛️ Cumplimiento Legal en México</h3>
            <p>Esta Política de Privacidad para el servicio web VOXIA cumple con:</p>
            <ul>
              <li><strong>Ley Federal de Protección de Datos Personales en Posesión de los Particulares (LFPDPPP)</strong></li>
              <li><strong>Reglamento de la LFPDPPP</strong></li>
              <li><strong>Lineamientos del Aviso de Privacidad del INAI</strong></li>
              <li><strong>Código Civil Federal aplicable</strong></li>
              <li><strong>Normativa aplicable a servicios web en México</strong></li>
            </ul>
          </div>

          <h2>1. RESPONSABLE DEL TRATAMIENTO DE DATOS</h2>
          <div className="contact-info">
            <p><strong>Desarrollador:</strong> VOXIA - Aplicación Web</p>
            <p><strong>Naturaleza:</strong> Plataforma web en producción disponible en internet</p>
            <p><strong>Tipo de software:</strong> Aplicación propietaria en línea</p>
            <p><strong>Estado:</strong> Servicio activo y disponible públicamente</p>
            <p><strong>Jurisdicción:</strong> Estados Unidos Mexicanos</p>
            <p><strong>Contacto para ejercer derechos ARCO:</strong> A través de los canales oficiales de contacto de VOXIA</p>
          </div>

          <h2>2. DATOS PERSONALES QUE RECOPILAMOS</h2>
          
          <h3>📊 Datos Recopilados Automáticamente:</h3>
          <ul>
            <li><strong>Información de la cuenta Google:</strong>
              <ul>
                <li>Nombre completo</li>
                <li>Dirección de correo electrónico</li>
                <li>Foto de perfil (avatar)</li>
                <li>ID único de usuario de Google</li>
              </ul>
            </li>
            <li><strong>Datos de acceso a YouTube:</strong>
              <ul>
                <li>Permisos de lectura de YouTube (solo consulta)</li>
                <li>Historial de búsquedas de videos (temporal)</li>
                <li>Preferencias de reproducción</li>
              </ul>
            </li>
            <li><strong>Datos de acceso a Google Calendar:</strong>
              <ul>
                <li>Acceso a calendarios del usuario (lectura y escritura)</li>
                <li>Eventos del calendario (creación, modificación, eliminación)</li>
                <li>Configuraciones de calendario</li>
                <li>Recordatorios y notificaciones</li>
              </ul>
            </li>
          </ul>

          <h3>🎤 Datos de Audio (Procesamiento Local):</h3>
          <div className="important">
            <p><strong>⚠️ IMPORTANTE:</strong> Los datos de audio del micrófono se procesan localmente en tu dispositivo y se transmiten directamente a los servidores de Google (Gemini API) para síntesis de voz. VOXIA no almacena, guarda ni tiene acceso a tus grabaciones de audio.</p>
          </div>

          <h2>3. FINALIDADES DEL TRATAMIENTO</h2>
          
          <h3>🎯 Finalidades Primarias (Necesarias para el servicio):</h3>
          <ol>
            <li><strong>Autenticación de usuario:</strong> Identificarte y darte acceso a la aplicación</li>
            <li><strong>Funcionalidad de voz:</strong> Procesar audio para conversaciones con IA</li>
            <li><strong>Integración con YouTube:</strong> Buscar y reproducir contenido de video</li>
            <li><strong>Integración con Google Calendar:</strong> Gestionar eventos y calendario personal</li>
            <li><strong>Personalización:</strong> Recordar tus preferencias y configuraciones</li>
            <li><strong>Funcionalidad técnica:</strong> Hacer que la aplicación funcione correctamente</li>
          </ol>

          <div className="warning">
            <p><strong>⚖️ CONSENTIMIENTO:</strong> Al usar VOXIA, otorgas tu consentimiento para el tratamiento de datos para las finalidades primarias. Para las finalidades secundarias, puedes manifestar tu negativa sin que esto afecte el uso del servicio.</p>
          </div>

          <h2>4. TRANSFERENCIA DE DATOS</h2>
          
          <h3>🌐 Terceros que Reciben Datos:</h3>
          <ul>
            <li><strong>Google LLC (Estados Unidos):</strong>
              <ul>
                <li>Para autenticación OAuth</li>
                <li>API de Gemini (procesamiento de IA)</li>
                <li>YouTube Data API</li>
                <li>Google Calendar API</li>
                <li>Síntesis de voz y audio</li>
              </ul>
            </li>
            <li><strong>Supabase (Estados Unidos):</strong>
              <ul>
                <li>Gestión de sesiones de usuario</li>
                <li>Base de datos de autenticación</li>
              </ul>
            </li>
          </ul>

          <div className="highlight">
            <p><strong>🔒 PROTECCIÓN EN TRANSFERENCIAS INTERNACIONALES:</strong></p>
            <p>Las transferencias de datos a Estados Unidos se realizan con empresas que cumplen con marcos de protección reconocidos internacionalmente y que tienen políticas de privacidad compatibles con estándares mexicanos.</p>
          </div>

          <h2>5. DERECHOS ARCO Y REVOCACIÓN DEL CONSENTIMIENTO</h2>
          
          <h3>⚖️ Tus Derechos Bajo la Ley Mexicana:</h3>
          <ul>
            <li><strong>ACCESO:</strong> Conocer qué datos tuyos tenemos</li>
            <li><strong>RECTIFICACIÓN:</strong> Corregir datos incorrectos</li>
            <li><strong>CANCELACIÓN:</strong> Eliminar tus datos</li>
            <li><strong>OPOSICIÓN:</strong> Oponerte al tratamiento de tus datos</li>
            <li><strong>REVOCACIÓN:</strong> Retirar tu consentimiento en cualquier momento</li>
          </ul>

          <div className="important">
            <p><strong>⏰ TIEMPO DE RESPUESTA:</strong> Tenemos hasta 20 días hábiles para responder a tu solicitud de derechos ARCO, conforme a la legislación mexicana.</p>
          </div>

          <h2>6. MENORES DE EDAD</h2>
          
          <div className="important">
            <p><strong>🔞 RESTRICCIÓN DE EDAD:</strong></p>
            <p>VOXIA está diseñado para usuarios mayores de 18 años. Si eres menor de edad:</p>
            <ul>
              <li>Necesitas autorización explícita de tus padres o tutores legales</li>
              <li>Tus padres/tutores son responsables de tu uso de la aplicación</li>
              <li>Recomendamos supervisión adulta durante el uso</li>
              <li>Si detectamos uso no autorizado por menores, podemos suspender el acceso</li>
            </ul>
          </div>

          <div className="footer">
            <p><strong>🇲🇽 VOXIA - Política de Privacidad México</strong></p>
            <p>Documento legal válido conforme a la legislación mexicana</p>
            <p>Versión 1.0 - Septiembre 2025</p>
          </div>
        </div>

        {!hasScrolled && (
          <div className="scroll-indicator">
            <p>⬇️ Desplázate para leer todo el contenido antes de continuar</p>
          </div>
        )}

        <div className="terms-actions">
          <button 
            onClick={onReject} 
            className="reject-button"
          >
            Rechazar
          </button>
          <button 
            onClick={onAccept} 
            className={`accept-button ${hasScrolled ? 'enabled' : 'disabled'}`}
            disabled={!hasScrolled}
          >
            {hasScrolled ? 'Aceptar y Continuar' : 'Lee todo el contenido primero'}
          </button>
        </div>
      </div>
    </div>
  )
}

export default TermsDialog
