interface ThinkingModeToggleProps {
  className?: string;
}

const ThinkingModeToggle: React.FC<ThinkingModeToggleProps> = ({ className = '' }) => {
  const [thinkingMode, setThinkingMode] = useState(false);
  const { setModel, setConfig, config } = useLiveAPIContext();

  const toggleThinkingMode = () => {
    const newMode = !thinkingMode;    setThinkingMode(newMode);

    // Obtener configuración de voz actual
    const currentVoiceName = config.speechConfig?.voiceConfig?.prebuiltVoiceConfig?.voiceName || "Zephyr";

    // Cambiar el modelo según el modo
    if (newMode) {
      // Activar modo de razonamiento
      setModel("models/gemini-2.5-flash-native-audio-preview-09-2025");
      console.log("🧠 Modo de razonamiento activado");
    } else {
      // Volver al modo normal
      setModel("models/gemini-2.5-flash-native-audio-preview-09-2025");
      console.log("💬 Modo normal activado");
    }

    // Mantener la configuración base con todas las funcionalidades y voz actual
    setConfig({
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { 
          prebuiltVoiceConfig: {
            voiceName: currentVoiceName
          }
        }
        // NO configurar languageCode - Gemini 2.5 Flash detecta automáticamente
      },
      tools: [
        { googleSearch: {} },
        { functionDeclarations: [declaration, youtubeDeclaration, youtubeVolumeDeclaration, studyDeclaration, studyAnswerDeclaration] },
      ],
    });
  };

  return (
    <div className={`thinking-mode-toggle ${className}`}>
      <button
        className={`toggle-button ${thinkingMode ? 'thinking' : 'normal'}`}
        onClick={toggleThinkingMode}
        title={`Cambiar a modo ${thinkingMode ? 'Normal' : 'Razonamiento'}`}
        aria-label={`Modo ${thinkingMode ? 'Razonamiento' : 'Normal'} activo`}
      >
        <div className="bulb-container">
          <div className="bulb-icon">
            {thinkingMode ? '🧠' : '💡'}
          </div>
          <div className="bulb-glow"></div>
        </div>
        <span className="mode-text">
          {thinkingMode ? 'THINKING' : 'NORMAL'}
        </span>
      </button>
    </div>
  );
};

export default ThinkingModeToggle;
