/**
 * Hook para hacer paneles arrastrables en desktop
 * Solo funciona en PC, no en móviles
 */

import { useState, useCallback, useRef, useEffect } from 'react';

interface Position {
  x: number;
  y: number;
}

interface DragState {
  isDragging: boolean;
  dragStart: Position;
  panelStart: Position;
}

interface UseDraggablePanelReturn {
  position: Position;
  isDragging: boolean;
  dragHandleProps: {
    onMouseDown: (e: React.MouseEvent) => void;
    style: { cursor: string };
  };
  panelStyle: React.CSSProperties;
  resetPosition: () => void;
}

export const useDraggablePanel = (
  initialPosition: Position = { x: 0, y: 0 },
  isEnabled: boolean = true
): UseDraggablePanelReturn => {
  const [position, setPosition] = useState<Position>(initialPosition);
  const [dragState, setDragState] = useState<DragState>({
    isDragging: false,
    dragStart: { x: 0, y: 0 },
    panelStart: { x: 0, y: 0 }
  });

  const dragRef = useRef<DragState>(dragState);
  const isMobile = useRef<boolean>(false);

  // Detectar si es móvil
  useEffect(() => {
    const checkMobile = () => {
      isMobile.current = window.innerWidth <= 768 || 
        'ontouchstart' in window ||
        navigator.maxTouchPoints > 0;
    };

    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  // Actualizar ref cuando cambie el estado
  useEffect(() => {
    dragRef.current = dragState;
  }, [dragState]);

  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    // Solo permitir drag en desktop
    console.log('🔍 DEBUG: handleMouseDown called', {
      isEnabled,
      isMobile: isMobile.current,
      eventType: e.type,
      button: e.button
    });
    
    if (!isEnabled || isMobile.current) {
      console.log('🚫 DEBUG: Drag disabled - isEnabled:', isEnabled, 'isMobile:', isMobile.current);
      return;
    }

    e.preventDefault();
    e.stopPropagation();

    const newDragState: DragState = {
      isDragging: true,
      dragStart: { x: e.clientX, y: e.clientY },
      panelStart: { ...position }
    };

    console.log('✅ DEBUG: Starting drag', newDragState);
    setDragState(newDragState);
  }, [position, isEnabled]);

  const handleMouseMove = useCallback((e: MouseEvent) => {
    console.log('🔍 DEBUG: handleMouseMove called', {
      isDragging: dragRef.current.isDragging,
      isMobile: isMobile.current
    });
    
    if (!dragRef.current.isDragging || isMobile.current) {
      return;
    }

    e.preventDefault();

    const deltaX = e.clientX - dragRef.current.dragStart.x;
    const deltaY = e.clientY - dragRef.current.dragStart.y;

    const newPosition: Position = {
      x: dragRef.current.panelStart.x + deltaX,
      y: dragRef.current.panelStart.y + deltaY
    };

    // Limitar a los bordes de la ventana con dimensiones dinámicas del panel
    const panelWidth = Math.min(600, window.innerWidth * 0.9); // ancho máximo del panel
    const panelHeight = Math.min(500, window.innerHeight * 0.85); // altura máxima del panel
    const maxX = Math.max(0, window.innerWidth - panelWidth - 20); // margen de 20px
    const maxY = Math.max(0, window.innerHeight - panelHeight - 20); // margen de 20px

    newPosition.x = Math.max(20, Math.min(maxX, newPosition.x));
    newPosition.y = Math.max(20, Math.min(maxY, newPosition.y));

    console.log('🔄 DEBUG: Moving panel to', newPosition);
    setPosition(newPosition);
  }, []);

  const handleMouseUp = useCallback(() => {
    console.log('🔍 DEBUG: handleMouseUp called', {
      isDragging: dragRef.current.isDragging
    });
    
    if (dragRef.current.isDragging) {
      console.log('✅ DEBUG: Ending drag');
      setDragState(prev => ({ ...prev, isDragging: false }));
    }
  }, []);

  // Event listeners globales
  useEffect(() => {
    console.log('🔍 DEBUG: useEffect for event listeners', {
      isDragging: dragState.isDragging,
      isMobile: isMobile.current
    });
    
    if (dragState.isDragging && !isMobile.current) {
      console.log('✅ DEBUG: Adding event listeners');
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'grabbing';
      document.body.style.userSelect = 'none';

      return () => {
        console.log('🧹 DEBUG: Removing event listeners');
        document.removeEventListener('mousemove', handleMouseMove);
        document.removeEventListener('mouseup', handleMouseUp);
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
      };
    }
  }, [dragState.isDragging, handleMouseMove, handleMouseUp]);

  const resetPosition = useCallback(() => {
    setPosition(initialPosition);
  }, [initialPosition]);

  const panelStyle: React.CSSProperties = {
    transform: `translate(${position.x}px, ${position.y}px)`,
    transition: dragState.isDragging ? 'none' : 'transform 0.2s ease',
    position: 'fixed' as const,
    zIndex: dragState.isDragging ? 9999 : 1000
  };

  return {
    position,
    isDragging: dragState.isDragging,
    dragHandleProps: {
      onMouseDown: handleMouseDown,
      style: { 
        cursor: isMobile.current ? 'default' : (dragState.isDragging ? 'grabbing' : 'grab')
      }
    },
    panelStyle,
    resetPosition
  };
};
