import { useState, useEffect, useCallback, useRef } from "react";
import { UseMediaStreamResult } from "./use-media-stream-mux";
import { logger } from "../utils/logger";
import { executeMediaStreamWithFallback } from "../utils/media-stream-fallback";

interface EnhancedScreenCaptureResult extends UseMediaStreamResult {
  error: string | null;
  retryCount: number;
  permissionStatus: 'unknown' | 'granted' | 'denied' | 'prompt';
  isSupported: boolean;
  forceRetry: () => Promise<MediaStream | null>;
}

const MAX_RETRY_ATTEMPTS = 3;
const RETRY_DELAYS = [1000, 2000, 4000]; // Backoff exponencial en ms

export function useScreenCapture(): EnhancedScreenCaptureResult {
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [isStreaming, setIsStreaming] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [retryCount, setRetryCount] = useState(0);
  const [permissionStatus, setPermissionStatus] = useState<'unknown' | 'granted' | 'denied' | 'prompt'>('unknown');
  const retryTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  // Verificar compatibilidad completa del navegador
  const isSupported = !!(
    navigator.mediaDevices && 
    navigator.mediaDevices.getDisplayMedia &&
    typeof navigator.mediaDevices.getDisplayMedia === 'function'
  );

  // Verificar permisos al cargar
  useEffect(() => {
    const checkPermissions = async () => {
      if (!isSupported) return;
      
      try {
        // La API de permissions no soporta 'display-capture' directamente
        // pero podemos intentar detectar el estado basado en intentos previos
        if (localStorage.getItem('screen-capture-denied') === 'true') {
          setPermissionStatus('denied');
        }
      } catch (err) {
        logger.debug('No se pudieron verificar permisos de pantalla:', err);
      }
    };

    checkPermissions();
  }, [isSupported]);

  // Limpiar timeouts al desmontar
  useEffect(() => {
    return () => {
      if (retryTimeoutRef.current) {
        clearTimeout(retryTimeoutRef.current);
      }
    };
  }, []);

  const handleStreamEnded = useCallback(() => {
    logger.info('Stream de pantalla terminado por el usuario');
    setIsStreaming(false);
    setStream(null);
    setError(null);
  }, []);

  useEffect(() => {
    if (stream) {
      stream
        .getTracks()
        .forEach((track) => track.addEventListener("ended", handleStreamEnded));
      return () => {
        stream
          .getTracks()
          .forEach((track) =>
            track.removeEventListener("ended", handleStreamEnded),
          );
      };
    }
  }, [stream, handleStreamEnded]);

  const getDetailedError = (err: any): string => {
    const errorName = err.name || err.code;
    
    switch (errorName) {
      case 'NotAllowedError':
        return 'Permisos denegados para compartir pantalla. Por favor, permite el acceso e inténtalo de nuevo.';
      case 'NotFoundError':
        return 'No se encontraron pantallas disponibles para compartir.';
      case 'NotSupportedError':
        return 'Tu navegador no soporta la función de compartir pantalla. Usa Chrome, Firefox o Edge.';
      case 'NotReadableError':
        return 'Error al acceder a la pantalla. Puede estar siendo usada por otra aplicación.';
      case 'OverconstrainedError':
        return 'Las configuraciones de pantalla no son compatibles.';
      case 'SecurityError':
        return 'Error de seguridad al acceder a la pantalla. Verifica que estés en HTTPS.';
      case 'AbortError':
        return 'La captura de pantalla fue cancelada.';
      case 'InvalidStateError':
        return 'El dispositivo de pantalla está en un estado inválido.';
      case 'UnknownError':
        return 'Error desconocido del sistema al capturar pantalla.';
      default:
        return err.message || 'Error desconocido al capturar la pantalla';
    }
  };

  const attemptCapture = useCallback(async (): Promise<MediaStream> => {
    logger.info('Intentando captura de pantalla...');
    
    if (!isSupported) {
      throw new Error('BROWSER_NOT_SUPPORTED');
    }

    // Configuraciones optimizadas para máxima compatibilidad
    const options = {
      video: {
        mediaSource: 'screen' as any,
        width: { ideal: 1920, max: 1920 },
        height: { ideal: 1080, max: 1080 },
        frameRate: { ideal: 30, max: 60 }
      },
      audio: {
        echoCancellation: true,
        noiseSuppression: true,
        sampleRate: 44100
      }
    };

    try {
      // Primer intento con configuraciones completas
      const displayStream = await navigator.mediaDevices.getDisplayMedia(options);
      logger.info('Captura de pantalla exitosa con opciones completas');
      return displayStream;
    } catch (initialErr: any) {
      logger.warn('Fallo captura con opciones completas, intentando configuración básica:', initialErr);
      
      try {
        // Segundo intento con configuración mínima
        const basicStream = await navigator.mediaDevices.getDisplayMedia({
          video: true,
          audio: true
        });
        logger.info('Captura de pantalla exitosa con configuración básica');
        return basicStream;
      } catch (basicErr: any) {
        logger.warn('Fallo captura básica, intentando solo video:', basicErr);
        
        try {
          // Tercer intento solo con video
          const videoOnlyStream = await navigator.mediaDevices.getDisplayMedia({
            video: true
          });
          logger.info('Captura de pantalla exitosa solo con video');
          return videoOnlyStream;
        } catch (finalErr: any) {
          logger.error('Todos los intentos de captura fallaron:', finalErr);
          throw finalErr;
        }
      }
    }
  }, [isSupported]);

  const start = useCallback(async (): Promise<MediaStream> => {
    if (!isSupported) {
      const errorMsg = 'La captura de pantalla no está disponible en este navegador. Usa Chrome, Firefox o Edge.';
      setError(errorMsg);
      logger.error(errorMsg);
      throw new Error(errorMsg);
    }

    if (isStreaming) {
      logger.debug('Captura ya en progreso, ignorando nueva solicitud');
      return stream!;
    }

    setError(null);

    // Usar sistema de fallback robusto
    const fallbackResult = await executeMediaStreamWithFallback(
      attemptCapture,
      'screen'
    );

    if (fallbackResult.success && fallbackResult.result) {
      setStream(fallbackResult.result);
      setIsStreaming(true);
      setPermissionStatus('granted');
      setRetryCount(fallbackResult.retryCount);
      setError(null);
      
      // Limpiar flag de permisos denegados
      localStorage.removeItem('screen-capture-denied');
      
      logger.info(`Stream de pantalla establecido correctamente (fallback: ${fallbackResult.fallbackUsed})`);
      return fallbackResult.result;
    } else {
      const errorMessage = fallbackResult.error || 'Error desconocido al capturar pantalla';
      setError(errorMessage);
      setRetryCount(fallbackResult.retryCount);
      
      if (errorMessage.includes('Permisos denegados')) {
        setPermissionStatus('denied');
        localStorage.setItem('screen-capture-denied', 'true');
      }

      logger.error('Error con sistema de fallback:', {
        error: errorMessage,
        fallbackUsed: fallbackResult.fallbackUsed,
        retryCount: fallbackResult.retryCount
      });

      throw new Error(errorMessage);
    }
  }, [isSupported, isStreaming, stream, attemptCapture]);

  const forceRetry = useCallback(async (): Promise<MediaStream | null> => {
    setRetryCount(0);
    setError(null);
    setPermissionStatus('unknown');
    localStorage.removeItem('screen-capture-denied');
    
    try {
      return await start();
    } catch (err) {
      logger.error('Error en force retry:', err);
      return null;
    }
  }, [start]);

  const stop = useCallback(() => {
    if (retryTimeoutRef.current) {
      clearTimeout(retryTimeoutRef.current);
      retryTimeoutRef.current = null;
    }

    if (stream) {
      logger.info('Deteniendo captura de pantalla');
      stream.getTracks().forEach((track) => track.stop());
      setStream(null);
      setIsStreaming(false);
    }
    
    setError(null);
    setRetryCount(0);
  }, [stream]);

  const result: EnhancedScreenCaptureResult = {
    type: "screen",
    start,
    stop,
    isStreaming,
    stream,
    error,
    retryCount,
    permissionStatus,
    isSupported,
    forceRetry,
  };

  return result;
}
