// Utilidades para manejo de fechas y zona horaria
export class DateTimeUtils {
  
  /**
   * Obtiene la zona horaria del usuario de manera automática
   */
  static getUserTimeZone(): string {
    try {
      return Intl.DateTimeFormat().resolvedOptions().timeZone;
    } catch (error) {
      console.warn('⚠️ No se pudo detectar zona horaria automáticamente, usando America/Mexico_City');
      return 'America/Mexico_City'; // Fallback para México
    }
  }

  /**
   * Obtiene la fecha actual en la zona horaria del usuario
   */
  static getCurrentDate(): Date {
    const now = new Date();
    const timeZone = this.getUserTimeZone();
    
    // Crear una fecha ajustada a la zona horaria local
    const localDate = new Date(now.toLocaleString("en-US", { timeZone }));
    
    console.log('🕐 DateTimeUtils.getCurrentDate:', {
      fechaUTC: now.toISOString(),
      fechaLocal: localDate.toLocaleString(),
      zonaHoraria: timeZone,
      diaSemana: localDate.toLocaleDateString('es-ES', { weekday: 'long' }),
      fechaCompleta: localDate.toLocaleDateString('es-ES', { 
        weekday: 'long', 
        year: 'numeric', 
        month: 'long', 
        day: 'numeric' 
      })
    });
    
    return localDate;
  }

  /**
   * Crea una fecha desde componentes (año, mes, día, hora, minuto) en zona horaria local
   */
  static createLocalDate(year: number, month: number, day: number, hour: number = 0, minute: number = 0): Date {
    const date = new Date(year, month - 1, day, hour, minute);
    const timeZone = this.getUserTimeZone();
    
    console.log('🗓️ DateTimeUtils.createLocalDate:', {
      entrada: { year, month, day, hour, minute },
      fechaCreada: date.toLocaleString(),
      fechaISO: date.toISOString(),
      zonaHoraria: timeZone
    });
    
    return date;
  }

  /**
   * Obtiene el rango de fechas para "hoy" en la zona horaria local
   */
  static getTodayRange(): { startOfDay: Date; endOfDay: Date } {
    const now = this.getCurrentDate();
    
    // Inicio del día (00:00:00)
    const startOfDay = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0, 0);
    
    // Final del día (23:59:59.999)
    const endOfDay = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999);
    
    console.log('🌅 DateTimeUtils.getTodayRange:', {
      fechaActual: now.toLocaleString(),
      inicioDelDia: startOfDay.toLocaleString(),
      finDelDia: endOfDay.toLocaleString(),
      inicioDelDiaISO: startOfDay.toISOString(),
      finDelDiaISO: endOfDay.toISOString(),
      zonaHoraria: this.getUserTimeZone()
    });
    
    return { startOfDay, endOfDay };
  }

  /**
   * Formatea una fecha para mostrar en la interfaz
   */
  static formatForDisplay(date: Date): string {
    return date.toLocaleDateString('es-ES', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      timeZone: this.getUserTimeZone()
    });
  }

  /**
   * Convierte una fecha a ISO string con zona horaria
   */
  static toISOWithTimeZone(date: Date): { dateTime: string; timeZone: string } {
    return {
      dateTime: date.toISOString(),
      timeZone: this.getUserTimeZone()
    };
  }
}