import React, { useState } from 'react'
import { useAuth } from '../../contexts/AuthContext'
import { TermsDialog } from '../terms-dialog/TermsDialog'
import './LoginButton.scss'

interface LoginButtonProps {
  className?: string
  variant?: 'primary' | 'secondary' | 'outline'
  size?: 'small' | 'medium' | 'large'
}

export function LoginButton({ 
  className = '', 
  variant = 'primary', 
  size = 'medium' 
}: LoginButtonProps) {
  const { signInWithGoogle } = useAuth()
  const [isLoading, setIsLoading] = useState(false)

  const handleGoogleLogin = async () => {
    // Comprobar aceptación previa de términos
    const accepted = localStorage.getItem('voxia-terms-accepted')
    if (accepted !== 'true') {
      // Cargar y mostrar la política antes de continuar
      setShowPolicyModal(true)
      return
    }

    try {
      setIsLoading(true)
      await signInWithGoogle()
    } catch (error) {
      console.error('Error al iniciar sesión:', error)
      alert('Error al iniciar sesión. Por favor, intenta de nuevo.')
    } finally {
      setIsLoading(false)
    }
  }

  const [showPolicyModal, setShowPolicyModal] = useState(false)

  const handleAcceptPolicy = async () => {
    localStorage.setItem('voxia-terms-accepted', 'true')
    setShowPolicyModal(false)
    try {
      setIsLoading(true)
      await signInWithGoogle()
    } catch (error) {
      console.error('Error al iniciar sesión después de aceptar términos:', error)
      alert('Error al iniciar sesión. Por favor, intenta de nuevo.')
    } finally {
      setIsLoading(false)
    }
  }

  const handleRejectPolicy = () => {
    // No iniciar sesión si rechaza
    setShowPolicyModal(false)
  }

  return (
    <>
    <button
      onClick={handleGoogleLogin}
      disabled={isLoading}
      className={`login-button login-button--${variant} login-button--${size} ${className}`}
    >
      <div className="login-button__content">
        <svg 
          className="login-button__icon" 
          viewBox="0 0 24 24" 
          width="20" 
          height="20"
        >
          <path
            fill="#4285F4"
            d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
          />
          <path
            fill="#34A853"
            d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
          />
          <path
            fill="#FBBC05"
            d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
          />
          <path
            fill="#EA4335"
            d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
          />
        </svg>
        <span className="login-button__text">
          {isLoading ? 'Iniciando sesión...' : 'Iniciar sesión con Google'}
        </span>
      </div>
    </button>
    
    {/* Modal de términos usando TermsDialog */}
    <TermsDialog
      isOpen={showPolicyModal}
      onAccept={handleAcceptPolicy}
      onReject={handleRejectPolicy}
    />
    </>
  )
}