export interface UserPreferences {
  // Configuraciones de datos personalizados
  enablePersonalizedData: boolean;
  autoLoadCalendarData: boolean;
  
  // Configuraciones de privacidad
  shareDataWithAI: boolean;
  saveConversationHistory: boolean;
  
  // Configuraciones de interfaz
  enableAnimations: boolean;
  compactMode: boolean;
  
  // Metadatos
  lastUpdated: Date;
  version: string;
}

class UserPreferencesService {
  private static instance: UserPreferencesService;
  private readonly STORAGE_KEY = 'voxia_user_preferences';
  private readonly CURRENT_VERSION = '1.0.0';

  private defaultPreferences: UserPreferences = {
    enablePersonalizedData: true, // Activado por defecto para mejor experiencia
    autoLoadCalendarData: true, // Google Calendar activo por defecto
    shareDataWithAI: false,
    saveConversationHistory: true,
    enableAnimations: true,
    compactMode: false,
    lastUpdated: new Date(),
    version: this.CURRENT_VERSION
  };

  private constructor() {}

  public static getInstance(): UserPreferencesService {
    if (!UserPreferencesService.instance) {
      UserPreferencesService.instance = new UserPreferencesService();
    }
    return UserPreferencesService.instance;
  }

  /**
   * Obtiene las preferencias del usuario
   */
  getPreferences(): UserPreferences {
    try {
      const stored = localStorage.getItem(this.STORAGE_KEY);
      if (!stored) {
        return { ...this.defaultPreferences };
      }

      const parsed = JSON.parse(stored);
      
      // Verificar versión y migrar si es necesario
      if (parsed.version !== this.CURRENT_VERSION) {
        return this.migratePreferences(parsed);
      }

      // Asegurar que todas las propiedades existan
      return {
        ...this.defaultPreferences,
        ...parsed,
        lastUpdated: new Date(parsed.lastUpdated)
      };
    } catch (error) {
      console.error('Error al cargar preferencias:', error);
      return { ...this.defaultPreferences };
    }
  }

  /**
   * Guarda las preferencias del usuario
   */
  savePreferences(preferences: Partial<UserPreferences>): void {
    try {
      const current = this.getPreferences();
      const updated: UserPreferences = {
        ...current,
        ...preferences,
        lastUpdated: new Date(),
        version: this.CURRENT_VERSION
      };

      localStorage.setItem(this.STORAGE_KEY, JSON.stringify(updated));
      console.log('📁 Preferencias guardadas exitosamente');
    } catch (error) {
      console.error('Error al guardar preferencias:', error);
    }
  }

  /**
   * Obtiene una preferencia específica
   */
  getPreference<K extends keyof UserPreferences>(key: K): UserPreferences[K] {
    const preferences = this.getPreferences();
    return preferences[key];
  }

  /**
   * Establece una preferencia específica
   */
  setPreference<K extends keyof UserPreferences>(key: K, value: UserPreferences[K]): void {
    this.savePreferences({ [key]: value } as Partial<UserPreferences>);
  }

  /**
   * Verifica si el usuario tiene datos personalizados habilitados
   */
  isPersonalizedDataEnabled(): boolean {
    return this.getPreference('enablePersonalizedData');
  }

  /**
   * Verifica si debe cargar automáticamente datos del calendario
   */
  shouldAutoLoadCalendarData(): boolean {
    return this.getPreference('autoLoadCalendarData') && this.isPersonalizedDataEnabled();
  }

  /**
   * Activa/desactiva datos personalizados
   */
  togglePersonalizedData(enabled: boolean): void {
    this.setPreference('enablePersonalizedData', enabled);
    
    // Si se desactiva, también desactivar carga automática del calendario
    if (!enabled) {
      this.setPreference('autoLoadCalendarData', false);
    }
    
    console.log(`📊 Datos personalizados ${enabled ? 'activados' : 'desactivados'}`);
  }

  /**
   * Activa/desactiva carga automática del calendario
   */
  toggleAutoLoadCalendarData(enabled: boolean): void {
    if (enabled && !this.isPersonalizedDataEnabled()) {
      console.warn('No se puede activar carga automática sin datos personalizados habilitados');
      return;
    }
    
    this.setPreference('autoLoadCalendarData', enabled);
    console.log(`📅 Carga automática del calendario ${enabled ? 'activada' : 'desactivada'}`);
  }

  /**
   * Reinicia todas las preferencias a valores por defecto
   */
  resetToDefaults(): void {
    try {
      localStorage.removeItem(this.STORAGE_KEY);
      console.log('🔄 Preferencias reiniciadas a valores por defecto');
    } catch (error) {
      console.error('Error al reiniciar preferencias:', error);
    }
  }

  /**
   * Migra preferencias de versiones anteriores
   */
  private migratePreferences(oldPreferences: any): UserPreferences {
    console.log('🔄 Migrando preferencias a nueva versión');
    
    // Mantener configuraciones compatibles y agregar nuevas por defecto
    const migrated: UserPreferences = {
      ...this.defaultPreferences,
      enablePersonalizedData: oldPreferences.enablePersonalizedData ?? true, // Activado por defecto
      autoLoadCalendarData: oldPreferences.autoLoadCalendarData ?? true, // Google Calendar por defecto
      shareDataWithAI: oldPreferences.shareDataWithAI ?? false,
      saveConversationHistory: oldPreferences.saveConversationHistory ?? true,
      // Migrar otras configuraciones si existen...
    };

    this.savePreferences(migrated);
    return migrated;
  }

  /**
   * Exporta las preferencias para respaldo
   */
  exportPreferences(): string {
    const preferences = this.getPreferences();
    return JSON.stringify(preferences, null, 2);
  }

  /**
   * Importa preferencias desde respaldo
   */
  importPreferences(data: string): boolean {
    try {
      const imported = JSON.parse(data);
      this.savePreferences(imported);
      return true;
    } catch (error) {
      console.error('Error al importar preferencias:', error);
      return false;
    }
  }
}

// Exportar instancia singleton
export const userPreferencesService = UserPreferencesService.getInstance();
export default userPreferencesService;