import React from 'react';
import './PreferencesToggle.scss';

export interface PreferencesToggleProps {
  id: string;
  label: string;
  description?: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
  disabled?: boolean;
  icon?: string;
  className?: string;
}

export const PreferencesToggle: React.FC<PreferencesToggleProps> = ({
  id,
  label,
  description,
  checked,
  onChange,
  disabled = false,
  icon,
  className = ''
}) => {
  const handleToggle = () => {
    if (!disabled) {
      onChange(!checked);
    }
  };

  return (
    <div className={`preferences-toggle ${className} ${disabled ? 'disabled' : ''}`}>
      <div className="toggle-content">
        <div className="toggle-label-section">
          {icon && <span className="toggle-icon">{icon}</span>}
          <div className="toggle-text">
            <label htmlFor={id} className="toggle-label">
              {label}
            </label>
            {description && (
              <span className="toggle-description">{description}</span>
            )}
          </div>
        </div>
        
        <div className="toggle-switch-container">
          <input
            type="checkbox"
            id={id}
            className="toggle-input"
            checked={checked}
            onChange={handleToggle}
            disabled={disabled}
            aria-describedby={description ? `${id}-desc` : undefined}
          />
          <label htmlFor={id} className="toggle-switch">
            <span className="toggle-slider">
              <span className="toggle-indicator"></span>
            </span>
          </label>
        </div>
      </div>
      
      {description && (
        <div 
          id={`${id}-desc`} 
          className="toggle-description-full"
          aria-hidden="true"
        >
          {description}
        </div>
      )}
    </div>
  );
};

export default PreferencesToggle;