import { useState, useCallback, useEffect, useMemo } from 'react'
import { googleCalendar, CalendarEvent, CalendarList, CreateEventRequest, UpdateEventRequest, FreeBusyRequest, FreeBusyResponse, CalendarColors } from '../services/googleCalendar'
import { useAuth } from '../contexts/AuthContext'

interface UseGoogleCalendarResult {
  // Estados
  loading: boolean
  error: string | null
  events: CalendarEvent[]
  calendars: CalendarList[]
  
  // Estado de acceso
  hasAccess: boolean
  checkingAccess: boolean
  
  // Funciones básicas para eventos
  getEvents: (calendarId?: string) => Promise<CalendarEvent[]>
  getTodayEvents: () => Promise<CalendarEvent[]>
  getUpcomingEvents: (maxResults?: number) => Promise<CalendarEvent[]>
  createEvent: (eventData: CreateEventRequest, calendarId?: string) => Promise<CalendarEvent>
  updateEvent: (eventId: string, eventData: Partial<CreateEventRequest>, calendarId?: string) => Promise<CalendarEvent>
  deleteEvent: (eventId: string, calendarId?: string) => Promise<void>
  createQuickEvent: (summary: string, date?: Date, duration?: number) => Promise<CalendarEvent>
  searchEvents: (query: string, maxResults?: number) => Promise<CalendarEvent[]>
  
  // Funciones para calendarios
  getCalendarList: () => Promise<CalendarList[]>
  createCalendar: (calendar: { summary: string; description?: string; timeZone?: string }) => Promise<CalendarList>
  updateCalendar: (calendarId: string, calendar: Partial<{ summary: string; description?: string; timeZone?: string }>) => Promise<CalendarList>
  deleteCalendar: (calendarId: string) => Promise<void>
  
  // Funciones avanzadas para eventos
  createRecurringEvent: (eventData: CreateEventRequest & { recurrence: string[] }) => Promise<CalendarEvent>
  addAttendees: (eventId: string, attendees: { email: string; optional?: boolean }[], calendarId?: string) => Promise<CalendarEvent>
  addGoogleMeetToEvent: (eventId: string, calendarId?: string) => Promise<CalendarEvent>
  
  // Funciones de consulta
  getFreeBusy: (request: FreeBusyRequest) => Promise<FreeBusyResponse>
  setCalendarColor: (calendarId: string, colorId: string) => Promise<void>
  
  // Utilidades
  clearError: () => void
  refreshAccess: () => Promise<void>
  clearCache: () => void
}

export function useGoogleCalendar(): UseGoogleCalendarResult {
  const { hasCalendarAccess, checkingCalendarAccess } = useAuth()
  
  // Estados locales
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [events, setEvents] = useState<CalendarEvent[]>([])
  const [calendars, setCalendars] = useState<CalendarList[]>([])
  const [internalHasAccess, setInternalHasAccess] = useState(false)
  const [internalCheckingAccess, setInternalCheckingAccess] = useState(true)
  
  // Funciones de utilidad
  const clearError = useCallback(() => {
    setError(null)
  }, [])

  const handleError = useCallback((error: any, context: string) => {
    console.error(`Error en ${context}:`, error)
    setError(error?.message || error?.toString() || `Error en ${context}`)
  }, [])

  const clearCache = useCallback(() => {
    setEvents([])
    setCalendars([])
  }, [])

  // Verificación independiente de acceso
  const checkInternalAccess = useCallback(async () => {
    console.log('🗓️ useGoogleCalendar: Verificando acceso interno...')
    setInternalCheckingAccess(true)
    try {
      const hasAccess = await googleCalendar.checkCalendarAccess()
      console.log('🗓️ useGoogleCalendar: Resultado verificación interna:', hasAccess)
      setInternalHasAccess(hasAccess)
    } catch (error) {
      console.error('🗓️ useGoogleCalendar: Error en verificación interna:', error)
      setInternalHasAccess(false)
    } finally {
      setInternalCheckingAccess(false)
    }
  }, [])

  // Ejecutar verificación al montar el componente
  useEffect(() => {
    checkInternalAccess()
  }, [])

  // Estado final de acceso - usar ambas verificaciones
  const finalHasAccess = useMemo(() => {
    const finalAccess = hasCalendarAccess || internalHasAccess
    console.log('🗓️ finalHasAccess:', {
      hasCalendarAccess,
      internalHasAccess,
      finalAccess
    })
    return finalAccess
  }, [hasCalendarAccess, internalHasAccess])

  const finalCheckingAccess = useMemo(() => {
    return checkingCalendarAccess || internalCheckingAccess
  }, [checkingCalendarAccess, internalCheckingAccess])

  const refreshAccess = useCallback(async () => {
    console.log('🗓️ Refrescando acceso...')
    await checkInternalAccess()
  }, [checkInternalAccess])

  // FUNCIONES DE EVENTOS
  const getEvents = useCallback(async (calendarId?: string): Promise<CalendarEvent[]> => {
    if (!finalHasAccess) {
      console.warn('🗓️ getEvents: Sin acceso a Calendar')
      return []
    }

    setLoading(true)
    setError(null)
    
    try {
      const result = await googleCalendar.getEvents({ calendarId })
      setEvents(result)
      return result
    } catch (error) {
      handleError(error, 'obtener eventos')
      return []
    } finally {
      setLoading(false)
    }
  }, [finalHasAccess, handleError])

  const getTodayEvents = useCallback(async (): Promise<CalendarEvent[]> => {
    console.log('🗓️ getTodayEvents: INICIO - Estado actual:', {
      hasCalendarAccess,
      internalHasAccess,
      finalHasAccess,
      loading
    })
    
    if (!finalHasAccess) {
      console.warn('🗓️ getTodayEvents: Sin acceso a Calendar - retornando array vacío')
      return []
    }

    console.log('🗓️ getTodayEvents: Iniciando setLoading(true)')
    setLoading(true)
    setError(null)
    
    try {
      console.log('🗓️ getTodayEvents: Llamando googleCalendar.getTodayEvents()...')
      const result = await googleCalendar.getTodayEvents()
      console.log('🗓️ getTodayEvents: ÉXITO - Eventos obtenidos:', result.length)
      console.log('🗓️ getTodayEvents: Eventos:', result.map(e => ({ id: e.id, summary: e.summary })))
      setEvents(result)
      return result
    } catch (error) {
      console.error('🗓️ getTodayEvents: ERROR capturado:', error)
      handleError(error, 'obtener eventos de hoy')
      return []
    } finally {
      console.log('🗓️ getTodayEvents: FINALIZANDO - setLoading(false)')
      setLoading(false)
    }
  }, [hasCalendarAccess, internalHasAccess, finalHasAccess, handleError])

  const getUpcomingEvents = useCallback(async (maxResults: number = 10): Promise<CalendarEvent[]> => {
    if (!finalHasAccess) {
      console.warn('🗓️ getUpcomingEvents: Sin acceso a Calendar')
      return []
    }

    setLoading(true)
    setError(null)
    
    try {
      const result = await googleCalendar.getUpcomingEvents(maxResults)
      setEvents(result)
      return result
    } catch (error) {
      handleError(error, 'obtener eventos próximos')
      return []
    } finally {
      setLoading(false)
    }
  }, [finalHasAccess, handleError])

  const createEvent = useCallback(async (eventData: CreateEventRequest, calendarId: string = 'primary'): Promise<CalendarEvent> => {
    if (!finalHasAccess) {
      console.error('🗓️ createEvent: Sin acceso a Calendar - No se puede crear evento')
      const errorMessage = 'Sin acceso a Google Calendar. Necesitas iniciar sesión y autorizar el acceso.';
      setError(errorMessage);
      throw new Error(errorMessage);
    }

    setLoading(true)
    setError(null)
    
    try {
      console.log('🗓️ createEvent: Creando evento...', eventData);
      const result = await googleCalendar.createEvent(eventData, calendarId)
      console.log('🗓️ createEvent: Evento creado exitosamente', result);
      console.log('🗓️ createEvent: Verificando fecha del evento creado:', {
        id: result.id,
        summary: result.summary,
        startTime: result.start?.dateTime || result.start?.date,
        endTime: result.end?.dateTime || result.end?.date,
        fechaActual: new Date().toLocaleDateString(),
        horaActual: new Date().toLocaleTimeString()
      });
      
      // Esperar un momento para que Google Calendar procese el cambio
      console.log('🗓️ createEvent: Esperando 1.5 segundos para sincronización...');
      await new Promise(resolve => setTimeout(resolve, 1500));
      
      // Recargar los eventos del día
      console.log('🗓️ createEvent: Recargando eventos del día...');
      await getTodayEvents()
      return result
    } catch (error) {
      console.error('🗓️ createEvent: Error creando evento:', error);
      handleError(error, 'crear evento')
      throw error; // Re-lanzar el error para que lo maneje el formulario
    } finally {
      setLoading(false)
    }
  }, [finalHasAccess, handleError, getTodayEvents])

  const updateEvent = useCallback(async (eventId: string, eventData: Partial<CreateEventRequest>, calendarId: string = 'primary'): Promise<CalendarEvent> => {
    if (!finalHasAccess) {
      console.error('🗓️ updateEvent: Sin acceso a Calendar - No se puede actualizar evento');
      const errorMessage = 'Sin acceso a Google Calendar. Necesitas iniciar sesión y autorizar el acceso.';
      setError(errorMessage);
      throw new Error(errorMessage);
    }
    
    setLoading(true)
    setError(null)
    
    try {
      console.log('🗓️ updateEvent: Actualizando evento...', { eventId, eventData });
      const result = await googleCalendar.updateEvent(eventId, eventData, calendarId)
      console.log('🗓️ updateEvent: Evento actualizado exitosamente', result);
      
      // Esperar un momento para que Google Calendar procese el cambio
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      // Recargar los eventos del día
      await getTodayEvents()
      return result
    } catch (error) {
      console.error('🗓️ updateEvent: Error actualizando evento:', error);
      handleError(error, 'actualizar evento')
      throw error; // Re-lanzar el error para que lo maneje el formulario
    } finally {
      setLoading(false)
    }
  }, [finalHasAccess, handleError, getTodayEvents])

  const deleteEvent = useCallback(async (eventId: string, calendarId: string = 'primary'): Promise<void> => {
    if (!finalHasAccess) return
    setLoading(true)
    setError(null)
    try {
      await googleCalendar.deleteEvent(eventId, calendarId)
      
      // Esperar un momento para que Google Calendar procese el cambio
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      // Recargar los eventos del día
      await getTodayEvents()
    } catch (error) {
      handleError(error, 'eliminar evento')
    } finally {
      setLoading(false)
    }
  }, [finalHasAccess, handleError, getTodayEvents])

  const createQuickEvent = useCallback(async (summary: string, date?: Date, duration: number = 60): Promise<CalendarEvent> => {
    if (!finalHasAccess) return {} as CalendarEvent
    setLoading(true)
    setError(null)
    try {
      const result = await googleCalendar.createQuickEvent(summary, date, duration)
      
      // Esperar un momento para que Google Calendar procese el cambio
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      // Recargar los eventos del día
      await getTodayEvents()
      return result
    } catch (error) {
      handleError(error, 'crear evento rápido')
      return {} as CalendarEvent
    } finally {
      setLoading(false)
    }
  }, [finalHasAccess, handleError, getTodayEvents])

  const searchEvents = useCallback(async (query: string, maxResults: number = 10): Promise<CalendarEvent[]> => {
    if (!finalHasAccess) return []
    setLoading(true)
    setError(null)
    try {
      const result = await googleCalendar.searchEvents(query, maxResults)
      return result
    } catch (error) {
      handleError(error, 'buscar eventos')
      return []
    } finally {
      setLoading(false)
    }
  }, [finalHasAccess, handleError])

  // FUNCIONES DE CALENDARIOS
  const getCalendarList = useCallback(async (): Promise<CalendarList[]> => {
    if (!finalHasAccess) return []
    setLoading(true)
    setError(null)
    try {
      const result = await googleCalendar.getCalendarList()
      setCalendars(result)
      return result
    } catch (error) {
      handleError(error, 'obtener lista de calendarios')
      return []
    } finally {
      setLoading(false)
    }
  }, [finalHasAccess, handleError])

  const createCalendar = useCallback(async (calendar: { summary: string; description?: string; timeZone?: string }): Promise<CalendarList> => {
    if (!finalHasAccess) return {} as CalendarList
    setLoading(true)
    setError(null)
    try {
      const result = await googleCalendar.createCalendar(calendar)
      await getCalendarList()
      return result
    } catch (error) {
      handleError(error, 'crear calendario')
      return {} as CalendarList
    } finally {
      setLoading(false)
    }
  }, [finalHasAccess, handleError, getCalendarList])

  const updateCalendar = useCallback(async (calendarId: string, calendar: Partial<{ summary: string; description?: string; timeZone?: string }>): Promise<CalendarList> => {
    if (!finalHasAccess) return {} as CalendarList
    setLoading(true)
    setError(null)
    try {
      const result = await googleCalendar.updateCalendar(calendarId, calendar)
      await getCalendarList()
      return result
    } catch (error) {
      handleError(error, 'actualizar calendario')
      return {} as CalendarList
    } finally {
      setLoading(false)
    }
  }, [finalHasAccess, handleError, getCalendarList])

  const deleteCalendar = useCallback(async (calendarId: string): Promise<void> => {
    if (!finalHasAccess) return
    setLoading(true)
    setError(null)
    try {
      await googleCalendar.deleteCalendar(calendarId)
      await getCalendarList()
    } catch (error) {
      handleError(error, 'eliminar calendario')
    } finally {
      setLoading(false)
    }
  }, [finalHasAccess, handleError, getCalendarList])

  // FUNCIONES AVANZADAS
  const createRecurringEvent = useCallback(async (eventData: CreateEventRequest & { recurrence: string[] }): Promise<CalendarEvent> => {
    if (!finalHasAccess) return {} as CalendarEvent
    setLoading(true)
    setError(null)
    try {
      const result = await googleCalendar.createRecurringEvent(eventData)
      await getEvents()
      return result
    } catch (error) {
      handleError(error, 'crear evento recurrente')
      return {} as CalendarEvent
    } finally {
      setLoading(false)
    }
  }, [finalHasAccess, handleError, getEvents])

  const addAttendees = useCallback(async (eventId: string, attendees: { email: string; optional?: boolean }[], calendarId: string = 'primary'): Promise<CalendarEvent> => {
    if (!finalHasAccess) return {} as CalendarEvent
    setLoading(true)
    setError(null)
    try {
      const result = await googleCalendar.addAttendees(eventId, attendees, calendarId)
      return result
    } catch (error) {
      handleError(error, 'agregar invitados')
      return {} as CalendarEvent
    } finally {
      setLoading(false)
    }
  }, [finalHasAccess, handleError])

  const addGoogleMeetToEvent = useCallback(async (eventId: string, calendarId: string = 'primary'): Promise<CalendarEvent> => {
    if (!finalHasAccess) return {} as CalendarEvent
    setLoading(true)
    setError(null)
    try {
      const result = await googleCalendar.addGoogleMeetToEvent(eventId, calendarId)
      return result
    } catch (error) {
      handleError(error, 'agregar Google Meet')
      return {} as CalendarEvent
    } finally {
      setLoading(false)
    }
  }, [finalHasAccess, handleError])

  const getFreeBusy = useCallback(async (request: FreeBusyRequest): Promise<FreeBusyResponse> => {
    if (!finalHasAccess) return {} as FreeBusyResponse
    setLoading(true)
    setError(null)
    try {
      const result = await googleCalendar.getFreeBusy(request)
      return result
    } catch (error) {
      handleError(error, 'obtener disponibilidad')
      return {} as FreeBusyResponse
    } finally {
      setLoading(false)
    }
  }, [finalHasAccess, handleError])

  const setCalendarColor = useCallback(async (calendarId: string, colorId: string): Promise<void> => {
    if (!finalHasAccess) return
    setLoading(true)
    setError(null)
    try {
      await googleCalendar.setCalendarColor(calendarId, colorId)
    } catch (error) {
      handleError(error, 'establecer color de calendario')
    } finally {
      setLoading(false)
    }
  }, [finalHasAccess, handleError])

  return {
    loading,
    error,
    events,
    calendars,
    hasAccess: finalHasAccess,
    checkingAccess: finalCheckingAccess,
    getEvents,
    getTodayEvents,
    getUpcomingEvents,
    createEvent,
    updateEvent,
    deleteEvent,
    createQuickEvent,
    searchEvents,
    getCalendarList,
    createCalendar,
    updateCalendar,
    deleteCalendar,
    createRecurringEvent,
    addAttendees,
    addGoogleMeetToEvent,
    getFreeBusy,
    setCalendarColor,
    clearError,
    refreshAccess,
    clearCache
  }
}

// Exportación default también para compatibilidad
export default useGoogleCalendar