/**
 * Servicio de YouTube para búsqueda y reproducción de videos
 * Integración con YouTube Data API v3
 * Licencia MIT - Libre de copyright
 */

export interface YouTubeVideo {
  id: string;
  title: string;
  channelTitle: string;
  description: string;
  thumbnail: string;
  duration: string;
  publishedAt: string;
  url: string;
}

export interface YouTubeSearchParams {
  query: string;
  maxResults?: number;
  type?: 'video' | 'channel' | 'playlist';
  order?: 'relevance' | 'date' | 'rating' | 'title' | 'viewCount';
  videoDuration?: 'any' | 'short' | 'medium' | 'long';
}

export class YouTubeService {
  // Ya no se usa apiKey ni baseUrl, todo va por OAuth
  constructor() {}

  /**
   * Detectar si estamos en modo screen sharing para ajustar la conectividad
   */
  private isScreenSharingActive(): boolean {
    try {
      // Verificar si hay elementos de screen sharing activos
      const screenShareElements = document.querySelectorAll('[data-screen-sharing="true"]');
      return screenShareElements.length > 0;
    } catch {
      return false;
    }
  }

  /**
   * Obtener configuración de fetch optimizada según el contexto
   */
  private getFetchConfig(): RequestInit {
    const isScreenSharing = this.isScreenSharingActive();
    
    return {
      signal: AbortSignal.timeout(isScreenSharing ? 15000 : 10000), // Más tiempo si hay screen sharing
      headers: {
        'User-Agent': 'Mozilla/5.0 (compatible; VOXIA/1.0)',
        'Accept': 'application/json',
      },
    };
  }
  /**
   * Buscar videos en YouTube
   */
  async searchVideos(params: YouTubeSearchParams): Promise<YouTubeVideo[]> {
    try {
      const { query, maxResults = 10 } = params;
      // Usar el servicio OAuth
      // @ts-ignore
      const data = await (await import('./youtubeOAuth')).youtubeOAuth.searchVideos(query, maxResults);
      if (!data.items || data.items.length === 0) {
        console.warn('⚠️ No se encontraron videos para:', query);
        return [];
      }
      // Obtener detalles adicionales de los videos
      const videoIds = data.items.map((item: any) => item.id.videoId).join(',');
      const videosDetails = await this.getVideoDetails(videoIds);
      const videos: YouTubeVideo[] = data.items.map((item: any, index: number) => {
        const details = videosDetails[index] || {};
        return {
          id: item.id.videoId,
          title: item.snippet.title,
          channelTitle: item.snippet.channelTitle,
          description: item.snippet.description,
          thumbnail: item.snippet.thumbnails?.high?.url || item.snippet.thumbnails?.default?.url,
          duration: details.duration || 'Desconocida',
          publishedAt: item.snippet.publishedAt,
          url: `https://www.youtube.com/watch?v=${item.id.videoId}`
        };
      });
      console.log(`✅ Encontrados ${videos.length} videos para "${query}"`);
      return videos;
    } catch (error) {
      console.error('❌ Error al buscar videos en YouTube:', error);
      throw error;
    }
  }

  /**
   * Obtener detalles adicionales de videos (duración, estadísticas, etc.)
   */
  private async getVideoDetails(videoIds: string): Promise<any[]> {
    try {
      // Usar el servicio OAuth
      // @ts-ignore
      const data = await (await import('./youtubeOAuth')).youtubeOAuth.getVideoDetails(videoIds);
      return data.items || [];
    } catch (error) {
      console.warn('⚠️ Error al obtener detalles de videos:', error);
      return [];
    }
  }
  /**
   * Buscar una canción específica con filtros optimizados
   */
  async searchSong(songName: string, artist?: string): Promise<YouTubeVideo[]> {
    let query = songName;
    if (artist) {
      query = `${artist} ${songName}`;
    }
    query += ' música canción oficial';
    return this.searchVideos({
      query,
      maxResults: 5,
      order: 'relevance',
      videoDuration: 'medium'
    });
  }
  /**
   * Buscar el video más relevante para una canción
   */
  async findBestMatch(songName: string, artist?: string): Promise<YouTubeVideo | null> {
    try {
      const videos = await this.searchSong(songName, artist);
      if (videos.length === 0) {
        return null;
      }
      // Priorizar videos oficiales o con mejor calidad
      const officialVideo = videos.find(video => 
        video.title.toLowerCase().includes('oficial') ||
        video.title.toLowerCase().includes('official') ||
        video.channelTitle.toLowerCase().includes('oficial') ||
        video.channelTitle.toLowerCase().includes('vevo')
      );
      return officialVideo || videos[0];
    } catch (error) {
      console.error('❌ Error al buscar la mejor coincidencia:', error);
      return null;
    }
  }

  /**
   * Formatear duración de video desde formato ISO 8601
   */
  static formatDuration(isoDuration: string): string {
    try {
      const match = isoDuration.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
      if (!match) return 'Desconocida';

      const hours = parseInt(match[1] || '0', 10);
      const minutes = parseInt(match[2] || '0', 10);
      const seconds = parseInt(match[3] || '0', 10);

      if (hours > 0) {
        return `${hours}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
      } else {
        return `${minutes}:${seconds.toString().padStart(2, '0')}`;
      }
    } catch (error) {
      return 'Desconocida';
    }
  }

  /**
   * Generar URL embebida para reproducción
   */
  static getEmbedUrl(videoId: string, autoplay: boolean = false): string {
    const url = new URL(`https://www.youtube.com/embed/${videoId}`);
    url.searchParams.set('autoplay', autoplay ? '1' : '0');
    url.searchParams.set('rel', '0'); // No mostrar videos relacionados
    url.searchParams.set('modestbranding', '1'); // Branding mínimo
    url.searchParams.set('controls', '1'); // Mostrar controles COMPLETOS
    url.searchParams.set('playsinline', '1'); // Reproducir inline en móviles
    url.searchParams.set('enablejsapi', '1'); // Habilitar API de JavaScript
    url.searchParams.set('origin', window.location.origin); // Origen para CORS
    url.searchParams.set('widget_referrer', window.location.href); // Referrer
    url.searchParams.set('disablekb', '0'); // PERMITIR controles de teclado
    url.searchParams.set('fs', '1'); // PERMITIR fullscreen
    return url.toString();
  }

  /**
   * Generar URL específicamente pensada para autoplay continuo en el reproductor principal
   * Separamos esto de `getEmbedUrl` para poder ajustar parámetros futuros (por ejemplo, mute inicial, loop, etc.)
   */
  static getAutoplayEmbedUrl(videoId: string): string {
    try {
      const base = YouTubeService.getEmbedUrl(videoId, true);
      const url = new URL(base);
      // Parámetros adicionales pensados para una experiencia fluida
      url.searchParams.set('mute', '0'); // Asegurar sonido (si el navegador lo permite)
      url.searchParams.set('playsinline', '1');
      url.searchParams.set('iv_load_policy', '3'); // Sin anotaciones
      url.searchParams.set('cc_load_policy', '0'); // Sin subtítulos forzados
      url.searchParams.set('fs', '1'); // PERMITIR fullscreen y controles avanzados
      url.searchParams.set('disablekb', '0'); // PERMITIR controles de teclado
      return url.toString();
    } catch {
      // Fallback mínimo
      return `https://www.youtube.com/embed/${videoId}?autoplay=1&rel=0&controls=1&fs=1&disablekb=0`;
    }
  }
  /**
   * Validar si la API key está configurada correctamente
   */
  async validateApiKey(): Promise<boolean> {
    // Ya no se valida API key, solo se verifica acceso OAuth
    try {
      // @ts-ignore
      const { youtubeOAuth } = await import('./youtubeOAuth');
      return await youtubeOAuth.checkYouTubeAccess();
    } catch (error) {
      console.error('❌ Error al validar acceso OAuth de YouTube:', error);
      return false;
    }
  }

  /**
   * Buscar y generar URL para el panel integrado con parámetros optimizados
   */
  static async searchAndPlayForPanel(query: string): Promise<{url: string, title: string, channelTitle: string}> {
    try {
      const service = new YouTubeService();
      
      // Intentar búsqueda con manejo robusto de errores
      let videos: YouTubeVideo[] = [];
      
      try {
        videos = await service.searchVideos({
          query: query + ' música',
          maxResults: 1,
          order: 'relevance',
          videoDuration: 'medium'
        });
      } catch (searchError: any) {
        // Si hay error QUIC, intentar búsqueda simplificada
        if (searchError.message.includes('QUIC') || searchError.message.includes('conectividad')) {
          console.warn('🎵 ⚠️ Error de conectividad, intentando búsqueda simplificada...');
          
          try {
            videos = await service.searchVideos({
              query: query,
              maxResults: 1,
              order: 'relevance'
            });
          } catch (fallbackError) {
            console.error('❌ Error en búsqueda de respaldo:', fallbackError);
            throw new Error('No se pudo establecer conexión con YouTube después de múltiples intentos');
          }
        } else {
          throw searchError;
        }
      }

      if (videos.length === 0) {
        throw new Error('No se encontraron videos para: ' + query);
      }

      const video = videos[0];
      
      // Generar URL para iframe con parámetros específicos del panel
      const embedUrl = new URL(`https://www.youtube.com/embed/${video.id}`);
      
      // Parámetros optimizados para el panel integrado con EVENTOS
      embedUrl.searchParams.set('autoplay', '1');
      embedUrl.searchParams.set('enablejsapi', '1'); // CRÍTICO para eventos
      embedUrl.searchParams.set('origin', window.location.origin);
      embedUrl.searchParams.set('playsinline', '1');
      embedUrl.searchParams.set('rel', '0'); // No mostrar videos relacionados
      embedUrl.searchParams.set('showinfo', '0'); // Ocultar información
      embedUrl.searchParams.set('modestbranding', '1'); // Branding mínimo
      embedUrl.searchParams.set('fs', '1'); // HABILITAR fullscreen para mejor API
      embedUrl.searchParams.set('cc_load_policy', '0'); // Sin subtítulos automáticos
      embedUrl.searchParams.set('iv_load_policy', '3'); // Sin anotaciones
      embedUrl.searchParams.set('widget_referrer', window.location.href);
      embedUrl.searchParams.set('disablekb', '0'); // PERMITIR controles de teclado
      embedUrl.searchParams.set('controls', '1'); // MOSTRAR controles completos

      console.log(`🎵 Video encontrado para panel: "${video.title}" por ${video.channelTitle}`);
      
      return {
        url: embedUrl.toString(),
        title: video.title,
        channelTitle: video.channelTitle
      };

    } catch (error) {
      console.error('❌ Error en búsqueda para panel:', error);
      throw error;
    }
  }

  /**
   * Buscar múltiples videos para mostrar en lista (para funcionalidad futura)
   */
  static async searchForPlaylist(query: string, maxResults: number = 10): Promise<YouTubeVideo[]> {
    try {
      const service = new YouTubeService();
      return await service.searchVideos({
        query,
        maxResults,
        order: 'relevance',
        videoDuration: 'any'
      });
    } catch (error) {
      console.error('❌ Error en búsqueda de playlist:', error);
      return [];
    }
  }

  /**
   * Obtener siguiente video basado en el actual evitando repetir historial.
   * 1. Intenta usar videos relacionados del endpoint de YouTube.
   * 2. Filtra videos ya reproducidos (historial) y el actual.
   * 3. Fallback: una búsqueda derivada del título del video actual.
   */
  async getNextVideoInSequence(currentVideo: YouTubeVideo, playHistory: string[]): Promise<YouTubeVideo | null> {
    const alreadyPlayed = new Set<string>([currentVideo.id, ...playHistory]);
    // Helper para construir objeto de video normalizado desde item snippet + details opcionales
    const buildVideoObject = (item: any, details?: any): YouTubeVideo => ({
      id: item.id.videoId || item.id,
      title: item.snippet.title,
      channelTitle: item.snippet.channelTitle,
      description: item.snippet.description,
      thumbnail: item.snippet.thumbnails?.high?.url || item.snippet.thumbnails?.default?.url,
      duration: details?.duration || 'Desconocida',
      publishedAt: item.snippet.publishedAt,
      url: `https://www.youtube.com/watch?v=${item.id.videoId || item.id}`
    });
    // 1. Intentar obtener videos relacionados usando OAuth
    try {
      // @ts-ignore
      const { youtubeOAuth } = await import('./youtubeOAuth');
      const data = await youtubeOAuth.searchRelatedVideos(currentVideo.id, 10);
      const items: any[] = data.items || [];
      const filtered = items.filter(it => it.id?.videoId && !alreadyPlayed.has(it.id.videoId));
      if (filtered.length > 0) {
        // Obtener detalles para duración
        const ids = filtered.slice(0, 5).map(f => f.id.videoId).join(',');
        const details = ids ? await this.getVideoDetails(ids) : [];
        const first = filtered[0];
        const detailsMap: Record<string, any> = {};
        details.forEach((d: any) => { detailsMap[d.id] = d.contentDetails ? { duration: YouTubeService.formatDuration(d.contentDetails.duration) } : {}; });
        return buildVideoObject(first, detailsMap[first.id.videoId]);
      }
    } catch (error) {
      console.warn('🎵 ⚠️ Error al obtener relacionados, aplicando fallback:', error);
    }

    // 2. Fallback: derivar una búsqueda del título
    try {
      // Limpiar título de palabras poco útiles
      const cleaned = currentVideo.title
        .toLowerCase()
        .replace(/\b(official|video|lyrics|letra|hd|4k|audio|remastered|oficial)\b/g, ' ')
        .replace(/[^a-z0-9áéíóúñü ]/gi, ' ') // quitar símbolos
        .replace(/\s+/g, ' ') // espacios múltiples
        .trim();

      const searchQuery = cleaned.length > 0 ? cleaned : currentVideo.title;
      const fallbackResults = await this.searchVideos({
        query: searchQuery + ' música',
        maxResults: 8,
        order: 'relevance',
        videoDuration: 'any'
      });

      const candidate = fallbackResults.find(v => !alreadyPlayed.has(v.id) && v.id !== currentVideo.id);
      if (candidate) return candidate;
    } catch (error) {
      console.warn('🎵 ⚠️ Error en búsqueda fallback siguiente video:', error);
    }

    console.warn('🎵 ⚠️ No se encontró siguiente video adecuado');
    return null;
  }

  /**
   * Fallback cuando la API falla - usar videos predefinidos por género
   */
  public async searchVideosFallback(query: string): Promise<YouTubeVideo[]> {
    console.log('🎵 🚨 FALLBACK ACTIVADO para:', query);
    
    // Videos populares organizados por género/estilo para fallback
    const fallbackVideos = this.getFallbackVideosByGenre(query);
    
    // Seleccionar 3-5 videos aleatorios del género detectado
    const shuffled = fallbackVideos.sort(() => Math.random() - 0.5);
    const selected = shuffled.slice(0, Math.min(5, fallbackVideos.length));
    
    return selected.map(video => ({
      id: video.id,
      title: video.title,
      channelTitle: video.channel,
      description: `Música ${query}`,
      thumbnail: `https://img.youtube.com/vi/${video.id}/hqdefault.jpg`,
      duration: '3:30',
      publishedAt: new Date().toISOString(),
      url: `https://www.youtube.com/watch?v=${video.id}`
    }));
  }

  /**
   * Obtener videos de fallback por género
   */
  private getFallbackVideosByGenre(query: string): Array<{id: string, title: string, channel: string}> {
    const queryLower = query.toLowerCase();
    
    // Videos populares por género (IDs reales de YouTube)
    const genres = {
      reggaeton: [
        { id: 'kLpH1nSLJSs', title: 'SAFAERA - Bad Bunny', channel: 'Bad Bunny' },
        { id: 'saGlrVWn_vE', title: 'Con Altura - Rosalía ft. J Balvin', channel: 'Rosalía' },
        { id: 'OSUxrSe5GbI', title: 'TQG - Karol G, Shakira', channel: 'Karol G' },
        { id: 'ixkoVwKQaJg', title: 'La Botella - Myke Towers', channel: 'Myke Towers' },
        { id: 'DoUbDbZ7lek', title: 'Todo De Ti - Rauw Alejandro', channel: 'Rauw Alejandro' }
      ],
      pop: [
        { id: 'YykjpeuMNEk', title: 'Shape of You - Ed Sheeran', channel: 'Ed Sheeran' },
        { id: 'hTWKbfoikeg', title: 'Blinding Lights - The Weeknd', channel: 'The Weeknd' },
        { id: 'O-ty7K7nPoI', title: 'Flowers - Miley Cyrus', channel: 'Miley Cyrus' },
        { id: 'iAeYPfrXwk4', title: 'Unholy - Sam Smith', channel: 'Sam Smith' }
      ],
      latin: [
        { id: 'saGlrVWn_vE', title: 'Con Altura - Rosalía ft. J Balvin', channel: 'Rosalía' },
        { id: 'ixkoVwKQaJg', title: 'La Botella - Myke Towers', channel: 'Myke Towers' },
        { id: 'OSUxrSe5GbI', title: 'TQG - Karol G, Shakira', channel: 'Karol G' },
        { id: 'DoUbDbZ7lek', title: 'Todo De Ti - Rauw Alejandro', channel: 'Rauw Alejandro' }
      ],
      bachata: [
        { id: 'Zkjz3Xe4Q0w', title: 'Bachata Rosa - Juan Luis Guerra', channel: 'Juan Luis Guerra' },
        { id: 'MCJH-kY8_ds', title: 'Eres Mía - Romeo Santos', channel: 'Romeo Santos' }
      ],
      salsa: [
        { id: 'QhYPsO1OKuk', title: 'La Vida Es Un Carnaval - Celia Cruz', channel: 'Celia Cruz' },
        { id: 'iOe6dI2JhgU', title: 'Vivir Mi Vida - Marc Anthony', channel: 'Marc Anthony' }
      ],
      trap: [
        { id: 'kLpH1nSLJSs', title: 'SAFAERA - Bad Bunny', channel: 'Bad Bunny' },
        { id: 'ixkoVwKQaJg', title: 'La Botella - Myke Towers', channel: 'Myke Towers' }
      ]
    };

    // Detectar género de la consulta
    for (const [genre, videos] of Object.entries(genres)) {
      if (queryLower.includes(genre) || 
          queryLower.includes(genre.replace(' ', '')) ||
          videos.some(v => queryLower.includes(v.channel.toLowerCase()))) {
        return videos;
      }
    }

    // Si no se detecta género específico, mezclar todo
    const allVideos = Object.values(genres).flat();
    return allVideos.sort(() => Math.random() - 0.5);
  }
}

export default YouTubeService;
