import React, { useState } from 'react'
import { CalendarEvent, CalendarList } from '../../services/googleCalendar'
import './CalendarComponents.scss'

interface SearchFilters {
  query: string
  startDate: string
  endDate: string
  calendarIds: string[]
  attendeeEmail: string
  status: 'all' | 'confirmed' | 'tentative' | 'cancelled'
  hasAttachments: boolean
  hasLocation: boolean
  hasDescription: boolean
}

interface AdvancedSearchProps {
  onSearch: (filters: SearchFilters) => void
  onClear: () => void
  calendars: CalendarList[]
  loading: boolean
  results: CalendarEvent[]
  onEventClick: (event: CalendarEvent) => void
}

export function AdvancedSearch({ 
  onSearch, 
  onClear, 
  calendars, 
  loading, 
  results,
  onEventClick 
}: AdvancedSearchProps) {
  const [isExpanded, setIsExpanded] = useState(false)
  const [filters, setFilters] = useState<SearchFilters>({
    query: '',
    startDate: '',
    endDate: '',
    calendarIds: [],
    attendeeEmail: '',
    status: 'all',
    hasAttachments: false,
    hasLocation: false,
    hasDescription: false
  })

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault()
    onSearch(filters)
  }

  const handleClear = () => {
    setFilters({
      query: '',
      startDate: '',
      endDate: '',
      calendarIds: [],
      attendeeEmail: '',
      status: 'all',
      hasAttachments: false,
      hasLocation: false,
      hasDescription: false
    })
    onClear()
  }

  const toggleCalendar = (calendarId: string) => {
    setFilters({
      ...filters,
      calendarIds: filters.calendarIds.includes(calendarId)
        ? filters.calendarIds.filter(id => id !== calendarId)
        : [...filters.calendarIds, calendarId]
    })
  }

  const formatEventDate = (event: CalendarEvent) => {
    const startDate = new Date(event.start.dateTime || event.start.date || '')
    const endDate = new Date(event.end.dateTime || event.end.date || '')
    
    if (event.start.date) {
      // Evento de todo el día
      return startDate.toLocaleDateString('es-ES')
    } else {
      // Evento con hora específica
      return `${startDate.toLocaleDateString('es-ES')} ${startDate.toLocaleTimeString('es-ES', {
        hour: '2-digit',
        minute: '2-digit'
      })}`
    }
  }

  const getEventColor = (event: CalendarEvent) => {
    const colors: Record<string, string> = {
      '1': '#a4bdfc', '2': '#7ae7bf', '3': '#dbadff', '4': '#ff887c',
      '5': '#fbd75b', '6': '#ffb878', '7': '#46d6db', '8': '#e1e1e1',
      '9': '#5484ed', '10': '#51b749', '11': '#dc2127'
    }
    return colors[event.colorId || '1'] || '#1976d2'
  }

  const highlightText = (text: string, query: string) => {
    if (!query) return text
    
    const regex = new RegExp(`(${query})`, 'gi')
    const parts = text.split(regex)
    
    return parts.map((part, index) => 
      regex.test(part) ? (
        <mark key={index} className="search-highlight">{part}</mark>
      ) : part
    )
  }

  return (
    <div className="advanced-search">
      <div className="search-header">
        <h3>Búsqueda Avanzada</h3>
        <button 
          className="expand-btn"
          onClick={() => setIsExpanded(!isExpanded)}
        >
          {isExpanded ? '▼' : '▶'}
        </button>
      </div>

      <form onSubmit={handleSearch} className="search-form">
        {/* Búsqueda básica - siempre visible */}
        <div className="basic-search">
          <div className="search-input-group">
            <input
              type="text"
              value={filters.query}
              onChange={(e) => setFilters({ ...filters, query: e.target.value })}
              placeholder="Buscar eventos por título, descripción..."
              className="search-input"
            />
            <button type="submit" disabled={loading} className="search-btn">
              {loading ? '🔄' : '🔍'}
            </button>
          </div>
        </div>

        {/* Filtros avanzados - expandibles */}
        {isExpanded && (
          <div className="advanced-filters">
            {/* Rango de fechas */}
            <div className="filter-section">
              <h4>Rango de fechas</h4>
              <div className="date-range">
                <div className="form-group">
                  <label>Desde</label>
                  <input
                    type="date"
                    value={filters.startDate}
                    onChange={(e) => setFilters({ ...filters, startDate: e.target.value })}
                  />
                </div>
                <div className="form-group">
                  <label>Hasta</label>
                  <input
                    type="date"
                    value={filters.endDate}
                    onChange={(e) => setFilters({ ...filters, endDate: e.target.value })}
                  />
                </div>
              </div>
            </div>

            {/* Calendarios */}
            <div className="filter-section">
              <h4>Calendarios</h4>
              <div className="calendar-filters">
                {calendars.map(calendar => (
                  <label key={calendar.id} className="calendar-checkbox">
                    <input
                      type="checkbox"
                      checked={filters.calendarIds.includes(calendar.id)}
                      onChange={() => toggleCalendar(calendar.id)}
                    />
                    <span 
                      className="calendar-color-indicator"
                      style={{ backgroundColor: calendar.backgroundColor || '#1976d2' }}
                    ></span>
                    <span className="calendar-name">{calendar.summary}</span>
                  </label>
                ))}
              </div>
            </div>

            {/* Filtros adicionales */}
            <div className="filter-section">
              <h4>Filtros adicionales</h4>
              
              <div className="form-group">
                <label>Asistente (email)</label>
                <input
                  type="email"
                  value={filters.attendeeEmail}
                  onChange={(e) => setFilters({ ...filters, attendeeEmail: e.target.value })}
                  placeholder="correo@ejemplo.com"
                />
              </div>

              <div className="form-group">
                <label>Estado del evento</label>
                <select
                  value={filters.status}
                  onChange={(e) => setFilters({ ...filters, status: e.target.value as any })}
                >
                  <option value="all">Todos los estados</option>
                  <option value="confirmed">Confirmado</option>
                  <option value="tentative">Tentativo</option>
                  <option value="cancelled">Cancelado</option>
                </select>
              </div>

              <div className="checkbox-group">
                <label>
                  <input
                    type="checkbox"
                    checked={filters.hasAttachments}
                    onChange={(e) => setFilters({ ...filters, hasAttachments: e.target.checked })}
                  />
                  Con archivos adjuntos
                </label>
                <label>
                  <input
                    type="checkbox"
                    checked={filters.hasLocation}
                    onChange={(e) => setFilters({ ...filters, hasLocation: e.target.checked })}
                  />
                  Con ubicación
                </label>
                <label>
                  <input
                    type="checkbox"
                    checked={filters.hasDescription}
                    onChange={(e) => setFilters({ ...filters, hasDescription: e.target.checked })}
                  />
                  Con descripción
                </label>
              </div>
            </div>

            {/* Acciones */}
            <div className="filter-actions">
              <button type="button" onClick={handleClear} className="clear-btn">
                Limpiar filtros
              </button>
              <button type="submit" disabled={loading} className="apply-btn">
                Aplicar filtros
              </button>
            </div>
          </div>
        )}
      </form>

      {/* Resultados */}
      <div className="search-results">
        {loading && (
          <div className="search-loading">
            <div className="loading-spinner"></div>
            <p>Buscando eventos...</p>
          </div>
        )}

        {!loading && results.length > 0 && (
          <>
            <div className="results-header">
              <h4>Resultados ({results.length})</h4>
            </div>
            <div className="results-list">
              {results.map(event => (
                <div 
                  key={event.id} 
                  className="search-result-item"
                  onClick={() => onEventClick(event)}
                >
                  <div 
                    className="event-color-bar"
                    style={{ backgroundColor: getEventColor(event) }}
                  ></div>
                  
                  <div className="event-content">
                    <div className="event-title">
                      {highlightText(event.summary, filters.query)}
                    </div>
                    
                    <div className="event-date">
                      📅 {formatEventDate(event)}
                    </div>

                    {event.location && (
                      <div className="event-location">
                        📍 {highlightText(event.location, filters.query)}
                      </div>
                    )}

                    {event.description && (
                      <div className="event-description">
                        {highlightText(
                          event.description.length > 100 
                            ? event.description.substring(0, 100) + '...'
                            : event.description,
                          filters.query
                        )}
                      </div>
                    )}

                    {event.attendees && event.attendees.length > 0 && (
                      <div className="event-attendees">
                        👥 {event.attendees.length} asistente{event.attendees.length !== 1 ? 's' : ''}
                      </div>
                    )}

                    <div className="event-status">
                      <span className={`status-badge ${event.status}`}>
                        {event.status === 'confirmed' ? 'Confirmado' :
                         event.status === 'tentative' ? 'Tentativo' :
                         event.status === 'cancelled' ? 'Cancelado' : 'Desconocido'}
                      </span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </>
        )}

        {!loading && results.length === 0 && filters.query && (
          <div className="no-results">
            <div className="no-results-icon">🔍</div>
            <p>No se encontraron eventos con los criterios especificados</p>
            <button onClick={handleClear} className="clear-search-btn">
              Limpiar búsqueda
            </button>
          </div>
        )}
      </div>
    </div>
  )
}