import React, { useState, useEffect } from 'react'
import { CalendarList } from '../../services/googleCalendar'
import './CalendarComponents.scss'

interface CalendarManagerProps {
  calendars: CalendarList[]
  loading: boolean
  onCalendarToggle: (calendarId: string, visible: boolean) => void
  onCreateCalendar: (calendar: { summary: string; description?: string; timeZone?: string }) => void
  onEditCalendar: (calendarId: string, calendar: Partial<{ summary: string; description?: string; timeZone?: string }>) => void
  onDeleteCalendar: (calendarId: string) => void
  onRefresh: () => void
  visibleCalendars: Set<string>
}

interface NewCalendarForm {
  summary: string
  description: string
  timeZone: string
}

const predefinedColors = [
  { id: '1', name: 'Azul claro', color: '#a4bdfc' },
  { id: '2', name: 'Verde claro', color: '#7ae7bf' },
  { id: '3', name: 'Morado', color: '#dbadff' },
  { id: '4', name: 'Rojo', color: '#ff887c' },
  { id: '5', name: 'Amarillo', color: '#fbd75b' },
  { id: '6', name: 'Naranja', color: '#ffb878' },
  { id: '7', name: 'Turquesa', color: '#46d6db' },
  { id: '8', name: 'Gris', color: '#e1e1e1' },
  { id: '9', name: 'Azul', color: '#5484ed' },
  { id: '10', name: 'Verde', color: '#51b749' },
  { id: '11', name: 'Rojo oscuro', color: '#dc2127' }
]

export function CalendarManager({ 
  calendars, 
  loading, 
  onCalendarToggle,
  onCreateCalendar,
  onEditCalendar,
  onDeleteCalendar,
  onRefresh,
  visibleCalendars 
}: CalendarManagerProps) {
  const [showNewCalendarForm, setShowNewCalendarForm] = useState(false)
  const [editingCalendar, setEditingCalendar] = useState<CalendarList | null>(null)
  const [newCalendarData, setNewCalendarData] = useState<NewCalendarForm>({
    summary: '',
    description: '',
    timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
  })

  const getCalendarColor = (calendar: CalendarList): string => {
    if (calendar.backgroundColor) {
      return calendar.backgroundColor
    }
    const colorMatch = predefinedColors.find(c => c.id === calendar.colorId)
    return colorMatch?.color || '#1976d2'
  }

  const handleCreateCalendar = (e: React.FormEvent) => {
    e.preventDefault()
    if (newCalendarData.summary.trim()) {
      onCreateCalendar({
        summary: newCalendarData.summary.trim(),
        description: newCalendarData.description.trim() || undefined,
        timeZone: newCalendarData.timeZone
      })
      setNewCalendarData({
        summary: '',
        description: '',
        timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
      })
      setShowNewCalendarForm(false)
    }
  }

  const handleEditCalendar = (e: React.FormEvent) => {
    e.preventDefault()
    if (editingCalendar && newCalendarData.summary.trim()) {
      onEditCalendar(editingCalendar.id, {
        summary: newCalendarData.summary.trim(),
        description: newCalendarData.description.trim() || undefined,
        timeZone: newCalendarData.timeZone
      })
      setEditingCalendar(null)
      setNewCalendarData({
        summary: '',
        description: '',
        timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
      })
    }
  }

  const startEditCalendar = (calendar: CalendarList) => {
    setEditingCalendar(calendar)
    setNewCalendarData({
      summary: calendar.summary || '',
      description: calendar.description || '',
      timeZone: calendar.timeZone || Intl.DateTimeFormat().resolvedOptions().timeZone
    })
    setShowNewCalendarForm(true)
  }

  const cancelForm = () => {
    setShowNewCalendarForm(false)
    setEditingCalendar(null)
    setNewCalendarData({
      summary: '',
      description: '',
      timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
    })
  }

  const confirmDelete = (calendar: CalendarList) => {
    if (calendar.accessRole === 'owner' && !calendar.primary) {
      const confirmed = window.confirm(
        `¿Estás seguro de que quieres eliminar el calendario "${calendar.summary}"? Esta acción no se puede deshacer.`
      )
      if (confirmed) {
        onDeleteCalendar(calendar.id)
      }
    }
  }

  if (loading) {
    return (
      <div className="calendar-manager loading">
        <div className="loading-content">
          <div className="loading-spinner"></div>
          <p>Cargando calendarios...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="calendar-manager">
      <div className="manager-header">
        <h3>Mis Calendarios</h3>
        <div className="header-actions">
          <button className="refresh-btn" onClick={onRefresh} title="Actualizar">
            🔄
          </button>
          <button 
            className="add-calendar-btn" 
            onClick={() => setShowNewCalendarForm(true)}
            title="Crear nuevo calendario"
          >
            ➕
          </button>
        </div>
      </div>

      {/* Lista de calendarios */}
      <div className="calendars-list">
        {calendars.map(calendar => (
          <div key={calendar.id} className="calendar-item">
            <div className="calendar-main">
              <label className="calendar-checkbox">
                <input
                  type="checkbox"
                  checked={visibleCalendars.has(calendar.id)}
                  onChange={(e) => onCalendarToggle(calendar.id, e.target.checked)}
                />
                <span 
                  className="calendar-color" 
                  style={{ backgroundColor: getCalendarColor(calendar) }}
                ></span>
              </label>

              <div className="calendar-info">
                <div className="calendar-name">
                  {calendar.summary}
                  {calendar.primary && <span className="primary-badge">Principal</span>}
                </div>
                {calendar.description && (
                  <div className="calendar-description">{calendar.description}</div>
                )}
                <div className="calendar-meta">
                  <span className="access-role">{calendar.accessRole}</span>
                  {calendar.timeZone && (
                    <span className="timezone">• {calendar.timeZone}</span>
                  )}
                </div>
              </div>
            </div>

            <div className="calendar-actions">
              {calendar.accessRole === 'owner' && (
                <>
                  <button
                    className="edit-btn"
                    onClick={() => startEditCalendar(calendar)}
                    title="Editar calendario"
                  >
                    ✏️
                  </button>
                  {!calendar.primary && (
                    <button
                      className="delete-btn"
                      onClick={() => confirmDelete(calendar)}
                      title="Eliminar calendario"
                    >
                      🗑️
                    </button>
                  )}
                </>
              )}
            </div>
          </div>
        ))}

        {calendars.length === 0 && (
          <div className="empty-calendars">
            <div className="empty-icon">📅</div>
            <p>No se encontraron calendarios</p>
            <button onClick={onRefresh} className="retry-btn">
              Intentar de nuevo
            </button>
          </div>
        )}
      </div>

      {/* Formulario de crear/editar calendario */}
      {showNewCalendarForm && (
        <div className="calendar-form-overlay">
          <div className="calendar-form">
            <div className="form-header">
              <h4>{editingCalendar ? 'Editar Calendario' : 'Nuevo Calendario'}</h4>
              <button className="close-btn" onClick={cancelForm}>✕</button>
            </div>

            <form onSubmit={editingCalendar ? handleEditCalendar : handleCreateCalendar}>
              <div className="form-group">
                <label htmlFor="calendar-name">Nombre del calendario *</label>
                <input
                  id="calendar-name"
                  type="text"
                  value={newCalendarData.summary}
                  onChange={(e) => setNewCalendarData({
                    ...newCalendarData,
                    summary: e.target.value
                  })}
                  placeholder="Mi calendario"
                  required
                />
              </div>

              <div className="form-group">
                <label htmlFor="calendar-description">Descripción</label>
                <textarea
                  id="calendar-description"
                  value={newCalendarData.description}
                  onChange={(e) => setNewCalendarData({
                    ...newCalendarData,
                    description: e.target.value
                  })}
                  placeholder="Descripción opcional del calendario"
                  rows={3}
                />
              </div>

              <div className="form-group">
                <label htmlFor="calendar-timezone">Zona horaria</label>
                <select
                  id="calendar-timezone"
                  value={newCalendarData.timeZone}
                  onChange={(e) => setNewCalendarData({
                    ...newCalendarData,
                    timeZone: e.target.value
                  })}
                >
                  <option value="America/Mexico_City">Ciudad de México (GMT-6)</option>
                  <option value="America/New_York">Nueva York (GMT-5)</option>
                  <option value="America/Los_Angeles">Los Ángeles (GMT-8)</option>
                  <option value="Europe/Madrid">Madrid (GMT+1)</option>
                  <option value="Europe/London">Londres (GMT+0)</option>
                  <option value="Asia/Tokyo">Tokio (GMT+9)</option>
                  <option value="UTC">UTC (GMT+0)</option>
                </select>
              </div>

              <div className="form-actions">
                <button type="button" onClick={cancelForm} className="cancel-btn">
                  Cancelar
                </button>
                <button type="submit" className="submit-btn">
                  {editingCalendar ? 'Actualizar' : 'Crear'} Calendario
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Estadísticas */}
      <div className="calendar-stats">
        <div className="stat-item">
          <span className="stat-label">Total:</span>
          <span className="stat-value">{calendars.length}</span>
        </div>
        <div className="stat-item">
          <span className="stat-label">Visibles:</span>
          <span className="stat-value">{visibleCalendars.size}</span>
        </div>
        <div className="stat-item">
          <span className="stat-label">Propios:</span>
          <span className="stat-value">
            {calendars.filter(c => c.accessRole === 'owner').length}
          </span>
        </div>
      </div>
    </div>
  )
}