import React, { useState } from 'react';
import { 
  RiCloseLine,
  RiVoiceprintLine
} from 'react-icons/ri';
import { useDraggablePanel } from '../../hooks/useDraggablePanel';
import './study-panel.scss';

interface StudyPanelProps {
  isVisible: boolean;
  onClose: () => void;
  onVoiceInteraction: (message: string) => void;
  position?: 'left' | 'right';
  isRepositioned?: boolean; // Nueva prop para controlar el estado reposicionado
}

const StudyPanel: React.FC<StudyPanelProps> = ({
  isVisible,
  onClose,
  onVoiceInteraction,
  position = 'right',
  isRepositioned = false // Valor por defecto
}) => {
  const [textContent, setTextContent] = useState<string>('');
  const [difficulty, setDifficulty] = useState<'easy' | 'medium' | 'hard'>('medium');
  const [numQuestions, setNumQuestions] = useState<number>(10);
  const [hasExistingQuestions, setHasExistingQuestions] = useState<boolean>(false);
  const [questionMode, setQuestionMode] = useState<'generate' | 'existing'>('generate');
  const [isMobile, setIsMobile] = useState<boolean>(false);

  // Hook para hacer el panel arrastrable (solo en desktop)
  const initialPosition = position === 'left' ? { x: 25, y: 80 } : { x: window.innerWidth - 365, y: 80 };
  const { panelStyle, dragHandleProps, isDragging } = useDraggablePanel(
    initialPosition,
    !isMobile // Solo habilitado en desktop
  );

  // Detectar móvil
  React.useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth <= 768);
    };
    
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  const detectQuestions = (text: string): boolean => {
    if (!text || typeof text !== 'string' || text.trim() === '') {
      return false;
    }

    const questionPatterns = [
      /\?\s*$/gm,
      /^\s*\d+\.\s*¿[^?]*\?/gm,
      /^\s*\d+\)\s*¿[^?]*\?/gm,
      /respuesta\s*:/gi,
      /cuestionario/gi,
      /pregunta\s*\d+/gi,
    ];
    
    let questionCount = 0;
    
    questionPatterns.forEach(pattern => {
      const matches = text.match(pattern);
      if (matches && matches.length > 0) {
        questionCount++;
      }
    });

    const hasResponsePattern = /respuesta\s*:/gi.test(text);
    const hasCuestionarioTitle = /cuestionario/gi.test(text);
    
    return hasResponsePattern || hasCuestionarioTitle || questionCount >= 2;
  };

  const handleTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const text = e.target.value;
    setTextContent(text);
    
    const hasQuestions = detectQuestions(text);
    setHasExistingQuestions(hasQuestions);
    
    if (hasQuestions && questionMode === 'generate') {
      setQuestionMode('existing');
    }
  };
  const startStudyWithVOXIA = () => {
    if (!textContent.trim()) {
      alert("⚠️ Primero debes escribir o pegar el contenido de estudio");
      return;
    }

    let studyMessage = '';

    if (questionMode === 'existing') {
      studyMessage = `🚨 MODO ESTRICTO: COPIAR PREGUNTAS EXACTAS DEL DOCUMENTO

DOCUMENTO CARGADO:
"${textContent}"

INSTRUCCIONES:
1. ENCUENTRA las preguntas en el documento
2. COPIA cada pregunta PALABRA POR PALABRA 
3. NO cambies nada
4. Di "Pregunta del documento:" seguido de la pregunta exacta
5. Espera mi respuesta y continúa

EMPEZAR: Busca la primera pregunta y cópiala exactamente.`;
    } else {
      studyMessage = `🎓 ¡Tiempo de estudiar! Material:

"${textContent}"

Configuración:
- Dificultad: ${difficulty === 'easy' ? 'Fácil' : difficulty === 'medium' ? 'Intermedio' : 'Avanzado'}
- Preguntas: ${numQuestions}

Genera ${numQuestions} preguntas de nivel ${difficulty} y hazlas una por una.`;
    }
    
    onVoiceInteraction(studyMessage);
    
    setTimeout(() => {
      onClose();
    }, 1000);
  };

  if (!isVisible) return null;

  // Construir clases dinámicamente
  const panelClasses = [
    'voice-assistant-panel', // Clase base principal
    position, // 'left' or 'right'
    isRepositioned ? 'repositioned' : '', // Conditionally add 'repositioned'
    isMobile ? 'mobile' : '', // Añadir clase mobile
    isDragging ? 'dragging' : '' // Añadir clase dragging
  ].filter(Boolean).join(' ');

  // Estilos combinados para arrastre o posición fija
  const combinedStyles = !isMobile ? 
    { ...panelStyle, top: 'unset', left: 'unset', right: 'unset', bottom: 'unset' } : 
    {};

  return (
    <div 
      className={panelClasses}
      style={combinedStyles}
    >
      <div className="voice-panel-content">
        <div 
          className="voice-panel-header"
          {...(!isMobile ? dragHandleProps : {})}
        >
          <div className="voice-header-info">
            <RiVoiceprintLine className="voice-icon" />
            <div>
              <h3>
                🧠 Técnica de Richard Feynman
                {!isMobile && (
                  <span className="drag-indicator" title="Arrastra para mover el panel">⋮⋮</span>
                )}
              </h3>
              <span>Aprende explicando con VOXIA</span>
            </div>
          </div>
          <button className="voice-close-btn" onClick={onClose}>
            <RiCloseLine />
          </button>
        </div>

        <div className="voice-content-upload">
          <h4>📝 Contenido de Estudio</h4>
          <div className="text-input-area">
            <textarea
              value={textContent}
              onChange={handleTextChange}
              placeholder="Pega aquí tu contenido de estudio..."
              className="study-textarea"
              rows={12}
            />
            <div className="textarea-info">
              <span>📊 {textContent.length} caracteres</span>
              {hasExistingQuestions && (
                <span className="questions-detected">✅ Preguntas detectadas</span>
              )}
            </div>
          </div>
        </div>

        <div className="voice-study-config">
          <h4>🎯 Configuración del Examen</h4>
          
          {textContent && (
            <div className="config-group">
              <label>📝 Tipo de Preguntas:</label>
              <div className="question-mode-buttons">
                <button
                  className={`mode-btn ${questionMode === 'existing' ? 'active' : ''}`}
                  onClick={() => setQuestionMode('existing')}
                  disabled={!hasExistingQuestions}
                >
                  📋 Usar Preguntas del Texto
                  {hasExistingQuestions ? (
                    <small>✅ Detectadas</small>
                  ) : (
                    <small>❌ No detectadas</small>
                  )}
                </button>
                <button
                  className={`mode-btn ${questionMode === 'generate' ? 'active' : ''}`}
                  onClick={() => setQuestionMode('generate')}
                >
                  🎲 Generar Preguntas Nuevas
                  <small>IA creará preguntas personalizadas</small>
                </button>
              </div>
            </div>
          )}
          
          {questionMode === 'generate' && (
            <>
              <div className="config-group">
                <label>Dificultad:</label>
                <div className="difficulty-buttons">
                  {(['easy', 'medium', 'hard'] as const).map((level) => (
                    <button
                      key={level}
                      className={`difficulty-btn ${difficulty === level ? 'active' : ''}`}
                      onClick={() => setDifficulty(level)}
                    >
                      <span className="emoji">
                        {level === 'easy' ? '�' : level === 'medium' ? '🤔' : '🤯'}
                      </span>
                      {level === 'easy' ? 'Fácil' : level === 'medium' ? 'Intermedio' : 'Avanzado'}
                    </button>
                  ))}
                </div>
              </div>

              <div className="config-group">
                <label>Número de Preguntas:</label>
                <div className="range-container">
                  <div className="range-labels">
                    <span className="range-min">5</span>
                    <span className="range-current">{numQuestions} preguntas</span>
                    <span className="range-max">50</span>
                  </div>
                  <div className="range-track-container">
                    <div className="range-track"></div>
                    <div 
                      className="range-progress" 
                      style={{ width: `${((numQuestions - 5) / (50 - 5)) * 100}%` }}
                    ></div>
                    <div 
                      className="range-thumb"
                      style={{ left: `${((numQuestions - 5) / (50 - 5)) * 100}%` }}
                    ></div>
                    <input
                      type="range"
                      min="5"
                      max="50"
                      value={numQuestions}
                      onChange={(e) => setNumQuestions(parseInt(e.target.value))}
                      className="voice-range"
                    />
                  </div>
                </div>
              </div>
            </>
          )}

          <button 
            className="start-study-btn"
            onClick={startStudyWithVOXIA}
            disabled={!textContent.trim()}
          >
            <span className="btn-icon">▶️</span>
            🔮 EMPEZAR EXAMEN CON VOXIA
            <span className="btn-icon">⚙️</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default StudyPanel;
