/**
 * Componente de pruebas para la funcionalidad española
 * Test component for Spanish functionality
 */

import React, { useState, useEffect } from 'react';
import { testSpanishVoices, getSpanishVoiceInfo } from '../../utils/voiceTestUtils';
import { SpanishVoiceService } from '../../services/SpanishVoiceService';
import { translations } from '../../i18n/translations';

export const SpanishTestPanel: React.FC = () => {
  const [voiceInfo, setVoiceInfo] = useState<any[]>([]);
  const [testResult, setTestResult] = useState<string>('');
  const voiceService = new SpanishVoiceService();

  useEffect(() => {
    // Esperar a que las voces se carguen
    const updateVoices = () => {
      const info = getSpanishVoiceInfo();
      setVoiceInfo(info);
    };

    if (window.speechSynthesis.getVoices().length > 0) {
      updateVoices();
    } else {
      window.speechSynthesis.addEventListener('voiceschanged', updateVoices);
    }

    return () => {
      window.speechSynthesis.removeEventListener('voiceschanged', updateVoices);
    };
  }, []);

  const handleVoiceTest = () => {
    const result = testSpanishVoices();
    setTestResult(result ? '✅ Prueba exitosa' : '❌ Prueba fallida');
  };

  const handleSpeak = async (text: string) => {
    try {
      // No usar síntesis de voz del sistema - SOLO VOXIA audio nativo
      console.log("🚫 Síntesis de voz del sistema deshabilitada");
      console.log("✅ SOLO se permite audio nativo de Gemini 2.5 Flash con Zephyr");
      setTestResult('✅ Configurado para SOLO audio nativo de VOXIA');
    } catch (error) {
      setTestResult(`❌ Error: ${error}`);
    }
  };

  return (
    <div style={{ 
      padding: '20px', 
      border: '2px solid #4285f4', 
      borderRadius: '8px', 
      margin: '10px',
      backgroundColor: '#f8f9fa'
    }}>
      <h3>🧪 Panel de Pruebas - Funcionalidad Española</h3>
      
      <div style={{ marginBottom: '15px' }}>
        <h4>📊 Estado del Sistema:</h4>
        <p><strong>API de Voz:</strong> {window.speechSynthesis ? '✅ Disponible' : '❌ No disponible'}</p>
        <p><strong>Voces en Español:</strong> {voiceInfo.length} encontradas</p>
        <p><strong>Traducciones:</strong> {Object.keys(translations).length} cadenas cargadas</p>
      </div>

      <div style={{ marginBottom: '15px' }}>
        <h4>🎤 Voces Disponibles:</h4>
        {voiceInfo.map((voice, index) => (
          <div key={index} style={{ 
            padding: '5px', 
            margin: '3px 0', 
            backgroundColor: 'white', 
            borderRadius: '4px',
            fontSize: '12px'
          }}>
            <strong>{voice.name}</strong> ({voice.lang}) - {voice.gender}
            {voice.default && <span style={{ color: '#4285f4' }}> [Predeterminada]</span>}
          </div>
        ))}
      </div>

      <div style={{ marginBottom: '15px' }}>
        <h4>🧪 Pruebas:</h4>
        <button 
          onClick={handleVoiceTest}
          style={{ 
            margin: '5px', 
            padding: '8px 12px', 
            backgroundColor: '#4285f4', 
            color: 'white', 
            border: 'none', 
            borderRadius: '4px',
            cursor: 'pointer'
          }}
        >
          Probar Detección de Voces
        </button>
        
        <button 
          onClick={() => handleSpeak('¡Hola! Soy la consola web multimodal en español.')}
          style={{ 
            margin: '5px', 
            padding: '8px 12px', 
            backgroundColor: '#34a853', 
            color: 'white', 
            border: 'none', 
            borderRadius: '4px',
            cursor: 'pointer'
          }}
        >
          Probar Síntesis de Voz
        </button>        <button 
          onClick={() => handleSpeak(translations.es.title)}
          style={{ 
            margin: '5px', 
            padding: '8px 12px', 
            backgroundColor: '#fbbc04', 
            color: 'black', 
            border: 'none', 
            borderRadius: '4px',
            cursor: 'pointer'
          }}
        >
          Probar Traducción
        </button>
      </div>

      {testResult && (
        <div style={{ 
          padding: '10px', 
          backgroundColor: testResult.includes('✅') ? '#d4edda' : '#f8d7da',
          border: `1px solid ${testResult.includes('✅') ? '#c3e6cb' : '#f5c6cb'}`,
          borderRadius: '4px',
          color: testResult.includes('✅') ? '#155724' : '#721c24'
        }}>
          <strong>Resultado:</strong> {testResult}
        </div>
      )}

      <div style={{ marginTop: '15px', fontSize: '12px', color: '#666' }}>
        <p><strong>Nota:</strong> Este panel de pruebas verifica que todas las funcionalidades españolas estén funcionando correctamente.</p>
      </div>
    </div>
  );
};

export default SpanishTestPanel;
