import cn from "classnames";
import { useEffect, useRef, useState } from "react";
import { RiSidebarFoldLine, RiSidebarUnfoldLine } from "react-icons/ri";
import { useLiveAPIContext } from "../../contexts/LiveAPIContext";
import { useLoggerStore } from "../../lib/store-logger";
import Logger from "../logger/Logger";
import AdvancedVoiceSelector from "../settings-dialog/AdvancedVoiceSelector";
import { translations } from "../../i18n/translations";
import "./side-panel.scss";

interface SidePanelProps {
  onOpenYouTube?: () => void;
  isVisible?: boolean;
  onClose?: () => void;
}

export default function SidePanel({ onOpenYouTube, isVisible = false, onClose }: SidePanelProps) {
  const { connected, client } = useLiveAPIContext();
  const [open, setOpen] = useState(true);
  const [showVoiceSettings, setShowVoiceSettings] = useState(false);
  
  // Detectar si es móvil
  const [isMobile, setIsMobile] = useState(false);
  
  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth <= 768);
    };
    
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);
  const loggerRef = useRef<HTMLDivElement>(null);
  const loggerLastHeightRef = useRef<number>(-1);
  const { log, logs } = useLoggerStore();
  const t = translations.es;

  const [textInput, setTextInput] = useState("");
  const inputRef = useRef<HTMLTextAreaElement>(null);

  //scroll the log to the bottom when new logs come in
  useEffect(() => {
    if (loggerRef.current) {
      const el = loggerRef.current;
      const scrollHeight = el.scrollHeight;
      if (scrollHeight !== loggerLastHeightRef.current) {
        el.scrollTop = scrollHeight;
        loggerLastHeightRef.current = scrollHeight;
      }
    }
  }, [logs]);

  // listen for log events and store them
  useEffect(() => {
    client.on("log", log);
    return () => {
      client.off("log", log);
    };
  }, [client, log]);
  const handleSubmit = () => {
    client.send([{ text: textInput }]);

    setTextInput("");
    if (inputRef.current) {
      inputRef.current.value = "";
    }
  };

  // En móviles, solo mostrar si isVisible es true
  if (isMobile && !isVisible) {
    return null;
  }

  return (
    <div className={`side-panel ${open ? "open" : ""} ${isMobile ? "mobile-overlay" : ""}`}>
      {/* Botón de cerrar para móviles */}
      {isMobile && (
        <div className="mobile-panel-header">
          <button className="mobile-close-btn" onClick={onClose}>
            ✕
          </button>
          <h2>{t.sidePanel.title}</h2>
        </div>
      )}
      
      {/* Header para desktop */}
      {!isMobile && (
        <header className="top">
          <h2>{t.sidePanel.title}</h2>
          {open ? (
            <button className="opener" onClick={() => setOpen(false)}>
              <RiSidebarFoldLine color="#b4b8bb" />
            </button>
          ) : (
            <button className="opener" onClick={() => setOpen(true)}>
              <RiSidebarUnfoldLine color="#b4b8bb" />
            </button>
          )}
        </header>
      )}
        {/* Selector de configuración de voz */}
      <section className="voice-settings-section">
        <button 
          className="voice-settings-toggle"
          onClick={() => setShowVoiceSettings(!showVoiceSettings)}
        >
          <span className="material-icons">mic</span>
          {showVoiceSettings ? 'Ocultar' : 'Mostrar'} Configuración de Voz
        </button>
        {showVoiceSettings && (
          <AdvancedVoiceSelector showToggleButton={false} defaultVisible={true} />
        )}
      </section>
      
      {/* Botón de YouTube */}
      <section className="youtube-section">
        <button 
          className="youtube-button"
          onClick={onOpenYouTube}
          title="Abrir panel de YouTube"
        >
          <span className="material-icons">music_note</span>
          Panel de YouTube
        </button>
        <p className="youtube-hint">
          <span className="material-icons">lightbulb</span>
          Panel integrado con búsqueda y auto-reposicionamiento
        </p>
      </section>
      
      <div className="side-panel-container" ref={loggerRef}>
        <Logger
          filter="none"
        />
      </div>
      <div className={cn("input-container", { disabled: !connected })}>
        <div className="input-content">
          <textarea
            className="input-area"
            ref={inputRef}
            placeholder={t.placeholders.message}
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey) {
                e.preventDefault();
                e.stopPropagation();
                handleSubmit();
              }
            }}
            onChange={(e) => setTextInput(e.target.value)}
            value={textInput}
          ></textarea>
          
          <div className="input-actions">
            <button
              className="expand-button"
              title="Expandir"
            >
              <span className="material-icons transform rotate-90">unfold_more</span>
            </button>
            <button
              className="send-button"
              onClick={handleSubmit}
              title={t.buttons.send}
            >
              <span className="material-icons">send</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
