import React, { useState } from 'react';
import { 
  RiCloseLine,
  RiUserLine
} from 'react-icons/ri';
import { useDraggablePanel } from '../../hooks/useDraggablePanel';
import './ponitivox-panel.scss';

interface PonitivoxPanelProps {
  isVisible: boolean;
  onClose: () => void;
  position?: 'left' | 'right';
  isRepositioned?: boolean;
}

const PonitivoxPanel: React.FC<PonitivoxPanelProps> = ({
  isVisible,
  onClose,
  position = 'right',
  isRepositioned = false
}) => {
  const [isMobile, setIsMobile] = useState<boolean>(false);

  // Hook para hacer el panel arrastrable (solo en desktop)
  const initialPosition = position === 'left' ? { x: 25, y: 80 } : { x: window.innerWidth - 365, y: 80 };
  const { panelStyle, dragHandleProps, isDragging } = useDraggablePanel(
    initialPosition,
    !isMobile // Solo habilitado en desktop
  );

  // Detectar móvil
  React.useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth <= 768);
    };
    
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  if (!isVisible) return null;

  return (
    <div 
      className={`ponitivox-panel ${isMobile ? 'mobile' : ''} ${isDragging ? 'dragging' : ''} ${isRepositioned ? 'repositioned' : ''}`}
      style={!isMobile ? panelStyle : undefined}
    >
      {/* Header arrastrable */}
      <div 
        className="ponitivox-panel-header"
        {...(!isMobile ? dragHandleProps : {})}
      >
        <div className="panel-title">
          <span className="panel-icon">🌟</span>
          <h3>PONITIVOX</h3>
        </div>
        <button 
          className="close-button"
          onClick={onClose}
          title="Cerrar panel"
        >
          <RiCloseLine />
        </button>
      </div>

      {/* Contenido del panel */}
      <div className="ponitivox-panel-content">
        {/* Sección principal */}
        <div className="ponitivox-main">
          <div className="coming-soon-section">
            <div className="coming-soon-icon">
              <span>🚀</span>
            </div>
            <h4>Próximamente</h4>
            <p>PONITIVOX estará disponible pronto con funcionalidades increíbles.</p>
          </div>

          {/* Botón de usuario con "Pronto - Inicio de sesión" */}
          <div className="user-section">
            <button className="user-login-btn coming-soon-btn" disabled>
              <RiUserLine className="user-icon" />
              <span>Pronto - Inicio de sesión</span>
            </button>
            <p className="user-hint">
              Sistema de autenticación y perfiles de usuario en desarrollo.
            </p>
          </div>

          {/* Sección de características futuras */}
          <div className="features-preview">
            <h5>Características en desarrollo:</h5>
            <ul className="features-list">
              <li>🎯 IA personalizada avanzada</li>
              <li>👤 Perfiles de usuario</li>
              <li>📊 Análisis y métricas</li>
              <li>🔧 Configuraciones avanzadas</li>
              <li>☁️ Sincronización en la nube</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PonitivoxPanel;