import React, { useState, useCallback } from 'react';
import './ConnectionDiagnostic.scss';

interface DiagnosticResult {
  apiKey: boolean;
  browserSupport: boolean;
  restAPI: boolean;
  webSocket: boolean;
}

interface LogEntry {
  timestamp: string;
  type: 'INFO' | 'SUCCESS' | 'ERROR';
  message: string;
}

export const ConnectionDiagnostic: React.FC = () => {
  const [isRunning, setIsRunning] = useState(false);
  const [results, setResults] = useState<DiagnosticResult | null>(null);
  const [logs, setLogs] = useState<LogEntry[]>([]);

  const addLog = useCallback((type: LogEntry['type'], message: string) => {
    const timestamp = new Date().toISOString().split('T')[1].split('.')[0];
    setLogs(prev => [...prev, { timestamp, type, message }]);
  }, []);

  const testAPIKey = useCallback(async (): Promise<boolean> => {
    addLog('INFO', '🔑 Verificando API Key de Gemini...');
    
    const apiKey = process.env.REACT_APP_GEMINI_API_KEY;
    
    if (!apiKey) {
      addLog('ERROR', '❌ REACT_APP_GEMINI_API_KEY no está definida');
      return false;
    }

    if (apiKey.includes("'") || apiKey.includes('"')) {
      addLog('ERROR', '❌ API Key contiene comillas - quítalas del archivo .env');
      return false;
    }

    if (!apiKey.startsWith('AIzaSy')) {
      addLog('ERROR', '❌ Formato de API Key inválido - debe empezar con AIzaSy');
      return false;
    }

    addLog('SUCCESS', '✅ API Key tiene formato válido');
    return true;
  }, [addLog]);

  const testBrowserSupport = useCallback((): boolean => {
    addLog('INFO', '🌐 Verificando soporte del navegador...');
    
    const tests = [
      { name: 'WebSocket', check: () => typeof WebSocket !== 'undefined' },
      { name: 'AudioContext', check: () => typeof AudioContext !== 'undefined' || typeof (window as any).webkitAudioContext !== 'undefined' },
      { name: 'MediaDevices', check: () => navigator.mediaDevices && navigator.mediaDevices.getUserMedia },
      { name: 'Fetch API', check: () => typeof fetch !== 'undefined' },
      { name: 'Promises', check: () => typeof Promise !== 'undefined' }
    ];

    let allSupported = true;
    tests.forEach(test => {
      if (test.check()) {
        addLog('SUCCESS', `✅ ${test.name} soportado`);
      } else {
        addLog('ERROR', `❌ ${test.name} NO soportado`);
        allSupported = false;
      }
    });

    return allSupported;
  }, [addLog]);

  const testWebSocketConnection = useCallback(async (): Promise<boolean> => {
    addLog('INFO', '🔌 Probando conexión WebSocket...');
    
    return new Promise((resolve) => {
      try {
        const apiKey = process.env.REACT_APP_GEMINI_API_KEY;
        const wsUrl = `wss://generativelanguage.googleapis.com/ws/google.ai.generativelanguage.v1alpha.GenerativeService.BidiGenerateContent?key=${apiKey}`;
        
        const ws = new WebSocket(wsUrl);
        let resolved = false;

        const timeout = setTimeout(() => {
          if (!resolved) {
            resolved = true;
            addLog('ERROR', '❌ Timeout: WebSocket no responde en 10 segundos');
            ws.close();
            resolve(false);
          }
        }, 10000);

        ws.onopen = () => {
          if (!resolved) {
            resolved = true;
            addLog('SUCCESS', '✅ WebSocket conectado exitosamente');
            clearTimeout(timeout);
            ws.close();
            resolve(true);
          }
        };

        ws.onerror = (error) => {
          if (!resolved) {
            resolved = true;
            addLog('ERROR', `❌ Error WebSocket: ${error.type}`);
            clearTimeout(timeout);
            resolve(false);
          }
        };

        ws.onclose = (event) => {
          if (!resolved) {
            resolved = true;
            addLog('ERROR', `❌ WebSocket cerrado inesperadamente: ${event.reason || 'Sin razón'}`);
            clearTimeout(timeout);
            resolve(false);
          }
        };

      } catch (error) {
        addLog('ERROR', `❌ Error creando WebSocket: ${error instanceof Error ? error.message : 'Error desconocido'}`);
        resolve(false);
      }
    });
  }, [addLog]);

  const runDiagnostic = useCallback(async () => {
    setIsRunning(true);
    setLogs([]);
    setResults(null);

    addLog('INFO', '🧪 Iniciando diagnóstico completo de conexión...');

    const results: DiagnosticResult = {
      apiKey: await testAPIKey(),
      browserSupport: testBrowserSupport(),
      restAPI: false,
      webSocket: false
    };

    if (results.apiKey && results.browserSupport) {
      results.webSocket = await testWebSocketConnection();
    }

    addLog('INFO', '📊 RESUMEN DE RESULTADOS:');
    addLog('INFO', `🔑 API Key: ${results.apiKey ? '✅' : '❌'}`);
    addLog('INFO', `🌐 Navegador: ${results.browserSupport ? '✅' : '❌'}`);
    addLog('INFO', `🔌 WebSocket: ${results.webSocket ? '✅' : '❌'}`);

    if (results.webSocket) {
      addLog('SUCCESS', '🎉 ¡Todo funcionando! La aplicación debería funcionar sin problemas');
    } else {
      addLog('ERROR', '🚨 Hay problemas de conexión que necesitan resolverse');
    }

    setResults(results);
    setIsRunning(false);
  }, [testAPIKey, testBrowserSupport, testWebSocketConnection, addLog]);

  const getLogClassName = (type: LogEntry['type']) => {
    switch (type) {
      case 'SUCCESS': return 'log-success';
      case 'ERROR': return 'log-error';
      default: return 'log-info';
    }
  };

  return (
    <div className="connection-diagnostic">
      <div className="diagnostic-header">
        <h2>🩺 Diagnóstico de Conexión API</h2>
        <p>Verifica el estado de conexión con Google Generative AI</p>
      </div>

      <div className="diagnostic-controls">
        <button 
          onClick={runDiagnostic} 
          disabled={isRunning}
          className="diagnostic-button"
        >
          {isRunning ? '🔄 Ejecutando...' : '🧪 Ejecutar Diagnóstico'}
        </button>
      </div>

      {results && (
        <div className="diagnostic-results">
          <h3>📊 Resultados</h3>
          <div className="results-grid">
            <div className={`result-item ${results.apiKey ? 'success' : 'error'}`}>
              <span className="result-icon">{results.apiKey ? '✅' : '❌'}</span>
              <span className="result-text">API Key</span>
            </div>
            <div className={`result-item ${results.browserSupport ? 'success' : 'error'}`}>
              <span className="result-icon">{results.browserSupport ? '✅' : '❌'}</span>
              <span className="result-text">Navegador</span>
            </div>
            <div className={`result-item ${results.webSocket ? 'success' : 'error'}`}>
              <span className="result-icon">{results.webSocket ? '✅' : '❌'}</span>
              <span className="result-text">WebSocket</span>
            </div>
          </div>
        </div>
      )}

      <div className="diagnostic-logs">
        <h3>📝 Log de Diagnóstico</h3>
        <div className="logs-container">
          {logs.map((log, index) => (
            <div key={index} className={`log-entry ${getLogClassName(log.type)}`}>
              <span className="log-timestamp">{log.timestamp}</span>
              <span className="log-message">{log.message}</span>
            </div>
          ))}
        </div>
      </div>

      {results && !results.webSocket && (
        <div className="diagnostic-solutions">
          <h3>💡 Soluciones Sugeridas</h3>
          
          {!results.apiKey && (
            <div className="solution-section">
              <h4>🔑 Para API Key:</h4>
              <ul>
                <li>Ve a <a href="https://aistudio.google.com/apikey" target="_blank" rel="noopener noreferrer">Google AI Studio</a></li>
                <li>Crea una nueva API key</li>
                <li>Añádela al archivo .env sin comillas</li>
                <li>Reinicia la aplicación</li>
              </ul>
            </div>
          )}

          {!results.browserSupport && (
            <div className="solution-section">
              <h4>🌐 Para soporte del navegador:</h4>
              <ul>
                <li>Usa Chrome, Firefox, Safari o Edge modernos</li>
                <li>Actualiza tu navegador a la última versión</li>
                <li>Habilita JavaScript</li>
              </ul>
            </div>
          )}

          {!results.webSocket && results.apiKey && (
            <div className="solution-section">
              <h4>🔌 Para WebSocket:</h4>
              <ul>
                <li>Verifica que tu red permite WebSockets</li>
                <li>Desactiva VPN temporalmente</li>
                <li>Prueba desde otra red (ej: datos móviles)</li>
                <li>Contacta a tu administrador de red</li>
                <li>Verifica que no hay firewall bloqueando</li>
              </ul>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default ConnectionDiagnostic;
