/**
 * Sistema de fallback robusto para MediaStream API
 * Garantiza que las funciones de cámara y pantalla funcionen "sí o sí"
 */

import { logger } from './logger';

export interface MediaStreamFallbackConfig {
  maxRetries: number;
  retryDelays: number[];
  enableAutoRetry: boolean;
  fallbackToBasicConfig: boolean;
  showUserGuidance: boolean;
}

export interface MediaStreamCapability {
  isSupported: boolean;
  hasPermission: boolean;
  availableDevices: MediaDeviceInfo[];
  browserInfo: {
    name: string;
    version: string;
    supportsGetDisplayMedia: boolean;
    supportsGetUserMedia: boolean;
  };
}

export interface FallbackResult<T = MediaStream> {
  success: boolean;
  result?: T;
  error?: string;
  fallbackUsed: string;
  retryCount: number;
}

const DEFAULT_CONFIG: MediaStreamFallbackConfig = {
  maxRetries: 3,
  retryDelays: [1000, 2000, 4000],
  enableAutoRetry: true,
  fallbackToBasicConfig: true,
  showUserGuidance: true,
};

class MediaStreamFallbackSystem {
  private config: MediaStreamFallbackConfig;
  private capabilities: MediaStreamCapability | null = null;
  
  constructor(config: Partial<MediaStreamFallbackConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Detecta las capacidades completas del navegador y dispositivo
   */
  async detectCapabilities(): Promise<MediaStreamCapability> {
    if (this.capabilities) {
      return this.capabilities;
    }

    const capability: MediaStreamCapability = {
      isSupported: false,
      hasPermission: false,
      availableDevices: [],
      browserInfo: {
        name: this.getBrowserName(),
        version: this.getBrowserVersion(),
        supportsGetDisplayMedia: !!(navigator.mediaDevices?.getDisplayMedia),
        supportsGetUserMedia: !!(navigator.mediaDevices?.getUserMedia),
      }
    };

    try {
      // Verificar soporte básico
      capability.isSupported = !!(
        navigator.mediaDevices && 
        (navigator.mediaDevices.getUserMedia || navigator.mediaDevices.getDisplayMedia)
      );

      if (capability.isSupported) {
        // Verificar permisos si es posible
        if ('permissions' in navigator) {
          try {
            const cameraPermission = await navigator.permissions.query({ name: 'camera' as PermissionName });
            capability.hasPermission = cameraPermission.state === 'granted';
          } catch (err) {
            logger.debug('No se pudo verificar permisos de cámara:', err);
          }
        }

        // Obtener dispositivos disponibles
        try {
          const devices = await navigator.mediaDevices.enumerateDevices();
          capability.availableDevices = devices;
        } catch (err) {
          logger.debug('No se pudieron enumerar dispositivos:', err);
        }
      }

    } catch (err) {
      logger.error('Error detectando capacidades:', err);
    }

    this.capabilities = capability;
    return capability;
  }

  /**
   * Ejecuta un intento de captura con sistema de fallback completo
   */
  async executeWithFallback<T>(
    operation: () => Promise<T>,
    operationType: 'camera' | 'screen',
    deviceId?: string
  ): Promise<FallbackResult<T>> {
    const result: FallbackResult<T> = {
      success: false,
      fallbackUsed: 'none',
      retryCount: 0,
    };

    // Verificar capacidades antes de intentar
    const capabilities = await this.detectCapabilities();
    
    if (!capabilities.isSupported) {
      result.error = `Tu navegador no soporta ${operationType === 'camera' ? 'cámara' : 'compartir pantalla'}. Usa Chrome, Firefox o Edge.`;
      result.fallbackUsed = 'browser-not-supported';
      return result;
    }

    // Intentar operación principal
    try {
      result.result = await operation();
      result.success = true;
      result.fallbackUsed = 'none';
      logger.info(`${operationType} exitosa sin fallback`);
      return result;
    } catch (primaryError: any) {
      logger.warn(`Error en ${operationType} principal:`, primaryError);
      result.error = primaryError.message;
    }

    // Sistema de reintentos con fallback
    if (this.config.enableAutoRetry) {
      for (let attempt = 0; attempt < this.config.maxRetries; attempt++) {
        result.retryCount = attempt + 1;
        
        const delay = this.config.retryDelays[attempt] || this.config.retryDelays[this.config.retryDelays.length - 1];
        logger.info(`Reintento ${attempt + 1}/${this.config.maxRetries} en ${delay}ms`);
        
        await this.delay(delay);

        try {
          // Intentar con configuración progresivamente más básica
          if (operationType === 'camera') {
            result.result = await this.fallbackCameraCapture(deviceId) as T;
          } else {
            result.result = await this.fallbackScreenCapture() as T;
          }
          
          result.success = true;
          result.fallbackUsed = `retry-${attempt + 1}`;
          logger.info(`${operationType} exitosa en reintento ${attempt + 1}`);
          return result;
        } catch (retryError: any) {
          logger.warn(`Reintento ${attempt + 1} falló:`, retryError);
          result.error = retryError.message;
        }
      }
    }

    // Intentar fallback de emergencia
    try {
      if (operationType === 'camera') {
        result.result = await this.emergencyFallbackCamera() as T;
      } else {
        result.result = await this.emergencyFallbackScreen() as T;
      }
      
      result.success = true;
      result.fallbackUsed = 'emergency';
      logger.info(`${operationType} exitosa con fallback de emergencia`);
    } catch (emergencyError: any) {
      logger.error('Fallback de emergencia falló:', emergencyError);
      result.error = emergencyError.message;
      result.fallbackUsed = 'all-failed';
      
      // Mostrar guía al usuario si está habilitada
      if (this.config.showUserGuidance) {
        this.showUserGuidance(operationType, result.error || 'Error desconocido');
      }
    }

    return result;
  }

  /**
   * Fallback progresivo para cámara
   */
  private async fallbackCameraCapture(deviceId?: string): Promise<MediaStream> {
    const configs = [
      // Con dispositivo específico si se proporciona
      ...(deviceId ? [{
        video: { deviceId: { exact: deviceId }, facingMode: 'user' },
        audio: true
      }] : []),
      
      // Configuración estándar
      {
        video: { facingMode: 'user', width: 640, height: 480 },
        audio: true
      },
      
      // Solo video básico
      {
        video: { facingMode: 'user' }
      },
      
      // Cualquier cámara disponible
      {
        video: true
      }
    ];

    let lastError: any;
    
    for (const config of configs) {
      try {
        return await navigator.mediaDevices.getUserMedia(config);
      } catch (err) {
        lastError = err;
        if ((err as any).name === 'NotAllowedError') {
          break; // No intentar más si los permisos están denegados
        }
      }
    }

    throw lastError;
  }

  /**
   * Fallback progresivo para pantalla
   */
  private async fallbackScreenCapture(): Promise<MediaStream> {
    const configs = [
      // Configuración básica con audio
      {
        video: true,
        audio: true
      },
      
      // Solo video
      {
        video: true
      }
    ];

    let lastError: any;
    
    for (const config of configs) {
      try {
        return await navigator.mediaDevices.getDisplayMedia(config);
      } catch (err) {
        lastError = err;
        if ((err as any).name === 'NotAllowedError') {
          break; // No intentar más si los permisos están denegados
        }
      }
    }

    throw lastError;
  }

  /**
   * Fallback de emergencia para cámara
   */
  private async emergencyFallbackCamera(): Promise<MediaStream> {
    // Último intento con la configuración más básica posible
    return await navigator.mediaDevices.getUserMedia({ video: true });
  }

  /**
   * Fallback de emergencia para pantalla
   */
  private async emergencyFallbackScreen(): Promise<MediaStream> {
    // Último intento con la configuración más básica posible
    return await navigator.mediaDevices.getDisplayMedia({ video: true });
  }

  /**
   * Muestra guía al usuario para resolver problemas
   */
  private showUserGuidance(operationType: 'camera' | 'screen', error: string): void {
    const deviceName = operationType === 'camera' ? 'cámara' : 'compartir pantalla';
    
    let guidance = `❌ No se pudo acceder a ${deviceName}\n\n`;
    guidance += `Error: ${error}\n\n`;
    guidance += `🔧 Soluciones:\n`;
    
    if (operationType === 'camera') {
      guidance += `1. Verifica que tu cámara esté conectada\n`;
      guidance += `2. Cierra otras aplicaciones que usen la cámara\n`;
      guidance += `3. Recarga la página y permite el acceso\n`;
      guidance += `4. Verifica la configuración de privacidad del navegador\n`;
    } else {
      guidance += `1. Usa Chrome, Firefox o Edge actualizado\n`;
      guidance += `2. Verifica que estés en HTTPS\n`;
      guidance += `3. Recarga la página e inténtalo de nuevo\n`;
      guidance += `4. Reinicia el navegador si es necesario\n`;
    }
    
    guidance += `\n💡 Si el problema persiste, prueba con otro navegador.`;

    if (window.alert) {
      window.alert(guidance);
    }
    
    logger.error('Guía mostrada al usuario:', { operationType, error, guidance });
  }

  private getBrowserName(): string {
    const userAgent = navigator.userAgent;
    if (userAgent.indexOf('Chrome') > -1) return 'Chrome';
    if (userAgent.indexOf('Firefox') > -1) return 'Firefox';
    if (userAgent.indexOf('Safari') > -1) return 'Safari';
    if (userAgent.indexOf('Edge') > -1) return 'Edge';
    return 'Unknown';
  }

  private getBrowserVersion(): string {
    const userAgent = navigator.userAgent;
    const match = userAgent.match(/(?:Chrome|Firefox|Safari|Edge)\/(\d+)/);
    return match ? match[1] : 'Unknown';
  }

  private delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  /**
   * Resetea las capacidades detectadas (útil después de cambios de permisos)
   */
  resetCapabilities(): void {
    this.capabilities = null;
  }

  /**
   * Obtiene información de diagnóstico
   */
  async getDiagnosticInfo(): Promise<any> {
    const capabilities = await this.detectCapabilities();
    
    return {
      timestamp: new Date().toISOString(),
      capabilities,
      config: this.config,
      userAgent: navigator.userAgent,
      isSecureContext: window.isSecureContext,
      hasMediaDevices: !!navigator.mediaDevices,
    };
  }
}

// Exportar instancia singleton
export const mediaStreamFallback = new MediaStreamFallbackSystem();

// Exportar función helper para uso fácil
export async function executeMediaStreamWithFallback<T>(
  operation: () => Promise<T>,
  operationType: 'camera' | 'screen',
  deviceId?: string
): Promise<FallbackResult<T>> {
  return await mediaStreamFallback.executeWithFallback(operation, operationType, deviceId);
}