/**
 * Componente de notificación de reproducción automática
 * Muestra automáticamente qué canción se reproducirá a continuación
 */

import React, { useState, useEffect } from 'react';
import './AutoplayNotification.scss';

interface AutoplayNotificationProps {
  isVisible: boolean;
  message: string;
  onClose?: () => void;
}

export const AutoplayNotification: React.FC<AutoplayNotificationProps> = ({
  isVisible,
  message,
  onClose
}) => {
  const [forceVisible, setForceVisible] = useState(false);
  const [forceMessage, setForceMessage] = useState('');

  // Escuchar eventos forzados de notificación
  useEffect(() => {
    const handleForceNotification = (event: CustomEvent) => {
      console.log('🎵 🔔 Notificación forzada recibida:', event.detail);
      setForceMessage(event.detail.message);
      setForceVisible(true);
      
      // Auto-ocultar después de 5 segundos
      setTimeout(() => {
        setForceVisible(false);
        setForceMessage('');
      }, 5000);
    };

    window.addEventListener('autoplay-notification', handleForceNotification as EventListener);
    
    return () => {
      window.removeEventListener('autoplay-notification', handleForceNotification as EventListener);
    };
  }, []);

  // Mostrar notificación si hay evento forzado o estado normal
  const shouldShow = forceVisible || isVisible;
  const displayMessage = forceMessage || message;

  if (!shouldShow || !displayMessage) {
    return null;
  }

  return (
    <div className="autoplay-notification" style={{ zIndex: 9999 }}>
      <div className="autoplay-notification__content">
        <div className="autoplay-notification__icon">
          <div className="music-note-animation">
            <span>🎵</span>
          </div>
        </div>
        
        <div className="autoplay-notification__text">
          <div className="autoplay-notification__title">
            Reproducción Automática
          </div>
          <div className="autoplay-notification__message">
            {displayMessage}
          </div>
        </div>

        <div className="autoplay-notification__progress">
          <div className="progress-bar"></div>
        </div>

        {onClose && (
          <button 
            className="autoplay-notification__close"
            onClick={onClose}
            aria-label="Cerrar notificación"
          >
            ×
          </button>
        )}
      </div>
    </div>
  );
};
