/**
 * Hook personalizado para el manejo del Panel de YouTube
 * Incluye auto-reposicionamiento y gestión de estado
 * 100% libre de copyright - Licencia MIT
 */

import { useState, useEffect, useCallback } from 'react';

export interface YouTubePanelState {
  isVisible: boolean;
  isMinimized: boolean;
  position: 'left' | 'right';
  currentQuery: string;
}

export interface YouTubePanelActions {
  show: (query?: string) => void;
  hide: () => void;
  minimize: () => void;
  expand: () => void;
  toggle: () => void;
  setQuery: (query: string) => void;
  setPosition: (position: 'left' | 'right') => void;
}

export interface UseYouTubePanelOptions {
  defaultPosition?: 'left' | 'right';
  autoMinimizeOnVideoStream?: boolean;
  autoRepositionOnVideoStream?: boolean;
}

export const useYouTubePanel = (options: UseYouTubePanelOptions = {}): [YouTubePanelState, YouTubePanelActions] => {
  const {
    defaultPosition = 'right',
    autoMinimizeOnVideoStream = true,
    autoRepositionOnVideoStream = true
  } = options;

  const [state, setState] = useState<YouTubePanelState>({
    isVisible: false, // Cerrado por defecto al recargar la página
    isMinimized: false,
    position: defaultPosition,
    currentQuery: ''
  });

  // Acciones del panel
  const actions: YouTubePanelActions = {
    show: useCallback((query?: string) => {
      setState(prev => ({
        ...prev,
        isVisible: true,
        isMinimized: false,
        currentQuery: query || prev.currentQuery
      }));
    }, []),

    hide: useCallback(() => {
      setState(prev => ({
        ...prev,
        isVisible: false
      }));
    }, []),

    minimize: useCallback(() => {
      setState(prev => ({
        ...prev,
        isMinimized: true
      }));
    }, []),

    expand: useCallback(() => {
      setState(prev => ({
        ...prev,
        isMinimized: false
      }));
    }, []),

    toggle: useCallback(() => {
      setState(prev => ({
        ...prev,
        isVisible: !prev.isVisible,
        isMinimized: prev.isVisible ? false : prev.isMinimized
      }));
    }, []),

    setQuery: useCallback((query: string) => {
      setState(prev => ({
        ...prev,
        currentQuery: query
      }));
    }, []),

    setPosition: useCallback((position: 'left' | 'right') => {
      setState(prev => ({
        ...prev,
        position
      }));
    }, [])
  };
  // Auto-reposicionamiento cuando hay streams de video activos
  const handleVideoStreamChange = useCallback((hasActiveStream: boolean) => {
    if (!autoRepositionOnVideoStream && !autoMinimizeOnVideoStream) return;

    setState(prev => {
      if (!prev.isVisible) return prev;

      const newState = { ...prev };

      // SOLO auto-minimizar si está habilitado Y no hay YouTube activo reproduciendo
      if (autoMinimizeOnVideoStream && hasActiveStream && !prev.isMinimized) {
        // Verificar si hay contenido de YouTube reproduciéndose
        const youtubeIframes = document.querySelectorAll('iframe[src*="youtube"]');
        const hasActiveYouTube = Array.from(youtubeIframes).some(iframe => 
          iframe.getAttribute('src')?.includes('autoplay=1') || 
          iframe.getAttribute('src')?.includes('embed/')
        );
        
        // Solo minimizar si NO hay YouTube activo
        if (!hasActiveYouTube) {
          newState.isMinimized = true;
        }
      }

      // Auto-reposicionar para evitar solapamiento (solo si no es screen sharing)
      if (autoRepositionOnVideoStream) {
        const isScreenSharing = document.querySelector('.screen-sharing-display');
        
        if (hasActiveStream && !isScreenSharing) {
          // Mover a la izquierda solo si NO es screen sharing
          newState.position = 'left';
        } else if (!hasActiveStream) {
          // Volver a la posición por defecto solo si no hay streams
          newState.position = defaultPosition;
        }
        // Si hay screen sharing, mantener la posición actual (no mover)
      }

      return newState;
    });
  }, [autoMinimizeOnVideoStream, autoRepositionOnVideoStream, defaultPosition]);  // Efecto para escuchar cambios en el DOM que indiquen streams activos
  useEffect(() => {
    const checkForActiveStreams = () => {
      // Buscar elementos de video activos en el DOM (EXCLUYENDO YouTube)
      const videoElements = document.querySelectorAll('video:not(.youtube-iframe)');
      const hasActiveVideo = Array.from(videoElements).some(video => {
        const videoEl = video as HTMLVideoElement;
        return videoEl.srcObject !== null && !videoEl.paused && !videoEl.src.includes('youtube');
      });

      // Buscar elementos específicos del control tray que indiquen streams activos
      const cameraButton = document.querySelector('.action-button [title*="cámara"], .action-button [title*="camera"]');
      const screenButton = document.querySelector('.action-button [title*="pantalla"], .action-button [title*="screen"]');
      
      // Verificar si hay screen sharing activo
      const isScreenSharing = document.querySelector('.screen-sharing-display');
      
      // Solo considerar como "stream activo" si es cámara o screen sharing, NO YouTube
      const hasActiveStream = Boolean(
        (hasActiveVideo && !isScreenSharing) || // Video de cámara (no screen sharing)
        (cameraButton?.classList.contains('active') && !isScreenSharing) || // Cámara activa (no screen sharing)
        (screenButton?.classList.contains('active') && isScreenSharing) // Screen sharing activo
      );

      // NO contar YouTube como stream que deba minimizar el panel
      handleVideoStreamChange(hasActiveStream);
    };

    // Observar cambios en el DOM
    const observer = new MutationObserver(checkForActiveStreams);
    observer.observe(document.body, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['class', 'src']
    });

    // Check inicial
    checkForActiveStreams();

    return () => {
      observer.disconnect();
    };
  }, [handleVideoStreamChange]);

  // Manejo de teclas de acceso rápido
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      // Ctrl+Y para toggle del panel
      if (event.ctrlKey && event.key.toLowerCase() === 'y') {
        event.preventDefault();
        actions.toggle();
      }

      // Escape para cerrar panel
      if (event.key === 'Escape' && state.isVisible) {
        actions.hide();
      }

      // Ctrl+M para minimizar/expandir
      if (event.ctrlKey && event.key.toLowerCase() === 'm' && state.isVisible) {
        event.preventDefault();
        if (state.isMinimized) {
          actions.expand();
        } else {
          actions.minimize();
        }
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [actions, state.isVisible, state.isMinimized]);
  return [state, actions];
};
