import { audioContext } from "./utils";
import AudioRecordingWorklet from "./worklets/audio-processing";
import VolMeterWorket from "./worklets/vol-meter";

import { createWorketFromSrc } from "./audioworklet-registry";
import EventEmitter from "eventemitter3";

function arrayBufferToBase64(buffer: ArrayBuffer) {
  var binary = "";
  var bytes = new Uint8Array(buffer);
  var len = bytes.byteLength;
  for (var i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return window.btoa(binary);
}

export class AudioRecorder extends EventEmitter {
  stream: MediaStream | undefined;
  audioContext: AudioContext | undefined;
  source: MediaStreamAudioSourceNode | undefined;
  recording: boolean = false;
  recordingWorklet: AudioWorkletNode | undefined;
  vuWorklet: AudioWorkletNode | undefined;

  private starting: Promise<void> | null = null;

  constructor(public sampleRate = 16000) {
    super();
  }

  async start() {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      throw new Error("🎤 Tu navegador no soporta grabación de audio o no está disponible MediaDevices API");
    }

    // Verificar si estamos en un contexto seguro (HTTPS o localhost)
    if (window.location.protocol !== 'https:' && window.location.hostname !== 'localhost' && window.location.hostname !== '127.0.0.1') {
      throw new Error("🔒 VOXIA requiere HTTPS para acceder al micrófono. Por favor, accede desde una URL segura (https://)");
    }

    this.starting = new Promise(async (resolve, reject) => {
      try {
        // Verificar permisos antes de solicitar el stream
        if (navigator.permissions) {
          try {
            const permission = await navigator.permissions.query({ name: 'microphone' as PermissionName });
            if (permission.state === 'denied') {
              throw new Error("🚫 Acceso al micrófono denegado. Por favor, permite el acceso al micrófono en la configuración del navegador y recarga la página.");
            }
          } catch (permissionError) {
            console.warn("No se pudo verificar permisos:", permissionError);
            // Continuar intentando, algunos navegadores no soportan permissions API
          }
        }

        console.log("🎤 Solicitando acceso al micrófono...");
        
        // Solicitar stream de audio con configuración optimizada
        this.stream = await navigator.mediaDevices.getUserMedia({ 
          audio: {
            echoCancellation: true,
            noiseSuppression: true,
            autoGainControl: true,
            sampleRate: this.sampleRate
          } 
        });
        
        console.log("✅ Micrófono obtenido exitosamente");
        
        this.audioContext = await audioContext({ sampleRate: this.sampleRate });
        
        // 🔧 CORRECCIÓN CRÍTICA: NO conectar el source directamente al destination
        // Esto evita el eco (feedback loop) donde el micrófono se reproduce por las bocinas
        this.source = this.audioContext.createMediaStreamSource(this.stream);
        
        // El source SOLO debe conectarse a los worklets de procesamiento,
        // NUNCA al destination (bocinas) para evitar eco
      } catch (error: any) {
        console.error("❌ Error al acceder al micrófono:", error);
        
        // Manejo específico de errores comunes
        let userFriendlyMessage = "❌ No se pudo acceder al micrófono. ";
        
        if (error.name === 'NotAllowedError' || error.name === 'PermissionDeniedError') {
          userFriendlyMessage += "Acceso denegado. Por favor:\n" +
            "1. Permite el acceso al micrófono cuando el navegador lo solicite\n" +
            "2. Verifica que no haya otras aplicaciones usando el micrófono\n" +
            "3. Recarga la página e intenta de nuevo";
        } else if (error.name === 'NotFoundError' || error.name === 'DevicesNotFoundError') {
          userFriendlyMessage += "No se encontró ningún micrófono.\n" +
            "Por favor verifica que tengas un micrófono conectado y funcionando.";
        } else if (error.name === 'NotReadableError' || error.name === 'TrackStartError') {
          userFriendlyMessage += "El micrófono está siendo usado por otra aplicación.\n" +
            "Cierra otras aplicaciones que puedan estar usando el micrófono.";
        } else if (error.name === 'OverconstrainedError' || error.name === 'ConstraintNotSatisfiedError') {
          userFriendlyMessage += "Configuración de audio no compatible.\n" +
            "Tu micrófono no soporta la configuración requerida.";
        } else if (error.name === 'NotSupportedError') {
          userFriendlyMessage += "Tu navegador no soporta grabación de audio.\n" +
            "Intenta usar Chrome, Firefox, Safari o Edge más recientes.";
        } else if (error.name === 'SecurityError') {
          userFriendlyMessage += "Error de seguridad.\n" +
            "Asegúrate de estar usando HTTPS y que el sitio tenga permisos.";
        } else {
          userFriendlyMessage += `Error: ${error.message || error}`;
        }
        
        reject(new Error(userFriendlyMessage));
        return;
      }

      try {
        const workletName = "audio-recorder-worklet";
        const src = createWorketFromSrc(workletName, AudioRecordingWorklet);

        await this.audioContext.audioWorklet.addModule(src);
        this.recordingWorklet = new AudioWorkletNode(
          this.audioContext,
          workletName,
        );

        this.recordingWorklet.port.onmessage = async (ev: MessageEvent) => {
          // worklet processes recording floats and messages converted buffer
          const arrayBuffer = ev.data.data.int16arrayBuffer;

          if (arrayBuffer) {
            const arrayBufferString = arrayBufferToBase64(arrayBuffer);
            this.emit("data", arrayBufferString);
          }
        };
        this.source.connect(this.recordingWorklet);

        // vu meter worklet
        const vuWorkletName = "vu-meter";
        await this.audioContext.audioWorklet.addModule(
          createWorketFromSrc(vuWorkletName, VolMeterWorket),
        );
        this.vuWorklet = new AudioWorkletNode(this.audioContext, vuWorkletName);
        this.vuWorklet.port.onmessage = (ev: MessageEvent) => {
          this.emit("volume", ev.data.volume);
        };

        // 🔧 CORRECCIÓN: VU meter también conectado SOLO para monitoreo
        // NO conectado al destination para evitar eco
        this.source.connect(this.vuWorklet);
        
        this.recording = true;
        console.log("🎙️ VOXIA micrófono iniciado correctamente (SIN ECO)");
        resolve();
        this.starting = null;
      } catch (workletError: any) {
        console.error("❌ Error al inicializar worklets de audio:", workletError);
        reject(new Error(`Error de configuración de audio: ${workletError.message}`));
      }
    });
  }

  stop() {
    // its plausible that stop would be called before start completes
    // such as if the websocket immediately hangs up
    const handleStop = () => {
      this.source?.disconnect();
      this.stream?.getTracks().forEach((track) => track.stop());
      this.stream = undefined;
      this.recordingWorklet = undefined;
      this.vuWorklet = undefined;
    };
    if (this.starting) {
      this.starting.then(handleStop);
      return;
    }
    handleStop();
  }
}
