import { SPANISH_VOICES } from '../i18n/translations';

export interface VoiceConfig {
  rate: number;
  pitch: number;
  volume: number;
  lang: string;
  voice?: string;
}

export class SpanishVoiceService {
  private synth: SpeechSynthesis;
  private currentUtterance: SpeechSynthesisUtterance | null = null;
  private config: VoiceConfig;
  private availableVoices: SpeechSynthesisVoice[] = [];

  constructor() {
    this.synth = window.speechSynthesis;
    this.config = {
      rate: 0.9,
      pitch: 1.0,
      volume: 1.0,
      lang: 'es-ES'
    };
    this.loadVoices();
  }

  private loadVoices(): void {
    const loadVoicesAsync = () => {
      const voices = this.synth.getVoices();
      this.availableVoices = voices.filter(voice => 
        voice.lang.startsWith('es') || 
        voice.name.toLowerCase().includes('spanish') ||
        voice.name.toLowerCase().includes('español')
      );
      
      // Set default voice for multiple languages
      if (this.availableVoices.length > 0 && !this.config.voice) {
        const preferredVoice = this.availableVoices.find(voice => 
          voice.lang === 'es-ES' || voice.lang.includes('es-ES')
        ) || this.availableVoices[0];
        
        this.config.voice = preferredVoice.name;
      }
    };

    if (this.synth.getVoices().length > 0) {
      loadVoicesAsync();
    } else {
      this.synth.onvoiceschanged = loadVoicesAsync;
    }
  }

  public getAvailableVoices(): SpeechSynthesisVoice[] {
    return this.availableVoices;
  }

  public getVoicesByRegion(region: string): SpeechSynthesisVoice[] {
    return this.availableVoices.filter(voice => 
      voice.lang.includes(region)
    );
  }

  public setVoiceConfig(config: Partial<VoiceConfig>): void {
    this.config = { ...this.config, ...config };
  }

  public getVoiceConfig(): VoiceConfig {
    return { ...this.config };
  }

  public speak(text: string, onStart?: () => void, onEnd?: () => void, onError?: (error: any) => void): void {
    // Cancelar cualquier reproducción en curso
    this.stop();

    if (!text.trim()) return;

    const utterance = new SpeechSynthesisUtterance(text);
    
    // Configurar la voz
    const selectedVoice = this.availableVoices.find(voice => 
      voice.name === this.config.voice
    );
    
    if (selectedVoice) {
      utterance.voice = selectedVoice;
    }

    // Aplicar configuraciones
    utterance.rate = this.config.rate;
    utterance.pitch = this.config.pitch;
    utterance.volume = this.config.volume;
    utterance.lang = this.config.lang;

    // Configurar eventos
    utterance.onstart = () => {
      if (onStart) onStart();
    };

    utterance.onend = () => {
      this.currentUtterance = null;
      if (onEnd) onEnd();
    };

    utterance.onerror = (event) => {
      this.currentUtterance = null;
      console.error('Error en síntesis de voz:', event.error);
      if (onError) onError(event.error);
    };

    this.currentUtterance = utterance;
    this.synth.speak(utterance);
  }

  public stop(): void {
    if (this.synth.speaking) {
      this.synth.cancel();
    }
    this.currentUtterance = null;
  }

  public pause(): void {
    if (this.synth.speaking) {
      this.synth.pause();
    }
  }

  public resume(): void {
    if (this.synth.paused) {
      this.synth.resume();
    }
  }

  public isSpeaking(): boolean {
    return this.synth.speaking;
  }

  public isPaused(): boolean {
    return this.synth.paused;
  }

  // Método para probar la voz seleccionada
  public testVoice(): void {
    const testText = "Hola, esta es una prueba de la síntesis de voz en español. ¿Puedes escucharme correctamente?";
    this.speak(testText);
  }

  // Método para obtener información de la voz actual
  public getCurrentVoiceInfo(): string {
    const currentVoice = this.availableVoices.find(voice => 
      voice.name === this.config.voice
    );
    
    if (currentVoice) {
      return `${currentVoice.name} (${currentVoice.lang})`;
    }
    
    return 'Voz por defecto del sistema';
  }
}

// Instancia global del servicio
export const spanishVoiceService = new SpanishVoiceService();
