/**
 * A registry to map attached worklets by their audio-context
 * any module using `audioContext.audioWorklet.addModule(` should register the worklet here
 */
export type WorkletGraph = {
  node?: AudioWorkletNode;
  handlers: Array<(this: MessagePort, ev: MessageEvent) => any>;
};

export const registeredWorklets: Map<
  AudioContext,
  Record<string, WorkletGraph>
> = new Map();

export const createWorketFromSrc = (
  workletName: string,
  workletSrc: string,
) => {
  const script = new Blob(
    [workletSrc],
    {
      type: "application/javascript",
    },
  );

  const url = URL.createObjectURL(script);
  
  // Limpiar el blob URL después de un breve delay para evitar problemas de memoria
  // El delay asegura que el worklet se haya cargado antes de limpiar
  setTimeout(() => {
    try {
      URL.revokeObjectURL(url);
    } catch (error) {
      console.warn('Error al limpiar blob URL:', error);
    }
  }, 5000); // 5 segundos debería ser suficiente

  return url;
};
