/**
 * Servicio de Reproducción Automática para YouTube
 * Gestiona la cola automática y transiciones entre videos
 * Activado por defecto - Sin controles manuales
 */

import { YouTubeService, YouTubeVideo, YouTubeSearchParams } from './YouTubeService';
import { logger } from '../utils/logger';

export interface AutoplayState {
  isActive: boolean;
  currentVideo: YouTubeVideo | null;
  nextVideo: YouTubeVideo | null;
  queue: YouTubeVideo[];
  playHistory: string[];
  showNotification: boolean;
  notificationMessage: string;
}

export class AutoplayService {
  private youtubeService: YouTubeService;
  private state: AutoplayState;
  private listeners: ((state: AutoplayState) => void)[] = [];
  private checkInterval: NodeJS.Timeout | null = null;
  private notificationTimeout: NodeJS.Timeout | null = null;
  private currentPlayer: any = null; // YouTube IFrame Player instance
  private initialized: boolean = false; // Flag para controlar inicialización

  constructor() {
    this.youtubeService = new YouTubeService();
    this.state = {
      isActive: true, // SIEMPRE ACTIVADO POR DEFECTO
      currentVideo: null,
      nextVideo: null,
      queue: [],
      playHistory: [],
      showNotification: false,
      notificationMessage: ''
    };

    logger.log('🎵 🏗️ Constructor AutoplayService - Inicialización LAZY');
    // No inicializar API inmediatamente para optimizar recursos
    // this.initializeYouTubeAPI();
  }

  /**
   * Inicialización manual del API de YouTube (solo cuando se necesite)
   */
  public initialize() {
    if (!this.initialized) {
      logger.log('🎵 🚀 Inicializando YouTube API bajo demanda...');
      this.initializeYouTubeAPI();
      this.initialized = true;
    }
  }

  /**
   * Inicializar YouTube IFrame API OFICIAL para detección de eventos
   */
  private initializeYouTubeAPI() {
    logger.log('🎵 🔧 Inicializando YouTube IFrame API OFICIAL...');
    
    // Cargar YouTube IFrame API si no está cargado
    if (!(window as any).YT) {
      const tag = document.createElement('script');
      tag.src = 'https://www.youtube.com/iframe_api';
      const firstScriptTag = document.getElementsByTagName('script')[0];
      firstScriptTag.parentNode?.insertBefore(tag, firstScriptTag);

      // Configurar callback global CORRECTO
      (window as any).onYouTubeIframeAPIReady = () => {
        logger.log('🎵 ✅ YouTube IFrame API cargada correctamente');
        this.setupYouTubePlayer();
      };
    } else {
      logger.log('🎵 ♻️ YouTube API ya disponible, configurando player...');
      this.setupYouTubePlayer();
    }
  }

  /**
   * NUEVO: Configurar el reproductor de YouTube oficial con eventos
   */
  private setupYouTubePlayer() {
    console.log('🎵 🎮 Configurando reproductor de YouTube...');
    
    // Buscar el iframe existente
    const existingIframe = document.querySelector('iframe[src*="youtube.com/embed"]') as HTMLIFrameElement;
    if (!existingIframe) {
      console.log('🎵 ⏰ No hay iframe todavía, esperando...');
      setTimeout(() => this.setupYouTubePlayer(), 500); // Reducido de 2000ms a 500ms
      return;
    }

    // Extraer el video ID del iframe src
    const src = existingIframe.src;
    const videoIdMatch = src.match(/\/embed\/([^?&]+)/);
    if (!videoIdMatch) {
      console.log('🎵 ⚠️ No se pudo extraer video ID del iframe');
      return;
    }

    const videoId = videoIdMatch[1];
    console.log('🎵 🆔 Video ID detectado:', videoId);

    try {
      // Crear reproductor de YouTube oficial
      this.currentPlayer = new (window as any).YT.Player(existingIframe, {
        events: {
          'onReady': this.onPlayerReady.bind(this),
          'onStateChange': this.onPlayerStateChange.bind(this),
          'onError': this.onPlayerError.bind(this)
        }
      });

      console.log('🎵 ✅ Reproductor de YouTube oficial configurado');
      
    } catch (error) {
      console.error('🎵 ❌ Error configurando reproductor:', error);
      // Fallback al método anterior
      this.setupAutoplayMonitoring();
    }
  }

  /**
   * NUEVO: Evento cuando el reproductor está listo
   */
  private onPlayerReady(event: any) {
    console.log('🎵 🎮 ¡Reproductor de YouTube listo!', event);
    this.currentPlayer = event.target;
  }

  /**
   * NUEVO: Evento OFICIAL cuando cambia el estado del reproductor
   */
  private onPlayerStateChange(event: any) {
    const state = event.data;
    console.log('🎵 📊 Estado del reproductor cambió:', state);

    // Usar constantes oficiales de YouTube
    const YT = (window as any).YT;
    
    switch (state) {
      case YT.PlayerState.ENDED: // 0 - Video terminado
        console.log('🎵 🎯 ¡VIDEO TERMINADO! Reproduciendo siguiente inmediatamente...');
        this.playNextVideoInstant();
        break;
        
      case YT.PlayerState.PLAYING: // 1 - Reproduciendo
        console.log('🎵 ▶️ Video reproduciéndose');
        this.lastVideoChangeTime = Date.now();
        break;
        
      case YT.PlayerState.PAUSED: // 2 - Pausado
        console.log('🎵 ⏸️ Video pausado');
        break;
        
      case YT.PlayerState.BUFFERING: // 3 - Cargando
        console.log('🎵 ⏳ Video cargando...');
        break;
        
      case YT.PlayerState.CUED: // 5 - Video preparado
        console.log('🎵 🔄 Video preparado para reproducir');
        break;
        
      case YT.PlayerState.UNSTARTED: // -1 - No iniciado
        console.log('🎵 ⭕ Video no iniciado');
        break;
        
      default:
        console.log('🎵 ❓ Estado desconocido:', state);
    }
  }

  /**
   * NUEVO: Manejar errores del reproductor
   */
  private onPlayerError(event: any) {
    console.error('🎵 ❌ Error en reproductor de YouTube:', event.data);
    
    // Si hay error, intentar reproducir siguiente video
    setTimeout(() => {
      console.log('🎵 🔄 Error detectado, intentando siguiente video...');
      this.playNextVideoInstant();
    }, 2000);
  }

  /**
   * Configurar listener de mensajes para eventos del iframe MEJORADO
   */
  private setupMessageListener() {
    console.log('🎵 📡 Configurando listener de mensajes AVANZADO...');
    
    window.addEventListener('message', (event) => {
      // Verificar que viene de YouTube
      if (!event.origin.includes('youtube.com') && !event.origin.includes('youtu.be')) {
        return;
      }

      try {
        const data = typeof event.data === 'string' ? JSON.parse(event.data) : event.data;
        console.log('🎵 📨 Mensaje recibido de YouTube:', data);

        // Manejar diferentes tipos de eventos
        if (data.event === 'video-progress') {
          this.handleVideoProgress(data);
        } else if (data.event === 'infoDelivery') {
          this.handleInfoDelivery(data);
        } else if (data.info) {
          this.handlePlayerStateChange(data.info);
        } else if (data.event === 'onStateChange') {
          console.log('🎵 🎯 Cambio de estado detectado:', data.info);
          this.handlePlayerStateChange({ playerState: data.info });
        } else if (typeof data === 'number') {
          // Respuesta directa del estado del reproductor
          console.log('🎵 📊 Estado del reproductor (número):', data);
          this.handlePlayerStateChange({ playerState: data });
        }

      } catch (error) {
        console.warn('🎵 ⚠️ Error procesando mensaje de YouTube:', error);
      }
    });

    console.log('🎵 ✅ Listener de mensajes configurado');
  }

  /**
   * Manejar cambios de estado del reproductor MEJORADO
   */
  private handlePlayerStateChange(info: any) {
    console.log('🎵 🔄 Estado del reproductor:', info);

    if (info.playerState !== undefined) {
      const playerState = info.playerState;
      console.log('🎵 📊 Estado actual:', playerState);

      // Estado 0 = Finalizado - ¡REPRODUCIR INMEDIATAMENTE!
      if (playerState === 0) {
        console.log('🎵 🎯 ¡Video finalizado! Reproduciendo siguiente INMEDIATAMENTE...');
        this.playNextVideoInstant();
        this.lastVideoChangeTime = Date.now();
      }
      // Estado 1 = Reproduciendo
      else if (playerState === 1) {
        console.log('🎵 ▶️ Video reproduciéndose');
        this.lastVideoChangeTime = Date.now(); // Resetear timer
      }
      // Estado 2 = Pausado
      else if (playerState === 2) {
        console.log('🎵 ⏸️ Video pausado');
      }
      // Estado 3 = Buffering
      else if (playerState === 3) {
        console.log('🎵 ⏳ Video cargando...');
      }
      // Estado -1 = Sin comenzar
      else if (playerState === -1) {
        console.log('🎵 🔄 Video sin comenzar');
      }
    }

    // Verificar tiempo restante para preparar siguiente
    if (info.currentTime && info.duration) {
      const timeLeft = info.duration - info.currentTime;
      console.log(`🎵 ⏰ Tiempo restante: ${timeLeft.toFixed(1)}s`);
      
      if (timeLeft <= 3 && timeLeft > 0) {
        console.log('🎵 ⏰ Quedan pocos segundos, preparando siguiente video...');
        this.preloadNextVideoInstant();
      }
      
      // Si el tiempo restante es negativo o cero, forzar siguiente
      if (timeLeft <= 0) {
        console.log('🎵 ⚡ Tiempo agotado detectado, forzando siguiente video...');
        this.playNextVideoInstant();
        this.lastVideoChangeTime = Date.now();
      }
    }
  }

  /**
   * Manejar información de entrega del reproductor
   */
  private handleInfoDelivery(data: any) {
    console.log('🎵 📦 Información recibida:', data);
    if (data.info) {
      this.handlePlayerStateChange(data.info);
    }
  }

  /**
   * Manejar progreso del video
   */
  private handleVideoProgress(data: any) {
    if (data.currentTime && data.duration) {
      const timeLeft = data.duration - data.currentTime;
      if (timeLeft <= 2) {
        console.log('🎵 ⚡ Tiempo casi agotado, activando autoplay...');
        this.playNextVideoInstant();
      }
    }
  }

  /**
   * Configurar monitoreo automático de reproducción OPTIMIZADO
   */
  private setupAutoplayMonitoring() {
    // Monitorear cambios cada 1 segundo para detección MÁS RÁPIDA
    this.checkInterval = setInterval(() => {
      this.checkPlayerState();
      this.detectVideoEnd(); // NUEVA función para detectar fin de video
    }, 1000); // Reducido de 2000 a 1000ms para mayor responsividad

    console.log('🎵 ⚡ Sistema de reproducción automática OPTIMIZADO iniciado');
  }

  /**
   * NUEVA: Detectar activamente si un video ha terminado - CON LOGGING
   */
  private detectVideoEnd() {
    const iframe = document.querySelector('iframe[src*="youtube.com/embed"]') as HTMLIFrameElement;
    if (!iframe || !iframe.contentWindow) {
      console.log('🎵 ⚠️ Iframe o contentWindow no disponible');
      return;
    }

    try {
      console.log('🎵 🔍 Solicitando estado del reproductor...');
      
      // Solicitar información del reproductor
      iframe.contentWindow.postMessage(
        JSON.stringify({
          event: 'command',
          func: 'getPlayerState',
          args: ''
        }),
        '*'
      );

      iframe.contentWindow.postMessage(
        JSON.stringify({
          event: 'command',
          func: 'getCurrentTime',
          args: ''
        }),
        '*'
      );

      iframe.contentWindow.postMessage(
        JSON.stringify({
          event: 'command',
          func: 'getDuration',
          args: ''
        }),
        '*'
      );

      console.log('🎵 📤 Comandos enviados al iframe');

    } catch (error) {
      console.warn('🎵 ⚠️ Error enviando comandos al iframe:', error);
      // Fallback: detectar por cambio de URL o título
      this.fallbackVideoEndDetection();
    }
  }

  /**
   * Detección alternativa sin iframe API - MEJORADA
   */
  private fallbackVideoEndDetection() {
    const iframe = document.querySelector('iframe[src*="youtube.com/embed"]') as HTMLIFrameElement;
    if (!iframe) return;

    try {
      const currentTime = Date.now();
      
      // Si han pasado más de 5 minutos desde el último cambio, asumir que terminó
      const timeThreshold = 300000; // 5 minutos
      
      if (this.lastVideoChangeTime && (currentTime - this.lastVideoChangeTime) > timeThreshold) {
        console.log('🎵 ⏰ Video probablemente terminado por tiempo, reproduciendo siguiente...');
        this.playNextVideoInstant();
        this.lastVideoChangeTime = currentTime;
      }
      
      // También intentar detectar si el iframe cambió o si hay indicadores visuales
      this.detectVisualEnd();
      
    } catch (error) {
      console.warn('🎵 ⚠️ Error en detección fallback:', error);
    }
  }

  /**
   * NUEVA: Detectar fin de video por indicadores visuales
   */
  private detectVisualEnd() {
    try {
      const iframe = document.querySelector('iframe[src*="youtube.com/embed"]') as HTMLIFrameElement;
      if (!iframe) return;

      // Verificar si el URL del iframe cambió (indica un nuevo video)
      const currentSrc = iframe.src;
      if (this.lastIframeSrc && this.lastIframeSrc !== currentSrc) {
        console.log('🎵 🔄 Cambio de URL detectado en iframe');
        this.lastIframeSrc = currentSrc;
        this.lastVideoChangeTime = Date.now();
        return;
      }
      
      if (!this.lastIframeSrc) {
        this.lastIframeSrc = currentSrc;
      }

      // Monitorear por 4 minutos y luego forzar cambio
      const videoLength = 240000; // 4 minutos promedio
      if (this.lastVideoChangeTime && (Date.now() - this.lastVideoChangeTime) > videoLength) {
        console.log('🎵 🎵 Tiempo promedio de video alcanzado, activando siguiente...');
        this.playNextVideoInstant();
        this.lastVideoChangeTime = Date.now();
      }

    } catch (error) {
      console.warn('🎵 ⚠️ Error en detección visual:', error);
    }
  }

  private lastVideoChangeTime: number = 0;
  private lastIframeSrc: string = '';

  /**
   * Verificar estado del reproductor y gestionar transiciones
   */
  private checkPlayerState() {
    const iframe = document.querySelector('iframe[src*="youtube.com/embed"]') as HTMLIFrameElement;
    if (!iframe) return;

    try {
      // Verificar si el iframe tiene enablejsapi
      const src = iframe.src;
      if (!src.includes('enablejsapi=1')) {
        // Actualizar URL para habilitar API
        const url = new URL(src);
        url.searchParams.set('enablejsapi', '1');
        url.searchParams.set('origin', window.location.origin);
        iframe.src = url.toString();
        return;
      }

      // Enviar comando para obtener estado del reproductor
      iframe.contentWindow?.postMessage(
        '{"event":"command","func":"getPlayerState","args":""}',
        '*'
      );

      // Enviar comando para obtener tiempo actual
      iframe.contentWindow?.postMessage(
        '{"event":"command","func":"getCurrentTime","args":""}',
        '*'
      );

      // Enviar comando para obtener duración
      iframe.contentWindow?.postMessage(
        '{"event":"command","func":"getDuration","args":""}',
        '*'
      );

    } catch (error) {
      console.warn('🎵 ⚠️ Error al verificar estado del reproductor:', error);
    }
  }



  /**
   * Manejar cambios de estado del reproductor
   */
  private handleStateChange(state: number) {
    console.log('🎵 📊 Estado del reproductor:', state);
    
    switch (state) {
      case 0: // Video terminado - REPRODUCCIÓN INSTANTÁNEA
        console.log('🎵 ✅ Video terminado - Iniciando siguiente video INMEDIATAMENTE');
        // Reproducir siguiente video SIN DELAY
        setTimeout(() => this.playNextVideoInstant(), 0);
        break;
      case 1: // Reproduciendo
        console.log('🎵 ▶️ Video reproduciéndose');
        this.hideNotification();
        // Precargar inmediatamente para garantizar transición sin cortes
        setTimeout(() => this.preloadNextVideoInstant(), 200); // Reducido de 1000ms a 200ms
        break;
      case 2: // Pausado
        console.log('🎵 ⏸️ Video pausado');
        break;
      case 3: // Buffering
        console.log('🎵 🔄 Video en buffer');
        break;
    }
  }

  /**
   * Manejar información del reproductor (tiempo, duración, etc.)
   */
  private handlePlayerInfo(info: any) {
    if (info.currentTime && info.duration && this.state.currentVideo) {
      const timeRemaining = info.duration - info.currentTime;
      
      // Mostrar notificación 5 segundos antes de que termine (reducido)
      if (timeRemaining <= 5 && timeRemaining > 3 && !this.state.showNotification) {
        this.showNextVideoNotification();
      }
      
      // Precargar siguiente video 30 segundos antes (aumentado para mejor precarga)
      if (timeRemaining <= 30 && !this.state.nextVideo) {
        this.preloadNextVideoInstant();
      }
      
      // Precarga ANTICIPADA para videos cortos (menos de 60 segundos)
      if (info.duration <= 60 && timeRemaining <= info.duration * 0.7 && !this.state.nextVideo) {
        console.log('🎵 ⚡ Video corto detectado - Precarga anticipada');
        this.preloadNextVideoInstant();
      }
    }
  }

  /**
   * Mostrar notificación del siguiente video
   */
  private showNextVideoNotification() {
    if (!this.state.nextVideo) return;

    const message = `A continuación "${this.state.nextVideo.title}" se reproducirá`;
    
    this.updateState({
      ...this.state,
      showNotification: true,
      notificationMessage: message
    });

    console.log('🎵 📢 Mostrando notificación:', message);

    // Ocultar notificación después de 5 segundos
    this.notificationTimeout = setTimeout(() => {
      this.hideNotification();
    }, 5000);
  }

  /**
   * Ocultar notificación
   */
  private hideNotification() {
    if (this.notificationTimeout) {
      clearTimeout(this.notificationTimeout);
      this.notificationTimeout = null;
    }

    this.updateState({
      ...this.state,
      showNotification: false,
      notificationMessage: ''
    });
  }

  /**
   * Iniciar precarga del siguiente video
   */
  private startNextVideoPreload() {
    if (this.state.nextVideo) return; // Ya hay un video precargado

    // Esperar 3 segundos después de iniciar reproducción para precargar
    setTimeout(() => {
      this.preloadNextVideo();
    }, 3000);
  }

  /**
   * Precargar siguiente video
   */
  private async preloadNextVideo() {
    if (!this.state.currentVideo) return;

    try {
      console.log('🎵 🔍 Precargando siguiente video...');

      let nextVideo: YouTubeVideo | null = null;

      // Si hay videos en cola, usar el primero
      if (this.state.queue.length > 0) {
        nextVideo = this.state.queue[0];
        console.log('🎵 📋 Siguiente video desde cola:', nextVideo.title);
      } else {
        // Buscar video relacionado automáticamente
        nextVideo = await this.findRelatedVideo();
      }

      if (nextVideo) {
        this.updateState({
          ...this.state,
          nextVideo,
          queue: this.state.queue.slice(1) // Remover de cola si vino de ahí
        });

        console.log('🎵 ✅ Siguiente video precargado:', nextVideo.title);
      }

    } catch (error) {
      console.error('🎵 ❌ Error al precargar siguiente video:', error);
    }
  }

  /**
   * Buscar video relacionado automáticamente
   */
  private async findRelatedVideo(): Promise<YouTubeVideo | null> {
    if (!this.state.currentVideo) return null;

    try {
      // Generar búsqueda relacionada basada en el video actual
      const searchTerms = this.generateRelatedSearchTerms(this.state.currentVideo);
      
      for (const term of searchTerms) {
        const results = await this.youtubeService.searchVideos({
          query: term,
          maxResults: 10,
          order: 'relevance'
        });

        // Filtrar videos ya reproducidos
        const filtered = results.filter(video => 
          !this.state.playHistory.includes(video.id) && 
          video.id !== this.state.currentVideo?.id
        );

        if (filtered.length > 0) {
          return filtered[0];
        }
      }

      return null;
    } catch (error) {
      console.error('🎵 ❌ Error al buscar video relacionado:', error);
      return null;
    }
  }

  /**
   * Generar términos de búsqueda relacionados
   */
  private generateRelatedSearchTerms(video: YouTubeVideo): string[] {
    const terms: string[] = [];

    // 1. Detectar artista del título actual
    const extractedArtist = this.extractArtistFromTitle(video.title);
    if (extractedArtist) {
      terms.push(extractedArtist);
      terms.push(`${extractedArtist} type beat`);
      terms.push(`similar a ${extractedArtist}`);
    }

    // 2. Detectar género musical del título/canal
    const detectedGenre = this.detectMusicGenre(video.title, video.channelTitle);
    if (detectedGenre) {
      terms.push(detectedGenre);
      terms.push(`${detectedGenre} nueva`);
      terms.push(`${detectedGenre} 2024`);
      terms.push(`${detectedGenre} hits`);
    }

    // 3. Usar el canal para encontrar más música del mismo artista/estilo
    if (video.channelTitle) {
      terms.push(video.channelTitle);
      terms.push(`${video.channelTitle} similar`);
    }

    // 4. Extraer palabras clave musicales del título
    const musicalKeywords = this.extractMusicalKeywords(video.title);
    terms.push(...musicalKeywords);

    // 5. Solo si no hay términos relacionados, usar algunos aleatorios
    if (terms.length < 5) {
      const randomTerms = this.generateRandomMusicTerms().slice(0, 3);
      terms.push(...randomTerms);
    }

    console.log('🎵 🔍 Términos de búsqueda RELACIONADA:', terms);
    return terms;
  }

  /**
   * Reproducir siguiente video automáticamente
   */
  private async playNextVideo() {
    if (!this.state.nextVideo) {
      console.log('🎵 🔍 No hay siguiente video, buscando automáticamente...');
      await this.preloadNextVideo();
    }

    if (this.state.nextVideo) {
      console.log('🎵 ▶️ Reproduciendo siguiente video:', this.state.nextVideo.title);
      
      // Actualizar historial
      const newHistory = this.state.currentVideo 
        ? [...this.state.playHistory.slice(-19), this.state.currentVideo.id]
        : this.state.playHistory;

      // Guardar referencia al video antes de actualizar
      const videoToPlay = this.state.nextVideo;

      this.updateState({
        ...this.state,
        currentVideo: videoToPlay,
        nextVideo: null,
        playHistory: newHistory
      });

      // Notificar a los componentes que reproduzcan el nuevo video
      if (videoToPlay) {
        this.notifyVideoChange(videoToPlay);
      }
    }
  }

  /**
   * Reproducir siguiente video INSTANTÁNEAMENTE (sin delays)
   */
  private async playNextVideoInstant() {
    console.log('🎵 ⚡ REPRODUCCIÓN INSTANTÁNEA activada');
    
    // Si no hay video precargado, buscar uno inmediatamente
    if (!this.state.nextVideo) {
      console.log('🎵 🚀 No hay video precargado - Búsqueda URGENTE');
      await this.preloadNextVideoInstant();
    }

    if (this.state.nextVideo) {
      console.log('🎵 ⚡ REPRODUCIENDO INMEDIATAMENTE:', this.state.nextVideo.title);
      
      // Actualizar historial
      const newHistory = this.state.currentVideo 
        ? [...this.state.playHistory.slice(-19), this.state.currentVideo.id]
        : this.state.playHistory;

      // Ocultar notificación inmediatamente
      this.hideNotification();

      // Guardar referencia al video antes de actualizar estado
      const videoToPlay = this.state.nextVideo;

      // Actualizar estado INMEDIATAMENTE
      this.updateState({
        ...this.state,
        currentVideo: videoToPlay,
        nextVideo: null,
        playHistory: newHistory,
        showNotification: false
      });

      // Notificar cambio INMEDIATO a los componentes con video válido
      if (videoToPlay) {
        this.notifyVideoChange(videoToPlay);
      }
      
      // Precargar el siguiente inmediatamente para mantener el flujo
      setTimeout(() => this.preloadNextVideoInstant(), 100); // Reducido de 500ms a 100ms
      
    } else {
      console.warn('🎵 ⚠️ No se pudo encontrar video para reproducción instantánea');
      // Como fallback, intentar una búsqueda rápida
      this.findQuickVideo();
    }
  }

  /**
   * Precarga INSTANTÁNEA y AGRESIVA del siguiente video
   */
  private async preloadNextVideoInstant() {
    if (!this.state.currentVideo) {
      console.log('🎵 ⚠️ No hay video actual para precarga instantánea');
      return;
    }

    // Verificar si ya hay un video precargado
    if (this.state.nextVideo) {
      console.log('🎵 ✅ Ya hay video precargado:', this.state.nextVideo.title);
      return;
    }

    try {
      console.log('🎵 ⚡ PRECARGA INSTANTÁNEA iniciada...');

      let nextVideo: YouTubeVideo | null = null;

      // Si hay videos en cola, usar el primero INMEDIATAMENTE
      if (this.state.queue.length > 0) {
        nextVideo = this.state.queue[0];
        console.log('🎵 📋 Video desde cola (INSTANTÁNEO):', nextVideo.title);
      } else {
        // Búsqueda RÁPIDA de video relacionado
        nextVideo = await this.findRelatedVideoFast();
      }

      if (nextVideo) {
        this.updateState({
          ...this.state,
          nextVideo,
          queue: this.state.queue.slice(1) // Remover de cola si vino de ahí
        });

        console.log('🎵 ⚡ Video precargado INSTANTÁNEAMENTE:', nextVideo.title);
      } else {
        console.warn('🎵 ⚠️ No se pudo precargar video instantáneamente');
      }

    } catch (error) {
      console.error('🎵 ❌ Error en precarga instantánea:', error);
    }
  }

  /**
   * Búsqueda RÁPIDA de video relacionado (optimizada para velocidad)
   */
  private async findRelatedVideoFast(): Promise<YouTubeVideo | null> {
    if (!this.state.currentVideo) return null;

    try {
      console.log('🎵 🚀 Búsqueda RÁPIDA de video relacionado...');
      
      // Usar solo el término más relevante para búsqueda rápida
      const currentVideo = this.state.currentVideo;
      const searchTerms = this.generateSearchTermsFast(currentVideo);
      
      // Probar cada término hasta encontrar resultados
      for (const term of searchTerms) {
        try {
          const results = await this.youtubeService.searchVideos({
            query: term,
            maxResults: 5, // Menos resultados para mayor velocidad
            videoDuration: 'medium' // Priorizar videos de duración media
          });

          if (results.length > 0) {
            // Filtrar videos ya reproducidos y seleccionar el mejor
            const availableVideos = results.filter(video => 
              !this.state.playHistory.includes(video.id) && 
              video.id !== currentVideo.id
            );

            if (availableVideos.length > 0) {
              const selectedVideo = availableVideos[0];
              console.log('🎵 ⚡ Video encontrado RÁPIDAMENTE:', selectedVideo.title);
              return selectedVideo;
            }
          }
        } catch (termError: any) {
          console.warn('🎵 ⚠️ Error con término de búsqueda:', term, termError);
          
          // Si es error 403 (cuota excedida), usar fallback
          if (termError.message && termError.message.includes('403')) {
            console.log('🎵 🚨 Error 403 detectado, usando FALLBACK...');
            try {
              const fallbackResults = await this.youtubeService.searchVideosFallback(term);
              if (fallbackResults.length > 0) {
                const availableVideos = fallbackResults.filter(video => 
                  !this.state.playHistory.includes(video.id) && 
                  video.id !== currentVideo.id
                );
                
                if (availableVideos.length > 0) {
                  const selectedVideo = availableVideos[0];
                  console.log('🎵 ⚡ Video FALLBACK encontrado:', selectedVideo.title);
                  return selectedVideo;
                }
              }
            } catch (fallbackError) {
              console.warn('🎵 ⚠️ Error en fallback:', fallbackError);
            }
          }
          
          continue; // Probar siguiente término
        }
      }

      console.warn('🎵 ⚠️ No se encontró video en búsqueda rápida');
      return null;

    } catch (error) {
      console.error('🎵 ❌ Error en búsqueda rápida:', error);
      return null;
    }
  }

  /**
   * Generar términos de búsqueda OPTIMIZADOS para velocidad
   */
  private generateSearchTermsFast(video: YouTubeVideo): string[] {
    const terms: string[] = [];

    // Solo los términos más efectivos para búsqueda rápida
    
    // 1. Artista/Canal (más efectivo)
    if (video.channelTitle) {
      terms.push(video.channelTitle);
    }

    // 2. Primera palabra del título + "música"
    const firstWord = video.title.split(' ')[0];
    if (firstWord && firstWord.length > 2) {
      terms.push(firstWord + ' música');
    }

    // 3. Búsquedas COMPLETAMENTE ALEATORIAS para mayor variedad
    terms.push(...this.generateRandomMusicTerms());

    console.log('🎵 🔍 Términos de búsqueda rápida:', terms);
    return terms;
  }

  /**
   * Generar términos de música completamente ALEATORIOS
   */
  private generateRandomMusicTerms(): string[] {
    const genres = [
      'pop', 'rock', 'reggaeton', 'bachata', 'salsa', 'merengue', 
      'cumbia', 'vallenato', 'trap', 'hip hop', 'electronic', 
      'indie', 'jazz', 'blues', 'country', 'folk', 'classical',
      'latin', 'spanish', 'english', 'ballad', 'dance', 'regueton',
      'urbano', 'tropical', 'bolero', 'tango', 'flamenco', 'rumba'
    ];

    const adjectives = [
      'nueva', 'hit', 'popular', 'top', 'best', 'latest', 'trending',
      'viral', 'famosa', 'nueva generación', 'underground', 'remix',
      'éxito', 'romántica', 'bailable', 'moderna', 'clásica'
    ];

    const years = ['2024', '2023', '2022', '2021', '2020', '2019'];

    const artists = [
      'Bad Bunny', 'Karol G', 'Rosalía', 'J Balvin', 'Shakira',
      'Daddy Yankee', 'Ozuna', 'Maluma', 'Anuel AA', 'Sech',
      'Manuel Turizo', 'Rauw Alejandro', 'Myke Towers', 'Jhay Cortez'
    ];

    const randomTerms: string[] = [];

    // Generar 5-6 términos aleatorios diferentes
    for (let i = 0; i < 6; i++) {
      const genre = genres[Math.floor(Math.random() * genres.length)];
      const adjective = adjectives[Math.floor(Math.random() * adjectives.length)];
      const year = years[Math.floor(Math.random() * years.length)];
      const artist = artists[Math.floor(Math.random() * artists.length)];

      // Diferentes combinaciones aleatorias
      switch (Math.floor(Math.random() * 6)) {
        case 0:
          randomTerms.push(`${adjective} ${genre}`);
          break;
        case 1:
          randomTerms.push(`${genre} ${year}`);
          break;
        case 2:
          randomTerms.push(`música ${genre} ${adjective}`);
          break;
        case 3:
          randomTerms.push(`${genre} hits`);
          break;
        case 4:
          randomTerms.push(`${artist} type beat`);
          break;
        case 5:
          randomTerms.push(`${adjective} canciones ${year}`);
          break;
      }
    }

    console.log('🎵 🎲 Términos de música aleatorios generados:', randomTerms);
    return randomTerms;
  }

  /**
   * Encontrar video rápido como fallback de emergencia
   */
  private async findQuickVideo() {
    try {
      console.log('🎵 🚨 BÚSQUEDA DE EMERGENCIA activada');
      
      // Usar términos completamente aleatorios
      const randomTerms = this.generateRandomMusicTerms();
      const searchTerm = randomTerms[0];
      
      console.log('🎵 🎲 Buscando con término aleatorio:', searchTerm);
      
      const results = await this.youtubeService.searchVideos({
        query: searchTerm,
        maxResults: 5,
        order: 'relevance'
      });

      if (results.length > 0) {
        // Seleccionar video aleatorio de los resultados
        const randomIndex = Math.floor(Math.random() * results.length);
        const quickVideo = results[randomIndex];
        
        console.log('🎵 🚨 Video de emergencia encontrado:', quickVideo.title);
        
        this.updateState({
          ...this.state,
          currentVideo: quickVideo,
          nextVideo: null
        });

        this.notifyVideoChange(quickVideo);
        
        // Precargar siguiente inmediatamente
        setTimeout(() => this.preloadNextVideoInstant(), 200); // Reducido de 1000ms a 200ms
      }
    } catch (error) {
      console.error('🎵 ❌ Error en búsqueda de emergencia:', error);
    }
  }

  /**
   * Notificar cambio de video a los componentes
   */
  private notifyVideoChange(video: YouTubeVideo | null) {
    // Verificar que el video sea válido
    if (!video || !video.id) {
      console.warn('🎵 ⚠️ Intento de notificar video inválido:', video);
      return;
    }

    console.log('🎵 📢 Notificando cambio de video:', video.title || video.id);
    
    // Enviar evento personalizado para que los componentes reaccionen
    const event = new CustomEvent('autoplay-video-change', {
      detail: { video }
    });
    window.dispatchEvent(event);
  }

  /**
   * Actualizar estado y notificar listeners
   */
  private updateState(newState: AutoplayState) {
    this.state = newState;
    this.listeners.forEach(listener => listener(newState));
  }

  /**
   * Suscribirse a cambios de estado
   */
  public subscribe(listener: (state: AutoplayState) => void): () => void {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  /**
   * Obtener estado actual
   */
  public getState(): AutoplayState {
    return { ...this.state };
  }

  /**
   * Iniciar autoplay con música completamente ALEATORIA
   */
  public async startRandomMusic(): Promise<void> {
    try {
      // Inicializar API solo cuando se necesite
      this.initialize();
      
      console.log('🎵 🎲 Iniciando música completamente ALEATORIA...');
      
      const randomTerms = this.generateRandomMusicTerms();
      const searchTerm = randomTerms[0];
      
      console.log('🎵 🔍 Buscando música aleatoria con:', searchTerm);
      
      const results = await this.youtubeService.searchVideos({
        query: searchTerm,
        maxResults: 10,
        order: 'relevance',
        videoDuration: 'medium'
      });

      if (results.length > 0) {
        // Seleccionar video completamente aleatorio
        const randomIndex = Math.floor(Math.random() * results.length);
        const randomVideo = results[randomIndex];
        
        console.log('🎵 🎲 Video aleatorio seleccionado:', randomVideo.title);
        
        // Establecer como video actual
        this.setCurrentVideo(randomVideo);
        
        // Precargar siguiente inmediatamente
        setTimeout(() => this.preloadNextVideoInstant(), 300); // Reducido de 2000ms a 300ms
        
        return;
      }
      
      console.warn('🎵 ⚠️ No se encontraron videos aleatorios');
      
    } catch (error) {
      console.error('🎵 ❌ Error iniciando música aleatoria:', error);
      // Fallback con búsqueda simple
      this.findQuickVideo();
    }
  }

  /**
   * Establecer video actual (llamado desde componentes)
   */
  public setCurrentVideo(video: YouTubeVideo) {
    // Inicializar API cuando se establece un video
    this.initialize();
    
    this.updateState({
      ...this.state,
      currentVideo: video,
      nextVideo: null // Limpiar siguiente para forzar nueva búsqueda
    });

    console.log('🎵 🎯 Video actual establecido:', video.title);
    
    // Inicializar listener de mensajes si no está configurado
    if (!this.currentPlayer) {
      this.setupMessageListener();
      this.currentPlayer = true;
    }
  }

  /**
   * Agregar video a la cola
   */
  public addToQueue(video: YouTubeVideo) {
    this.updateState({
      ...this.state,
      queue: [...this.state.queue, video]
    });

    console.log('🎵 ➕ Video agregado a cola:', video.title);
  }

  /**
   * Limpiar cola
   */
  public clearQueue() {
    this.updateState({
      ...this.state,
      queue: [],
      nextVideo: null
    });

    console.log('🎵 🗑️ Cola limpiada');
  }

  /**
   * Extraer artista del título del video
   */
  private extractArtistFromTitle(title: string): string | null {
    // Patrones comunes para detectar artistas
    const artistPatterns = [
      // "Artista - Canción"
      /^([^-]+)\s*-/i,
      // "Artista ft. Otro" o "Artista feat. Otro"
      /^([^(ft|feat|featuring|con|x|)]+)/i,
      // "Artista (Official Video)"
      /^([^(]+)\s*\(/i,
      // Artistas latinos conocidos
      /(bad bunny|karol g|j balvin|rosalia|ozuna|maluma|daddy yankee|anuel aa|sech|rauw alejandro|myke towers|jhay cortez|manuel turizo|natti natasha|becky g|anitta)/i
    ];

    for (const pattern of artistPatterns) {
      const match = title.match(pattern);
      if (match && match[1]) {
        const artist = match[1].trim();
        if (artist.length > 2 && artist.length < 30) {
          return artist;
        }
      }
    }

    return null;
  }

  /**
   * Detectar género musical del título y canal
   */
  private detectMusicGenre(title: string, channelTitle: string): string | null {
    const titleAndChannel = `${title} ${channelTitle}`.toLowerCase();
    
    const genrePatterns = {
      'reggaeton': /reggaeton|regueton|urbano|trap latino|perreo/i,
      'pop latino': /pop latino|latin pop|balada/i,
      'bachata': /bachata|romeo santos|prince royce/i,
      'salsa': /salsa|marc anthony|gilberto santa rosa/i,
      'cumbia': /cumbia|sonidero|tropical/i,
      'merengue': /merengue|dominican/i,
      'vallenato': /vallenato|acordeón/i,
      'rock en español': /rock en español|mana|héroes del silencio/i,
      'trap': /trap|drill|rap/i,
      'hip hop': /hip hop|rap|freestyle/i,
      'electronic': /electronic|techno|house|edm/i,
      'indie': /indie|alternativo|underground/i,
      'jazz': /jazz|smooth|blues/i,
      'classical': /classical|clásica|orquesta/i,
      'folk': /folk|acústico|tradicional/i,
      'ranchera': /ranchera|mariachi|vicente fernández/i,
      'bolero': /bolero|romántica/i,
      'tango': /tango|argentino/i
    };

    for (const [genre, pattern] of Object.entries(genrePatterns)) {
      if (pattern.test(titleAndChannel)) {
        return genre;
      }
    }

    return null;
  }

  /**
   * Extraer palabras clave musicales del título
   */
  private extractMusicalKeywords(title: string): string[] {
    const keywords: string[] = [];
    const titleLower = title.toLowerCase();

    // Palabras clave musicales
    const musicalTerms = [
      'remix', 'official video', 'music video', 'live', 'acoustic',
      'unplugged', 'cover', 'instrumental', 'karaoke', 'dance',
      'mix', 'mashup', 'beat', 'type beat', 'hits', 'best of',
      'greatest hits', 'álbum', 'single', 'ep', 'deluxe'
    ];

    for (const term of musicalTerms) {
      if (titleLower.includes(term)) {
        keywords.push(term);
      }
    }

    // Extraer años
    const yearMatch = title.match(/20\d{2}/);
    if (yearMatch) {
      keywords.push(yearMatch[0]);
    }

    return keywords.slice(0, 3); // Limitar a 3 palabras clave
  }

  /**
   * Destruir servicio y limpiar recursos
   */
  public destroy() {
    if (this.checkInterval) {
      clearInterval(this.checkInterval);
    }
    if (this.notificationTimeout) {
      clearTimeout(this.notificationTimeout);
    }
    this.listeners = [];
    console.log('🎵 🔄 Servicio de autoplay destruido');
  }
}

// Exportar instancia singleton
export const autoplayService = new AutoplayService();
