/**
 * Componente de visualización mejorado para cámara y pantalla compartida
 * Optimizado para PC y móvil con mejor experiencia visual
 */

import React, { useRef, useEffect, useState, useCallback } from 'react';
import './video-display.scss';

interface VideoDisplayProps {
  stream: MediaStream | null;
  type: 'webcam' | 'screen';
  isActive: boolean;
  className?: string;
  onToggleFullscreen?: () => void;
  showControls?: boolean;
  autoPlay?: boolean;
  muted?: boolean;
  onVideoRef?: (videoElement: HTMLVideoElement | null) => void;
}

export const VideoDisplay: React.FC<VideoDisplayProps> = ({
  stream,
  type,
  isActive,
  className = '',
  onToggleFullscreen,
  showControls = true,
  autoPlay = true,
  muted = true,
  onVideoRef,
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [videoError, setVideoError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [dimensions, setDimensions] = useState({ width: 0, height: 0 });

  // Configurar el stream del video
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    if (stream && isActive) {
      setIsLoading(true);
      setVideoError(null);
      
      video.srcObject = stream;
      
      const handleLoadedMetadata = () => {
        setIsLoading(false);
        setDimensions({
          width: video.videoWidth,
          height: video.videoHeight,
        });
      };

      const handleError = () => {
        setIsLoading(false);
        setVideoError(`Error al cargar ${type === 'webcam' ? 'cámara' : 'pantalla'}`);
      };

      video.addEventListener('loadedmetadata', handleLoadedMetadata);
      video.addEventListener('error', handleError);

      return () => {
        video.removeEventListener('loadedmetadata', handleLoadedMetadata);
        video.removeEventListener('error', handleError);
      };
    } else {
      video.srcObject = null;
      setIsLoading(false);
      setVideoError(null);
      setDimensions({ width: 0, height: 0 });
    }
  }, [stream, isActive, type]);

  // Pasar el videoRef al componente padre si se proporciona callback
  useEffect(() => {
    if (onVideoRef) {
      onVideoRef(videoRef.current);
    }
  }, [onVideoRef]);

  // Manejar fullscreen
  const toggleFullscreen = useCallback(async () => {
    const container = containerRef.current;
    if (!container) return;

    try {
      if (!isFullscreen) {
        if (container.requestFullscreen) {
          await container.requestFullscreen();
        } else if ((container as any).webkitRequestFullscreen) {
          await (container as any).webkitRequestFullscreen();
        } else if ((container as any).msRequestFullscreen) {
          await (container as any).msRequestFullscreen();
        }
      } else {
        if (document.exitFullscreen) {
          await document.exitFullscreen();
        } else if ((document as any).webkitExitFullscreen) {
          await (document as any).webkitExitFullscreen();
        } else if ((document as any).msExitFullscreen) {
          await (document as any).msExitFullscreen();
        }
      }
    } catch (err) {
      console.error('Error toggling fullscreen:', err);
    }
  }, [isFullscreen]);

  // Detectar cambios de fullscreen
  useEffect(() => {
    const handleFullscreenChange = () => {
      const isNowFullscreen = !!(
        document.fullscreenElement ||
        (document as any).webkitFullscreenElement ||
        (document as any).msFullscreenElement
      );
      setIsFullscreen(isNowFullscreen);
    };

    document.addEventListener('fullscreenchange', handleFullscreenChange);
    document.addEventListener('webkitfullscreenchange', handleFullscreenChange);
    document.addEventListener('msfullscreenchange', handleFullscreenChange);

    return () => {
      document.removeEventListener('fullscreenchange', handleFullscreenChange);
      document.removeEventListener('webkitfullscreenchange', handleFullscreenChange);
      document.removeEventListener('msfullscreenchange', handleFullscreenChange);
    };
  }, []);

  // Handle custom fullscreen toggle
  const handleFullscreenClick = () => {
    if (onToggleFullscreen) {
      onToggleFullscreen();
    } else {
      toggleFullscreen();
    }
  };

  if (!isActive || !stream) {
    return (
      <div className={`video-display-placeholder ${className}`}>
        <div className="placeholder-content">
          <span className="placeholder-icon">
            {type === 'webcam' ? '📹' : '🖥️'}
          </span>
          <span className="placeholder-text">
            {type === 'webcam' ? 'Cámara desactivada' : 'Pantalla no compartida'}
          </span>
        </div>
      </div>
    );
  }

  return (
    <div 
      ref={containerRef}
      className={`video-display ${type} ${className} ${isFullscreen ? 'fullscreen' : ''}`}
    >
      {/* Indicador de tipo */}
      <div className="video-type-indicator">
        <span className="type-icon">
          {type === 'webcam' ? '📹' : '🖥️'}
        </span>
        <span className="type-label">
          {type === 'webcam' ? 'Cámara' : 'Pantalla'}
        </span>
        {dimensions.width > 0 && (
          <span className="resolution">
            {dimensions.width}×{dimensions.height}
          </span>
        )}
      </div>

      {/* Video principal */}
      <video
        ref={videoRef}
        autoPlay={autoPlay}
        playsInline
        muted={muted}
        className="video-element"
        style={{ display: isLoading ? 'none' : 'block' }}
      />

      {/* Estado de carga */}
      {isLoading && (
        <div className="video-loading">
          <div className="loading-spinner"></div>
          <span>Iniciando {type === 'webcam' ? 'cámara' : 'pantalla'}...</span>
        </div>
      )}

      {/* Error de video */}
      {videoError && (
        <div className="video-error">
          <span className="error-icon">❌</span>
          <span className="error-message">{videoError}</span>
        </div>
      )}

      {/* Controles */}
      {showControls && !isLoading && !videoError && (
        <div className="video-controls">
          <button
            className="control-button fullscreen-btn"
            onClick={handleFullscreenClick}
            title={isFullscreen ? 'Salir de pantalla completa' : 'Pantalla completa'}
          >
            {isFullscreen ? '⤢' : '⛶'}
          </button>
          
          {type === 'screen' && (
            <button
              className="control-button picture-in-picture-btn"
              onClick={() => {
                const video = videoRef.current;
                if (video && (video as any).requestPictureInPicture) {
                  (video as any).requestPictureInPicture();
                }
              }}
              title="Picture in Picture"
            >
              📱
            </button>
          )}
        </div>
      )}

      {/* Overlay de información en fullscreen */}
      {isFullscreen && (
        <div className="fullscreen-overlay">
          <div className="fullscreen-info">
            <span>{type === 'webcam' ? '📹 Cámara' : '🖥️ Pantalla Compartida'}</span>
            <span className="fullscreen-hint">Presiona ESC o toca para salir</span>
          </div>
        </div>
      )}
    </div>
  );
};