import { useEffect, useRef } from 'react';
import { AutoplayService } from '../services/AutoplayService';
import { YouTubeVideo } from '../services/YouTubeService';
import { logger } from '../utils/logger';

/**
 * Hook para usar autoplay instantáneo de YouTube
 * Optimizado para reducir consumo de recursos
 */
export const useAutoplayInstant = (currentVideoUrl?: string) => {
  const autoplayServiceRef = useRef<AutoplayService | null>(null);

  // Solo inicializar el servicio cuando hay un video cargado
  useEffect(() => {
    if (currentVideoUrl && !autoplayServiceRef.current) {
      logger.log('🎵 🚀 Inicializando AutoplayService (video detectado)...');
      autoplayServiceRef.current = new AutoplayService();
      logger.log('🎵 ✅ AutoplayService creado');
    }

    return () => {
      // Solo limpiar si no hay video activo
      if (!currentVideoUrl && autoplayServiceRef.current) {
        logger.log('🎵 🧹 Limpiando autoplay service (sin video activo)...');
        autoplayServiceRef.current.destroy();
        autoplayServiceRef.current = null;
      }
    };
  }, [currentVideoUrl]);

  // Función para activar música aleatoria (lazy initialization)
  const startRandomMusic = async () => {
    if (!autoplayServiceRef.current) {
      logger.log('🎵 🚀 Inicializando AutoplayService (música solicitada)...');
      autoplayServiceRef.current = new AutoplayService();
    }
    
    if (autoplayServiceRef.current) {
      logger.log('🎵 🎲 Iniciando música aleatoria...');
      await autoplayServiceRef.current.startRandomMusic();
    } else {
      console.warn('🎵 ⚠️ AutoplayService no disponible');
    }
  };

  // Función para establecer video actual
  const setCurrentVideo = (video: YouTubeVideo) => {
    if (!autoplayServiceRef.current) {
      logger.log('🎵 🚀 Inicializando AutoplayService (video establecido)...');
      autoplayServiceRef.current = new AutoplayService();
    }
    
    if (autoplayServiceRef.current) {
      autoplayServiceRef.current.setCurrentVideo(video);
    }
  };

  // Función para obtener estado
  const getState = () => {
    return autoplayServiceRef.current?.getState();
  };

  // Función para suscribirse a cambios
  const subscribe = (listener: (state: any) => void) => {
    if (autoplayServiceRef.current) {
      return autoplayServiceRef.current.subscribe(listener);
    }
    return () => {};
  };

  return {
    autoplayService: autoplayServiceRef.current,
    startRandomMusic,
    setCurrentVideo,
    getState,
    subscribe
  };
};
