import { useState, useCallback } from 'react';

interface ChatbotVoxState {
  isVisible: boolean;
  isMinimized: boolean;
  position: 'left' | 'right';
}

export const useChatbotVox = () => {
  const [state, setState] = useState<ChatbotVoxState>({
    isVisible: false,
    isMinimized: false,
    position: 'right'
  });

  const showChatbot = useCallback(() => {
    setState(prev => ({ ...prev, isVisible: true }));
  }, []);

  const hideChatbot = useCallback(() => {
    setState(prev => ({ ...prev, isVisible: false }));
  }, []);

  const toggleChatbot = useCallback(() => {
    setState(prev => ({ ...prev, isVisible: !prev.isVisible }));
  }, []);

  const minimizeChatbot = useCallback(() => {
    setState(prev => ({ ...prev, isMinimized: !prev.isMinimized }));
  }, []);

  const setPosition = useCallback((position: 'left' | 'right') => {
    setState(prev => ({ ...prev, position }));
  }, []);

  return {
    ...state,
    showChatbot,
    hideChatbot,
    toggleChatbot,
    minimizeChatbot,
    setPosition
  };
};