import React from 'react'
import { useAuth } from '../contexts/AuthContext'
import { LoginButton } from '../components/auth'
import './AuthWrapper.scss'

interface AuthWrapperProps {
  children: React.ReactNode
}

export function AuthWrapper({ children }: AuthWrapperProps) {
  const { user, loading } = useAuth()

  if (loading) {
    return (
      <div className="auth-loading">
        <div className="auth-loading__content">
          <div className="auth-loading__spinner"></div>
          <p>Cargando...</p>
        </div>
      </div>
    )
  }

  if (!user) {
    return (
      <div className="auth-login">
        <div className="auth-login__content">
          <div className="auth-login__header">
            <img 
              src="/voxia-logo.png" 
              alt="VOXIA" 
              className="auth-login__logo"
            />
            <h1 className="auth-login__title">VOXIA</h1>
            <p className="auth-login__subtitle">
              Asistente de IA Multimodal en Español
            </p>
          </div>
          
          <div className="auth-login__form">
            <h2>Inicia sesión para continuar</h2>
            <p className="auth-login__description">
              Accede a todas las funciones de VOXIA con tu cuenta de Google
            </p>
            
            <LoginButton 
              variant="primary" 
              size="large"
              className="auth-login__button"
            />
          </div>
          
          <div className="auth-login__features">
            <h3>¿Qué puedes hacer con VOXIA?</h3>
            <ul>
              <li>🎤 Conversaciones de voz en tiempo real</li>
              <li>🎵 Integración completa con YouTube</li>
              <li>� Gestión de Google Calendar integrada</li>
              <li>�💬 Chatbot multimodal avanzado</li>
              <li>📚 Herramientas de estudio interactivo</li>
              <li>🖥️ Compartir pantalla y grabación</li>
              <li>⏰ Creación rápida de eventos</li>
              <li>🌟 Y mucho más...</li>
            </ul>
          </div>
        </div>
      </div>
    )
  }

  return <>{children}</>
}