import { useState, useEffect, useCallback, useRef } from "react";
import { UseMediaStreamResult } from "./use-media-stream-mux";
import { logger } from "../utils/logger";
import { executeMediaStreamWithFallback } from "../utils/media-stream-fallback";

interface EnhancedWebcamResult extends UseMediaStreamResult {
  error: string | null;
  retryCount: number;
  permissionStatus: 'unknown' | 'granted' | 'denied' | 'prompt';
  isSupported: boolean;
  forceRetry: () => Promise<MediaStream | null>;
  availableDevices: MediaDeviceInfo[];
  switchCamera: (deviceId?: string) => Promise<MediaStream | null>;
}

const MAX_RETRY_ATTEMPTS = 3;
const RETRY_DELAYS = [1000, 2000, 4000]; // Backoff exponencial en ms

export function useWebcam(): EnhancedWebcamResult {
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [isStreaming, setIsStreaming] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [retryCount, setRetryCount] = useState(0);
  const [permissionStatus, setPermissionStatus] = useState<'unknown' | 'granted' | 'denied' | 'prompt'>('unknown');
  const [availableDevices, setAvailableDevices] = useState<MediaDeviceInfo[]>([]);
  const [currentDeviceId, setCurrentDeviceId] = useState<string>('');
  const retryTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  // Verificar compatibilidad completa del navegador
  const isSupported = !!(
    navigator.mediaDevices && 
    navigator.mediaDevices.getUserMedia &&
    typeof navigator.mediaDevices.getUserMedia === 'function'
  );

  // Verificar permisos y dispositivos al cargar
  useEffect(() => {
    const checkPermissionsAndDevices = async () => {
      if (!isSupported) return;
      
      try {
        // Verificar permisos de cámara si está disponible
        if ('permissions' in navigator) {
          const result = await navigator.permissions.query({ name: 'camera' as PermissionName });
          setPermissionStatus(result.state as any);
          
          result.addEventListener('change', () => {
            setPermissionStatus(result.state as any);
          });
        }

        // Obtener dispositivos disponibles si hay permisos
        if (permissionStatus === 'granted') {
          const devices = await navigator.mediaDevices.enumerateDevices();
          const videoDevices = devices.filter(device => device.kind === 'videoinput');
          setAvailableDevices(videoDevices);
        }
      } catch (err) {
        logger.debug('No se pudieron verificar permisos de cámara:', err);
      }
    };

    checkPermissionsAndDevices();
  }, [isSupported, permissionStatus]);

  // Limpiar timeouts al desmontar
  useEffect(() => {
    return () => {
      if (retryTimeoutRef.current) {
        clearTimeout(retryTimeoutRef.current);
      }
    };
  }, []);

  const handleStreamEnded = useCallback(() => {
    logger.info('Stream de cámara terminado por el usuario');
    setIsStreaming(false);
    setStream(null);
    setError(null);
  }, []);

  useEffect(() => {
    if (stream) {
      stream
        .getTracks()
        .forEach((track) => track.addEventListener("ended", handleStreamEnded));
      return () => {
        stream
          .getTracks()
          .forEach((track) =>
            track.removeEventListener("ended", handleStreamEnded),
          );
      };
    }
  }, [stream, handleStreamEnded]);

  const getDetailedError = (err: any): string => {
    const errorName = err.name || err.code;
    
    switch (errorName) {
      case 'NotAllowedError':
        return 'Permisos denegados para acceder a la cámara. Por favor, permite el acceso e inténtalo de nuevo.';
      case 'NotFoundError':
        return 'No se encontró ninguna cámara disponible en este dispositivo.';
      case 'NotSupportedError':
        return 'Tu navegador no soporta el acceso a la cámara. Usa Chrome, Firefox o Edge.';
      case 'NotReadableError':
        return 'Error al acceder a la cámara. Puede estar siendo usada por otra aplicación.';
      case 'OverconstrainedError':
        return 'Las configuraciones de cámara no son compatibles con el dispositivo.';
      case 'SecurityError':
        return 'Error de seguridad al acceder a la cámara. Verifica que estés en HTTPS.';
      case 'AbortError':
        return 'El acceso a la cámara fue cancelado.';
      case 'InvalidStateError':
        return 'La cámara está en un estado inválido.';
      case 'UnknownError':
        return 'Error desconocido del sistema al acceder a la cámara.';
      default:
        return err.message || 'Error desconocido al acceder a la cámara';
    }
  };

  const attemptCapture = useCallback(async (deviceId?: string): Promise<MediaStream> => {
    logger.info('Intentando acceso a cámara...', { deviceId });
    
    if (!isSupported) {
      throw new Error('BROWSER_NOT_SUPPORTED');
    }

    // Configuraciones optimizadas por prioridad (de mejor a más básica)
    const configs = [
      // Configuración ideal con dispositivo específico
      ...(deviceId ? [{
        video: {
          deviceId: { exact: deviceId },
          width: { ideal: 1920, max: 1920 },
          height: { ideal: 1080, max: 1080 },
          frameRate: { ideal: 30, max: 60 },
          facingMode: 'user'
        },
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true
        }
      }] : []),
      
      // Configuración ideal sin dispositivo específico
      {
        video: {
          width: { ideal: 1920, max: 1920 },
          height: { ideal: 1080, max: 1080 },
          frameRate: { ideal: 30, max: 60 },
          facingMode: 'user'
        },
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true
        }
      },
      
      // Configuración media
      {
        video: {
          width: { ideal: 1280, max: 1280 },
          height: { ideal: 720, max: 720 },
          frameRate: { ideal: 30 },
          facingMode: 'user'
        },
        audio: true
      },
      
      // Configuración básica solo video
      {
        video: {
          facingMode: 'user'
        }
      },
      
      // Configuración mínima
      {
        video: true
      }
    ];

    let lastError: any;
    
    for (let i = 0; i < configs.length; i++) {
      try {
        const webcamStream = await navigator.mediaDevices.getUserMedia(configs[i]);
        logger.info(`Acceso a cámara exitoso con configuración ${i + 1}/${configs.length}`);
        return webcamStream;
      } catch (err: any) {
        lastError = err;
        logger.warn(`Fallo configuración ${i + 1}/${configs.length}:`, err);
        
        // Si es error de permisos, no intentar más configuraciones
        if (err.name === 'NotAllowedError') {
          break;
        }
      }
    }

    logger.error('Todos los intentos de acceso a cámara fallaron:', lastError);
    throw lastError;
  }, [isSupported]);

  const start = useCallback(async (): Promise<MediaStream> => {
    if (!isSupported) {
      const errorMsg = 'El acceso a la cámara no está disponible en este navegador. Usa Chrome, Firefox o Edge.';
      setError(errorMsg);
      logger.error(errorMsg);
      throw new Error(errorMsg);
    }

    if (isStreaming) {
      logger.debug('Cámara ya en uso, ignorando nueva solicitud');
      return stream!;
    }

    setError(null);

    // Usar sistema de fallback robusto
    const fallbackResult = await executeMediaStreamWithFallback(
      () => attemptCapture(currentDeviceId),
      'camera',
      currentDeviceId
    );

    if (fallbackResult.success && fallbackResult.result) {
      setStream(fallbackResult.result);
      setIsStreaming(true);
      setPermissionStatus('granted');
      setRetryCount(fallbackResult.retryCount);
      setError(null);
      
      // Actualizar dispositivos disponibles
      try {
        const devices = await navigator.mediaDevices.enumerateDevices();
        const videoDevices = devices.filter(device => device.kind === 'videoinput');
        setAvailableDevices(videoDevices);
      } catch (deviceErr) {
        logger.warn('No se pudieron actualizar dispositivos:', deviceErr);
      }
      
      logger.info(`Stream de cámara establecido correctamente (fallback: ${fallbackResult.fallbackUsed})`);
      return fallbackResult.result;
    } else {
      const errorMessage = fallbackResult.error || 'Error desconocido al acceder a la cámara';
      setError(errorMessage);
      setRetryCount(fallbackResult.retryCount);
      
      if (errorMessage.includes('Permisos denegados')) {
        setPermissionStatus('denied');
      }

      logger.error('Error con sistema de fallback:', {
        error: errorMessage,
        fallbackUsed: fallbackResult.fallbackUsed,
        retryCount: fallbackResult.retryCount
      });

      throw new Error(errorMessage);
    }
  }, [isSupported, isStreaming, stream, attemptCapture, currentDeviceId]);

  const switchCamera = useCallback(async (deviceId?: string): Promise<MediaStream | null> => {
    if (isStreaming) {
      stop();
    }
    
    setCurrentDeviceId(deviceId || '');
    
    try {
      return await start();
    } catch (err) {
      logger.error('Error al cambiar cámara:', err);
      return null;
    }
  }, [isStreaming, start]);

  const forceRetry = useCallback(async (): Promise<MediaStream | null> => {
    setRetryCount(0);
    setError(null);
    setPermissionStatus('unknown');
    
    try {
      return await start();
    } catch (err) {
      logger.error('Error en force retry:', err);
      return null;
    }
  }, [start]);

  const stop = useCallback(() => {
    if (retryTimeoutRef.current) {
      clearTimeout(retryTimeoutRef.current);
      retryTimeoutRef.current = null;
    }

    if (stream) {
      logger.info('Deteniendo cámara');
      stream.getTracks().forEach((track) => track.stop());
      setStream(null);
      setIsStreaming(false);
    }
    
    setError(null);
    setRetryCount(0);
  }, [stream]);

  const result: EnhancedWebcamResult = {
    type: "webcam",
    start,
    stop,
    isStreaming,
    stream,
    error,
    retryCount,
    permissionStatus,
    isSupported,
    forceRetry,
    availableDevices,
    switchCamera,
  };

  return result;
}
