import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { GenAILiveClient } from "../lib/genai-live-client";
import { LiveClientOptions } from "../types";
import { AudioStreamer } from "../lib/audio-streamer";
import { audioContext } from "../lib/utils";
import VolMeterWorket from "../lib/worklets/vol-meter";
import { LiveConnectConfig } from "@google/genai";

export type UseLiveAPIResults = {
  client: GenAILiveClient;
  setConfig: (config: LiveConnectConfig) => void;
  config: LiveConnectConfig;
  model: string;
  setModel: (model: string) => void;
  connected: boolean;
  connect: () => Promise<void>;
  disconnect: () => Promise<void>;
  volume: number;
};

export function useLiveAPI(options: LiveClientOptions): UseLiveAPIResults {
  const client = useMemo(() => new GenAILiveClient(options), [options]);
  const audioStreamerRef = useRef<AudioStreamer | null>(null);

  const [model, setModel] = useState<string>("models/gemini-2.5-flash-native-audio-preview-09-2025");
  const [config, setConfig] = useState<LiveConnectConfig>({});
  const [connected, setConnected] = useState(false);
  const [volume, setVolume] = useState(0);

  // register audio for streaming server -> speakers
  useEffect(() => {
    if (!audioStreamerRef.current) {
      audioContext({ id: "audio-out" }).then((audioCtx: AudioContext) => {
        audioStreamerRef.current = new AudioStreamer(audioCtx);
        audioStreamerRef.current
          .addWorklet<any>("vu-meter", VolMeterWorket, (ev: any) => {
            setVolume(ev.data.volume);
          })
          .then(() => {
            // Successfully added worklet
          });
      });
    }
  }, [audioStreamerRef]);

  useEffect(() => {
    const onOpen = () => {
      setConnected(true);
    };

    const onClose = (event?: any) => {
      setConnected(false);
      
      // Detectar si la desconexión fue por cuota excedida
      if (event && event.reason && event.reason.includes("exceeded your current quota")) {
        console.error("🚫 CUOTA EXCEDIDA: Se ha agotado la cuota de API de Gemini");
        // Emitir evento personalizado para notificar el error de cuota
        window.dispatchEvent(new CustomEvent('quota-exceeded', {
          detail: {
            message: "Se ha agotado la cuota de la API de Gemini. Verifica tu plan y detalles de facturación.",
            reason: event.reason
          }
        }));
      }
    };

    const onError = (error: ErrorEvent) => {
      console.error("error", error);
      
      // Detectar errores de cuota en el mensaje de error
      if (error.message && error.message.includes("exceeded your current quota")) {
        console.error("🚫 CUOTA EXCEDIDA detectada en error:", error.message);
        window.dispatchEvent(new CustomEvent('quota-exceeded', {
          detail: {
            message: "Se ha agotado la cuota de la API de Gemini. Verifica tu plan y detalles de facturación.",
            reason: error.message
          }
        }));
      }
    };

    const stopAudioStreamer = () => audioStreamerRef.current?.stop();

    const onAudio = (data: ArrayBuffer) =>
      audioStreamerRef.current?.addPCM16(new Uint8Array(data));

    client
      .on("error", onError)
      .on("open", onOpen)
      .on("close", onClose)
      .on("interrupted", stopAudioStreamer)
      .on("audio", onAudio);

    return () => {
      client
        .off("error", onError)
        .off("open", onOpen)
        .off("close", onClose)
        .off("interrupted", stopAudioStreamer)
        .off("audio", onAudio)
        .disconnect();
    };
  }, [client]);

  const connect = useCallback(async () => {
    if (!config) {
      console.error("🚫 Error: Configuración no establecida");
      throw new Error("La configuración no ha sido establecida. Por favor verifica la configuración de VOXIA.");
    }
    
    try {
      console.log("🔄 Intentando conectar a VOXIA...");
      client.disconnect();
      await client.connect(model, config);
      console.log("✅ Conectado exitosamente a VOXIA");
    } catch (error) {
      console.error("❌ Error al conectar a VOXIA:", error);
      
      // Mejorar el mensaje de error para el usuario
      let userMessage = "No se pudo conectar a VOXIA. ";
      
      if (error instanceof Error) {
        // Detectar error de cuota excedida
        if (error.message.includes("exceeded your current quota") || 
            error.message.includes("quota")) {
          userMessage = "🚫 CUOTA EXCEDIDA: Se ha agotado la cuota de la API de Gemini. Verifica tu plan y detalles de facturación. No se realizarán más intentos de conexión automática.";
          
          // Emitir evento para notificar el error de cuota
          window.dispatchEvent(new CustomEvent('quota-exceeded', {
            detail: {
              message: userMessage,
              reason: error.message
            }
          }));
        } else if (error.message.includes("API_KEY") || error.message.includes("authentication")) {
          userMessage += "Verifica que tu API key de Gemini esté configurada correctamente.";
        } else if (error.message.includes("network") || error.message.includes("fetch")) {
          userMessage += "Verifica tu conexión a internet.";
        } else {
          userMessage += error.message;
        }
      }
      
      // Lanzar error con mensaje amigable
      throw new Error(userMessage);
    }
  }, [client, config, model]);

  const disconnect = useCallback(async () => {
    client.disconnect();
    setConnected(false);
  }, [setConnected, client]);

  return {
    client,
    config,
    setConfig,
    model,
    setModel,
    connected,
    connect,
    disconnect,
    volume,
  };
}
