import { supabase } from './supabase'

interface YouTubeVideo {
  id: { videoId: string }
  snippet: {
    title: string
    description: string
    thumbnails: {
      default: { url: string }
      medium: { url: string }
      high: { url: string }
    }
    channelTitle: string
    publishedAt: string
  }
}

interface YouTubeSearchResponse {
  items: YouTubeVideo[]
  nextPageToken?: string
  prevPageToken?: string
  pageInfo: {
    totalResults: number
    resultsPerPage: number
  }
}

interface YouTubeChannel {
  id: string
  snippet: {
    title: string
    description: string
    thumbnails: {
      default: { url: string }
      medium: { url: string }
      high: { url: string }
    }
  }
}

class YouTubeOAuthService {
  // Buscar videos relacionados usando OAuth
  async searchRelatedVideos(videoId: string, maxResults: number = 10): Promise<any> {
    return this.makeYouTubeRequest('search', {
      part: 'snippet',
      type: 'video',
      relatedToVideoId: videoId,
      maxResults: maxResults.toString(),
      safeSearch: 'none'
    });
  }
  private async getGoogleToken(): Promise<string | null> {
    try {
      const { data: { session } } = await supabase.auth.getSession()
      
      if (!session?.provider_token) {
        console.warn('No hay token de Google disponible. Usuario debe autenticarse.')
        return null
      }
      
      // Verificar si el token tiene los scopes necesarios
      // Por ahora, simplemente retornamos el token y manejaremos errores en las llamadas
      return session.provider_token
    } catch (error) {
      console.error('Error obteniendo token de Google:', error)
      return null
    }
  }

  private async makeYouTubeRequest(endpoint: string, params: Record<string, string> = {}): Promise<any> {
    const token = await this.getGoogleToken()
    
    if (!token) {
      throw new Error('Token de Google no disponible. El usuario debe autenticarse primero.')
    }

    const url = new URL(`https://www.googleapis.com/youtube/v3/${endpoint}`)
    Object.entries(params).forEach(([key, value]) => {
      url.searchParams.append(key, value)
    })

    const response = await fetch(url.toString(), {
      headers: {
        'Authorization': `Bearer ${token}`,
        'Accept': 'application/json',
      },
    })

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}))
      
      // Manejar específicamente errores de scopes
      if (response.status === 403 && errorData.error?.message?.includes('insufficient authentication scopes')) {
        throw new Error('Sin permisos de YouTube. Necesitas reautenticarte con scopes de YouTube.')
      }
      
      if (response.status === 403 && errorData.error?.message?.includes('access_denied')) {
        throw new Error('Acceso denegado a YouTube API. Verifica configuración OAuth.')
      }
      
      throw new Error(`YouTube API Error: ${response.status} - ${errorData.error?.message || response.statusText}`)
    }

    return response.json()
  }

  async searchVideos(query: string, maxResults: number = 10): Promise<YouTubeSearchResponse> {
    return this.makeYouTubeRequest('search', {
      part: 'snippet',
      q: query,
      type: 'video',
      maxResults: maxResults.toString(),
      order: 'relevance',
    })
  }

  async getVideoDetails(videoId: string): Promise<any> {
    return this.makeYouTubeRequest('videos', {
      part: 'snippet,contentDetails,statistics',
      id: videoId,
    })
  }

  async getUserChannels(): Promise<YouTubeChannel[]> {
    const response = await this.makeYouTubeRequest('channels', {
      part: 'snippet',
      mine: 'true',
    })
    return response.items || []
  }

  async getUserPlaylists(): Promise<any[]> {
    const response = await this.makeYouTubeRequest('playlists', {
      part: 'snippet',
      mine: 'true',
      maxResults: '50',
    })
    return response.items || []
  }

  async getPlaylistVideos(playlistId: string, maxResults: number = 50): Promise<any[]> {
    const response = await this.makeYouTubeRequest('playlistItems', {
      part: 'snippet',
      playlistId: playlistId,
      maxResults: maxResults.toString(),
    })
    return response.items || []
  }

  async getTrendingVideos(regionCode: string = 'ES', maxResults: number = 20): Promise<YouTubeSearchResponse> {
    return this.makeYouTubeRequest('videos', {
      part: 'snippet',
      chart: 'mostPopular',
      regionCode: regionCode,
      maxResults: maxResults.toString(),
    })
  }

  // Método para verificar si el usuario tiene permisos de YouTube
  async checkYouTubeAccess(): Promise<boolean> {
    try {
      await this.getUserChannels()
      return true
    } catch (error) {
      console.warn('Usuario no tiene acceso a YouTube API:', error)
      return false
    }
  }

  // Método para obtener información de cuota restante (aproximada)
  async getQuotaInfo(): Promise<{ hasAccess: boolean; message: string }> {
    try {
      const hasAccess = await this.checkYouTubeAccess()
      if (hasAccess) {
        return {
          hasAccess: true,
          message: 'Acceso a YouTube API disponible con cuota individual del usuario'
        }
      } else {
        return {
          hasAccess: false,
          message: 'Sin acceso a YouTube API. Usuario debe autenticarse con permisos de YouTube.'
        }
      }
    } catch (error) {
      return {
        hasAccess: false,
        message: `Error verificando acceso: ${error}`
      }
    }
  }
}

export const youtubeOAuth = new YouTubeOAuthService()
export type { YouTubeVideo, YouTubeSearchResponse, YouTubeChannel }